export const course = {"id":"preset-ielts7","title":"雅思7分语法日常训练","description":"雅思 7.0 语法（CEFR C1） · 成人","goal":"雅思 7.0 语法（CEFR C1）","cefr":"C1","syllabus":[{"title":"Advanced Tense & Aspect Combinations","skills":["past_perfect_continuous_in_narrative","future_perfect_vs_future_continuous","aspect_choice_for_emphasis","tense_consistency_in_academic_writing","mixed_tense_sequences","present_perfect_vs_past_simple"],"description":"C1级复杂时态与体的综合运用：完成进行时、过去完成时与叙事时态的精确搭配"},{"title":"Modal Verbs: Nuance & Epistemic Use","skills":["epistemic_modals_must_should_may","modal_perfect_for_past_deduction","semi_modals_be_bound_to_be_likely_to","modals_for_academic_hedging","contrast_between_similar_modals"],"description":"C1级情态动词的细微语义区分：推测、必要性、可能性及学术写作中的语气表达"},{"title":"Passive Voice & Causative Structures","skills":["passive_with_complex_tenses","passive_reporting_verbs_it_is_claimed","causative_have_get_with_past_participle","passive_infinitive_and_gerund","impersonal_passive_in_academic_prose","active_vs_passive_by_meaning"],"description":"C1级被动语态的多时态形式及使役结构have/get的书面语用法"},{"title":"Conditionals: Mixed, Inverted & Implied","skills":["mixed_conditionals_past_to_present","inverted_conditionals_had_were_should","implied_conditionals_with_otherwise_but_for","conditionals_in_formal_writing","conditional_like_structures_suppose_provided","mixed_conditionals_present_to_past","real_vs_hypothetical_conditionals"],"description":"C1级条件句：混合条件、倒装条件及隐含条件的书面表达"},{"title":"Relative Clauses: Advanced Forms","skills":["non_defining_relative_with_quantifiers_many_of_which","preposition_fronting_in_relative_clauses","sentential_relative_which_referring_to_clause","reduced_relative_clauses_with_participles","relative_clauses_with_whoever_whatever","defining_vs_non_defining_relative_clauses","relative_pronoun_accuracy"],"description":"C1级关系从句：含量词的非限制性从句、介词前置及which指代整句"},{"title":"Participle & Absolute Clauses","skills":["present_participle_clauses_for_result_reason","past_participle_clauses_for_condition_concession","perfect_participle_having_done","absolute_participial_constructions","dangling_participle_avoidance","participle_active_vs_passive"],"description":"C1级分词短语与独立主格结构在书面语中压缩信息、增强连贯性的用法"},{"title":"Reported Speech & Reporting Verbs","skills":["backshift_in_complex_reported_speech","reporting_verbs_with_varied_patterns_claim_argue_suggest","reporting_questions_and_imperatives","no_backshift_for_general_truths","academic_reporting_with_that_clauses"],"description":"C1级间接引语的时态回移、多样化报告动词及学术转述的书面规范"},{"title":"Gerunds, Infinitives & Complex Noun Phrases","skills":["gerund_vs_infinitive_meaning_difference","perfect_and_passive_infinitives","gerunds_as_subjects_in_formal_writing","complex_noun_phrase_with_gerund","verbs_taking_both_with_meaning_change","verb_patterns_doing_or_to_do","preposition_plus_doing"],"description":"C1级动名词与不定式的深层用法：主语位置、复合动词宾语及语义差异"},{"title":"Articles, Determiners & Quantifiers","skills":["generic_vs_specific_article_use","article_omission_in_abstract_nouns","advanced_quantifiers_the_majority_a_number_of","determiners_in_academic_noun_phrases","double_determiners_and_pre_determiners","countable_vs_uncountable_quantifiers"],"description":"C1级冠词的泛指与特指精确运用、限定词堆叠及高频量词的书面用法"},{"title":"Comparatives, Superlatives & Degree Structures","skills":["double_comparatives_the_more_the_more","comparative_clauses_with_ellipsis","superlatives_with_present_perfect","degree_adverbs_with_adjectives_and_nouns","as_as_constructions_with_inversion","superlatives_in_data_description"],"description":"C1级比较级与最高级的复杂结构：双重比较、平行比较及程度副词的书面搭配"},{"title":"Advanced Clause Connectors & Discourse Markers","skills":["concession_clauses_although_while_whereas","result_clauses_such_that_so_that","fronted_adverbial_clauses_for_cohesion","noun_clauses_as_subject_and_complement","cleft_sentences_for_emphasis_it_is_what"],"description":"C1级书面连接词精确运用：让步、原因、结果及对比连接词在段落中的语法搭配"},{"title":"Accuracy & Paraphrase in IELTS Writing","skills":["open_cloze_grammar_word_selection","word_formation_affixation_and_conversion","key_word_transformation_paraphrase","error_correction_in_written_text","integrated_grammar_accuracy_review"],"description":"雅思写作综合：改写题目写开头段、按位置用对词形、把常见复杂句写准写好（复习前 11 单元）"}],"unitsData":{"1":{"levels":{"1":[{"id":"gen-1-1-100","type":"choice","instruction":"〔口语 Part 2〕读句子，回答问题。原句：My hands were covered in paint because I had been decorating my bedroom all afternoon.","sentence":"Why were the speaker's hands covered in paint?","options":["The speaker was about to start decorating.","The speaker had finished decorating days before.","The speaker had spent the afternoon decorating.","The speaker was going to decorate the next day."],"correctIndex":2,"explanation":"had been decorating = 到那时为止一下午都在刷，手上的油漆就是这么来的。had been doing 常用来说明过去某个时候的样子（累、脏、湿）是怎么来的。","subSkill":"past_perfect_continuous_in_narrative"},{"id":"gen-1-1-101","type":"choice","instruction":"〔口语 Part 2〕读句子，回答问题。原句：By the time we arrived at the wedding, the couple had exchanged rings.","sentence":"Did the speaker see the couple exchange rings?","options":["Yes, the speaker got there just in time.","No, it was over before the speaker arrived.","Yes, it was happening as the speaker walked in.","No, the wedding was cancelled that day."],"correctIndex":1,"explanation":"had exchanged 发生在 we arrived 之前：他们到的时候，戒指已经换完了。By the time + 过去的事，后半句常用 had done。","subSkill":"mixed_tense_sequences"},{"id":"gen-1-1-102","type":"match","instruction":"〔口语 Part 2〕前半句都是 By the time the power went off（到停电的时候）。只看后半句：那件事当时已经做完，还是一直在做？","left":["…, I had baked two cakes.","…, I had been baking since lunchtime.","…, my brother had been playing video games for hours.","…, I had sent the email."],"right":["Finished by that time","Still going on up to that time"],"correctPairs":[[0,0],[1,1],[2,1],[3,0]],"explanation":"had baked two cakes、had sent 说的是那时已经完成的结果；had been baking、had been playing 说的是一直在进行的过程，停电时可能还没做完。","subSkill":"aspect_choice_for_emphasis"},{"id":"gen-1-1-103","type":"match","instruction":"〔口语 Part 1〕两句只差一处。说话人现在还住在厦门吗？连线。","left":["I lived in Xiamen for five years.","I've lived in Xiamen for five years."],"right":["The speaker has moved away.","The speaker still lives there."],"correctPairs":[[0,0],[1,1]],"explanation":"lived：那五年已经结束，现在不住了。have lived：五年一直延续到现在，还住在那里。考官问 Where do you live? 时用错，意思就反了。","subSkill":"present_perfect_vs_past_simple"},{"id":"gen-1-1-104","type":"choice","instruction":"〔口语 Part 3〕读句子，回答问题。原句：By the end of this decade, my city will have planted a million new trees.","sentence":"What will the situation be at the end of this decade?","options":["The planting will only just be starting.","The planting will still be going on.","The city will still be planning it.","All the trees will already be planted."],"correctIndex":3,"explanation":"will have planted = 到这个十年结束之前已经种完。如果想说那时还在一棵一棵地种，要用 will be planting。","subSkill":"future_perfect_vs_future_continuous"},{"id":"gen-1-1-105","type":"scenario","instruction":"读考生的回答，回答问题：What will the candidate's life be like this time next year?","context":"雅思口语 Part 1 · Work or studies","dialogue":[{"speaker":"examiner","text":"Examiner: What do you think you'll be doing this time next year?"},{"speaker":"player","text":"Hopefully I'll be working for a design company. By then, I'll have finished my degree."}],"options":["Working for a design company, with the degree finished.","Looking for work, with the degree not yet finished.","Interning at a design company, with the degree just started.","Still studying, with the degree almost finished."],"correctIndex":0,"explanation":"I'll be working = 那时正在上班（进行中）；I'll have finished = 在那之前已经读完。两种将来时各管一件事。","subSkill":"future_perfect_vs_future_continuous"},{"id":"gen-1-1-106","type":"match","instruction":"〔口语 Part 2〕三句只差一处。我到家时，晚饭是什么情况？连线。","left":["When I got home, my sister cooked dinner.","When I got home, my sister had cooked dinner.","When I got home, my sister was cooking dinner."],"right":["She started cooking after I got home.","Dinner was ready before I got home.","She was in the middle of cooking it."],"correctPairs":[[0,0],[1,1],[2,2]],"explanation":"cooked：我到了她才做（按顺序发生）。had cooked：我到之前就做好了。was cooking：我进门时她正做到一半。时态一变，事情的先后就变了。","subSkill":"mixed_tense_sequences"},{"id":"gen-1-1-107","type":"choice","instruction":"〔写作 Task 1〕读句子，回答问题。原句：The number of students taking French had been falling for a decade before it levelled off in 2015.","sentence":"What does the sentence say about the number of students taking French?","options":["It fell for ten years and then stopped falling.","It started falling in 2015 and is still falling.","It fell for ten years and kept falling after 2015.","It stayed about the same for ten years."],"correctIndex":0,"explanation":"had been falling for a decade before… = 到 2015 年为止，下降已经持续了十年；levelled off 说的是 2015 年开始趋于平稳。","subSkill":"tense_consistency_in_academic_writing"},{"id":"gen-1-1-108","type":"choice","instruction":"〔口语 Part 3〕读句子，回答问题。原句：Young people have been moving to big cities for decades, and many villages have been left almost empty.","sentence":"Are young people still moving to big cities?","options":["No, that stopped decades ago.","Yes, but it only began recently.","No, but it will happen soon.","Yes, it has gone on for decades."],"correctIndex":3,"explanation":"have been moving for decades = 从几十年前一直持续到现在，还在继续。have been left 说的是到现在的结果：很多村子已经快空了。","subSkill":"present_perfect_vs_past_simple"}],"2":[{"id":"gen-1-2-100","type":"fill","instruction":"〔口语 Part 1 · Studies〕想说「我学英语大约十年了，现在还在学」。","sentence":"I ___ English for about ten years.","hint":"一直学到现在","acceptableAnswers":["have been learning","have learned","have learnt","have been studying","have studied"],"explanation":"学了十年、现在还在学 → have been learning（have learned 也对）。am learning、learn 不能和 for + 一段时间连用；learned 说的是已经结束的十年。","subSkill":"present_perfect_vs_past_simple"},{"id":"gen-1-2-101","type":"choice","instruction":"〔口语 Part 2〕想说「我们到营地时，雨已经连着下了三天」。","sentence":"It ___ for three days when we arrived at the campsite, so everything was soaked.","options":["was raining","had been raining","has been raining","rains"],"correctIndex":1,"explanation":"下雨从三天前一直持续到「我们到达」这个过去时刻 → had been raining。has been raining 说的是到现在；was raining 不和「for 三天 + when…」连用。","subSkill":"past_perfect_continuous_in_narrative"},{"id":"gen-1-2-102","type":"choice","instruction":"〔口语 Part 2〕想说比赛之前，我们已经把这首曲子练了大约两百遍。","sentence":"By the day of the competition, we ___ the piece about two hundred times.","options":["had played","had been playing","have played","were playing"],"correctIndex":0,"explanation":"说的是次数（two hundred times）→ 已经完成的结果，用 had played。had been playing 说的是过程，不和具体次数连用；have played 说的是到现在。","subSkill":"aspect_choice_for_emphasis"},{"id":"gen-1-2-103","type":"choice","instruction":"〔口语 Part 3〕想说「在 2040 年之前，机器人就已经取代很多工厂岗位了」。","sentence":"By 2040, robots ___ many factory jobs.","options":["will replace","will be replacing","would have replaced","will have replaced"],"correctIndex":3,"explanation":"by 2040 是截止时间，说到那时已经取代 → will have replaced。will be replacing 是那时正在取代；will replace 没说出「在那之前已完成」。","subSkill":"future_perfect_vs_future_continuous"},{"id":"gen-1-2-104","type":"choice","instruction":"〔口语 Part 1 · Studies〕想说「明天这个时候，我正在考期末数学」。","sentence":"This time tomorrow, I ___ my final maths exam.","options":["will take","will be taking","will have taken","take"],"correctIndex":1,"explanation":"this time tomorrow 说的是那一刻正在进行 → will be taking。will have taken 是那时已经考完；will take 只说会考，没有「正在考」的意思。","subSkill":"future_perfect_vs_future_continuous"},{"id":"gen-1-2-105","type":"scenario","instruction":"考生想说「我们八岁就认识了，到现在还是好朋友」。选出准确的一句。","context":"雅思口语 Part 1 · Friends","dialogue":[{"speaker":"examiner","text":"Examiner: How long have you known your best friend?"}],"options":["I know her since we were eight.","I've been knowing her since we were eight.","I've known her since we were eight.","I knew her since we were eight."],"correctIndex":2,"explanation":"从八岁一直到现在 → 现在完成时；know 说的是状态，不用进行时 → I've known her。I know、I knew 都不能和 since 连用。","subSkill":"aspect_choice_for_emphasis"},{"id":"gen-1-2-106","type":"choice","instruction":"〔写作 Task 2〕想说「过去二十年里，独居的人一直在增加」。","sentence":"Over the past two decades, the number of people living alone ___ dramatically.","options":["have risen","had risen","has risen","is rising"],"correctIndex":2,"explanation":"over the past two decades 连到现在 → 现在完成时；the number 是单数 → has risen，不是 have risen。","subSkill":"tense_consistency_in_academic_writing"},{"id":"gen-1-2-107","type":"match","instruction":"〔写作 Task 1〕图表显示 2015 年到今年的电子书销量。三句只差时间说法，给每句配上合适的形式。","left":["Between 2015 and 2020, sales of e-books ___ steadily.","Since 2020, sales of e-books ___ steadily.","By 2020, sales of e-books ___ to three million."],"right":["rose","have risen","had risen"],"correctPairs":[[0,0],[1,1],[2,2]],"explanation":"2015–2020 已经结束 → rose；since 2020 一直连到今年 → have risen；by 2020 = 到那年为止已经达到 → had risen。时间说法一变，形式就跟着变。","subSkill":"tense_consistency_in_academic_writing"},{"id":"gen-1-2-108","type":"scenario","instruction":"考生想说「去过，去年夏天去的」。选出准确的回答。","context":"雅思口语 Part 1 · Music","dialogue":[{"speaker":"examiner","text":"Examiner: Have you ever been to a music festival?"}],"options":["Yes, I've been to one last summer.","Yes, I went to one last summer.","Yes, I had gone to one last summer.","Yes, I've gone to one last summer."],"correctIndex":1,"explanation":"有 last summer 这种已经结束的时间 → 一般过去时 went。考官用 Have you ever… 问，回答说出具体时间时要换成过去时。","subSkill":"present_perfect_vs_past_simple"}],"3":[{"id":"gen-1-3-100","type":"fill","instruction":"〔口语 Part 2〕把两句合成一句，说出这件事从 2021 年一直延续到现在。原句：I started volunteering at the animal shelter in 2021. I still volunteer there.","sentence":"I ___ at the animal shelter since 2021.","acceptableAnswers":["have been volunteering","have volunteered","have been working","have worked","have been helping out","have helped out","have been helping","have helped","have been a volunteer","have been doing volunteer work","have been working as a volunteer"],"explanation":"从 2021 年一直做到现在 → have been volunteering（have volunteered 也对）。现在时 volunteer / am volunteering 不能和 since 连用。","subSkill":"present_perfect_vs_past_simple"},{"id":"gen-1-3-101","type":"fill","instruction":"〔口语 Part 2〕合成一句，说出队长退出时，机器人已经做了三个月、还没做完。原句：We started building the robot in September. In December, our team leader suddenly quit.","sentence":"We ___ the robot for three months when our team leader suddenly quit.","acceptableAnswers":["had been building","had been working on","had been making","had been designing","had been developing","had been putting together","had been constructing","had been assembling"],"explanation":"造机器人从九月一直持续到十二月队长退出那一刻，而且还没做完 → had been building。写成 had built，会让人以为机器人已经造好了。","subSkill":"past_perfect_continuous_in_narrative"},{"id":"gen-1-3-102","type":"fill","instruction":"〔口语 Part 2〕合成一句，说出我到的时候电影早就开场了。原句：The film started at 7:30. I got to the cinema at eight.","sentence":"When I got to the cinema at eight, the film ___ (start).","acceptableAnswers":["had started","had already started","had started already","had begun","had already begun"],"explanation":"电影开场（7:30）比我到（8:00）早 → had started。写成 the film started，意思就成了「我一到，电影才开始」。","subSkill":"mixed_tense_sequences"},{"id":"gen-1-3-103","type":"reorder","instruction":"〔口语 Part 2〕排出这句：考过驾照之前，我已经练了好几个月。","words":["months","I","practising","had","driving","for","before","test.","been","I","my","passed"],"correctSentence":"I had been practising for months before I passed my driving test.","acceptableSentences":["Before I passed my driving test, I had been practising for months.","I had been practising driving for months before I passed my test.","Before I passed my test, I had been practising driving for months."],"explanation":"练车从几个月前一直持续到考过为止 → had been practising。考过（passed）是后发生的事，用一般过去时。","subSkill":"past_perfect_continuous_in_narrative"},{"id":"gen-1-3-104","type":"fill","instruction":"〔口语 Part 1 · Travel〕合成一句，说出三十岁以前就会完成的计划。原句：I plan to visit every province in China. I will finish before I turn thirty.","sentence":"By the time I turn thirty, I ___ every province in China.","acceptableAnswers":["will have visited","will have been to","will have travelled to","will have traveled to","will have seen","will probably have visited","will hopefully have visited","will already have visited","will have already visited","will likely have visited"],"explanation":"三十岁之前就会完成 → will have visited。by the time 后面说将来用一般现在时 turn，不用 will turn。","subSkill":"future_perfect_vs_future_continuous"},{"id":"gen-1-3-105","type":"fill","instruction":"〔口语 Part 1 · Holidays〕用括号里的动词，说出「下周一同事们上班的时候，我正躺在三亚的沙滩上」。","sentence":"While my colleagues are at work next Monday, I ___ (lie) on a beach in Sanya.","acceptableAnswers":["will be lying","will probably be lying","will hopefully be lying","should be lying","might be lying","may be lying","am going to be lying","could be lying"],"explanation":"同事上班的那段时间我正在做的事 → will be lying（lie 的 -ing 形式是 lying）。while 后面说将来用一般现在时 are。will lie 没有「正在」的画面。","subSkill":"future_perfect_vs_future_continuous"},{"id":"gen-1-3-106","type":"fill","instruction":"〔口语 Part 2〕合成一句，分清「一直在写」和「已经写完几章」。原句：I started writing my dissertation in March. Four chapters are finished now.","sentence":"I ___ my dissertation since March, and so far I ___ four chapters.","acceptableAnswers":["have been writing","have written"],"blankAnswers":[["have been writing","have been working on","have been doing","have been writing up"],["have written","have finished","have completed","have done","have drafted","have written up","have got through","have already written","have already finished","have already completed"]],"explanation":"写论文从三月一直在进行、还没写完 → have been writing；能数出来的结果（four chapters）→ have written / have finished。","subSkill":"aspect_choice_for_emphasis"},{"id":"gen-1-3-107","type":"fill","instruction":"〔写作 Task 1〕把两个年份的数据合成一句，说出到 2015 年为止的变化。原句：In 2005, there were 2 million international students. In 2015, there were 4 million.","sentence":"There were 2 million international students in 2005, but by 2015 the number ___ to 4 million.","acceptableAnswers":["had risen","had grown","had increased","had climbed","had doubled","had jumped","had gone up","had soared","had shot up","had surged","had already risen","had already doubled","had rocketed","had leapt","had leaped","had expanded","had already increased","had already grown"],"explanation":"by + 过去的年份 = 到那时为止已经完成的变化 → had risen。图表全是过去的数据，所以不用 has risen。","subSkill":"tense_consistency_in_academic_writing"},{"id":"gen-1-3-108","type":"reorder","instruction":"〔写作 Task 2〕排出这句：过去十年里，电动汽车普及多了。","words":["more","Over","have","decade,","the","electric","common.","much","become","past","cars"],"correctSentence":"Over the past decade, electric cars have become much more common.","acceptableSentences":["Electric cars have become much more common over the past decade.","Electric cars have, over the past decade, become much more common."],"explanation":"over the past decade 一直连到现在 → 现在完成时 have become。说 in 2015 这种已经结束的时间，才用 became。","subSkill":"tense_consistency_in_academic_writing"}],"4":[{"id":"gen-1-4-100","type":"error","instruction":"〔口语 Part 1 · 考生常见错误〕从我出生起，我家就住在这套公寓里，现在还住着。点出用错的部分。","words":["My family","lives","in this flat","since","I","was","born."],"errorIndex":1,"correction":"has lived","explanation":"从我出生一直住到现在 → has lived（has been living 也对）。lives 只说现在，不能和 since 连用。since I was born 里的 was 没错。","subSkill":"present_perfect_vs_past_simple"},{"id":"gen-1-4-101","type":"error","instruction":"〔口语 Part 1 · 考生常见错误〕点出用错的部分。","words":["I","have graduated","from high school","in 2022,","and then","I","moved","to Wuhan."],"errorIndex":1,"correction":"graduated","explanation":"in 2022 是已经结束的时间 → 一般过去时 graduated。现在完成时不能和 in 2022、last year、ago 这类过去时间连用。","subSkill":"present_perfect_vs_past_simple"},{"id":"gen-1-4-102","type":"fill","instruction":"〔口语 Part 2 · 考生常见错误〕讲的是去年的事，有两个动词用错了，在空里写出正确的形式。原句：Last summer I go to Yunnan with my cousins, and we stay in a small village for a week.","sentence":"Last summer I ___ to Yunnan with my cousins, and we ___ in a small village for a week.","acceptableAnswers":["went","stayed"],"blankAnswers":[["went","travelled","traveled","flew","headed","drove"],["stayed","lived"]],"explanation":"讲去年的经历，动词要一路用过去时：went、stayed。中文动词没有时态变化，口语一紧张就容易滑回现在时，考官会把它当作反复出现的错误。","subSkill":"mixed_tense_sequences"},{"id":"gen-1-4-103","type":"choice","instruction":"〔口语 Part 2 · 考生常见写法〕两件事的先后没说清，选出改对的后半句。原句：I had been working at the café for a year when the owner had decided to sell it.","sentence":"I had been working at the café for a year ___","options":["when the owner had decided to sell it.","when the owner has decided to sell it.","when the owner decided to sell it.","when the owner was deciding to sell it."],"correctIndex":2,"explanation":"老板决定卖店是后来的那一刻，用一般过去时 decided；had been working 已经交代了「在那之前一直在做」。两半句都用 had，反而分不出先后。","subSkill":"past_perfect_continuous_in_narrative"},{"id":"gen-1-4-104","type":"error","instruction":"〔写作 Task 2 · 考生常见错误〕点出用错的部分。","words":["In recent years,","the number of","people","working from home","increased","sharply,","and","this trend","is likely","to continue."],"errorIndex":4,"correction":"has increased","explanation":"in recent years 说的是一直连到现在的一段时间 → 现在完成时 has increased。主语是 the number（单数），用 has，不用 have。","subSkill":"present_perfect_vs_past_simple"},{"id":"gen-1-4-105","type":"error","instruction":"〔口语 Part 2 · 考生常见错误〕考生只是在讲上周末的一件事。点出用错的部分。","words":["Last weekend,","I","had gone","to a food festival","in Hangzhou","with some friends,","and","we","tried","dozens of","local dishes."],"errorIndex":2,"correction":"went","explanation":"只讲上周末这一件事，没有更晚的过去时刻作参照 → 一般过去时 went。had done 要放在另一件过去的事之前才用，不是「更正式的过去时」。","subSkill":"mixed_tense_sequences"},{"id":"gen-1-4-106","type":"choice","instruction":"〔口语 Part 1 · 考生常见写法〕想说「等我毕业时，已经做完两份实习了」，这句有两处问题，选出改对的句子。原句：By the time I will graduate, I will finish two internships.","options":["By the time I graduate, I will have finished two internships.","By the time I will graduate, I will have finished two internships.","By the time I graduate, I will finish two internships.","By the time I graduated, I will have finished two internships."],"correctIndex":0,"explanation":"by the time、when 引出的时间说将来，用一般现在时 graduate，不用 will；到那时已经完成 → will have finished。","subSkill":"future_perfect_vs_future_continuous"},{"id":"gen-1-4-107","type":"error","instruction":"〔写作 Task 1 · 考生常见错误〕图表的数据截至 2020 年。点出用错的部分。","words":["In 2010,","the figure","stood at 20%,","but","by 2020","it","has risen","to 45%."],"errorIndex":6,"correction":"had risen","explanation":"by 2020 是过去的时间点，到那时为止的变化 → had risen。has risen 要连到现在，和过去的图表数据对不上。","subSkill":"tense_consistency_in_academic_writing"},{"id":"gen-1-4-108","type":"fill","instruction":"〔写作 Task 2 · 考生常见错误〕有一处时态用错了，在空里写出正确的形式。原句：Ever since smartphones became popular, people's reading habits changed dramatically.","sentence":"Ever since smartphones became popular, people's reading habits ___ dramatically.","acceptableAnswers":["have changed","have been changing","have shifted","have altered","have evolved","have been transformed","have been shifting","have been evolving"],"explanation":"ever since 引出的时间一直延续到现在，主句要用现在完成时 have changed。ever since 后面的 became 是一个过去的时间点，用一般过去时没错。","subSkill":"present_perfect_vs_past_simple"},{"id":"gen-1-4-109","type":"fill","instruction":"〔口语 Part 2 · 考生常见错误〕讲的是上大学以前的事，有一处时态不对，在空里写出正确的形式。原句：Before I came to university, I have never cooked a meal by myself.","sentence":"Before I came to university, I ___ a meal by myself.","acceptableAnswers":["had never cooked","never cooked","had never made","never made","had never prepared","never prepared","had not cooked","hadn't cooked","had not made","had not prepared","had never even cooked","never even cooked"],"explanation":"上大学以前的经历，参照点在过去 → had never cooked（never cooked 也行）。have never cooked 说的是到现在为止，和 before I came… 对不上。","subSkill":"mixed_tense_sequences"}],"5":[{"id":"gen-1-5-100","type":"fill","instruction":"〔口语 Part 2〕把三句合成一句，说出「一直在学」和「去年考过」。原句：I started learning the piano when I was seven. I am still learning it. I passed Grade 8 last year.","sentence":"I ___ the piano since I was seven, and I ___ Grade 8 last year.","acceptableAnswers":["have been learning","passed"],"blankAnswers":[["have been learning","have learned","have learnt","have been playing","have played","have been studying","have studied","have been learning to play","have been practising","have been practicing"],["passed","got","achieved","finally passed","took and passed","completed"]],"explanation":"从七岁一直学到现在 → have been learning；考过八级是去年的事，时间已经结束 → passed。一句话里两种时间分开说清，听的人就知道哪件事还在继续、哪件已经结束。","subSkill":"present_perfect_vs_past_simple"},{"id":"gen-1-5-101","type":"fill","instruction":"〔口语 Part 2〕补全这段回答，用括号里的动词。先想清楚每件事和哪个时间点比。","sentence":"My first half-marathon didn't go to plan. I ___ (run) for about an hour when my knee started to hurt.\nBy the time I crossed the finish line, most of the other runners ___ (go) home.\nStill, I didn't give up, and I ___ (run) four more races since then.","acceptableAnswers":["had been running","had gone","have run"],"blankAnswers":[["had been running","had run"],["had gone","had already gone","had gone back"],["have run","have done","have completed","have finished"]],"explanation":"① 跑步一直持续到膝盖开始疼 → had been running。② 别人回家比我冲线早 → had gone。③ since then 一直到现在 → have run。","subSkill":"mixed_tense_sequences"},{"id":"gen-1-5-102","type":"scenario","instruction":"考生想说「排了快三个小时队，轮到我时票已经卖完了」。哪个回答把这层意思说准确了？","context":"雅思口语 Part 2 · 题卡：Describe a time when you had to wait for something … and explain how you felt","dialogue":[],"options":["I was queuing for nearly three hours, and when I got to the front, the tickets sold out.","I queued for nearly three hours, and when I got to the front, I bought the last two tickets.","I've been queuing for nearly three hours, and when I got to the front, the tickets had sold out.","I'd been queuing for nearly three hours, and when I got to the front, the tickets had sold out."],"correctIndex":3,"explanation":"第 4 个准确：排队持续到轮到我 → I'd been queuing；票在那之前卖完 → had sold out。第 1 个 sold out 成了「我到了前面，票才卖完」；第 2 个意思反了；第 3 个 I've been 说的是到现在。","subSkill":"past_perfect_continuous_in_narrative"},{"id":"gen-1-5-103","type":"fill","instruction":"〔口语 Part 3〕考官问：How will libraries change in the future? 用括号里的动词补全回答。","sentence":"I think libraries will still exist in twenty years, but by then most of them ___ (turn) into community spaces, and people ___ (use) them mainly to meet and study.","acceptableAnswers":["will have turned","will be using"],"blankAnswers":[["will have turned","will have been turned","will probably have turned","will already have turned","will have already turned"],["will be using","will use","will probably be using","might be using","may be using","are going to be using"]],"explanation":"① by then 之前已经完成的变化 → will have turned。② 那时人们正在怎么用 → will be using（will use 也行）。","subSkill":"future_perfect_vs_future_continuous"},{"id":"gen-1-5-104","type":"fill","instruction":"〔写作 Task 1〕补全这段图表描述，用括号里的动词。图表：某博物馆 2000–2020 年的参观人数，加 2030 年的预测。","sentence":"In 2000, the museum ___ (attract) about 50,000 visitors. The figure rose steadily, and by 2020 it ___ (reach) 200,000. By 2030, it ___ (rise) to over 300,000, according to the forecast.","acceptableAnswers":["attracted","had reached","will have risen"],"blankAnswers":[["attracted"],["had reached","had already reached"],["will have risen","will rise","will have grown","will have increased","will have climbed","will probably have risen","is expected to rise","is projected to rise","is predicted to rise","is likely to rise","is forecast to rise","is set to rise","will grow","will increase","will climb","will have gone up","will go up"]],"explanation":"① 2000 年是过去 → attracted。② by 2020 = 到那年为止 → had reached。③ by 2030 = 到那年为止 → will have risen（will rise 也行）。时态跟着图表上的时间走。","subSkill":"tense_consistency_in_academic_writing"},{"id":"gen-1-5-105","type":"fill","instruction":"〔口语 Part 2〕补全这段回答，用括号里的动词：第一次去日本时，日语已经学了两年；之后又去过三次。","sentence":"When I first went to Japan, I ___ (learn) Japanese for two years, so I could chat with people easily. I ___ (go) back three times since then.","acceptableAnswers":["had been learning","have been"],"explanation":"① 学日语一直持续到第一次去日本 → had been learning（had learned 也对）。② since then 连到现在 → have been（have gone 也行）。","subSkill":"past_perfect_continuous_in_narrative","blankAnswers":[["had been learning","had learned","had learnt","had been studying","had studied","had already been learning","had already been studying","had already learned","had already learnt","had already studied"],["have been","have gone","have travelled","have traveled","have flown"]]},{"id":"gen-1-5-106","type":"fill","instruction":"〔口语 Part 3〕考官问：How has the way people listen to music changed? 用括号里的动词补全回答。","sentence":"Ever since streaming apps appeared, most people ___ (stop) buying CDs. When my parents were young, they ___ (save) up for weeks to buy a single album.","acceptableAnswers":["have stopped","saved"],"blankAnswers":[["have stopped","have more or less stopped","have basically stopped","have pretty much stopped","have almost stopped","have completely stopped","have largely stopped","have mostly stopped","have all but stopped"],["saved","used to save","would save","had to save","often saved","would often save","used to have to save"]],"explanation":"① ever since + 过去的时间点，一直到现在 → have stopped。② 父母年轻时，时间已结束 → saved（used to save 也行）。Part 3 常这样拿现在和过去对比。","subSkill":"present_perfect_vs_past_simple"},{"id":"gen-1-5-107","type":"fill","instruction":"〔口语 Part 1 · Work or studies〕考官问：Do you plan to stay in your current job? 用括号里的动词补全回答。","sentence":"Probably not for long. By next summer, I ___ (work) here for five years, and a year from now, I hope I ___ (study) for a master's in Australia.","acceptableAnswers":["will have been working","will be studying"],"blankAnswers":[["will have been working","will have worked"],["will be studying","am studying","am going to be studying"]],"explanation":"① 到明年夏天为止已经持续五年 → will have been working（will have worked 也对）。② 一年以后的那段时间正在读书 → will be studying。","subSkill":"future_perfect_vs_future_continuous"},{"id":"gen-1-5-108","type":"fill","instruction":"〔口语 Part 2 · 结束追问〕题卡：Describe a time you worked in a team。考官：Do you still keep in touch with your teammates? 用括号里的动词补全回答。","sentence":"Yes, I ___ (meet) two of them for dinner last month, and we ___ (plan) a new project together ever since.","acceptableAnswers":["met","have been planning"],"blankAnswers":[["met","met up with","met with"],["have been planning"]],"explanation":"last month 是已经结束的时间 → met；从那以后一直在计划，到现在还没完 → have been planning。","subSkill":"mixed_tense_sequences"}]},"mission":{"title":"写作 Task 2 段落：从前、现在和将来","description":"写一个雅思 Task 2 主体段（3 句）：先说这个变化的一个原因，再拿过去作对比，最后说说这是好是坏、预测将来（写法自选）。至少用对本单元的 2 种时态搭配，不必每句都用复杂时态。AI 老师会按雅思「语法多样性与准确性」给你反馈。","scenario":"题目：In many countries, fewer and fewer young people know how to cook. Why has this happened? Is it a positive or negative development?<br>你只写正文里的一段。用你的家乡或家人举例，说说做饭这件事几十年来的变化。","grammarType":"mixed_tense_sequences","scaffolds":[{"prefix":"Young people's relationship with cooking has changed enormously.","suffix":"","hint":"说一个原因（如外卖 App）：Since … , … have (been) …","grammarCheck":"present_perfect_vs_past_simple","example":"Since food delivery apps became widespread, many students in my city have stopped cooking for themselves altogether."},{"prefix":"The contrast with my grandparents' generation is striking.","suffix":"","hint":"拿过去作对比：By the age of …, they had … ，或者用一般过去时讲那个已经结束的年代。","grammarCheck":"mixed_tense_sequences","example":"By the age of twelve, my grandmother had learned to cook for a family of six, whereas I could barely boil an egg when I left home."},{"prefix":"In my view, this trend is more negative than positive.","suffix":"","hint":"说出为什么不好，并预测将来（结构自选）：可以用 By 2040, … will have …，也可以用 … will be …ing，或者干脆用一般将来时。","grammarCheck":"future_perfect_vs_future_continuous","example":"Young adults who cannot cook tend to eat less healthily, and by 2040 a whole generation will have grown up relying almost entirely on takeaways."}]},"discover":{"story":{"title":"口语 Part 2–3 范例回答：一个让我骄傲的项目","text":"读的时候想一想：哪些事先发生、哪些后发生？哪些一直延续到今天？蓝色的句子下面会逐句问你。\nPart 2 cue card: Describe a project you worked on that you are proud of. You should say: what the project was, who you worked with, what problems you had, and explain why you are proud of it.\nI'd like to talk about a short documentary I made with four classmates in my second year at university. It was about an old street market near our campus that was going to be knocked down. We had been interviewing the stall owners for about two months when the university suddenly cut our funding, and to be honest, I nearly gave up.\nThings got worse before they got better. By the time we found a new sponsor, a little bookshop in the market, two of the five members had left the team, so the three of us did all the filming and editing ourselves. We finished the night before the deadline, and the film won second prize in a city competition. I'm proud of it mainly because it taught me not to give up. I've made two more short films since then, and for the past few months I've been making a third one, about my grandmother's village.\n(Part 3) Examiner: Do you think traditional markets will survive? Candidate: Honestly, I doubt it. By 2035, I think most of them will have disappeared, and people will be doing almost all their shopping online.","highlights":["had been interviewing the stall owners","cut our funding","found a new sponsor","had left the team","I've made two more short films since then","I've been making a third one","will have disappeared","will be doing"]},"questions":[{"question":"第一段：<em>We had been interviewing the stall owners for about two months when the university suddenly cut our funding.</em><br>When the funding was cut, had they finished the interviews?","options":["No, they were still doing them.","No, they had only just started.","Yes, they had finished them by then."],"correctIndex":0,"nudge":"看 had been interviewing 里的 -ing，再看后面的 for about two months：说的是一个已经做完的结果，还是一段一直在进行的过程？","explanation":"还没做完：采访已经做了约两个月，经费被砍时还在做。<br><strong>规则 ①</strong>：had been doing + 一段时间 + when… = 到过去某一刻为止一直在做，强调持续了多久（这里当时还没做完）。","subSkill":"past_perfect_continuous_in_narrative"},{"question":"第二段：<em>By the time we found a new sponsor, two of the five members had left the team.</em><br>When they found the new sponsor, were those two members still in the team?","options":["Yes, but they left soon after.","Yes, and they stayed to the end.","No, they had gone before that."],"correctIndex":2,"nudge":"句子里有两件事：找到赞助（found）和组员退出（had left）。哪一件用了 had + 过去分词？它发生得更早还是更晚？","explanation":"找到赞助之前，他们就已经退出了。<br><strong>规则 ②</strong>：had done = 比另一件过去的事更早。按先后顺序讲的事（We finished… and the film won…）用一般过去时就够，不必加 had。","subSkill":"mixed_tense_sequences"},{"question":"第二段这半句去掉 since then，比较两种写法：<br>A. I <em>made</em> two more short films.<br>B. I<em>'ve made</em> two more short films.<br>Which one is about the time up to <strong>now</strong>?","options":["A","B","Both of them"],"correctIndex":1,"nudge":"两句只差 made 和 've made。原文这半句后面还有 since then（从那时起一直到现在）：哪个形式能和它放在一起？","explanation":"B。've made 把这段时间连到现在，以后还可能再拍；made 说的是已经结束的一段时间。<br><strong>规则 ③</strong>：since / for 连到现在 → have done / have been doing；时间已结束 → 一般过去时。","subSkill":"present_perfect_vs_past_simple"},{"question":"第二段：<em>…and for the past few months I've been making a third one, about my grandmother's village.</em><br>Has the candidate finished the third film?","options":["Yes, a few months ago.","No, it's still in progress.","No, it hasn't been started."],"correctIndex":1,"nudge":"比较 've made two more short films 和 've been making a third one：哪个能数出「拍完了几部」，哪个说的是一直在做的事？","explanation":"还没拍完：'ve been making 是这几个月一直在拍的过程；'ve made two 才是拍完、能数出来的结果。<br><strong>规则 ④</strong>：have done + 数量 = 完成的结果；have been doing = 过程，可能还没完。","subSkill":"aspect_choice_for_emphasis"},{"question":"第三段：<em>By 2035, I think most of them will have disappeared, and people will be doing almost all their shopping online.</em><br>In 2035, will most markets still be there? Will people be shopping online?","options":["No, they won't. Yes, they will.","Yes, they will. Yes, they will.","Yes, they will. No, they won't."],"correctIndex":0,"nudge":"By 2035 是一个截止时间。分开看两半句：will have disappeared 和 will be doing，哪个是那一年之前就完成的事，哪个是那一年正在进行的事？","explanation":"到 2035 年之前，大多数市场已经消失；那时人们正在网上购物。<br><strong>规则 ⑤</strong>：by + 将来时间 → will have done（到那时已完成）；那时正在做 → will be doing。","subSkill":"future_perfect_vs_future_continuous"},{"question":"你来试试：<br>Facts: we started climbing at noon. The sun went down at 5:30. We reached the top at 6:00.<br>Which sentence describes this correctly?","options":["When we reached the top, we have been climbing for six hours and the sun had set.","When we reached the top, we had been climbing for six hours and the sun set.","When we reached the top, we had been climbing for six hours and the sun had set."],"correctIndex":2,"nudge":"先想两件事和「到达山顶」的关系：爬山是一直持续到那一刻，还是早就结束了？太阳是那时才落，还是早就落了？再用规则 ① 和 ②。","explanation":"爬山一直持续到登顶 → had been climbing（规则 ①）；日落比登顶早 → had set（规则 ②）。the sun set 意思是「我们一到，太阳才落」；have been 说的是到现在。","subSkill":"past_perfect_continuous_in_narrative"}],"tip":"【先画时间线，再选时态】\n\n① had been doing + 一段时间 + when… → 到过去某一刻为止一直在做（常常还没做完）\n② had done → 比另一件过去的事（或 by + 过去年份）更早；按顺序讲的事用一般过去时\n③ since / for / in recent years 连到现在 → have done / have been doing；时间已结束 → 一般过去时\n④ have done + 数量 → 做完了的结果；have been doing → 过程，可能还没完\n⑤ by + 将来时间 → will have done；那时正在做 → will be doing；by the time / when 后说将来用现在时\n⑥ 讲过去的经历一路用过去时；现在仍成立的事才用现在时\n⑦ know、own、have（拥有）说的是状态，不用进行时\n\n【例句】\n✔ We had been interviewing stall owners for two months when the university cut our funding.\n✔ By 2030, I'll have finished my degree, and I'll be working in Shenzhen.\n\n【常见错误】\n✘ I **live** in Shanghai since 2019. → have lived / have been living（见 ③）\n✘ I **have graduated** from high school in 2022. → graduated（见 ③）\n✘ Last summer I **go** to Yunnan and we **stay** in a village. → went / stayed（见 ⑥）\n✘ By the time I **will graduate**, … → By the time I graduate（见 ⑤）\n✘ I **have been knowing** him since childhood. → have known（见 ⑦）"}},"2":{"levels":{"1":[{"id":"gen-2-1-100","type":"choice","instruction":"〔口语 Part 2 · Describe a time you lost something〕我很肯定：钱包是落在车上了。空格填哪个？","sentence":"I definitely had my wallet when I got on, so I ___ it on the bus.","options":["must leave","should have left","must have left","might leave"],"correctIndex":2,"explanation":"落在车上是过去的事，又很肯定 → must have left。must leave 是「必须留下」；should have left 是「本该留下」；might leave 说的是将来。","subSkill":"modal_perfect_for_past_deduction"},{"id":"gen-2-1-101","type":"choice","instruction":"〔写作 Task 2〕读句子，回答问题。原句：High rents might partly explain why so many young adults still live with their parents.","sentence":"Is the writer certain that high rents are the reason?","options":["Yes, they are the only reason.","No, they are possibly one reason.","No, rents have nothing to do with it.","Yes, but only in the past."],"correctIndex":1,"explanation":"might = 有可能，作者没把话说死；partly 再退一步：只是原因之一。没有确凿证据的因果，这样写更稳妥。","subSkill":"modals_for_academic_hedging"},{"id":"gen-2-1-102","type":"match","instruction":"〔口语 Part 3 · Work and education〕这几句里的 must / can't，是说话人的推断，还是一条规定？连线。","left":["Nurses often work twelve-hour shifts, so they must be exhausted.","In most hospitals, nurses must wear a uniform at all times.","Most new graduates have only just started work, so they can't be very experienced yet.","In many schools, students can't use their phones during lessons."],"right":["The speaker is drawing a conclusion","The speaker is stating a rule"],"correctPairs":[[0,0],[1,1],[2,0],[3,1]],"explanation":"根据线索下结论（so they must be…、so they can't be…）是推断；告诉别人能做什么、不能做什么是规定。同一个 must / can't，意思要看上下文。","subSkill":"epistemic_modals_must_should_may"},{"id":"gen-2-1-103","type":"choice","instruction":"〔写作 Task 2〕读句子，回答问题。原句：The sharp fall in bee numbers may have been caused by a new type of pesticide.","sentence":"Which statement matches what the writer says?","options":["A new pesticide definitely caused the fall.","A new pesticide will cause a fall in future.","A new pesticide cannot have caused the fall.","A new pesticide possibly caused the fall."],"correctIndex":3,"explanation":"may = 有可能；have been caused 说的是已经发生的事。作者只是推测农药是原因，没有说死，也没有排除。","subSkill":"modal_perfect_for_past_deduction"},{"id":"gen-2-1-104","type":"choice","instruction":"〔写作 Task 2〕读句子，回答问题。原句：Robots are likely to replace many factory jobs, but they are unlikely to replace teachers.","sentence":"What does the writer predict?","options":["Factory workers will probably be replaced; teachers probably won't.","Teachers will probably be replaced; factory workers probably won't.","Both groups will definitely be replaced in the future.","Neither group is at all likely to be replaced."],"correctIndex":0,"explanation":"be likely to = 很可能会；be unlikely to = 不太可能会。作者两边都没说死，只是判断哪边的可能性大：工厂岗位很可能被取代，教师多半不会。","subSkill":"semi_modals_be_bound_to_be_likely_to"},{"id":"gen-2-1-105","type":"scenario","instruction":"读考生的回答，回答问题：What does the candidate say about jobs?","context":"雅思口语 Part 1 · Hometown","dialogue":[{"speaker":"examiner","text":"Examiner: Has your hometown changed much in recent years?"},{"speaker":"player","text":"Quite a lot. They've built a huge shopping centre where the old market used to be. The market traders can't have been happy about it, but it must have created lots of new jobs."}],"options":["It may create a few jobs in the future.","It definitely created lots of new jobs.","It was expected to create jobs but failed.","It is impossible that it created any jobs."],"correctIndex":1,"explanation":"must have created = 推断过去一定是这样：新商场肯定带来了很多工作。前面的 can't have been happy 也是推断：商户不可能高兴。","subSkill":"modal_perfect_for_past_deduction"},{"id":"gen-2-1-106","type":"choice","instruction":"〔口语 Part 2 · Describe a time you were disappointed〕读句子，回答问题。原句：We should have booked the concert tickets earlier.","sentence":"Did the speaker book the tickets early?","options":["Yes, and it all went smoothly.","Yes, the speaker is certain of it.","No, and the speaker regrets it.","Perhaps, but the speaker isn't sure."],"correctIndex":2,"explanation":"should have booked = 本该订却没订，带着后悔，不是推测（推测要用 must / may have done）。","subSkill":"contrast_between_similar_modals"},{"id":"gen-2-1-107","type":"choice","instruction":"〔写作 Task 2〕读句子，回答问题。原句：The claim that violent video games make players aggressive may not be entirely accurate.","sentence":"What is the writer's view of the claim?","options":["It is completely true in all cases.","It is certainly false in every way.","The writer gives no opinion on it.","It may be only partly true."],"correctIndex":3,"explanation":"may not be entirely accurate = 可能不完全对。作者在表示怀疑，但说得很委婉；要说「绝对错」，会写 cannot be true。","subSkill":"modals_for_academic_hedging"},{"id":"gen-2-1-108","type":"match","instruction":"〔写作 Task 2〕作者对「明年食品涨价」有多大把握？连线。","left":["Food prices are bound to rise next year.","Food prices are likely to rise next year.","Food prices may rise next year.","Food prices are unlikely to rise next year."],"right":["They will probably rise","They probably won't rise","They will almost certainly rise","They might or might not rise"],"correctPairs":[[0,2],[1,0],[2,3],[3,1]],"explanation":"is bound to 最强（几乎一定），is likely to 次之，may 只是有可能，is unlikely to 是多半不会。写作时按证据选强度。","subSkill":"semi_modals_be_bound_to_be_likely_to"}],"2":[{"id":"gen-2-2-100","type":"choice","instruction":"〔写作 Task 2〕想说：过去二十年里，网购可能已经让许多小店关了门。","sentence":"The rise of online shopping ___ many small shops to close over the past twenty years.","options":["may cause","may have caused","must have caused","has caused"],"correctIndex":1,"explanation":"过去二十年里已经发生 → have caused；只是推测 → may。must have caused 太肯定；has caused 把推测说成了事实；may cause 时间不对。","subSkill":"modal_perfect_for_past_deduction"},{"id":"gen-2-2-101","type":"choice","instruction":"〔写作 Task 2〕研究才刚开始，作者不想把话说死。","sentence":"Early research suggests that green spaces in cities ___ reduce stress levels.","options":["might","will","must","are bound to"],"correctIndex":0,"explanation":"研究刚开始，证据不足 → might（may、could 也行）。will 和 are bound to 都说成了一定会；must 是很有把握的推断。","subSkill":"modals_for_academic_hedging"},{"id":"gen-2-2-102","type":"match","instruction":"〔口语 Part 2〕两句只差一个词。说话人的意思有什么不同？连线。","left":["He must have told his boss about the mistake.","He should have told his boss about the mistake."],"right":["I'm sure he told his boss.","It was wrong of him not to tell."],"correctPairs":[[0,0],[1,1]],"explanation":"must have told 是有把握的推断：他说了。should have told 是批评或遗憾：本该说，却没说。中文都可能说成「应该」，意思却相反。","subSkill":"contrast_between_similar_modals"},{"id":"gen-2-2-103","type":"choice","instruction":"〔写作 Task 2〕想说「常吃快餐的人更可能超重」。空格填哪个？","options":["are more possible to become","more likely to become","are more likely becoming","are more likely to become"],"correctIndex":3,"explanation":"be likely to do，人、事都能作主语。possible 不能这样接 to do（可以说 It is possible that…）；第 2 项少了 are；第 3 项 likely 后面要接 to do。","subSkill":"semi_modals_be_bound_to_be_likely_to","sentence":"People who eat fast food regularly ___ overweight."},{"id":"gen-2-2-104","type":"choice","instruction":"〔写作 Task 2〕想说「网上的评论不可能都是真的」。","sentence":"Online reviews ___ all be genuine; some companies pay people to write them.","options":["shouldn't","may not","needn't","can't"],"correctIndex":3,"explanation":"不可能 → can't。may not 只是「也许不是」，把握没那么大；shouldn't 是「不应该」；needn't 是「不必」。","subSkill":"epistemic_modals_must_should_may"},{"id":"gen-2-2-105","type":"choice","instruction":"〔口语 Part 2〕讲一次误会：想说「那封邮件不可能是他发的，他那天根本上不了网」。","sentence":"He ___ that email — he had no internet access that day.","options":["mustn't send","can't have sent","shouldn't have sent","may not send"],"correctIndex":1,"explanation":"不可能 + 过去的事 → can't have sent。shouldn't have sent 是「本不该发（却发了）」；mustn't send 是「不准发」；may not send 说的是将来。","subSkill":"modal_perfect_for_past_deduction"},{"id":"gen-2-2-106","type":"choice","instruction":"〔写作 Task 2〕想说：人口老龄化这么快，医疗开支几乎一定会上升。","sentence":"With the population ageing so quickly, healthcare spending ___ rise.","options":["may","could","is bound to","is unlikely to"],"correctIndex":2,"explanation":"几乎一定 → is bound to（也可以用 will）。may、could 只是有可能，语气太弱；is unlikely to 意思相反。","subSkill":"semi_modals_be_bound_to_be_likely_to"},{"id":"gen-2-2-107","type":"choice","instruction":"〔写作 Task 2〕想说：按理说新规定会减少食物浪费，但效果还要看执行。","sentence":"In theory, the new rules ___ reduce food waste, but much depends on how they are enforced.","options":["must","are bound to","can't","should"],"correctIndex":3,"explanation":"按理会、但不保证 → should（表示预期，贴士 ⑥），不是「应该去做」。must、are bound to 太肯定，和后半句 much depends 冲突；can't 意思相反。","subSkill":"epistemic_modals_must_should_may"},{"id":"gen-2-2-108","type":"scenario","instruction":"考生想说「可能是因为大家现在用手机看新闻吧」。选出意思准确的一句。","context":"雅思口语 Part 3 · News","dialogue":[{"speaker":"examiner","text":"Examiner: Why do you think fewer people watch the news on TV these days?"}],"options":["It must be because people read the news on their phones.","It might be because people read the news on their phones.","It should be because people read the news on their phones.","It can be because people read the news on their phones."],"correctIndex":1,"explanation":"「可能是因为」→ might / may / could be because。must 是「肯定是」；should 只表示「按理会」（贴士 ⑥），不用来猜原因；猜某个具体原因也不用 can。","subSkill":"contrast_between_similar_modals"}],"3":[{"id":"gen-2-3-100","type":"fill","instruction":"〔写作 Task 2〕这句说得太绝对，改得谨慎一些。原句：Increased urbanisation causes a rise in mental health problems among young adults.","sentence":"Increased urbanisation ___ a rise in mental health problems among young adults.","acceptableAnswers":["may cause","might cause","could cause","can cause","may lead to","might lead to","could lead to","can lead to","may contribute to","might contribute to","could contribute to","can contribute to","may result in","might result in","could result in","can result in","is likely to cause","is likely to lead to","is likely to contribute to","may well cause","may well lead to","may well contribute to","may be causing","might be causing","could be causing","may be contributing to","might be contributing to","could be contributing to","may be linked to","might be linked to","could be linked to","may be associated with","might be associated with","could be associated with","may have caused","might have caused","could have caused","may have led to","might have led to","could have led to","may have contributed to","might have contributed to","could have contributed to","is linked to","has been linked to","is associated with","appears to cause","seems to cause","tends to cause","probably causes","often causes","may partly cause","may be responsible for","might be responsible for","could be responsible for","might well cause","could well cause","might well lead to","could well lead to","may well result in","is likely to result in","may give rise to","might give rise to","could give rise to","may be leading to","might be leading to","could be leading to","may be partly responsible for","is thought to cause","is believed to cause","possibly causes","may possibly cause","could potentially cause","may potentially cause","seems to lead to","appears to lead to","may be a factor in","might be a factor in","could be a factor in","may be a cause of","could be a cause of"],"explanation":"加 may / might / could（或 is likely to），说「可能导致」，不说「一定导致」。没有确凿证据的因果，这样写更像学术论证。","subSkill":"modals_for_academic_hedging"},{"id":"gen-2-3-101","type":"fill","instruction":"〔口语 Part 1 · Mobile phones〕考官问：Do you use your phone a lot? 用 must 把两句合成一句推断。原句：My battery was full this morning and it's already dead. I'm sure some app has been running in the background all day.","sentence":"My battery was full this morning and it's already dead, so an app ___ in the background all day.","acceptableAnswers":["must have been running","must have run","must have been working","must have been active","must have kept running","must have been draining it","must have been using power","must've been running","must've run"],"explanation":"根据电量推断已经发生的事，而且很有把握 → must have been running（一直在运行）。只写 must run，说的就成了现在或「必须运行」。","subSkill":"modal_perfect_for_past_deduction"},{"id":"gen-2-3-102","type":"fill","instruction":"〔写作 Task 2 · 举例〕工厂早就关了，不可能是它。改写原句，意思不变。原句：It is impossible that the factory polluted the river last year, because it had closed in 2015.","sentence":"The factory ___ the river last year, because it had closed in 2015.","acceptableAnswers":["can't have polluted","couldn't have polluted","can't have been polluting","couldn't have been polluting","can't have contaminated","couldn't have contaminated","can't possibly have polluted","couldn't possibly have polluted","cannot possibly have polluted"],"explanation":"「不可能」+ 过去的事 → can't / couldn't have polluted。工厂 2015 年就关了，这是有证据的推断；may not have polluted 只是「可能没有」，太弱。","subSkill":"modal_perfect_for_past_deduction"},{"id":"gen-2-3-103","type":"fill","instruction":"〔写作 Task 2〕用 be likely to 改写，意思不变。原句：It is probable that the number of people working from home will continue to grow.","sentence":"The number of people working from home ___ to grow.","acceptableAnswers":["is likely to continue","is very likely to continue","is highly likely to continue","will probably continue","will likely continue","is expected to continue","is probably going to continue","looks likely to continue","seems likely to continue","appears likely to continue","will most likely continue","is most likely to continue"],"explanation":"It is probable that … will … → 事物做主语 + is likely to do。主语是 the number，所以用 is，不用 are。","subSkill":"semi_modals_be_bound_to_be_likely_to"},{"id":"gen-2-3-104","type":"fill","instruction":"〔写作 Task 2〕用 be likely to 改写，意思不变。原句：It is likely that there will be a serious shortage of nurses in rural areas.","sentence":"There ___ a serious shortage of nurses in rural areas.","acceptableAnswers":["is likely to be","is very likely to be","is highly likely to be","will probably be","will likely be","is expected to be","may well be","is probably going to be"],"explanation":"It is likely that there will be … → There is likely to be …。「将来很可能有」要说 there is likely to be，不能写 there is likely to have。","subSkill":"semi_modals_be_bound_to_be_likely_to"},{"id":"gen-2-3-105","type":"fill","instruction":"〔写作 Task 2〕作者批评政府当年没做好。把两句合成一句。原句：The government did not protect the old buildings in the city centre. That was a mistake.","sentence":"The government ___ the old buildings in the city centre.","acceptableAnswers":["should have protected","ought to have protected","should have preserved","ought to have preserved","should have saved","ought to have saved","should have conserved","should have done more to protect","ought to have done more to protect","should have done more to preserve","should have done more to save","ought to have done more to preserve","ought to have done more to save","should have taken better care of","should have looked after","should have tried to protect"],"explanation":"批评过去没做的事 → should have done（本该做，却没做）。must have protected 是推断「一定保护了」，意思正好相反。","subSkill":"contrast_between_similar_modals"},{"id":"gen-2-3-106","type":"fill","instruction":"〔写作 Task 2 · 建议段〕这条预测说得太满，改成留有余地的说法。原句：A four-day working week will improve employees' health.","sentence":"A four-day working week ___ employees' health.","acceptableAnswers":["could improve","may improve","might improve","is likely to improve","can improve","should improve","could well improve","may well improve","might well improve","will probably improve","would probably improve","will likely improve","is expected to improve","could help to improve","may help to improve","might help to improve","would help to improve","is likely to help improve","could help improve","may help improve","might help improve","would help improve","could benefit","may benefit","might benefit","is likely to benefit","could be good for","may be good for","might be good for","is likely to be good for","could potentially improve","may potentially improve","could boost","may boost","might boost","is likely to boost","could enhance","may enhance","will probably benefit","could well benefit","may well benefit","could have a positive effect on","may have a positive effect on","might have a positive effect on","is likely to have a positive effect on","could have a positive impact on","may have a positive impact on","might have a positive impact on","is likely to have a positive impact on","could be beneficial for","may be beneficial for","might be beneficial for","is likely to be beneficial for","could be beneficial to","may be beneficial to"],"explanation":"will 等于说一定会。改成 could / may / is likely to improve，承认证据还不够。建议段这样写，论证更稳。","subSkill":"modals_for_academic_hedging"},{"id":"gen-2-3-107","type":"fill","instruction":"〔写作 Task 2〕把两句合成一句，说出一个「可能的」过去原因。原句：Crime fell sharply in the 2000s. Perhaps better street lighting played a part in this.","sentence":"Better street lighting ___ (play a part) in the sharp fall in crime in the 2000s.","acceptableAnswers":["may have played a part","might have played a part","could have played a part","may have played a role","might have played a role","could have played a role","may also have played a part","might also have played a part","could also have played a part","may also have played a role","might also have played a role","could also have played a role","may well have played a part","might well have played a part","could well have played a part","may well have played a role","might well have played a role","could well have played a role","may have played an important role","might have played an important role","could have played an important role","may have played a key role","might have played a key role","could have played a key role","may have played a significant role","may have played a major role","may have played some part","probably played a part","probably played a role","is likely to have played a part","is likely to have played a role","may have been a factor","might have been a factor","could have been a factor","may have been a contributing factor","might have been a contributing factor","could have been a contributing factor","may have been one factor","might have been one factor","could have been one factor","may have been one of the factors","may have been a key factor","may have been an important factor","might have played a significant role","could have played a significant role","might have played a major role","could have played a major role","may have played an important part","might have played an important part","could have played an important part","may have played a crucial role","may have played a vital role","may have played a big part","perhaps played a part","perhaps played a role","possibly played a part","possibly played a role","may've played a part","might've played a part","could've played a part","may've played a role","might've played a role","could've played a role"],"explanation":"Perhaps + 过去 → may / might / could have played a part（可能起了作用）。这是推测，不能写 must have；也不能写 may play，时间不对。","subSkill":"modal_perfect_for_past_deduction"},{"id":"gen-2-3-108","type":"reorder","instruction":"〔写作 Task 2〕排出这句：青年失业问题短期内不太可能消失。","words":["in","unlikely","Youth","to","near","is","unemployment","disappear","the","future."],"correctSentence":"Youth unemployment is unlikely to disappear in the near future.","explanation":"be unlikely to do = 不太可能会。比 will not disappear 留有余地，又比 may not disappear 更有判断。in the near future = 短期内。","subSkill":"semi_modals_be_bound_to_be_likely_to","acceptableSentences":["In the near future, youth unemployment is unlikely to disappear."]}],"4":[{"id":"gen-2-4-100","type":"error","instruction":"〔写作 Task 2 · 考生常见错误〕点出用错的部分。","words":["Too much screen time","may","causes","sleep problems","in young children."],"errorIndex":2,"correction":"cause","explanation":"情态动词后面一律用原形：may cause，主语是单数也不加 -s。句子一长，这种基础错误最容易顺手写出来。","subSkill":"modals_for_academic_hedging"},{"id":"gen-2-4-101","type":"error","instruction":"〔写作 Task 2 · 考生常见错误〕点出用错的部分。","words":["This","maybe","the main reason","why","so many people","feel stressed","at work."],"errorIndex":1,"correction":"may be","explanation":"maybe 是副词（也许），句子里缺了动词。这里要写 may be；或者改成 Maybe this is the main reason…。","subSkill":"epistemic_modals_must_should_may"},{"id":"gen-2-4-102","type":"fill","instruction":"〔写作 Task 2 · 考生常见错误〕想说「打工时间长的学生更可能跟不上学业」。在空里写出正确的说法。原句：Students who work long hours in part-time jobs are more possible to fall behind in their studies.","sentence":"Students who work long hours in part-time jobs are more ___ fall behind in their studies.","acceptableAnswers":["likely to","liable to","prone to","apt to"],"explanation":"possible 不能这样用：不说 sb / sth is possible to do。要说 be (more) likely to do，或者换成 It is possible that…。","subSkill":"semi_modals_be_bound_to_be_likely_to"},{"id":"gen-2-4-103","type":"error","instruction":"〔口语 Part 2 · 考生常见错误〕讲一座 600 年前的古建筑。点出用错的部分。","words":["Without","modern machines,","the workers","must use","hundreds of horses","to move","the stones."],"errorIndex":3,"correction":"must have used","explanation":"推测的是几百年前的事 → must have used。must use 说的是现在，或者「必须用」，放在古建筑的故事里时间就错了。","subSkill":"modal_perfect_for_past_deduction"},{"id":"gen-2-4-104","type":"error","instruction":"〔口语 Part 2 · 考生常见错误〕没人开门，他很肯定朋友已经出门了。点出用错的部分。","words":["Nobody","answered","the door,","so","my friend","should have gone","out for the evening."],"errorIndex":5,"correction":"must have gone","explanation":"根据证据（没人开门）推断，很肯定 → must have gone。should have gone 是「本该出门」或「按理应该已经出门」，不是根据证据下结论。中文都说「应该」，英文要分开。","subSkill":"contrast_between_similar_modals"},{"id":"gen-2-4-105","type":"fill","instruction":"〔写作 Task 2 · 考生常见错误〕想说「这场洪水可能是暴雨引起的」。原句有错，在空里写出正确的形式。原句：The flood may have caused by heavy rain.","sentence":"The flood ___ by heavy rain.","acceptableAnswers":["may have been caused","might have been caused","could have been caused","was probably caused","may well have been caused","might well have been caused","could well have been caused"],"explanation":"洪水是「被引起」的，要用被动：may have been caused。少了 been，句子就成了「洪水引起了…」。","subSkill":"modal_perfect_for_past_deduction"},{"id":"gen-2-4-106","type":"choice","instruction":"〔写作 Task 2 · 考生常见写法〕证据只是一项小调查，这句话说得太绝对。选出更恰当的改法。原句：Online learning will definitely make students lazy.","options":["Online learning may make some students less motivated.","Online learning must make students lazy and less motivated.","Online learning is bound to make some students lazy.","Online learning maybe makes students lazy and unmotivated."],"correctIndex":0,"explanation":"一项小调查证明不了「一定」。may 表示有可能，some students 也缩小了范围。must、is bound to 还是说得太满；maybe 是口语词，书面语用 may 或 perhaps。","subSkill":"modals_for_academic_hedging"},{"id":"gen-2-4-107","type":"fill","instruction":"〔写作 Task 2 · 考生常见错误〕想说「将来一些地区很可能会严重缺水」。在空里写出正确的形式。原句：In the future, there is likely to have a serious shortage of clean water in some regions.","sentence":"In the future, there is likely ___ a serious shortage of clean water in some regions.","acceptableAnswers":["to be"],"explanation":"说「将来很可能会有…」用 there is likely to be，不说 there is likely to have。中文的「有」在这里对应 be。","subSkill":"semi_modals_be_bound_to_be_likely_to"},{"id":"gen-2-4-108","type":"error","instruction":"〔口语 Part 3 · 考生常见错误〕考官问为什么很多人搬到大城市。点出用错的部分。","words":["I think","it","may because","big cities","usually offer","better-paid jobs."],"errorIndex":2,"correction":"may be because","explanation":"「可能是因为」→ It may be because…，may 后面要有动词 be。也可以说 Maybe it's because…。","subSkill":"modals_for_academic_hedging"},{"id":"gen-2-4-109","type":"error","instruction":"〔口语 Part 2 · 考生常见错误〕讲一个后悔的决定。点出用错的部分。","words":["Looking","back,","I","should have","chose","a different subject at university."],"errorIndex":4,"correction":"chosen","explanation":"should have 后面接过去分词：should have chosen（choose – chose – chosen）。同理是 must have gone、might have taken。","subSkill":"contrast_between_similar_modals"}],"5":[{"id":"gen-2-5-100","type":"fill","instruction":"〔写作 Task 2〕用括号里的动词补全：有定论的直接说，证据不足的留余地。","sentence":"Air pollution ___ (damage) children's lungs; this is well established. It ___ (be) the main cause of the rise in childhood asthma, but the evidence is still limited.","acceptableAnswers":["damages","may be"],"explanation":"① 已有定论 → damages，直接说（处处加 may，反而显得没有判断）。② 证据有限 → may be / is likely to be。关键不是词难不难，而是语气和证据相配，论证才站得住。","subSkill":"modals_for_academic_hedging","blankAnswers":[["damages","does damage","clearly damages","can damage","certainly damages","definitely damages","seriously damages","is known to damage"],["may be","might be","could be","is likely to be","is probably","may well be","might well be","could well be","is possibly","is perhaps","is arguably","appears to be","seems to be","is very likely to be","may in fact be","is thought to be","is believed to be","is considered to be","is widely seen as","is often seen as","is widely believed to be","is widely thought to be","is widely considered to be","is widely regarded as","is regarded as","is often regarded as","is generally regarded as","is often thought to be","is often considered","is widely considered","could possibly be","may possibly be","might possibly be","is most likely","is quite possibly","might in fact be","could in fact be","is said to be","is suspected to be"]]},{"id":"gen-2-5-101","type":"fill","instruction":"〔写作 Task 2〕用括号里的动词补全。三处都不是确定的事实：第 1 处推测原因，第 2 处推断过去，第 3 处预测将来。","sentence":"Nobody knows why fewer students choose history, but it ___ (be) because they see few career prospects. Their grandparents ___ (not worry) much about jobs, as work was easy to find then. It is too soon to say, but history ___ (become) a minority subject.","acceptableAnswers":["may be","can't have worried","may become"],"blankAnswers":[["may be","might be","could be","is probably","is likely to be","may well be","might well be","could well be","is perhaps","is possibly","may partly be","might partly be","could partly be","may simply be","might simply be","may be partly","might be partly","could be partly","may be largely","may be mainly"],["can't have worried","couldn't have worried","may not have worried","might not have worried","probably didn't worry","wouldn't have worried","probably wouldn't have worried","can't have worried very","won't have worried","must not have worried","mustn't have worried","are unlikely to have worried"],["may become","might become","could become","is likely to become","will probably become","will likely become","may well become","might well become","could well become","may eventually become","might eventually become","could eventually become","may soon become","might soon become","could soon become","is very likely to become"]],"explanation":"① 没人确知 → may be（现在的原因）。② 推断祖辈当年（那时工作好找）→ can't have worried；没那么有把握就用 may not have worried。③ 说不准 → may become，别写 will become。","subSkill":"modal_perfect_for_past_deduction"},{"id":"gen-2-5-102","type":"scenario","instruction":"考生想说「我也说不清，可能是我把日期记错了」。哪个回答意思准确？","context":"雅思口语 Part 2 · 题卡：Describe a time when you missed an important appointment … and explain why you missed it","dialogue":[],"options":["I'm not sure why, but I may have written down the wrong date.","I'm not sure why, but I must have written down the wrong date.","I'm not sure why, but I wrote down the wrong date.","I'm not sure why, but I might write down the wrong date."],"correctIndex":0,"explanation":"说不清 + 过去的事 → may / might have written。must have written 是「肯定记错了」，把握太大；直接说 I wrote 成了确定的事实；might write 说的是将来。","subSkill":"contrast_between_similar_modals"},{"id":"gen-2-5-103","type":"fill","instruction":"〔写作 Task 2〕把口语化的 I think maybe … will … 改成书面、准确的一句。原句：I think maybe cash will disappear in the next twenty years.","sentence":"Cash ___ within the next twenty years.","acceptableAnswers":["is likely to disappear","may disappear","might disappear","could disappear","will probably disappear","will likely disappear","may well disappear","might well disappear","could well disappear","is expected to disappear","is very likely to disappear","is likely to disappear completely","may disappear completely","might disappear completely","could disappear completely","will probably disappear completely","may disappear entirely","could disappear entirely","may eventually disappear","might eventually disappear","could eventually disappear","is likely to vanish","may vanish","might vanish","could vanish","will probably vanish","is likely to die out","may die out","might die out","could die out","is likely to be phased out","may be phased out","might be phased out","could be phased out","is likely to go out of use","may go out of use","could go out of use","is likely to become obsolete","may become obsolete","might become obsolete","could become obsolete","will probably become obsolete","will most likely disappear","may largely disappear","could largely disappear","might disappear entirely","is likely to disappear entirely","may well vanish","could well vanish","might well vanish"],"explanation":"I think maybe … will 是口语写法：I think 和 maybe 叠在一起，啰嗦又不正式。书面上用一个 is likely to 或 may 就够了，又简洁又准确。","subSkill":"semi_modals_be_bound_to_be_likely_to"},{"id":"gen-2-5-104","type":"fill","instruction":"〔写作 Task 2〕原句把原因说成了确定的事实。改成作者的推测（不确定），其余不变。原句：Many traditional crafts have disappeared. Young people lost interest in learning them as factory goods became cheaper.","sentence":"Many traditional crafts have disappeared. Young people ___ interest in learning them as factory goods became cheaper.","acceptableAnswers":["may have lost","might have lost","could have lost","probably lost","possibly lost","perhaps lost","may well have lost","might well have lost","could well have lost","are likely to have lost","may have gradually lost","might have gradually lost","could have gradually lost","may gradually have lost","probably gradually lost","seem to have lost","appear to have lost","may have slowly lost","might have slowly lost","are thought to have lost"],"explanation":"过去的事 + 只是推测 → may / might have lost，也可以写 probably lost。must have lost 是很有把握的推断，不符合「不确定」。","subSkill":"modal_perfect_for_past_deduction"},{"id":"gen-2-5-105","type":"fill","instruction":"〔口语 Part 1 · Neighbours〕考官问：Do you know your neighbours well? 补全回答：第一处很有把握，第二处觉得不可能。","sentence":"Not really. The man next door leaves at six and gets home after ten, so he ___ (work) very long hours. He ___ (get) much sleep.","acceptableAnswers":["must work","can't get"],"blankAnswers":[["must work","must be working","must have to work","surely works"],["can't get","can't be getting","couldn't be getting","can't possibly get","must not get","must not be getting"]],"explanation":"有把握的推断 → must work（也可以 must be working）；觉得「不可能」→ can't get much sleep。说的都是现在，所以不用 have done。","subSkill":"epistemic_modals_must_should_may"},{"id":"gen-2-5-106","type":"fill","instruction":"〔写作 Task 2〕补全这段：第 1 处批评当地政府过去没做的事；第 2 处是对将来的谨慎预测。","sentence":"When the coal mine closed in 2010, the town lost its main employer. The local council ___ (plan) for this years earlier. Without new industries, the town ___ (keep) shrinking.","acceptableAnswers":["should have planned","is likely to keep"],"blankAnswers":[["should have planned","ought to have planned","could have planned","should have been planning","ought to have been planning","should already have planned","really should have planned","should have made plans","ought to have made plans"],["is likely to keep","may keep","might keep","could keep","will probably keep","will likely keep","may well keep","might well keep","could well keep","is very likely to keep","may keep on","might keep on","could keep on","is likely to keep on","would probably keep","would likely keep"]],"explanation":"① 批评过去没做 → should have planned（本该早做计划）。② 将来说不准 → is likely to / may keep shrinking，比 will keep 更稳妥。","subSkill":"contrast_between_similar_modals"},{"id":"gen-2-5-107","type":"fill","instruction":"〔口语 Part 3〕考官问：Why are fewer young people getting married these days? 补全回答，两处都是没把握的猜测。","sentence":"It's hard to say. High housing costs ___ (put) some couples off, or young people ___ (simply want) more freedom.","acceptableAnswers":["may put","may simply want"],"blankAnswers":[["may put","might put","could put","may be putting","might be putting","could be putting","may well put","might well put","could well put","are probably putting","probably put","may have put","might have put","could have put","are likely to put","are likely to be putting","may well be putting"],["may simply want","might simply want","could simply want","may just want","might just want","could just want","probably simply want","perhaps simply want","possibly simply want"]],"explanation":"两处都是没把握的猜测，都要带 may / might：High housing costs may put some couples off；young people may simply want more freedom。少了情态动词，就成了确定的事实。","subSkill":"modals_for_academic_hedging"},{"id":"gen-2-5-108","type":"fill","instruction":"〔口语 Part 2 · Describe a place that has closed down〕考官追问：Why do you think the cinema closed? 用括号里的动词补全：前两处是没把握的猜测，第三处有证据，很肯定地排除一个原因。","sentence":"I'm not sure. The rent ___ (go up), or the owner ___ (retire). It was always busy, so it ___ (not close) because of a lack of customers.","acceptableAnswers":["may have gone up","may have retired","can't have closed"],"blankAnswers":[["may have gone up","might have gone up","could have gone up","may well have gone up","might well have gone up","could well have gone up","probably went up","may have gone up a lot","might have gone up a lot","may have risen","might have risen","could have risen","may have increased","might have increased","could have increased"],["may have retired","might have retired","could have retired","may simply have retired","might simply have retired","could simply have retired","may just have retired","might just have retired","may have decided to retire","might have decided to retire","could have decided to retire","probably retired"],["can't have closed","couldn't have closed","can't have been closed","couldn't have been closed","can't possibly have closed","couldn't possibly have closed","must not have closed","mustn't have closed"]],"explanation":"前两处没把握 → may / might have + 过去分词。第三处有证据（一直很热闹）→ can't have closed：不可能是因为没客人才关的。","subSkill":"modal_perfect_for_past_deduction"}]},"mission":{"title":"写作 Task 2 段落：为什么读书的人少了？","description":"写一个雅思 Task 2 主体段（3 句）：先提出一个可能的原因（别说死），再推测过去的某个变化起了什么作用，最后对「这是不是坏事」做一个谨慎的判断（写法自选）。有证据的地方可以说得肯定，没证据的地方要留余地。AI 老师会按雅思「语法多样性与准确性」给你反馈。","scenario":"题目：In many countries, people are reading fewer books than in the past. Why is this happening, and is it a negative development?<br>你只写正文里的一段：分析原因，最后谨慎地判断这是不是坏事。可以写小说、纸质书、电子书、图书馆……用你自己或身边人的经历举例。","grammarType":"modals_for_academic_hedging","scaffolds":[{"prefix":"There is no single explanation for this trend.","suffix":"","hint":"提出一个可能的原因，别说死：One reason may / might be that …","grammarCheck":"modals_for_academic_hedging","example":"One reason may be that short videos on our phones demand far less effort than a novel."},{"prefix":"Changes over the past twenty years are also relevant.","suffix":"","hint":"推测过去的一个变化起了什么作用：有证据就用 must have done，没把握就用 may / might have done。","grammarCheck":"modal_perfect_for_past_deduction","example":"When many schools cut library time to make room for exam preparation, children may have lost the habit of reading for pleasure."},{"prefix":"Whether this is a negative development is less clear.","suffix":"","hint":"结构自选：对「这是不是坏事」做一个谨慎的判断，可以用 may not be / is unlikely to / could …，只要不把话说死。","grammarCheck":"semi_modals_be_bound_to_be_likely_to","example":"Many people may simply be reading in new ways, such as on e-readers, so the decline is unlikely to be as serious as it first appears."}]},"discover":{"story":{"title":"写作 Task 2 范文节选：越连接，越孤独？","text":"读的时候想一想：作者认为人们越来越孤独，主要怪手机吗？他对每个原因、每条预测有多肯定？蓝色的句子下面会逐句问你。\nQuestion: Although people today are more connected than ever through technology, many say they often feel lonely. Why might this be the case, and what can be done about it?\nIt is tempting to blame smartphones for this problem, but the real causes may be more complex. Surveys suggest that loneliness was already rising in the 1990s, so social media cannot have been the only cause. A more likely explanation lies in the way people now live and work.\nOver the past few decades, millions of young adults have left their hometowns to look for work in large cities. This shift must have weakened the close family ties that once protected people from isolation. Long working hours may also have played a part, leaving little time for friendship. Social media, then, is probably not the root of the problem, although it might make things worse for some young users.\nAs for solutions, local councils could fund community centres where people of different ages can meet. Such centres are unlikely to solve the problem on their own, but they would give isolated residents somewhere to go. If nothing is done, loneliness is likely to become one of the most serious health problems of the coming decades.","highlights":["may be more complex","cannot have been the only cause","must have weakened","may also have played a part","could fund community centres","are unlikely to solve the problem","is likely to become"]},"questions":[{"question":"第一段：<em>It is tempting to blame smartphones for this problem, but the real causes may be more complex.</em><br>What does the writer say about the real causes?","options":["They are certainly more complex.","They are possibly more complex.","Smartphones are the real cause."],"correctIndex":1,"nudge":"盯住 may 这个词。如果作者很肯定，这半句会怎么写？（提示：the real causes ___ more complex）","explanation":"可能更复杂。作者没有十足证据，用 may 给自己留了余地。<br><strong>规则 ①</strong>：may / might / could + 动词原形 = 现在或将来有可能，不说死。","subSkill":"modals_for_academic_hedging"},{"question":"第一段：<em>Surveys suggest that loneliness was already rising in the 1990s, so social media cannot have been the only cause.</em><br>Why is the writer so sure that social media was not the only cause?","options":["Loneliness was already rising before social media.","Most lonely people hardly use social media at all.","Surveys show that social media makes people happier."],"correctIndex":0,"nudge":"社交媒体大约是 2005 年以后才流行起来的。作者说孤独感在哪个年代就已经上升了？这说明了什么？","explanation":"因为有证据：90 年代还没有社交媒体，孤独感却已在上升，所以它不可能是唯一原因。<br><strong>规则 ②</strong>：can't / couldn't have done = 有证据：过去不可能是这样。","subSkill":"modal_perfect_for_past_deduction"},{"question":"第二段：<em>This shift must have weakened the close family ties…</em><br><em>Long working hours may also have played a part…</em><br>Which cause is the writer more certain about?","options":["Their long working hours","Both of them equally","Leaving their hometowns"],"correctIndex":2,"nudge":"两句各用了一个词：must 和 may。这里的 must 不是「必须」，是作者在下判断。哪个口气更重？","explanation":"离开家乡这个原因更肯定：远离家人，家庭纽带必然变弱，这是有把握的推断；加班只是可能的原因。<br><strong>规则 ③</strong>：must have done = 过去一定是这样（这里的 must 是推断，不是「必须」）；may / might have done = 过去可能是这样。","subSkill":"modal_perfect_for_past_deduction"},{"question":"第三段：<em>…local councils could fund community centres… Such centres are unlikely to solve the problem on their own…</em><br>What does the writer think of community centres?","options":["Worth trying, but not enough alone.","Too expensive for councils to fund.","Certain to solve the whole problem."],"correctIndex":0,"nudge":"单靠社区中心（on their own）解决问题的可能性大吗？作者还建议去做吗（could fund）？","explanation":"值得试（could fund 是委婉的建议），但单靠它多半解决不了。<br><strong>规则 ④</strong>：be likely / unlikely to do = 很可能 / 不太可能；主语可以是人，也可以是事物。","subSkill":"semi_modals_be_bound_to_be_likely_to"},{"question":"比较第三段最后一句的两种写法：<br>A. …loneliness <em>will become</em> one of the most serious health problems…<br>B. …loneliness <em>is likely to become</em> one of the most serious health problems…<br>Which version leaves room for doubt?","options":["Version A","Version B","They mean the same"],"correctIndex":1,"nudge":"谁能百分之百预测几十年以后的事？哪种写法承认了这一点？","explanation":"B。will 把将来说死了；is likely to 表示「很可能」，论证更稳妥。<br><strong>规则 ⑤</strong>：预测将来没有十足把握，用 is likely to / may，少用 will；is bound to = 几乎一定。","subSkill":"semi_modals_be_bound_to_be_likely_to"},{"question":"你来试试：想说「这家餐馆可能换了厨师（我也不确定）」，哪句对？","options":["The restaurant may change its chef.","The restaurant must have changed its chef.","The restaurant may have changed its chef."],"correctIndex":2,"nudge":"分两步想：换厨师是已经发生的事，还是将来的事？你有多肯定？再用规则 ① 和 ③。","explanation":"换厨师是过去的事 → have changed（规则 ③）；不确定 → may（规则 ①）。must have changed 太肯定；may change 说的是将来。","subSkill":"modal_perfect_for_past_deduction"}],"tip":"【有几分把握，就用几分的词】\n\n① may / might / could + 原形 → 现在或将来有可能，不说死（猜原因不用 can）\n② can't / couldn't have done → 有证据：过去不可能是这样\n③ must have done → 过去一定是这样（推断，不是「必须」）；may / might have done → 过去可能是这样\n④ be likely / unlikely to do → 很可能 / 不太可能（人、事都能作主语；很可能会有 = there is likely to be）\n⑤ 预测将来没把握 → is likely to / may，少用 will；is bound to = 几乎一定\n⑥ should → 按理会；should have done 多指「本该做却没做」。都不用来猜原因\n情态动词后用原形（may cause，不写 may causes）：+ 原形 说现在 / 将来（must be tired），+ have done 说过去（must have been tired）。\n\n【例句】\n✔ The streets are wet, so it must have rained overnight.（过去：有把握）\n✔ Community centres are unlikely to solve the problem on their own.（将来：不说死）\n\n【常见错误】\n✘ This maybe the main reason. → This may be（maybe 不能当谓语）\n✘ Students are possible to fail. → Students are likely to fail（possible 不能这样接 to do；可说 It is possible that…）\n✘ It may because … → It may be because …（别漏 be）\n✘ Prices must rise sharply last year. → must have risen（说过去用 have done）"}},"3":{"levels":{"1":[{"id":"gen-3-1-100","type":"choice","instruction":"〔口语 Part 1〕事实：上周我的笔记本电脑坏了，是店里的师傅修好的。空格填哪个，才符合事实？","sentence":"Last week I ___ at a small shop near my flat.","options":["repaired my laptop","had my laptop repaired","had repaired my laptop","was repaired my laptop"],"correctIndex":1,"explanation":"师傅修的，不是我修的 → had my laptop repaired（请别人做）。repaired my laptop 是自己动手修；had repaired 是过去完成时，还是自己修。","subSkill":"causative_have_get_with_past_participle"},{"id":"gen-3-1-101","type":"choice","instruction":"〔口语 Part 2〕读句子，回答问题。原句：As a child, I loved being read to by my grandfather before bed.","sentence":"Who did the reading?","options":["I read to my grandfather.","My grandfather read to me.","I read to myself before bed.","We took turns reading."],"correctIndex":1,"explanation":"being read to = 被（别人）读给我听：是爷爷给我读。loved reading to my grandfather 才是我读给爷爷听。介词 to 留在 read 后面。","subSkill":"passive_infinitive_and_gerund"},{"id":"gen-3-1-102","type":"choice","instruction":"〔写作 Task 1〕读句子，回答问题。原句：In the final stage, the water is filtered by plants in a shallow pond before it flows back into the river.","sentence":"What filters the water in the final stage?","options":["Workers at the treatment plant.","The river water itself.","Plants in a shallow pond.","The diagram doesn't say."],"correctIndex":2,"explanation":"by plants 说出了是植物在过滤。做事的人或物是新信息、值得说时才加 by…；by people、by workers 这种不说也知道的，就省掉。","subSkill":"impersonal_passive_in_academic_prose"},{"id":"gen-3-1-103","type":"choice","instruction":"〔写作 Task 2〕读句子，回答问题。原句：It is widely believed that online courses are less effective than classroom teaching.","sentence":"What is the writer doing in this sentence?","options":["Giving the writer's own view.","Quoting a named expert.","Stating a proven fact.","Reporting a common view."],"correctIndex":3,"explanation":"It is widely believed that… = 很多人认为…，没说是谁，也不代表作者同意。Task 2 里常用它先摆出别人的观点，再表明自己的立场。","subSkill":"passive_reporting_verbs_it_is_claimed"},{"id":"gen-3-1-104","type":"choice","instruction":"〔写作 Task 2〕读句子，回答问题。原句：The tourism scheme is said to have created over 2,000 local jobs.","sentence":"Has the scheme already created the jobs? Is this confirmed?","options":["Yes, but it isn't confirmed.","Not yet, and it isn't confirmed.","Yes, and it is confirmed.","Not yet, but it is confirmed."],"correctIndex":0,"explanation":"is said = 据说，没有证实；to have created = 创造在说话之前，已经发生。要说「据说将来会创造」，用 is expected to create。","subSkill":"passive_reporting_verbs_it_is_claimed"},{"id":"gen-3-1-105","type":"scenario","instruction":"〔口语 Part 1〕读考生的回答，回答问题：Who fixed the bike?","context":"雅思口语 Part 1 · Fixing things","dialogue":[{"speaker":"examiner","text":"Examiner: Do you usually repair things yourself?"},{"speaker":"player","text":"It depends. I fix small things like lamps myself, but when my bike broke last month, I got it fixed."}],"options":["He fixed it himself.","Nobody has fixed it yet.","He and a friend fixed it.","Someone else fixed it."],"correctIndex":3,"explanation":"got it fixed = 让别人把它修好：小东西他自己修（fix … myself），自行车是请别人修的。和 had it fixed 意思一样，get 更口语。","subSkill":"causative_have_get_with_past_participle"},{"id":"gen-3-1-106","type":"choice","instruction":"〔口语 Part 2〕读句子，回答问题。原句：On my first trip abroad, I had my wallet stolen on a crowded train.","sentence":"What happened to the speaker's wallet?","options":["He asked someone to keep it.","He dropped it somewhere.","He stole someone else's.","Someone stole it from him."],"correctIndex":3,"explanation":"have + 东西 + done 也能说遇到的倒霉事：钱包被人偷了，不是他安排的，也不是他自己弄丢的。不说 I was stolen my wallet。","subSkill":"causative_have_get_with_past_participle"},{"id":"gen-3-1-107","type":"match","instruction":"〔写作 Task 1 · 地图〕三句都在说旧电影院改成公寓。只看动词：改造到了哪一步？","left":["The old cinema has been turned into flats.","The old cinema is being turned into flats.","The old cinema is going to be turned into flats."],"right":["The work is finished.","The work is in progress.","The work hasn't started yet."],"correctPairs":[[0,0],[1,1],[2,2]],"explanation":"has been turned = 已经改完；is being turned = 正在改；is going to be turned = 将来要改。被动也有各种时态，看 be 的形式就知道。","subSkill":"passive_with_complex_tenses"},{"id":"gen-3-1-108","type":"choice","instruction":"〔写作 Task 1〕读句子，回答问题。原句：Between 2015 and 2020, the number of gym members rose steadily, while membership fees were raised twice.","sentence":"Which figure did someone adjust, rather than it changing by itself?","options":["Both of them.","Neither of them.","Only the number of members.","Only the fees."],"correctIndex":3,"explanation":"were raised = 会费是被（健身房）调高的，有人直接去调；rose = 人数自己涨了，没有谁去「涨」它。数字自己的变化用 rise、fall，不加 be。","subSkill":"active_vs_passive_by_meaning"}],"2":[{"id":"gen-3-2-100","type":"choice","instruction":"〔写作 Task 1〕描述果汁生产的一步：橙子由机器榨汁。","sentence":"Next, the oranges ___ by machine, and the juice is stored in large tanks.","options":["are squeezed","squeeze","are squeezing","have squeezed"],"correctIndex":0,"explanation":"橙子是被机器榨的 → are squeezed。squeeze 是「榨（别的东西）」，橙子自己不会榨；are squeezing 是「正在榨别的东西」。","subSkill":"impersonal_passive_in_academic_prose"},{"id":"gen-3-2-101","type":"choice","instruction":"〔写作 Task 1〕这一步不用水泵，水靠重力自己流下去。","sentence":"From the filter, the clean water ___ down into a storage tank.","options":["is flowed","flows","is pumped","is flowing"],"correctIndex":1,"explanation":"水自己流 → flows。flow 没有被动，不说 is flowed；is pumped 是用水泵抽，和说明不符；流程每次都这样，用一般现在时，不用 is flowing。","subSkill":"active_vs_passive_by_meaning"},{"id":"gen-3-2-102","type":"scenario","instruction":"〔口语 Part 2〕考生想说「那场洪水发生在我上初一那年」。选出准确的一句。","context":"雅思口语 Part 2 · Describe an extreme weather event you experienced","dialogue":[],"options":["It was happened in my first year at secondary school.","It happened in my first year at secondary school.","It had been happened in my first year at secondary school.","It was happening in my first year at secondary school."],"correctIndex":1,"explanation":"happen 只有主动：happened，没有 was happened、had been happened。was happening 是「当时正在发生」；讲一件事发生在哪一年，用一般过去时。","subSkill":"active_vs_passive_by_meaning"},{"id":"gen-3-2-103","type":"choice","instruction":"〔写作 Task 1 · 地图〕想说「2005 年以来，海滩边陆续建起了几家新酒店」。","sentence":"Since 2005, several new hotels ___ along the beach.","options":["have built","were built","have been built","are being built"],"correctIndex":2,"explanation":"since 2005 一直到现在 → 现在完成时；酒店是被建的 → have been built。have built 成了酒店去建别的；were built 不和 since 连用。","subSkill":"passive_with_complex_tenses"},{"id":"gen-3-2-104","type":"choice","instruction":"〔写作 Task 1 · 地图〕按规划，停车场明年会改成绿地。","sentence":"According to the plan, the car park ___ into a green space next year.","options":["will be converted","will convert","is converting","has been converted"],"correctIndex":0,"explanation":"明年、被改造 → will be converted。will convert / is converting 成了停车场去改造别的；has been converted 是已经改好了。","subSkill":"passive_with_complex_tenses"},{"id":"gen-3-2-105","type":"choice","instruction":"〔写作 Task 2〕想说「据说这种新药几乎没有副作用」。","sentence":"This new drug ___ very few side effects.","options":["is said that it has","is said to have","said to have","is said having"],"correctIndex":1,"explanation":"主语 + is said to + 原形 = 据说…。is said that it has 把两种说法混在一起了，要么写 It is said that this drug has…；said to have 漏了 is。","subSkill":"passive_reporting_verbs_it_is_claimed"},{"id":"gen-3-2-106","type":"choice","instruction":"〔写作 Task 2〕想说「据报道，这家工厂关闭之前污染过附近的河流」。","sentence":"The factory is reported ___ the nearby river before it closed.","options":["to pollute","to have been polluted","having polluted","to have polluted"],"correctIndex":3,"explanation":"污染发生在报道之前（工厂已经关了）→ to have polluted。to pollute 说的是现在还在污染；to have been polluted 成了工厂被污染。","subSkill":"passive_reporting_verbs_it_is_claimed"},{"id":"gen-3-2-107","type":"match","instruction":"〔口语 Part 2 · Describe an old building〕看动词：哪些事是自己发生的，哪些是有人做的？连线。","left":["A fire broke out in 1998.","The museum was rebuilt in 2001.","The fire spread very quickly.","The street was closed for a week."],"right":["It happened by itself.","Someone did it."],"correctPairs":[[0,0],[1,1],[2,0],[3,1]],"explanation":"broke out、spread 是火自己发生、蔓延，没有被动（不说 was broken out）；was rebuilt、was closed 是有人重建、有人封路。中文「路封了」不带「被」，要按意思选。","subSkill":"active_vs_passive_by_meaning"},{"id":"gen-3-2-108","type":"choice","instruction":"〔口语 Part 2〕想说「寄出之前，我请表哥帮我检查了个人陈述」。","sentence":"Before I sent off my personal statement, I got my cousin ___ it.","options":["check","checked","to check","to have checked"],"correctIndex":2,"explanation":"get + 人 + to do = 请某人做：got my cousin to check it（had my cousin check 也对）。人后面不接过去分词；检查和寄出是同一段时间的事，不用 to have checked。","subSkill":"causative_have_get_with_past_participle"},{"id":"gen-3-2-109","type":"fill","instruction":"〔口语 Part 3〕想说「很多青少年讨厌被父母指挥」。用括号里的动词填空。","sentence":"Many teenagers hate ___ (tell) what to do by their parents.","acceptableAnswers":["being told","to be told","getting told"],"explanation":"青少年是被告诉该做什么 → being told（to be told 也对，口语也说 getting told）。telling、to tell 成了他们去告诉别人。","subSkill":"passive_infinitive_and_gerund"}],"3":[{"id":"gen-3-3-100","type":"fill","instruction":"〔写作 Task 1〕流程图不必提工人。改写这句，以茶叶为主语。原句：Workers pick the tea leaves by hand and then weigh them at the collection point.","sentence":"The tea leaves ___ by hand and then ___ at the collection point.","acceptableAnswers":["are picked","weighed"],"blankAnswers":[["are picked","are plucked","are harvested","are gathered","are collected"],["weighed","are weighed"]],"explanation":"茶叶是被摘、被称重的 → are picked … (are) weighed。and 后面的 are 可以省。写成 weigh，就成了茶叶去称别的东西。","subSkill":"impersonal_passive_in_academic_prose"},{"id":"gen-3-3-101","type":"fill","instruction":"〔写作 Task 1〕重点是废热的用途，不是工厂。改写这句。原句：The factory can reuse the waste heat to warm nearby homes.","sentence":"The waste heat ___ to warm nearby homes.","acceptableAnswers":["can be reused","can be used","can then be reused","can then be used","can be recycled","could be reused","could be used","can be reused by the factory","can be used by the factory","can be re-used","could be re-used","can then be re-used","can be used again","could be used again","can then be used again"],"explanation":"热量是被重新利用的，can 后面接 be + 过去分词：can be reused。can reuse 成了热量去利用别的；can reused 漏了 be。","subSkill":"passive_infinitive_and_gerund"},{"id":"gen-3-3-102","type":"fill","instruction":"〔写作 Task 1 · 地图〕把两张图的变化合成一句。原句：In 2000 there was a fishing port here. Now there is a marina in its place.","sentence":"Since 2000, the fishing port ___ a marina.","acceptableAnswers":["has been replaced by","has been turned into","has been converted into","has been converted to","has been transformed into","has been redeveloped into","has been redeveloped as","has been made into","has made way for","has given way to","has been replaced with","has been changed into","has been developed into","has been rebuilt as","has become","has turned into","has changed into"],"explanation":"从 2000 年到现在，改造已经完成 → has been replaced by / has been turned into。港口是被改造的，been 不能少：不写 has replaced by。","subSkill":"passive_with_complex_tenses"},{"id":"gen-3-3-103","type":"fill","instruction":"〔写作 Task 2〕转述这个说法，不点名是谁说的，用 claim。原句：People claim that social media has made teenagers less patient.","sentence":"Social media ___ teenagers less patient.","acceptableAnswers":["is claimed to have made","is often claimed to have made","is widely claimed to have made","is commonly claimed to have made","has been claimed to have made","is claimed to make","is often claimed to make","is widely claimed to make","is claimed to be making","is often claimed to be making","is widely claimed to be making","is commonly claimed to make","is generally claimed to make","is frequently claimed to make","has been claimed to make","is generally claimed to have made","is frequently claimed to have made"],"explanation":"主语 + is claimed to…。「已经让青少年没耐心了」是之前造成的影响 → to have made（is claimed to make 说一般情况，也说得通）。","subSkill":"passive_reporting_verbs_it_is_claimed"},{"id":"gen-3-3-110","type":"fill","instruction":"〔写作 Task 1 · 线图〕图上 2030 年是预测值，不必写是谁预测的。原句：Experts predict that the number of electric cars will triple by 2030.","sentence":"The number of electric cars ___ triple by 2030.","acceptableAnswers":["is expected to","is predicted to","is projected to","is forecast to","is forecasted to","is estimated to","is anticipated to","is set to","is likely to"],"explanation":"主语 + is expected / predicted / projected to do = 预计会…，写线图里的预测数据最常用，不用写 experts。triple 是数字自己变，用原形。","subSkill":"passive_reporting_verbs_it_is_claimed"},{"id":"gen-3-3-108","type":"reorder","instruction":"〔写作 Task 1 · 地图〕排出这句：到 2015 年，五家图书馆里已经有三家被关掉了。","words":["By","2015,","three","of","the five libraries","had","been","closed."],"correctSentence":"By 2015, three of the five libraries had been closed.","acceptableSentences":["Three of the five libraries had been closed by 2015."],"explanation":"到 2015 年已经被关掉 → had been closed：过去完成时的被动，been 不能少。By 2015 放句首或句末都可以。","subSkill":"passive_with_complex_tenses"},{"id":"gen-3-3-111","type":"fill","instruction":"〔口语 Part 1 · Eyesight〕考官问 Do you wear glasses? 用 have 或 get 说出「每年去查一次视力」。","sentence":"Yes, I'm short-sighted, so I ___ once a year.","acceptableAnswers":["have my eyes tested","get my eyes tested","have my eyes checked","get my eyes checked","have my eyesight tested","get my eyesight tested","have my eyesight checked","get my eyesight checked","have my eyes examined","get my eyes examined","have an eye test","get an eye test"],"explanation":"视力是验光师查的 → have / get my eyes tested（have an eye test 也对）。test my eyes 是自己查；get my eyes test 漏了 -ed。","subSkill":"causative_have_get_with_past_participle"},{"id":"gen-3-3-106","type":"fill","instruction":"〔口语 Part 3〕把这句说得更简洁。原句：Most people don't like it when others criticise them in public.","sentence":"Most people don't like ___ in public.","acceptableAnswers":["being criticised","being criticized","to be criticised","to be criticized","being criticised by others","being criticized by others","to be criticised by others","to be criticized by others","getting criticised","getting criticized","to get criticised","to get criticized","being criticised by other people","being criticized by other people","to be criticised by other people","to be criticized by other people"],"explanation":"人是被批评的 → being criticised（to be criticised 也对，口语也说 getting criticised）。like criticising 就成了喜欢批评别人。","subSkill":"passive_infinitive_and_gerund"},{"id":"gen-3-3-107","type":"fill","instruction":"〔写作 Task 1 · 地图〕谁在施工不重要，把重点放在医院上。原句：At present, builders are extending the hospital.","sentence":"At present, the hospital ___.","acceptableAnswers":["is being extended","is being expanded","is being enlarged","is being extended by builders","is currently being extended","is currently being expanded","is currently being enlarged","is being expanded by builders","is being enlarged by builders"],"explanation":"现在正在进行、医院是被扩建的 → is being extended。is extending 成了医院在扩建别的；has been extended 是已经扩建完了。","subSkill":"passive_with_complex_tenses"},{"id":"gen-3-3-109","type":"reorder","instruction":"〔写作 Task 1〕排出这句：谷物必须先烘干，才能入仓储存。","words":["be","stored.","must","it","be","dried","before","The","grain","can"],"correctSentence":"The grain must be dried before it can be stored.","acceptableSentences":["Before it can be stored, the grain must be dried."],"explanation":"谷物是被烘干、被储存的：must 和 can 后面都接 be + 过去分词。少了 be，就成了谷物自己去烘干、储存别的东西。","subSkill":"passive_infinitive_and_gerund"}],"4":[{"id":"gen-3-4-100","type":"error","instruction":"〔写作 Task 1 · 考生常见错误〕描述巧克力生产的一步。点出用错的部分。","words":["After that, the mixture","poured","into moulds","and","left","to cool","for two hours."],"errorIndex":1,"correction":"is poured","explanation":"混合物是被倒进模具的 → is poured。少了 is，the mixture poured into moulds 读起来像混合物自己流进模具、没有人倒。后面的 left 共用 is，不用改。","subSkill":"impersonal_passive_in_academic_prose"},{"id":"gen-3-4-101","type":"error","instruction":"〔写作 Task 1 · 考生常见错误〕点出用错的部分。","words":["Overall,","the whole process","is consisted of","five main stages,","beginning with","the crushing of limestone."],"errorIndex":2,"correction":"consists of","explanation":"consist of 只有主动：the process consists of five stages。中文「由…组成」像被动，但英文不说 is consisted of；也可以说 is made up of。","subSkill":"active_vs_passive_by_meaning"},{"id":"gen-3-4-102","type":"fill","instruction":"〔写作 Task 2 · 考生常见错误〕有一处动词形式错了，在空里写出正确的形式。原句：This problem can solve if the government invests more in public health.","sentence":"This problem ___ if the government invests more in public health.","acceptableAnswers":["can be solved","could be solved","can be tackled","could be tackled","can be addressed","could be addressed","can be resolved","could be resolved","can be dealt with","could be dealt with","can be overcome","could be overcome","can be fixed","could be fixed","will be solved","may be solved"],"explanation":"问题是被解决的 → can be solved。can solve 成了问题去解决别的。情态动词后面说「被…」，都是 be + 过去分词。","subSkill":"passive_infinitive_and_gerund"},{"id":"gen-3-4-103","type":"choice","instruction":"〔写作 Task 2 · 考生常见错误〕想说「人们认为…」，却把两种说法混在了一起。选出改对的开头。原句：People are believed that video games make children more violent.","sentence":"___ video games make children more violent.","options":["It believes that","There is believed that","It is believed that","People are believing that"],"correctIndex":2,"explanation":"被「认为」的是一件事，不是人：It is believed that + 句子（或直接说 People believe that…）。It believes 成了「它认为」；believe 一般不用进行时。","subSkill":"passive_reporting_verbs_it_is_claimed"},{"id":"gen-3-4-104","type":"error","instruction":"〔写作 Task 2 · 考生常见错误〕这项政策是去年实施的。点出用错的部分。","words":["The new policy","is said","to reduce","street crime","by 20%","last year."],"errorIndex":2,"correction":"to have reduced","explanation":"「据说」是现在说的，减少犯罪是去年的事 → to have reduced。is said to reduce 说的是现在或一般情况，和 last year 冲突。","subSkill":"passive_reporting_verbs_it_is_claimed"},{"id":"gen-3-4-105","type":"fill","instruction":"〔口语 Part 1 · 考生常见错误〕照片是照相馆的人拍的，这句意思不对。在空里写出正确的说法。原句：I took my passport photo last week for my visa application.","sentence":"I ___ last week for my visa application.","acceptableAnswers":["had my passport photo taken","got my passport photo taken","had my passport photos taken","got my passport photos taken","had a passport photo taken","got a passport photo taken","had my photo taken","got my photo taken","had my passport photo done","got my passport photo done","had my passport photos done","got my passport photos done","had a passport photo done","got a passport photo done","had passport photos taken","got passport photos taken","had my picture taken","got my picture taken"],"explanation":"照片是别人拍的 → had / got my passport photo taken。took my photo 听起来是自己拍的。have + 东西 + done = 请别人做。","subSkill":"causative_have_get_with_past_participle"},{"id":"gen-3-4-110","type":"error","instruction":"〔写作 Task 1 · 地图 · 考生常见错误〕点出用错的部分。","words":["In the new plan,","the car park","for visitors","locates","to the north of","the station."],"errorIndex":3,"correction":"is located","explanation":"停车场是被安排在那里的，locate 要用被动：is located（或 is situated；也可以用主动的 lies）。中文「位于」没有「被」，所以常写成 locates。","subSkill":"active_vs_passive_by_meaning"},{"id":"gen-3-4-107","type":"error","instruction":"〔写作 Task 1 · 考生常见错误〕点出用错的部分。","words":["Finally, the bottles","are labelling","and","sent","to supermarkets."],"errorIndex":1,"correction":"are labelled","explanation":"瓶子是被贴标签的 → are labelled（美式 labeled）。are labelling 是「正在给别的东西贴标签」。被动用过去分词，不用 -ing；sent 共用 are，没有错。","subSkill":"impersonal_passive_in_academic_prose"},{"id":"gen-3-4-108","type":"choice","instruction":"〔写作 Task 1 · 考生常见写法〕中文「体育场 2018 年建成」直译成 The stadium built in 2018。选出改对的句子。","options":["The stadium was built in 2018.","The stadium has been built in 2018.","The stadium was building in 2018.","The stadium had built in 2018."],"correctIndex":0,"explanation":"体育场是被建的，2018 是过去的具体年份 → was built。has been built 不和具体年份连用；was building、had built 都成了体育场在建别的东西。","subSkill":"passive_with_complex_tenses"},{"id":"gen-3-4-109","type":"error","instruction":"〔写作 Task 1 · 考生常见错误〕点出用错的部分。","words":["Between 2000 and 2010,","the number of","overseas students","was increased","by","almost 50%."],"errorIndex":3,"correction":"increased","explanation":"人数是自己涨的，不是谁去「增加」它 → increased（或 rose）。rise、fall 没有被动；increase、decrease 只在有人主动调整时用被动（fees were increased）。","subSkill":"active_vs_passive_by_meaning"}],"5":[{"id":"gen-3-5-100","type":"fill","instruction":"〔写作 Task 1〕补全这段流程描述，用括号里的动词。先想清楚每一步是谁在做。","sentence":"Silkworms feed on mulberry leaves for about a month before they ___ (spin) cocoons. These ___ (collect) and boiled, so that the silk thread can ___ (unwind) and spun into yarn.","acceptableAnswers":["spin","are collected","be unwound"],"blankAnswers":[["spin","start to spin","begin to spin","start spinning","begin spinning"],["are collected","are then collected"],["be unwound","easily be unwound","be easily unwound"]],"explanation":"① 吐丝的是蚕自己 → spin。② 蚕茧是被人收走的 → are collected。③ can 后面说丝被抽出来 → be unwound。同一段里，主动还是被动按「谁在做」来选。","subSkill":"active_vs_passive_by_meaning"},{"id":"gen-3-5-101","type":"fill","instruction":"〔写作 Task 2〕不点名是谁，把开头改得更客观。原句：Many people say that fast food is the main cause of obesity, but I think this view is too simple.","sentence":"___ fast food is the main cause of obesity, but this view is too simple.","acceptableAnswers":["It is often claimed that","It is widely believed that","It is often argued that","It is said that","It is claimed that","It is believed that","It is argued that","It is thought that","It is suggested that","It is assumed that","It is maintained that","It is held that","It is often said that","It is often believed that","It is often thought that","It is often suggested that","It is often assumed that","It is often maintained that","It is often held that","It is widely claimed that","It is widely said that","It is widely argued that","It is widely thought that","It is widely suggested that","It is widely assumed that","It is widely maintained that","It is widely held that","It is commonly claimed that","It is commonly said that","It is commonly believed that","It is commonly argued that","It is commonly thought that","It is commonly suggested that","It is commonly assumed that","It is commonly maintained that","It is commonly held that","It is generally claimed that","It is generally said that","It is generally believed that","It is generally argued that","It is generally thought that","It is generally suggested that","It is generally assumed that","It is generally maintained that","It is generally held that","It is frequently claimed that","It is frequently said that","It is frequently believed that","It is frequently argued that","It is frequently thought that","It is frequently suggested that","It is frequently assumed that","It is frequently maintained that","It is frequently held that","It is sometimes claimed that","It is sometimes said that","It is sometimes believed that","It is sometimes argued that","It is sometimes thought that","It is sometimes suggested that","It is sometimes assumed that","It is sometimes maintained that","It is sometimes held that","It has been claimed that","It has been said that","It has been believed that","It has been argued that","It has been thought that","It has been suggested that","It has been assumed that","It has often been claimed that","It has often been said that","It has often been believed that","It has often been argued that","It has often been thought that","It has often been suggested that","It has often been assumed that","It has frequently been claimed that","It has frequently been said that","It has frequently been believed that","It has frequently been argued that","It has frequently been thought that","It has frequently been suggested that","It has frequently been assumed that","It has long been claimed that","It has long been said that","It has long been believed that","It has long been argued that","It has long been thought that","It has long been suggested that","It has long been assumed that","It is claimed","It is said","It is believed","It is argued","It is thought","It is often claimed","It is often said","It is often believed","It is often argued","It is often thought","It is widely claimed","It is widely said","It is widely believed","It is widely argued","It is widely thought","It is commonly claimed","It is commonly said","It is commonly believed","It is commonly argued","It is commonly thought","It is generally claimed","It is generally said","It is generally believed","It is generally argued","It is generally thought","It has been widely claimed that","It has been widely believed that","It has been widely argued that","It has been widely suggested that","It has been widely said that","It has been widely thought that","It has been widely assumed that","It is widely accepted that","It is generally accepted that","It is commonly accepted that","It is often stated that"],"explanation":"It is often claimed / widely believed that… 摆出对方的观点，不点名，也不代表作者同意；后半句再亮出自己的看法。Task 2 让步段常这样开头。","subSkill":"passive_reporting_verbs_it_is_claimed"},{"id":"gen-3-5-102","type":"fill","instruction":"〔写作 Task 1〕把学生笔记改成流程描述，不用 farmers 当主语。原句：After farmers shear the sheep, they wash the wool to remove dirt.","sentence":"After the sheep ___, the wool ___ to remove dirt.","acceptableAnswers":["have been sheared","is washed"],"blankAnswers":[["have been sheared","are sheared","have been shorn","are shorn"],["is washed","is then washed","is cleaned","is then cleaned","is scoured","is then scoured"]],"explanation":"羊被剪毛、羊毛被清洗：have been sheared（剪完再洗；are sheared 也对）→ is washed。the wool 是单数，用 is；写成 wash 就成了羊毛去洗别的东西。","subSkill":"impersonal_passive_in_academic_prose"},{"id":"gen-3-5-103","type":"scenario","instruction":"〔口语 Part 2〕考生想说「去年我请人把老家的房子翻修了一遍」。哪个回答把这层意思说准确了？","context":"雅思口语 Part 2 · 题卡：Describe a change you made to your home … and explain how you felt about it","dialogue":[],"options":["Last year I renovated my family's old house, so it looks completely different now.","Last year my family's old house was renovating, and it looks completely different now.","Last year I had my family's old house renovated, and it looks completely different now.","Last year I had renovated my family's old house, and it looks completely different now."],"correctIndex":2,"explanation":"第 3 个准确：had … renovated = 请人翻修。第 1 个语法对，但没说出是请人做的；第 2 个成了房子在翻修别的；第 4 个 had renovated 是过去完成时，还是自己修。","subSkill":"causative_have_get_with_past_participle"},{"id":"gen-3-5-104","type":"fill","instruction":"〔写作 Task 2〕以 Air pollution 开头改写，不点名是谁。原句：Experts believe that air pollution caused almost seven million deaths worldwide in 2019.","sentence":"Air pollution ___ almost seven million deaths worldwide in 2019.","acceptableAnswers":["is believed to have caused","is thought to have caused","is estimated to have caused","is said to have caused","is believed to have led to","is believed to have resulted in","is believed to have been responsible for","is believed to have contributed to","is thought to have led to","is thought to have resulted in","is thought to have been responsible for","is thought to have contributed to","is estimated to have led to","is estimated to have resulted in","is estimated to have been responsible for","is estimated to have contributed to","is said to have led to","is said to have resulted in","is said to have been responsible for","is said to have contributed to","is reported to have caused","is reported to have led to","is reported to have resulted in","is reported to have been responsible for","is reported to have contributed to","is understood to have caused","is understood to have led to","is understood to have resulted in","is understood to have been responsible for","is understood to have contributed to","is considered to have caused","is considered to have led to","is considered to have resulted in","is considered to have been responsible for","is considered to have contributed to","is claimed to have caused","is claimed to have led to","is claimed to have resulted in","is claimed to have been responsible for","is claimed to have contributed to","is widely believed to have caused","is widely believed to have led to","is widely believed to have resulted in","is widely believed to have been responsible for","is widely believed to have contributed to","is widely thought to have caused","is widely thought to have led to","is widely thought to have resulted in","is widely thought to have been responsible for","is widely thought to have contributed to","is generally believed to have caused","is generally believed to have led to","is generally believed to have resulted in","is generally believed to have been responsible for","is generally believed to have contributed to","is generally thought to have caused","is generally thought to have led to","is generally thought to have resulted in","is generally thought to have been responsible for","is generally thought to have contributed to","is commonly believed to have caused","is commonly believed to have led to","is commonly believed to have resulted in","is commonly believed to have been responsible for","is commonly believed to have contributed to","has been estimated to have caused","has been estimated to have led to","has been estimated to have resulted in","has been believed to have caused","has been believed to have led to","has been believed to have resulted in","has been thought to have caused","has been thought to have led to","has been thought to have resulted in","has been reported to have caused","has been reported to have led to","has been reported to have resulted in","is widely estimated to have caused","is commonly thought to have caused","is thought to have been the cause of"],"explanation":"主语 + is believed to…：死亡发生在 2019 年，比「认为」早 → to have caused。is believed to cause 说的是现在，和 in 2019 冲突。","subSkill":"passive_reporting_verbs_it_is_claimed"},{"id":"gen-3-5-105","type":"fill","instruction":"〔写作 Task 1 · 地图〕补全这段地图描述，用括号里的动词。注意每个变化发生在什么时候。","sentence":"Over the past twenty years, the village has changed dramatically. The old farm ___ (replace) by a housing estate, and a primary school ___ (build) next to it in 2012. At present, a sports centre ___ (construct) on the former car park.","acceptableAnswers":["has been replaced","was built","is being constructed"],"blankAnswers":[["has been replaced","was replaced"],["was built"],["is being constructed","is currently being constructed"]],"explanation":"① 到今天已经完成 → has been replaced（was replaced 也行）。② 有具体年份 2012 → was built。③ At present 正在施工 → is being constructed。三处都是被动，变的只是 be 的时态。","subSkill":"passive_with_complex_tenses"},{"id":"gen-3-5-106","type":"fill","instruction":"〔口语 Part 3〕考官问：Why are many people afraid of public speaking? 用括号里的动词补全回答。","sentence":"I think most people are afraid of ___ (judge) by others, and nobody likes ___ (laugh at).","acceptableAnswers":["being judged","being laughed at"],"blankAnswers":[["being judged","getting judged"],["being laughed at","to be laughed at","getting laughed at","to get laughed at"]],"explanation":"人是被评判、被嘲笑的：of 后面用 being judged；like 后面用 being laughed at（to be laughed at 也行），at 不能丢。口语也说 getting judged。","subSkill":"passive_infinitive_and_gerund"},{"id":"gen-3-5-107","type":"fill","instruction":"〔口语 Part 1 · Clothes〕考官问：Do you ever wear formal clothes? 用括号里的词补全回答。","sentence":"Not often. But last year I ___ (a suit / make) for my cousin's wedding, and now I ___ (it / clean) professionally once a year.","acceptableAnswers":["had a suit made","have it cleaned"],"blankAnswers":[["had a suit made","got a suit made"],["have it cleaned","get it cleaned","have it dry-cleaned","get it dry-cleaned","have it dry cleaned","get it dry cleaned"]],"explanation":"西装是裁缝做的 → had a suit made（过去）；现在每年送去洗 → have it cleaned（现在的习惯）。have / get 的时态跟着时间变，过去分词不变。","subSkill":"causative_have_get_with_past_participle"},{"id":"gen-3-5-108","type":"fill","instruction":"〔写作 Task 2〕补全这段论证，用括号里的词。先想清楚：哪句是别人的说法，哪件事已经发生，哪件还没发生。","sentence":"It ___ (often / claim) that new technology creates more jobs than it destroys. However, many factory jobs ___ (already / replace) by robots, and more ___ (expect) to disappear in the next decade.","acceptableAnswers":["is often claimed","have already been replaced","are expected"],"blankAnswers":[["is often claimed","has often been claimed"],["have already been replaced"],["are expected"]],"explanation":"① It is often claimed that… 引出别人的观点。② 到现在已被取代 → have already been replaced。③ 预计会消失 → are expected to disappear；disappear 没有被动，不写 to be disappeared。","subSkill":"passive_reporting_verbs_it_is_claimed"}]},"mission":{"title":"写作 Task 1：咖啡是怎样生产出来的","description":"写一段雅思 Task 1 流程描述（3 句）：先写总览，再写第 2–3 步，最后写第 5–7 步（写法自选）。每一步先问自己「是谁在做」：人或机器做的用被动，自己发生的变化用主动。至少用对本单元的 2 种写法。AI 老师会按雅思「语法多样性与准确性」给你反馈。","scenario":"题目：The diagram below shows how coffee is produced. Summarise the information by selecting and reporting the main features, and make comparisons where relevant.<br>流程图共 7 步：① 人工采摘成熟的咖啡果 → ② 摊在阳光下晒干（约两周）→ ③ 取出咖啡豆 → ④ 高温烘焙 → ⑤ 自然冷却 → ⑥ 磨成粉 → ⑦ 装袋密封。<br>你只写总览和正文的 3 句。","grammarType":"impersonal_passive_in_academic_prose","scaffolds":[{"prefix":"The diagram illustrates the stages in the production of coffee, from the picking of the fruit to the packing of the final product.","suffix":"","hint":"写总览：一共几步，哪些靠人或机器、哪些靠自然。consist of 只用主动：Overall, the process consists of …","grammarCheck":"active_vs_passive_by_meaning","example":"Overall, the process consists of seven stages, most of which are carried out by people or machines, although the drying stage relies on the sun."},{"prefix":"First, the ripe coffee cherries are picked by hand.","suffix":"","hint":"写第 2、3 步：晒干靠太阳（可以写 are left to dry）；取豆是人或机器做的。可以用 Once they have dried, …（自己干 → 主动）","grammarCheck":"passive_with_complex_tenses","example":"They are then left to dry in the sun for about two weeks, and once they have dried, the beans are removed from the fruit."},{"prefix":"After this, the beans are roasted at a high temperature.","suffix":"","hint":"写最后三步，结构自选：可以用 Once / After …，也可以用 need to be … 或 before being …；冷却是自己发生的，记得用主动。","grammarCheck":"passive_infinitive_and_gerund","example":"Once they have cooled, they are ground into a fine powder, which is finally packed into bags and sealed to keep it fresh."}]},"discover":{"story":{"title":"Task 1 范文：旧塑料瓶怎样变成衣服（附 Task 2 一段）","text":"读的时候想一想：每一步是谁在做——人和机器，还是它自己？蓝色的句子下面会逐句问你。\nTask 1: The diagram below shows how used plastic bottles are recycled to make clothing. Summarise the information by selecting and reporting the main features, and make comparisons where relevant.\nThe diagram illustrates how used plastic bottles are turned into polyester clothing. Overall, the process consists of a series of stages, beginning with collection and ending with the production of new garments.\nFirst, used bottles are collected from households and taken to a recycling plant, where they are sorted by colour. The caps and labels need to be removed at this stage, as they are made of a different kind of plastic. Once the bottles have been washed, they are shredded into small flakes. These flakes are then melted and forced through tiny holes. As the hot plastic cools, it hardens into long, thin fibres, which are spun into yarn. Finally, the yarn is knitted into fabric and made into items such as fleece jackets.\nTask 2: Some people believe that recycling is the best way to reduce plastic waste. To what extent do you agree or disagree?\nIt is often claimed that recycling is the answer to plastic waste. However, only around nine per cent of all plastic waste ever produced is estimated to have been recycled, and clothes made from old bottles are rarely recycled again. Using less plastic in the first place is therefore far more important.","highlights":["need to be removed","Once the bottles have been washed","they are shredded into small flakes","it hardens into long, thin fibres","are spun into yarn","It is often claimed that","is estimated to have been recycled"]},"questions":[{"question":"第二段：<em>The caps and labels need to be removed at this stage.</em><br>What happens to the caps and labels at this stage?","options":["Someone takes them off the bottles.","They take dirt off the bottles.","They fall off the bottles by themselves."],"correctIndex":0,"nudge":"need to be removed 里有个 be。瓶盖和标签是动手去 remove 别的东西，还是被别人 remove？","explanation":"有人把瓶盖和标签取下来：它们是被去掉的。少了 be 写成 need to remove，就成了瓶盖和标签去掉别的东西。<br><strong>规则 ①</strong>：东西被处理 → be + 过去分词；在 need to、can、must 后面也一样：need to be removed、can be recycled。","subSkill":"passive_infinitive_and_gerund"},{"question":"第二段原文：<em>Once the bottles have been washed, they are shredded into small flakes.</em><br>比较两种写法：<br>A. When the bottles <em>have been washed</em>, they are shredded.<br>B. When the bottles <em>are being washed</em>, they are shredded.<br>In which version do the two steps happen at the same time?","options":["Version A","Version B","They mean the same"],"correctIndex":1,"nudge":"两句只差在动词：have been washed 和 are being washed。哪个是「已经洗完」，哪个是「正在洗」？","explanation":"B：are being washed = 正在洗，边洗边切。原文的 have been washed = 已经洗完，切碎排在后面。<br><strong>规则 ②</strong>：once / after / when + have been done（are done 也可以）→ 强调这一步做完，才开始下一步。写流程图时很常用。","subSkill":"passive_with_complex_tenses"},{"question":"第二段：<em>As the hot plastic cools, it hardens into long, thin fibres, which are spun into yarn.</em><br>Which step needs a worker or a machine: hardening or spinning?","options":["Both of them do.","Only hardening does.","Only spinning does."],"correctIndex":2,"nudge":"热塑料冷下来以后，还需要有人让它变硬吗？纱线会自己纺出来吗？","explanation":"只有纺纱要人或机器做：are spun。变硬是冷却后自己发生的，所以用主动 hardens。<br><strong>规则 ③</strong>：有人做的步骤用被动，谁做不重要就不写 by…；自己发生的变化用主动。","subSkill":"active_vs_passive_by_meaning"},{"question":"最后一段：<em>It is often claimed that recycling is the answer to plastic waste. However, …</em><br>Does the writer think recycling is the answer to plastic waste?","options":["No, the writer disagrees.","Yes, this is the writer's own view.","The writer doesn't say."],"correctIndex":0,"nudge":"It is claimed 说的是谁的看法？再看紧跟着的 However。","explanation":"不认为。It is often claimed that… 先摆出别人常说的观点，作者接着用 However 反驳。<br><strong>规则 ④</strong>：It is claimed / believed / said (that) + 完整的句子 → 有人这么说，不点名是谁，作者也不一定同意。","subSkill":"passive_reporting_verbs_it_is_claimed"},{"question":"最后一段：<em>…only around nine per cent of all plastic waste ever produced is estimated to have been recycled…</em><br>Is the writer talking about recycling that has already happened?","options":["No, it is a plan for the future.","Yes, it happened before now.","No, it is happening right now."],"correctIndex":1,"nudge":"is estimated 是现在的估计。to have been recycled 里有 have，说的是比现在早，还是比现在晚？","explanation":"是已经发生的回收：估计是现在做的，回收发生在之前。<br><strong>规则 ⑤</strong>：主语 + is said / believed / estimated to do → 说现在的情况；to have done（被动：to have been done）→ 说更早的事。","subSkill":"passive_reporting_verbs_it_is_claimed"},{"question":"你来试试：流程图上写着「砖坯成型 → 放着自然晾干」。想写「砖坯成型以后，放在一边让它自己干」，哪句对？","options":["Once the bricks have shaped, they are left to be dried.","Once the bricks have been shaped, they are leaving to dry.","Once the bricks have been shaped, they are left to dry."],"correctIndex":2,"nudge":"先分三件事：成型、放着、晾干，各是谁做的？哪件已经做完了？再用规则 ①②③。","explanation":"成型是人做的、已经做完 → have been shaped；放着是人放 → are left；干是砖自己干 → to dry。have shaped 少了 been，成了砖去塑造别的东西；are leaving 是「它们正要离开」。","subSkill":"active_vs_passive_by_meaning"}],"tip":"【先问：这一步是谁做的？】\n\n① 东西被处理 → be + 过去分词，be 不能少：are sorted、need to be removed\n② once / after + have been done（are done 也可以）→ 强调这一步做完，才开始下一步\n③ 有人做的用被动，谁做不重要就不写 by…；自己发生的变化用主动：cools、rises\n④ It is claimed / believed (that) + 完整句子 → 有人这么说，不点名是谁\n⑤ 主语 + is said to do → 说现在；is said to have done → 说更早的事\n⑥ 时态看 be：was built（某年建成）、has been built（已建成）、is being built（正在建）\n⑦ have / get + 东西 + done → 请别人做；也能说倒霉事：I had my phone stolen\nhappen、occur、rise、consist of 没有被动。\n\n【例句】\n✔ Once the bottles have been washed, they are shredded into small flakes.（流程）\n✔ Only nine per cent of plastic waste is estimated to have been recycled.（Task 2 引数据）\n\n【常见错误】\n✘ The caps **need to remove** at this stage. → need to be removed（见 ①）\n✘ Overall, the process **is consisted of** six stages. → consists of（consist of 没有被动）\n✘ It is believed that the factory **built** in 1990. → … the factory was built in 1990（见 ①）\n✘ 理发店剪的头发：I **cut my hair** yesterday. → I had my hair cut（见 ⑦）"}},"4":{"discover":{"story":{"title":"写作 Task 2 范文节选：今天的堵车，昨天的决定","text":"读的时候想一想：作者认为今天堵车的根源是什么？蓝色的句子下面会逐句问你。\nQuestion: In many cities, traffic congestion is getting worse. What are the main causes of this problem, and what measures could be taken to solve it?\nTraffic jams are usually blamed on the number of cars on the road today, but the roots of the problem often lie in decisions made decades ago. In the 1980s, some fast-growing cities built metro lines, while others chose to widen their roads. If the second group had made the same choice, their streets would not be so congested today. Cities in the first group, by contrast, are now reaping the benefits: without those early metro lines, their commuters would be spending hours in traffic every day.\nAs for solutions, the most effective measure is to expand public transport, provided that fares remain affordable for ordinary workers. A new metro line can take ten years to build, so governments cannot afford to wait. Should fuel prices rise sharply in the future, a city with a reliable metro network will cope far better than one that depends on cars.\nIn short, today's congestion is largely the result of yesterday's planning. Had more cities thought about the long term, the problem would be far less serious now. The choices that leaders make in this decade will shape traffic for the next generation.","highlights":["had made the same choice","would not be so congested today","without those early metro lines","would be spending hours in traffic","provided that fares remain affordable","Had more cities thought about the long term","would be far less serious now"]},"questions":[{"question":"第一段：<em>If the second group had made the same choice, their streets would not be so congested today.</em><br>Did the second group of cities build metro lines? Are their streets congested today?","options":["Yes, they did. No, they aren't.","No, they didn't. No, they aren't.","No, they didn't. Yes, they are."],"correctIndex":2,"nudge":"注意 if 后面的 had made：作者是在说当年真的这么做了，还是在假设？（第一段前面说：some cities built metro lines, while others chose to widen their roads.）","explanation":"没修（它们当年拓宽了马路），所以今天很堵。<br><strong>规则 ①</strong>：if + had done = 过去其实没发生；would not be 也是假设，事实正好相反。","subSkill":"mixed_conditionals_past_to_present"},{"question":"比较原文这半句的两种写法：<br>A. …their streets <em>would not be</em> so congested.<br>B. …their streets <em>would not have been</em> so congested.<br>Which one is about the streets <strong>today</strong>?","options":["A","B","Both of them"],"correctIndex":0,"nudge":"原文这半句后面还有个 today。哪种写法能和 today 放在一起？","explanation":"A。would + 原形 说现在；would have been 说过去某个时候。<br><strong>规则 ②</strong>：条件在过去，结果可以在现在——两半句各看各的时间（这叫 mixed conditional）。","subSkill":"mixed_conditionals_past_to_present"},{"question":"第一段：<em>Cities in the first group, by contrast, are now reaping the benefits: without those early metro lines, their commuters would be spending hours in traffic every day.</em><br>Do the cities in the first group have metro lines? Do their commuters spend hours in traffic every day?","options":["No, they don't. Yes, they do.","Yes, they do. Yes, they do.","Yes, they do. No, they don't."],"correctIndex":2,"nudge":"第一类城市到底有没有地铁？would 说的是事实，还是假设？","explanation":"第一类城市<strong>有</strong>地铁，would 在假设「要是没有」。<br><strong>规则 ③</strong>：Without + 名词 = 要不是有…；口语也常说 If it weren't for…。别写 If not because of。","subSkill":"implied_conditionals_with_otherwise_but_for"},{"question":"第二段：<em>…the most effective measure is to expand public transport, provided that fares remain affordable for ordinary workers.</em><br>Does the writer support expanding public transport?","options":["Yes, but only if fares stay low.","No, because fares will be too high.","Yes, however high the fares are."],"correctIndex":0,"nudge":"provided that 后面是一个条件。如果这个条件不满足，作者还支持吗？","explanation":"支持，但有前提：票价得负担得起。<br><strong>规则 ④</strong>：if / provided that / unless 后面说将来，用一般现在时（remain），不用 will remain。","subSkill":"conditional_like_structures_suppose_provided"},{"question":"第三段：<em>Had more cities thought about the long term, the problem would be far less serious now.</em><br>Did enough cities think about the long term back then?","options":["Yes, most of them did.","No, too few of them did.","We can't tell from this."],"correctIndex":1,"nudge":"Had 在句首、没有 if。试着把它还原成 If more cities ___ about the long term…","explanation":"Had more cities thought = If more cities had thought，和问题 1 一样：过去没发生。<br><strong>规则 ⑤</strong>：去掉 if、把 had 提到主语前，意思不变，更正式。","subSkill":"inverted_conditionals_had_were_should"},{"question":"你来试试：<br>Fact: I didn't learn the piano as a child, so I can't play for my friends now.<br>Imagine it was different. Which sentence is correct?","options":["If I learned the piano as a child, I could play for my friends now.","If I had learned the piano as a child, I could play for my friends now.","If I had learned the piano as a child, I could have played for my friends now."],"correctIndex":1,"nudge":"先想两个时间：学钢琴是什么时候？弹给朋友听是什么时候？再用规则 ① 和 ②。","explanation":"学琴在过去、其实没学 → had learned（规则 ①）；弹琴在现在 → could play（规则 ②）。could have played 说的是过去，和 now 冲突。","subSkill":"mixed_conditionals_past_to_present"}],"tip":"【条件和结果，各看各的时间】\n\n① if + had done → 过去其实没发生\n② 结果在现在 → would do；结果在过去 → would have done\n③ Without + 名词 = 要不是有…（But for / Were it not for 更正式）\n④ if / provided that / unless 说将来，用一般现在时，不用 will\n⑤ Had + 主语 + done = If … had done，更正式；否定写 Had + 主语 + not done\n⑥ 现实可能 → if + 现在时，主句 will；只是假设 → if + 过去时，主句 would\n⑦ Should + 主语 + 原形 = 正式的 if，常带「万一」语气\n逗号：从句放句首，后面加逗号；放句尾，不加。\n\n【例句】\n✔ If those cities had invested back then, their streets would not be so congested today.（过去 → 现在）\n✔ If my English were better, I would have got that job last year.（现在 → 过去）\n\n【常见错误】\n✘ If I had chosen engineering, I **would have been** an engineer now. → would be\n✘ If the government **would provide** more funding, … → provides（现实可能）/ provided（假设），见 ⑥\n✘ **Unless** the government **does not** act, … → Unless the government acts\n✘ **If not because of** my teacher, … → If it hadn't been for / If not for / Without my teacher"},"mission":{"title":"写作 Task 2 段落：昨天的决定，今天的城市","description":"写一个雅思 Task 2 主体段（3 句）：先举一个「过去没做好」的决定和它今天的后果，再举一个「做对了」的决定，最后提一条建议（写法自选）。至少用对本单元的 2 种写法，不必每句都用条件句。AI 老师会按雅思「语法多样性与准确性」给你反馈。","scenario":"题目：Some people believe that many of the problems cities face today are the result of poor planning in the past. To what extent do you agree or disagree?<br>你只写正文里的一段。话题任选：交通、房价、空气、绿地、教育、医疗……用你熟悉的城市或家乡举例。","grammarType":"mixed_conditionals_past_to_present","scaffolds":[{"prefix":"Many of the problems cities face today were created decades ago.","suffix":"","hint":"举一个过去没做的决定 + 今天的后果：If … had …, … would (not) … today.","grammarCheck":"mixed_conditionals_past_to_present","example":"If my city had protected its green spaces in the 1990s, its summers would not be so unbearably hot today."},{"prefix":"However, some past decisions have clearly paid off.","suffix":"","hint":"举一个做对了的决定：Without / But for + 名词, … would …","grammarCheck":"implied_conditionals_with_otherwise_but_for","example":"Without the free school-meal programme introduced in the 2000s, many children in my city would still go to school hungry."},{"prefix":"Today's leaders must therefore plan for the long term.","suffix":"","hint":"提一条建议，结构自选：可以用 Should …, … will …，也可以用 … provided that …，或者干脆不用条件句。","grammarCheck":"conditionals_in_formal_writing","example":"Should housing prices keep rising, the government will need to build far more affordable homes."}]},"levels":{"1":[{"id":"gen-4-1-100","type":"choice","instruction":"〔口语 Part 2〕事实：我当年没接受北京那份工作，现在还在老家上班。空格填哪个，才符合事实？","sentence":"If I had accepted the job in Beijing, I ___ in my hometown now.","options":["wouldn't have worked","won't work","wouldn't be working","didn't work"],"correctIndex":2,"explanation":"现在还在老家 → 结果在现在，用 wouldn't be working。wouldn't have worked 说的是过去，和 now 对不上。","subSkill":"mixed_conditionals_past_to_present"},{"id":"gen-4-1-101","type":"choice","instruction":"〔写作 Task 2〕读句子，回答问题。原句：If the school had banned phones in class years ago, its students' results would be better.","sentence":"Did the school ban phones in class? How are the students' results now?","options":["It banned them, and the results are excellent now.","It didn't ban them, and the results could be better.","It didn't ban them, and the results are excellent now.","It banned them, but the results could be better."],"correctIndex":1,"explanation":"had banned 和过去相反：当年没禁。would be better 和现在相反：现在成绩不够好。原句里没有 now，would + 原形 本身就说明是现在。","subSkill":"mixed_conditionals_past_to_present"},{"id":"gen-4-1-102","type":"choice","instruction":"〔口语 Part 1〕读句子，回答问题。原句：Without online banking, I would have to queue at the bank every week.","sentence":"Does the speaker queue at the bank every week?","options":["Yes, because he can't bank online.","Only sometimes.","No, he banks online.","The sentence doesn't say."],"correctIndex":2,"explanation":"Without online banking = 要是没有网上银行（假设）。事实：他在用，所以不用排队。would have to 是「就得…」，不是 would have done。","subSkill":"implied_conditionals_with_otherwise_but_for"},{"id":"gen-4-1-103","type":"choice","instruction":"〔写作 Task 2〕读句子，回答问题。原句：Should the economy slow down, young graduates will be the first to suffer.","sentence":"Does the writer think the economy will slow down?","options":["It might. It's not certain.","Yes, it certainly will.","It has already slowed down.","No, it certainly won't."],"correctIndex":0,"explanation":"Should 放句首 = 正式的 if，常带「万一」语气：有可能，但说不准。说的是真实可能的将来，所以主句用 will。","subSkill":"inverted_conditionals_had_were_should"},{"id":"gen-4-1-104","type":"choice","instruction":"〔写作 Task 2〕读句子，回答问题。原句：Had the factory been closed earlier, the river would be much cleaner.","sentence":"What happened to the factory? What is the river like now?","options":["It closed early enough. The river is clean now.","It closed too late. The river isn't very clean.","It closes next year. The river will be cleaner.","It never closed. The river used to be dirty."],"correctIndex":1,"explanation":"Had the factory been closed = If the factory had been closed：其实关得晚。would be much cleaner 说现在：河还不够干净。","subSkill":"inverted_conditionals_had_were_should"},{"id":"gen-4-1-105","type":"scenario","instruction":"读考生的回答，回答问题：Does the candidate still live in that small town?","context":"雅思口语 Part 1 · Hometown","dialogue":[{"speaker":"examiner","text":"Examiner: Where did you live as a child?"},{"speaker":"player","text":"In a small town in Anhui. If my parents hadn't moved to Shanghai when I was ten, I'd probably still be living there."}],"options":["No, he moved away as a child.","Yes, he still lives there.","He only moved there at ten.","He plans to move back next year."],"correctIndex":0,"explanation":"hadn't moved：其实搬走了。I'd still be living there 说的是现在：他现在不住那里。口语里这样把过去的变化和现在连起来，很自然。","subSkill":"mixed_conditionals_past_to_present"},{"id":"gen-4-1-106","type":"choice","instruction":"〔写作 Task 2〕读句子，回答问题。原句：A congestion charge can work well, provided that the money is spent on public transport.","sentence":"When does the writer think a congestion charge works well?","options":["Always, no matter where the money goes.","It fails if the money goes to public transport.","Only after public transport gets better.","Only if the money goes to public transport."],"correctIndex":3,"explanation":"provided that = 前提是…：钱用在公共交通上，拥堵费才有效。条件说的是一般情况，用一般现在时 is spent，不用 will be spent。","subSkill":"conditional_like_structures_suppose_provided"},{"id":"gen-4-1-107","type":"match","instruction":"〔口语 Part 2〕前半句都在假设过去（If I had saved more… / Without that loan… / Had we known…）。只看后半句：结果在现在，还是在过去？","left":["…, I would be richer.","…, I could have bought that flat.","…, we would still be renting.","…, we would have sold earlier."],"right":["The result is about the present.","The result is about the past."],"correctPairs":[[0,0],[1,1],[2,0],[3,1]],"explanation":"would be、would still be renting 说现在；could have bought、would have sold 说过去。条件都在过去，结果却可以落在两个时间。","subSkill":"mixed_conditionals_past_to_present"}],"2":[{"id":"gen-4-2-100","type":"choice","instruction":"〔写作 Task 2〕当年没投资，影响一直到今天。选出合适的形式。","sentence":"If governments had invested in renewable energy earlier, we ___ so dependent on coal.","options":["would not have been","would not be","will not be","are not"],"correctIndex":1,"explanation":"影响到今天 → 结果在现在：would not be。would not have been 说过去某个时候；will not be 是对将来的真实预测；are not 是陈述事实。","subSkill":"mixed_conditionals_past_to_present"},{"id":"gen-4-2-101","type":"choice","instruction":"〔写作 Task 2〕选出合适的形式。","sentence":"If the warning had been issued earlier, fewer people ___ in the 2008 floods.","options":["would die","had died","would have died","would have been died"],"correctIndex":2,"explanation":"2008 年的洪水是过去 → would have died（结果在现在才用 would do）。die 没有被动，would have been died 是错的。","subSkill":"mixed_conditionals_past_to_present"},{"id":"gen-4-2-102","type":"choice","instruction":"〔口语 Part 2〕事实：我英语一直不够好，所以去年没拿到那份工作。","sentence":"If my English were better, I ___ that job last year.","options":["would get","had got","would have get","would have got"],"correctIndex":3,"explanation":"英语一直不够好（现在）→ were；没拿到工作是去年的事 → would have got（美式 gotten）。混合条件也可以反过来：现在的情况 → 过去的结果。","subSkill":"mixed_conditionals_present_to_past"},{"id":"gen-4-2-103","type":"fill","instruction":"〔口语 Part 2〕想说「要不是导师的建议，我现在可能在读完全不同的专业」。补上句子的开头。","sentence":"___ my tutor's advice, I would probably be studying a completely different subject now.","hint":"要不是…","acceptableAnswers":["Without","But for","If it hadn't been for","If it had not been for","If it weren't for","If it were not for","If it wasn't for","If it was not for","Had it not been for","Were it not for","If not for","If I hadn't followed","If I had not followed","If I hadn't taken","If I had not taken","Had I not followed","Had I not taken","If I hadn't listened to","If I hadn't had"],"explanation":"「要不是…」最常用 Without；也可以说 If it hadn't been for…。后半句说现在 → would be studying。别写 If not because of。","subSkill":"implied_conditionals_with_otherwise_but_for"},{"id":"gen-4-2-104","type":"choice","instruction":"〔写作 Task 2〕想说「万一将来开征糖税」，选哪个开头？","sentence":"___ food companies will have to change their recipes.","options":["If a sugar tax will be introduced,","Had a sugar tax been introduced,","Should a sugar tax be introduced,"],"correctIndex":2,"explanation":"「万一将来…」→ Should + 主语 + 原形，主句用 will 没问题。Had … been introduced 说的是过去；if 从句说将来不用 will。","subSkill":"inverted_conditionals_had_were_should"},{"id":"gen-4-2-105","type":"scenario","instruction":"考生想说「要是没有手机地图，我出门肯定老迷路」。选出意思准确的一句。","context":"雅思口语 Part 1 · Maps","dialogue":[{"speaker":"examiner","text":"Examiner: Do you use your phone to find your way around?"}],"options":["Without map apps, I would get lost all the time.","Without map apps, I would have got lost all the time.","Without map apps, I will get lost all the time.","If not because of map apps, I get lost all the time."],"correctIndex":0,"explanation":"事实是他有手机地图 → 和现在相反的假设：would get lost。would have got lost 说过去；will 表示真会发生；If not because of 是中文直译。","subSkill":"implied_conditionals_with_otherwise_but_for"},{"id":"gen-4-2-106","type":"choice","instruction":"〔写作 Task 2〕想说「只要监管到位，网约车对城市有好处」。","sentence":"Ride-hailing apps benefit cities ___ they are properly regulated.","options":["unless","even though","in case","as long as"],"correctIndex":3,"explanation":"as long as = 只要（= provided that）。unless = 除非，意思反了；even though = 尽管；in case = 以防万一。","subSkill":"conditional_like_structures_suppose_provided"},{"id":"gen-4-2-107","type":"choice","instruction":"〔写作 Task 2〕选出最合适的连接词。","sentence":"Many people now work from home. ___, the roads would be even busier during rush hour.","options":["However","Therefore","Unless","Otherwise"],"correctIndex":3,"explanation":"Otherwise = 要不是这样（要是大家不在家办公），后面接 would 表示假设。However、Therefore 没有假设的意思；Unless 是连词，后面要接从句。","subSkill":"implied_conditionals_with_otherwise_but_for"},{"id":"gen-4-2-108","type":"match","instruction":"〔写作 Task 2〕两句只差两处。作者的态度有什么不同？连线。","left":["If the government provides more funding, more students will go to university.","If the government provided more funding, more students would go to university."],"right":["The writer thinks this is a realistic proposal.","The writer is only imagining it."],"correctPairs":[[0,0],[1,1]],"explanation":"provides … will：现实可能，作者真在提建议。provided … would：只是假设，作者觉得不太会发生。两半句要配套：现在时配 will，过去时配 would。","subSkill":"real_vs_hypothetical_conditionals"}],"3":[{"id":"gen-4-3-100","type":"fill","instruction":"〔口语 Part 2〕把两个事实合成一句「要是当年…现在就…」。原句：I didn't learn to swim as a child. I'm afraid of deep water now.","sentence":"If I ___ to swim as a child, I ___ afraid of deep water.","acceptableAnswers":["had learned","would not be"],"blankAnswers":[["had learned","had learnt","had been taught","had learned how","had learnt how"],["would not be","might not be","would not be so","might not be so","would not be as","would be less","would be much less","would probably not be"]],"explanation":"两个事实都反过来说：当年没学（过去）→ had learned；现在怕水（现在）→ wouldn't be。句子里没有 now，时间要从原句里判断。","subSkill":"mixed_conditionals_past_to_present"},{"id":"gen-4-3-101","type":"fill","instruction":"〔写作 Task 2〕把原因和结果合成一句。原句：The government did not regulate plastic packaging in the 2000s. As a result, our rivers and beaches are full of plastic today.","sentence":"If the government ___ plastic packaging in the 2000s, our rivers and beaches ___ full of plastic.","acceptableAnswers":["had regulated","would not be"],"blankAnswers":[["had regulated","had controlled","had restricted","had limited","had banned","had curbed","had reduced"],["would not be","might not be","would not be so","might not be so","would not be as"]],"explanation":"2000 年代没管（过去）→ had regulated；今天满是塑料（现在）→ would not be。结果在现在，不能写 would not have been。","subSkill":"mixed_conditionals_past_to_present"},{"id":"gen-4-3-102","type":"fill","instruction":"〔写作 Task 2 · 结论段〕用 Had 开头改写，让句子更紧凑。原句：If the city had planned more green spaces, residents would be healthier today.","sentence":"___ more green spaces, residents would be healthier today.","acceptableAnswers":["Had the city planned","Had the city planned for","Had the city built","Had the city created","Had the city provided"],"explanation":"去掉 if，把 had 放到主语前面：Had the city planned … = If the city had planned …。意思一样，更正式，适合结论段。","subSkill":"inverted_conditionals_had_were_should"},{"id":"gen-4-3-103","type":"reorder","instruction":"〔口语 Part 2〕排出这句话：要不是奶奶一直鼓励我，我今天不会成为老师。","words":["a","teacher","Without","I","encouragement,","today.","my","wouldn't","grandmother's","be"],"correctSentence":"Without my grandmother's encouragement, I wouldn't be a teacher today.","acceptableSentences":["I wouldn't be a teacher today without my grandmother's encouragement."],"explanation":"Without + 名词 代替整个 if 从句（= If my grandmother hadn't encouraged me）。鼓励在过去，结果在今天 → wouldn't be … today。","subSkill":"implied_conditionals_with_otherwise_but_for"},{"id":"gen-4-3-104","type":"fill","instruction":"〔写作 Task 2〕把 but only if 换一种同样表示『只有…才』的说法。原句：Remote work is good for productivity, but only if employees have clear goals.","sentence":"Remote work is good for productivity, ___ employees have clear goals.","acceptableAnswers":["provided that","providing that","provided","providing","as long as","so long as","on condition that"],"explanation":"provided (that)、as long as、on condition that 都表示「只有…才」。条件从句说一般情况或将来，用一般现在时 have，不用 will have。","subSkill":"conditional_like_structures_suppose_provided"},{"id":"gen-4-3-105","type":"fill","instruction":"〔口语 Part 1 · Work or studies〕把两句合成一句。原句：I'm not good with numbers, so I didn't choose accounting.","sentence":"If I ___ good with numbers, I ___ accounting.","acceptableAnswers":["were","would have chosen"],"blankAnswers":[["were","was","had been"],["would have chosen","might have chosen","would have studied","might have studied","would have done","would have taken","would have majored in","could have chosen","could have studied","would have gone into","would have picked"]],"explanation":"不擅长数字一直如此 → were（口语常说 was；只说当时不擅长，had been 也对）；没选会计是过去的事 → would have chosen。","subSkill":"mixed_conditionals_present_to_past"},{"id":"gen-4-3-106","type":"fill","instruction":"〔写作 Task 2〕用 otherwise 把两句连起来。原句：Fortunately, the hospital had a backup generator. Thanks to it, the patients were safe during the power cut.","sentence":"Fortunately, the hospital had a backup generator; otherwise, many patients ___ at risk during the power cut.","acceptableAnswers":["would have been","could have been","might have been","would have been put","might have been put","could have been put"],"explanation":"otherwise = 要不是有发电机。说的是那次停电时的结果，在过去 → would have been。","subSkill":"implied_conditionals_with_otherwise_but_for"},{"id":"gen-4-3-107","type":"reorder","instruction":"〔写作 Task 2 · 建议段〕排出这句：万一政策失败，政府必须准备好调整方向。","words":["the","must","Should","ready","policy","to","fail,","government","change","be","the","course."],"correctSentence":"Should the policy fail, the government must be ready to change course.","acceptableSentences":["The government must be ready to change course should the policy fail."],"explanation":"Should + 主语 + 原形（fail）= If the policy fails，带「万一」语气，适合建议段。fail 用原形，不加 -s，也不加 to。","subSkill":"conditionals_in_formal_writing"}],"4":[{"id":"gen-4-4-100","type":"fill","instruction":"〔口语 Part 1 · 考生常见错误〕事实：父母 2015 年没送我出国。有一处时间用错了，在空里写出正确的形式。原句：If my parents sent me abroad in 2015, my English would be much better now.","sentence":"If my parents ___ me abroad in 2015, my English would be much better now.","acceptableAnswers":["had sent"],"explanation":"if 里的一般过去时要么表示和『现在』相反，要么表示过去真实的条件，都不是这里要说的『2015 年其实没送』，所以用 had sent。","subSkill":"mixed_conditionals_past_to_present"},{"id":"gen-4-4-101","type":"error","instruction":"〔口语 Part 2 · 考生常见错误〕他当年没选工程专业。点出用错的部分。","words":["If","I","had chosen","engineering at university,","I","would have been","an engineer","now."],"errorIndex":5,"correction":"would be","explanation":"now 说的是现在的身份 → would be。would have been 是过去的结果，和 now 冲突。高分段考生也常犯这种「时间错位」。","subSkill":"mixed_conditionals_past_to_present"},{"id":"gen-4-4-102","type":"error","instruction":"〔口语 Part 1 · 考生常见错误〕他现在正在英国读书。点出用错的部分。","words":["Without","my parents' support,","I","will","not be studying","in the UK","now."],"errorIndex":3,"correction":"would","explanation":"事实是父母支持了他。Without … 是假设「要是没有」，所以用 would；will 表示真的会发生。","subSkill":"implied_conditionals_with_otherwise_but_for"},{"id":"gen-4-4-103","type":"error","instruction":"〔写作 Task 2 · 考生常见错误〕点出用错的部分。","words":["Hadn't","the doctors","acted","quickly,","the outbreak","would have been","far worse."],"errorIndex":0,"correction":"Had the doctors not acted","explanation":"否定倒装是 Had + 主语 + not done：Had the doctors not acted…。没有 Hadn't the doctors… 这种写法。","subSkill":"inverted_conditionals_had_were_should"},{"id":"gen-4-4-104","type":"fill","instruction":"〔写作 Task 2 · 考生常见错误〕有一个动词用错了，在空里写出正确的形式。原句：Should the university raises its fees, many students will have to take part-time jobs.","sentence":"Should the university ___ its fees, many students will have to take part-time jobs.","acceptableAnswers":["raise","increase"],"explanation":"Should 放到句首后，主语后面跟动词原形：Should the university raise …（= If the university raises …）。不再加 -s。","subSkill":"inverted_conditionals_had_were_should"},{"id":"gen-4-4-105","type":"choice","instruction":"〔写作 Task 2 · 考生常见写法〕这句意思反了，选出改对的开头。原句：Unless people do not change their eating habits, obesity rates will keep rising.","sentence":"___ obesity rates will keep rising.","options":["If people change their eating habits,","Unless people will change their eating habits,","Unless people change their eating habits,","Unless people don't change their eating habits,"],"correctIndex":2,"explanation":"unless = 如果不，再加 not 意思就反了：Unless people change…（= If people don't change…）。说将来也不用 will。","subSkill":"conditional_like_structures_suppose_provided"},{"id":"gen-4-4-106","type":"choice","instruction":"〔口语 Part 2 · 考生常见写法〕这句是中文直译，选出自然的改法。原句：If not because of my teacher, I would have given up English.","sentence":"___ I would have given up English.","options":["Because of my teacher,","If it hadn't been for my teacher,","If without my teacher,","If it wasn't because of my teacher,"],"correctIndex":1,"explanation":"「要不是…」说 If it hadn't been for / Without …。If without、If it wasn't because of 是中文直译；Because of 意思反了。","subSkill":"implied_conditionals_with_otherwise_but_for"},{"id":"gen-4-4-107","type":"choice","instruction":"〔写作 Task 2 · 考生常见写法〕作者认为这是现实的建议，两半句不配套，选出改对的句子。原句：If the government provides more funding, more students would go to university.","options":["If the government will provide more funding, more students will go to university.","If the government provided more funding, more students will go to university.","If the government provides more funding, more students would have gone to university.","If the government provides more funding, more students will go to university."],"correctIndex":3,"explanation":"现实的建议 → if + 现在时，主句 will：provides … will go。if 从句不用 will；另外两句时态不配套。","subSkill":"real_vs_hypothetical_conditionals"},{"id":"gen-4-4-108","type":"error","instruction":"〔写作 Task 2 · 考生常见错误〕作者只是假设，觉得不太可能。点出用错的部分。","words":["If","the government","would provide","more funding,","more students","would go","to university."],"errorIndex":2,"correction":"provided","explanation":"表示条件时，if 那半句一般不用 would：If the government provided more funding（假设），主句才用 would go。","subSkill":"real_vs_hypothetical_conditionals"},{"id":"gen-4-4-109","type":"error","instruction":"〔写作 Task 2 · 考生常见错误〕点出用错的部分。","words":["Provided that","the government","will fund","the scheme,","it","can be launched","next year."],"errorIndex":2,"correction":"funds","explanation":"provided that 后面是条件，说将来也用一般现在时 funds；will / can 这类情态动词放在结果那半句。","subSkill":"conditional_like_structures_suppose_provided"}],"5":[{"id":"gen-4-5-100","type":"fill","instruction":"〔写作 Task 2〕用一句条件句改写，说出『本来可以不一样』。原句：The government didn't build enough affordable housing in the past, so many young people can't buy a home now.","sentence":"___ enough affordable housing in the past, many young people ___ a home.","acceptableAnswers":["Had the government built","could buy"],"blankAnswers":[["Had the government built","If the government had built","Had the government provided","If the government had provided","Had there been","If there had been","Had the government invested in","If the government had invested in","Had governments built","If governments had built","Had the government constructed","If the government had constructed"],["could buy","could afford","would be able to buy","would be able to afford","could own","would own","might own","could afford to buy","might be able to buy","might be able to afford","could have","would have"]],"explanation":"过去没建 → Had the government built（或 If … had built）；现在买不起 → could buy。原句用 so 只说因果，条件句把「本来可以不一样」说了出来。","subSkill":"mixed_conditionals_past_to_present"},{"id":"gen-4-5-101","type":"fill","instruction":"〔写作 Task 2〕用一个短语代替整个 if 从句。原句：If scholarships did not exist, many talented students from poor families would never go to university.","sentence":"___ scholarships, many talented students from poor families would never go to university.","acceptableAnswers":["Without","But for","If it were not for","If it weren't for","If it was not for","If it wasn't for","Were it not for","If not for","In the absence of","If there were no"],"explanation":"Without / But for + 名词 代替整个 if 从句。奖学金现在就有，说的是现在，所以也可以写 If it weren't for，最正式是 Were it not for。","subSkill":"implied_conditionals_with_otherwise_but_for"},{"id":"gen-4-5-102","type":"scenario","instruction":"考生想说『要不是搬到深圳，我现在可能还在舅舅店里干活』。哪个回答把这层意思说准确了？","context":"雅思口语 Part 2 · 题卡：Describe a decision that changed your life … and explain how it changed your life","dialogue":[],"options":["Well, if I hadn't moved to Shenzhen, I'd probably still be working in my uncle's shop.","It changed my life a lot. Because I moved to Shenzhen, I have a good job now.","Well, if I didn't move to Shenzhen, I would still work in my uncle's shop.","Well, had I not moved to Shenzhen, I would have still been working in my uncle's shop now."],"correctIndex":0,"explanation":"第 1 个准确。第 2 个语法正确，但意思成了「因为搬了所以工作好」，没说出「要不是…现在还会…」；第 3 个 didn't move 时间错；第 4 个 would have … now 冲突。","subSkill":"mixed_conditionals_past_to_present"},{"id":"gen-4-5-103","type":"fill","instruction":"〔写作 Task 2〕补全这段论证，用括号里的动词。先想清楚每句的结果在什么时间。","sentence":"Twenty years ago, most cities in the region ignored cycling. Had they built safe cycle lanes back then, far more people ___ (cycle) to work today.\nA few cities did invest early. Without that investment, their air ___ (be) much dirtier now.\nShould other cities follow their example, they ___ (see) results within a decade.","acceptableAnswers":["would cycle","would be","will see"],"blankAnswers":[["would cycle","would be cycling","might cycle","could cycle","might be cycling","could be cycling","would probably cycle"],["would be","might be","could be"],["will see","would see","could see","may see","might see","should see"]],"explanation":"① 当年没修 → 今天：would cycle。② 事实是投资了，without 假设没有 → 现在：would be。③ Should = 万一将来：will see（would see 也行）。","subSkill":"mixed_conditionals_past_to_present"},{"id":"gen-4-5-104","type":"fill","instruction":"〔写作 Task 2〕合成一句，用一个更正式的开头。原句：The volunteers kept the library open. Without them, it would have closed.","sentence":"___ the volunteers, the library would have closed.","acceptableAnswers":["Had it not been for","If it hadn't been for","If it had not been for","But for","Without","If not for","If it weren't for","If it wasn't for","Were it not for"],"explanation":"Had it not been for / But for … 比 Without 更正式（= 要不是…）。图书馆当时没关，这是过去的结果 → would have closed。","subSkill":"implied_conditionals_with_otherwise_but_for"},{"id":"gen-4-5-105","type":"fill","instruction":"〔写作 Task 2 · 建议段〕不用 if，把这句改得更正式。原句：If there is a shortage of teachers in the future, the government will need to raise salaries.","sentence":"___ a shortage of teachers in the future, the government will need to raise salaries.","acceptableAnswers":["Should there be","In the event of","Were there to be"],"explanation":"Should there be …（there is 倒装后 is 变原形 be）= 万一将来…；也可以用 In the event of + 名词。主句保留 will。","subSkill":"conditionals_in_formal_writing"},{"id":"gen-4-5-106","type":"fill","instruction":"〔写作 Task 2〕把原因和结果合成一句。原句：Many graduates cannot find jobs in their field. This is partly because universities did not update their courses ten years ago.","sentence":"If universities ___ their courses ten years ago, more graduates ___ jobs in their field today.","acceptableAnswers":["had updated","would find"],"blankAnswers":[["had updated","had modernised","had modernized","had revised","had reformed"],["would find","could find","would be finding","would have","would be able to find","might find"]],"explanation":"十年前没更新（过去）→ had updated；现在找不到对口工作（现在）→ would find / could find。","subSkill":"mixed_conditionals_past_to_present"},{"id":"gen-4-5-107","type":"fill","instruction":"〔口语 Part 3〕考官问：Why do so many young people leave small towns? 补全考生的回答。","sentence":"Small towns just don't offer enough jobs. If they ___ (offer) more opportunities, a lot of my friends ___ (not / leave) after graduation.","acceptableAnswers":["offered","would not have left"],"blankAnswers":[["offered","did offer","had offered"],["would not have left","might not have left","would never have left"]],"explanation":"offered（小镇一直如此，现在的情况）和 had offered（他们毕业那时没有机会）都对；结果是过去的事 → wouldn't have left。","subSkill":"mixed_conditionals_present_to_past"},{"id":"gen-4-5-108","type":"fill","instruction":"〔口语 Part 2 · 结束追问〕考官：Would your life be different if you hadn't gone to university? 用括号里的动词补全回答。","sentence":"If I hadn't gone to university, I ___ (not meet) my closest friends, and I probably ___ (not work) in finance now.","acceptableAnswers":["wouldn't have met","wouldn't be working"],"blankAnswers":[["wouldn't have met","would never have met","might not have met"],["wouldn't be working","wouldn't work"]],"explanation":"交到朋友是过去的事 → wouldn't have met；在金融业工作是现在 → wouldn't be working。一个回答里两种时间都用对，就是评分标准说的 flexibility。","subSkill":"mixed_conditionals_past_to_present"}]}},"5":{"levels":{"1":[{"id":"gen-5-1-100","type":"choice","instruction":"〔写作 Task 2〕读句子，回答问题。原句：The company employs 200 people, most of whom work from home.","sentence":"How many of the company's employees work from home?","options":["All 200 of the employees.","Most of the employees.","Only a few of the employees.","None of them do."],"correctIndex":1,"explanation":"most of whom = 他们（这 200 名员工）当中的大多数。whom 指回逗号前面的人，后面的 work 是这些人的动作。","subSkill":"non_defining_relative_with_quantifiers_many_of_which"},{"id":"gen-5-1-101","type":"match","instruction":"〔写作 Task 2〕两句只差两个逗号。各是什么意思？连线。","left":["The villagers who depend on tourism lost their income.","The villagers, who depend on tourism, lost their income."],"right":["Only some villagers lost their income.","All the villagers lost their income."],"correctPairs":[[0,0],[1,1]],"explanation":"没逗号：who… 挑出「靠旅游业的那部分」村民。有逗号：只是补充，说的是全体村民，他们都靠旅游业。逗号一加，意思就变了。","subSkill":"defining_vs_non_defining_relative_clauses"},{"id":"gen-5-1-102","type":"choice","instruction":"〔写作 Task 2〕读句子，回答问题。原句：Many teenagers now spend over six hours a day online, which many teachers blame for poor concentration in class.","sentence":"What do many teachers blame for poor concentration?","options":["Unsuitable content on the internet","The amount of homework students get","Teachers' own use of phones in class","The hours teenagers spend online"],"correctIndex":3,"explanation":"which 指逗号前面整件事：青少年每天上网六小时以上，老师把注意力差归咎于此。which 已做 blame 的宾语，后面不再加 it。","subSkill":"sentential_relative_which_referring_to_clause"},{"id":"gen-5-1-103","type":"match","instruction":"〔写作 Task 2〕只看名词后面的部分：这些人是自己在做，还是被别人做？","left":["workers replaced by robots","workers repairing robots","patients treated at home","nurses visiting patients at home"],"right":["They are doing it.","It is done to them."],"correctPairs":[[0,1],[1,0],[2,1],[3,0]],"explanation":"-ing 是自己在做：workers repairing robots = 修机器人的工人。过去分词是被做：workers replaced by robots = 被机器人取代的工人。","subSkill":"reduced_relative_clauses_with_participles"},{"id":"gen-5-1-104","type":"choice","instruction":"〔写作 Task 1〕读句子，回答问题。原句：The line graph shows that the average age at which children got their first smartphone fell steadily between 2012 and 2022.","sentence":"What does the line graph show falling?","options":["How many children owned a smartphone","How old children were when they got one","How much a child's first smartphone cost","How many smartphones were sold to children"],"correctIndex":1,"explanation":"the average age at which children got their first smartphone = 孩子拿到第一部手机时的平均年龄。下降的是年龄，不是人数。","subSkill":"preposition_fronting_in_relative_clauses"},{"id":"gen-5-1-105","type":"scenario","instruction":"读考生的回答，回答问题：Where are the candidate's old classmates now?","context":"雅思口语 Part 1 · Hometown","dialogue":[{"speaker":"examiner","text":"Examiner: Do many young people stay in your hometown after they finish school?"},{"speaker":"player","text":"Not really. I went to school with about forty kids, most of whom have moved to big cities like Shenzhen."}],"options":["Most are still in their hometown.","All of them have moved to big cities.","Most have moved to big cities.","Only a few have moved away."],"correctIndex":2,"explanation":"most of whom = 那四十个同学当中的大多数，have moved = 已经搬走了。口语里也可以说 and most of them have moved…。","subSkill":"non_defining_relative_with_quantifiers_many_of_which"},{"id":"gen-5-1-106","type":"choice","instruction":"〔写作 Task 2〕读句子，回答问题。原句：Whoever damages public property should pay for the repairs.","sentence":"Who should pay for the repairs, according to the writer?","options":["Only the local government","Anyone who damages it","The workers who repair it","Nobody needs to pay"],"correctIndex":1,"explanation":"Whoever = 任何…的人（anyone who）：谁损坏了公物，谁就付修理费。Whoever damages public property 整块做句子的主语。","subSkill":"relative_clauses_with_whoever_whatever"},{"id":"gen-5-1-107","type":"choice","instruction":"〔写作 Task 2〕读句子，回答问题。原句：The council closed two public libraries, which many elderly residents used every day.","sentence":"What did many elderly residents use every day?","options":["The two public libraries","The decision to close them","The council's own website","A nearby centre for seniors"],"correctIndex":0,"explanation":"这里的 which 指 two public libraries：老人每天用的是图书馆（used them）。which 有时指前面的名词，有时指整件事，要看后半句说得通哪一个。","subSkill":"sentential_relative_which_referring_to_clause"},{"id":"gen-5-1-108","type":"choice","instruction":"〔写作 Task 1〕读句子，回答问题。原句：The chart compares coffee consumption in five countries, two of which saw a fall after 2015.","sentence":"Which countries saw a fall after 2015?","options":["All five countries in the chart","Two countries not in the chart","Two of the five countries","Three of the five countries"],"correctIndex":2,"explanation":"two of which = 这五个国家当中的两个：which 指回 five countries（国家是物）。另外三个国家，这句没说下降。","subSkill":"non_defining_relative_with_quantifiers_many_of_which"}],"2":[{"id":"gen-5-2-100","type":"choice","instruction":"〔写作 Task 2〕想说「其中大多数不到三十岁」，一句话说完。","sentence":"Our city has thousands of food delivery riders, ___ are under thirty.","options":["most of them","most of who","most of whom","most of which"],"correctIndex":2,"explanation":"骑手是人，介词 of 后面用 whom：most of whom。most of them are… 是用逗号硬连两句；of 后面不用 who；which 指物。","subSkill":"non_defining_relative_with_quantifiers_many_of_which"},{"id":"gen-5-2-101","type":"choice","instruction":"〔写作 Task 2〕后半句想说「这件事迫使很多小店关门」，接在逗号后面。","sentence":"Online shopping has grown rapidly, ___ has forced many small shops to close.","options":["which","this","which it","that"],"correctIndex":0,"explanation":"接在逗号后、指前面整件事 → which。this 会让逗号连起两个句子；which 已经代替了这件事，后面不再加 it；that 不放在逗号后面。","subSkill":"sentential_relative_which_referring_to_clause"},{"id":"gen-5-2-102","type":"choice","instruction":"〔写作 Task 2〕作者的意思：护士普遍工资低，也常常加班。选出准确的一句。","options":["Nurses who are poorly paid often work long hours.","Nurses, that are poorly paid, often work long hours.","Nurses, who are poorly paid, often work long hours.","Nurses, they are poorly paid, often work long hours."],"correctIndex":2,"explanation":"说的是所有护士 → 加逗号补充。不加逗号就成了「工资低的那些护士常加班」；逗号后不用 that；they 让两个句子硬连。","subSkill":"defining_vs_non_defining_relative_clauses"},{"id":"gen-5-2-103","type":"choice","instruction":"〔写作 Task 2〕想说「很多人住不起自己上班的那座城市」。","sentence":"Many people cannot afford to live in the city ___ they work.","options":["which","in which","at which","in that"],"correctIndex":1,"explanation":"work in the city → the city in which they work（= where they work）。只写 which 就丢了 in；介词后面不能用 that。","subSkill":"preposition_fronting_in_relative_clauses"},{"id":"gen-5-2-104","type":"choice","instruction":"〔写作 Task 1〕想说「回收的生活垃圾所占的比例」。","sentence":"The proportion of household waste ___ rose from 20% to 45% between 2000 and 2020.","options":["was recycled","which recycled","that recycling","recycled"],"correctIndex":3,"explanation":"垃圾是被回收的 → recycled（= which was recycled）。which recycled 意思反了；was recycled 和 rose 抢谓语；that 后缺动词。","subSkill":"reduced_relative_clauses_with_participles"},{"id":"gen-5-2-105","type":"choice","instruction":"〔口语 Part 3〕想说「住在农村的老人往往没人照顾」。","sentence":"Older people ___ in the countryside often have no one to look after them.","options":["lived","living","are living","who living"],"correctIndex":1,"explanation":"「住」是老人自己的动作 → living（= who live）。lived、are living 会被当成谓语，和 have 冲突；who 后面要有完整的动词：who live。","subSkill":"reduced_relative_clauses_with_participles"},{"id":"gen-5-2-106","type":"scenario","instruction":"考生只有一位英语老师，想顺带补充「她在伦敦住过十年」。选出说得对的一句。","context":"雅思口语 Part 2 · 题卡：Describe a person who has influenced you","dialogue":[],"options":["My English teacher, she lived in London for ten years, taught me to love reading.","My English teacher who she lived in London for ten years taught me to love reading.","My English teacher, which lived in London for ten years, taught me to love reading.","My English teacher, who lived in London for ten years, taught me to love reading."],"correctIndex":3,"explanation":"补充一个人的情况 → , who lived…,。she 让句子多出一个主语；who 后面不再加 she；which 不指人。","subSkill":"relative_pronoun_accuracy"},{"id":"gen-5-2-107","type":"choice","instruction":"〔写作 Task 2〕想说「不管政府采取什么措施，总会有人不满」。","sentence":"___ the government does, some people will always complain.","options":["Whoever","However","Whatever","No matter"],"correctIndex":2,"explanation":"不管做什么 → Whatever，它同时做 does 的宾语。Whoever 指人；However 是「不管多么 / 怎样」，这里 does 缺宾语；No matter 漏了 what。","subSkill":"relative_clauses_with_whoever_whatever"},{"id":"gen-5-2-108","type":"choice","instruction":"〔写作 Task 2〕想说「有很多人认为考试不公平」。选出准确的一句。","options":["There are many people think exams are unfair.","There are many people who think exams are unfair.","There are many people who they think exams are unfair.","There are many people which think exams are unfair."],"correctIndex":1,"explanation":"There are many people 已是完整的句子，要靠 who 才能接上 think。who 后面不再加 they；which 不指人。更简洁：Many people think…","subSkill":"relative_pronoun_accuracy"},{"id":"gen-5-2-109","type":"match","instruction":"〔写作 Task 2〕每个空该填哪一个？连线。","left":["the city ___ they grew up","the age ___ people retire","a problem ___ there is no easy answer","the people ___ I share a flat"],"right":["in which","at which","to which","with whom"],"correctPairs":[[0,0],[1,1],[2,2],[3,3]],"explanation":"介词跟着原搭配走：grow up in、retire at、an answer to、share a flat with。指人用 whom；介词后不用 that。","subSkill":"preposition_fronting_in_relative_clauses"}],"3":[{"id":"gen-5-3-100","type":"fill","instruction":"〔写作 Task 2〕把两句合成一句。原句：More than 2,000 doctors left the country last year. Many of them moved to the UK.","sentence":"More than 2,000 doctors left the country last year, ___ moved to the UK.","acceptableAnswers":["many of whom","a lot of whom","a large number of whom","and many of them","a great many of whom"],"explanation":"Many of them 接在逗号后要变成 many of whom，两句才能合成一句。医生是人，用 whom；写成 many of them moved 就是两句硬连。","subSkill":"non_defining_relative_with_quantifiers_many_of_which"},{"id":"gen-5-3-101","type":"fill","instruction":"〔写作 Task 2〕把两句合成一句，后半句指前面整件事。原句：Many schools have given every pupil a tablet. This has made lessons more interactive.","sentence":"Many schools have given every pupil a tablet, ___ lessons more interactive.","acceptableAnswers":["which has made","which makes","which is making","which made","and this has made","making","and that has made","and this makes","and this made","thus making","thereby making"],"explanation":"This has made… 变成 , which has made…：which 指「给每个学生发平板」这整件事，动词用单数 has。","subSkill":"sentential_relative_which_referring_to_clause"},{"id":"gen-5-3-102","type":"fill","instruction":"〔写作 Task 2〕把句尾的介词移到前面，句子更正式。原句：Rural schools often lack the equipment which science lessons depend on.","sentence":"Rural schools often lack the equipment ___ science lessons depend.","acceptableAnswers":["on which","upon which"],"explanation":"depend on the equipment → the equipment on which science lessons depend。句尾不再写 on；介词后不用 that。","subSkill":"preposition_fronting_in_relative_clauses"},{"id":"gen-5-3-103","type":"fill","instruction":"〔写作 Task 1〕用括号里的动词补全，句子要紧凑。","sentence":"The chart shows the number of people ___ (use) public transport in five cities in 2020.","acceptableAnswers":["using","who used","that used","who were using"],"explanation":"这些人自己乘坐公共交通 → using（= who used）。写成 used，就成了「被使用的人」。","subSkill":"reduced_relative_clauses_with_participles"},{"id":"gen-5-3-104","type":"fill","instruction":"〔口语 Part 3〕用括号里的动词补全，句子要紧凑。","sentence":"Drivers ___ (catch) using a phone at the wheel should lose their licence.","acceptableAnswers":["caught","who are caught","that are caught","who get caught","that get caught","who have been caught","who are ever caught"],"explanation":"司机是被抓到的 → caught（= who are caught）。写成 catching，意思就成了司机去抓别人。","subSkill":"reduced_relative_clauses_with_participles"},{"id":"gen-5-3-105","type":"reorder","instruction":"〔口语 Part 2〕排出这句：我采访了二十位店主，其中一半已经不收现金了。","words":["half","no","I","accept","owners,","whom","twenty","cash.","interviewed","longer","of","shop"],"correctSentence":"I interviewed twenty shop owners, half of whom no longer accept cash.","explanation":"half of whom = 他们当中的一半，接在逗号后，一句话说完。店主是人，用 whom；写成 half of them 就要另起一句。","subSkill":"non_defining_relative_with_quantifiers_many_of_which"},{"id":"gen-5-3-106","type":"reorder","instruction":"〔写作 Task 2〕排出这句：买报纸的人越来越少，所以很多地方报纸停刊了。","words":["local","which","Fewer","have","is","newspapers,","papers","why","buy","many","closed.","people"],"correctSentence":"Fewer people buy newspapers, which is why many local papers have closed.","explanation":", which is why… = 「这就是为什么…」：which 指「买报纸的人越来越少」这整件事，适合在论证里引出结果。","subSkill":"sentential_relative_which_referring_to_clause"},{"id":"gen-5-3-107","type":"fill","instruction":"〔写作 Task 2〕把两句合成一句。原句：Some children fall behind at school. Their parents cannot afford private tutors.","sentence":"Children ___ parents cannot afford private tutors often fall behind at school.","acceptableAnswers":["whose"],"explanation":"Their parents → whose parents（他们的父母）。whose 后面直接接名词；别写 who's（= who is），也别写 who their / which their。","subSkill":"relative_pronoun_accuracy"},{"id":"gen-5-3-108","type":"fill","instruction":"〔口语 Part 2〕把第二句放进第一句中间，补充爷爷的情况。原句：My grandfather taught himself English at sixty. He had never been to school.","sentence":"My grandfather, ___ had never been to school, taught himself English at sixty.","acceptableAnswers":["who"],"explanation":"补充说明一个人 → , who …,（前后两个逗号）。He 变成 who，不再保留 he；句子主干还是 My grandfather taught himself English。","subSkill":"defining_vs_non_defining_relative_clauses"}],"4":[{"id":"gen-5-4-100","type":"fill","instruction":"〔写作 Task 2 · 考生常见错误〕这句少了一个词。把空格处改好的两个词写出来。原句：There are many students think that homework is a waste of time.","sentence":"There are many students ___ that homework is a waste of time.","acceptableAnswers":["who think","that think","who believe","who feel","that believe","that feel","who say","who claim","who argue"],"explanation":"There are many students 已是完整的句子，think 要靠 who 接上：many students who think…。也可以干脆写 Many students think…","subSkill":"relative_pronoun_accuracy"},{"id":"gen-5-4-101","type":"error","instruction":"〔写作 Task 2 · 考生常见错误〕点出用错的部分。","words":["The survey","questioned","500 parents,","most of which","said","they","check","their children's phones."],"errorIndex":3,"correction":"most of whom","explanation":"parents 是人，「其中大多数」要写 most of whom。which 只指物。","subSkill":"non_defining_relative_with_quantifiers_many_of_which"},{"id":"gen-5-4-102","type":"fill","instruction":"〔写作 Task 2 · 考生常见错误〕逗号后面又接了一个完整的句子，在空里改正。原句：The city has over a hundred museums, many of them are free to visit.","sentence":"The city has over a hundred museums, ___ are free to visit.","acceptableAnswers":["many of which","a lot of which","a large number of which","and many of them","a great many of which"],"explanation":"逗号后不能再接 many of them are… 这样的完整句子。博物馆是物 → many of which。也可以用句号断开：… museums. Many of them are free.","subSkill":"non_defining_relative_with_quantifiers_many_of_which"},{"id":"gen-5-4-103","type":"error","instruction":"〔写作 Task 2 · 考生常见错误〕点出用错的部分。","words":["Many factories","have","moved","to the suburbs,","that","has made","the air","in the city","much cleaner."],"errorIndex":4,"correction":"which","explanation":"指前面整件事（工厂搬去郊区），接在逗号后要用 which：…, which has made the air much cleaner。that 不能放在逗号后面。","subSkill":"sentential_relative_which_referring_to_clause"},{"id":"gen-5-4-104","type":"fill","instruction":"〔写作 Task 2 · 考生常见错误〕后半句的开头用错了，在空里改正。原句：The price of fresh fruit has doubled, this means poorer families eat less healthily.","sentence":"The price of fresh fruit has doubled, ___ poorer families eat less healthily.","acceptableAnswers":["which means","which means that","and this means","and this means that","meaning","meaning that","which has meant","which has meant that","so","and so","and as a result","which is why","which explains why","and that means","and that means that","and this has meant","and this has meant that","and therefore","and consequently","and thus"],"explanation":"逗号后面不能直接接 this means…（两个句子硬连）。用 , which means…，which 指「水果涨价一倍」这件事；或者写 and this means…。","subSkill":"sentential_relative_which_referring_to_clause"},{"id":"gen-5-4-105","type":"error","instruction":"〔写作 Task 2 · 考生常见错误〕想说「上夜班的人往往睡不好」。点出用错的部分。","words":["Many people","worked","night shifts","suffer","from","poor","sleep."],"errorIndex":1,"correction":"working","explanation":"worked 会被当成谓语，和 suffer 冲突。这些人自己上夜班 → working（= who work）。","subSkill":"reduced_relative_clauses_with_participles"},{"id":"gen-5-4-106","type":"choice","instruction":"〔写作 Task 2 · 考生常见写法〕选出改对的一句。原句：Hangzhou, that is famous for its tea, attracts millions of tourists every year.","options":["Hangzhou, which is famous for its tea, attracts millions of tourists every year.","Hangzhou which is famous for its tea attracts millions of tourists every year.","Hangzhou, it is famous for its tea, attracts millions of tourists every year.","Hangzhou, where is famous for its tea, attracts millions of tourists every year."],"correctIndex":0,"explanation":"杭州只有一个，后面的从句只能是补充 → 前后加逗号，用 which。逗号后不用 that；it 让句子多出一个主语；where 后面要有主语，不能直接接 is。","subSkill":"defining_vs_non_defining_relative_clauses"},{"id":"gen-5-4-107","type":"error","instruction":"〔写作 Task 2 · 考生常见错误〕想说「年轻夫妇面临的最大问题是房价高」。点出用错的部分。","words":["The biggest problem","that","young couples","face it","is","the high cost","of housing."],"errorIndex":3,"correction":"face","explanation":"that 已经代替了 problem，从句里不再写 it：the biggest problem that young couples face。照着中文「他们面对它」写，容易多出这个 it。","subSkill":"relative_pronoun_accuracy"},{"id":"gen-5-4-108","type":"fill","instruction":"〔写作 Task 2 · 考生常见错误〕有一处漏了词。把空格处改好的两个词写出来。原句：Many migrant workers are unhappy with the conditions which they live.","sentence":"Many migrant workers are unhappy with the conditions ___ they live.","acceptableAnswers":["in which","under which"],"explanation":"live in these conditions → the conditions in which they live。介词不能丢；也可放句尾：conditions they live in。","subSkill":"preposition_fronting_in_relative_clauses"},{"id":"gen-5-4-109","type":"choice","instruction":"〔口语 Part 3 · 考生常见写法〕这句是「谁想…谁就…」的直译，选出自然的改法。原句：Who wants to become a doctor must study for many years.","sentence":"___ must study for many years.","options":["Those who wants to become a doctor","Whoever want to become a doctor","Whoever wants to become a doctor","Everyone wants to become a doctor"],"correctIndex":2,"explanation":"「谁…谁就…」→ Whoever wants…，动词用单数；更常见的说法是 Anyone who wants…。Those who 后面要用复数 want；Everyone 后面要加 who。","subSkill":"relative_clauses_with_whoever_whatever"}],"5":[{"id":"gen-5-5-100","type":"fill","instruction":"〔写作 Task 2〕把两句并成一句，信息更紧凑。原句：The government has introduced several new education policies. The most controversial of them is the ban on private tutoring.","sentence":"The government has introduced several new education policies, ___ is the ban on private tutoring.","acceptableAnswers":["the most controversial of which","of which the most controversial","and the most controversial of them","and the most controversial of these","and the most controversial","and the most controversial one"],"explanation":"The most controversial of them 接在逗号后 → the most controversial of which：which 指回 policies，一句说完。","subSkill":"non_defining_relative_with_quantifiers_many_of_which"},{"id":"gen-5-5-101","type":"fill","instruction":"〔写作 Task 2〕把结果直接接在逗号后面，读起来更连贯。原句：Many young people now work in the gig economy. This has led to growing concern about their financial security.","sentence":"Many young people now work in the gig economy, ___ growing concern about their financial security.","acceptableAnswers":["which has led to","which has resulted in","which has caused","which has raised","which has created","which has given rise to","which has fuelled","which has fueled","which has prompted","which leads to","which led to","which is leading to","which is causing","leading to","resulting in","causing","raising","giving rise to","fuelling","fueling","prompting","and this has led to","and this has caused","and that has led to"],"explanation":"This has led to… 接在逗号后变成 , which has led to…：which 指「很多年轻人打零工」这整件事，动词用单数 has。","subSkill":"sentential_relative_which_referring_to_clause"},{"id":"gen-5-5-102","type":"fill","instruction":"〔写作 Task 2〕想说「社交媒体在多大程度上伤害青少年心理健康，研究者仍有分歧」。","sentence":"Researchers still disagree about the extent ___ social media harms teenagers' mental health.","acceptableAnswers":["to which"],"explanation":"harm … to some extent → the extent to which…（在多大程度上）。to 不能丢。这是 Task 2 讨论影响时很好用的说法。","subSkill":"preposition_fronting_in_relative_clauses"},{"id":"gen-5-5-103","type":"fill","instruction":"〔写作 Task 1〕补全这段图表描述。第一空说「其中大多数」。","sentence":"France received the most visitors, ___ came from other European countries. Thailand's visitor numbers doubled over the decade, ___ moved the country up to third place. The country ___ (receive) the fewest visitors was Egypt.","acceptableAnswers":["most of whom","which","receiving"],"blankAnswers":[["most of whom","the majority of whom","the vast majority of whom"],["which","and this","and that","a rise that","a rise which","an increase that","an increase which"],["receiving","that received","which received","to receive"]],"explanation":"① 游客是人 → most of whom。② which 指「泰国游客人数翻倍」这件事。③ 这个国家接待游客，是主动 → receiving（= that received）。","subSkill":"non_defining_relative_with_quantifiers_many_of_which"},{"id":"gen-5-5-104","type":"fill","instruction":"〔写作 Task 2〕删去多余的词，把两句并成一句。原句：Schools increasingly rely on teachers who are employed on short-term contracts. Many of them leave the profession within five years.","sentence":"Schools increasingly rely on teachers ___ on short-term contracts, ___ leave the profession within five years.","acceptableAnswers":["employed","many of whom"],"blankAnswers":[["employed","hired","working","recruited"],["many of whom","a lot of whom","a large number of whom","and many of them"]],"explanation":"who are employed → employed（老师是被雇用的）。Many of them 接在逗号后要变成 many of whom，两句才能并成一句。","subSkill":"reduced_relative_clauses_with_participles"},{"id":"gen-5-5-105","type":"scenario","instruction":"考生想说「年轻人结婚越来越晚，这让很多父母着急」。选出说得准确的一句。","context":"雅思口语 Part 3 · Family","dialogue":[{"speaker":"examiner","text":"Examiner: How are attitudes to marriage changing in your country?"}],"options":["Young people are getting married later and later, which really worries a lot of parents.","Young people are getting married later and later, what really worries a lot of parents.","Young people are getting married later and later, which really worry a lot of parents.","Young people are getting married later and later, this is really worrying a lot of parents."],"correctIndex":0,"explanation":"which 指「越来越晚结婚」这整件事，动词用单数 worries。what 不能指前文；worry 和单数不一致；this 让逗号连起两个句子。","subSkill":"sentential_relative_which_referring_to_clause"},{"id":"gen-5-5-106","type":"fill","instruction":"〔写作 Task 2〕补全这段论证，第二空用括号里的动词。","sentence":"Online consultations have become common, ___ saves patients long trips to hospital. Patients ___ (live) in remote villages benefit most. Hospital doctors, ___ are already overworked, also spend less time on routine check-ups.","acceptableAnswers":["which","living","who"],"blankAnswers":[["which","and this","and that"],["living","who live","that live"],["who","many of whom","most of whom","all of whom"]],"explanation":"① which 指「线上问诊普及」这件事 → 单数 saves。② 「住」是病人自己的动作 → living。③ 指全体医院医生，只是补充 → , who …,（不用 that）。","subSkill":"sentential_relative_which_referring_to_clause"},{"id":"gen-5-5-107","type":"fill","instruction":"〔口语 Part 2〕题卡：Describe a photo you like。用括号里的动词补全考生的描述。","sentence":"The photo, ___ (take) on my first trip abroad, shows my parents ___ (stand) in front of a huge waterfall.","acceptableAnswers":["taken","standing"],"blankAnswers":[["taken","which I took","which was taken"],["standing"]],"explanation":"照片是被拍的 → taken（= which was taken）。父母自己站着 → standing。过去分词表示被做，-ing 表示自己在做。","subSkill":"reduced_relative_clauses_with_participles"},{"id":"gen-5-5-108","type":"fill","instruction":"〔写作 Task 2〕想说「不管选择什么职业，年轻人都需要很强的沟通能力」。","sentence":"___, young people will need strong communication skills.","acceptableAnswers":["Whatever career they choose","Whichever career they choose","No matter what career they choose","No matter which career they choose","Regardless of what career they choose","Regardless of which career they choose","Irrespective of what career they choose","Whatever career they pursue","Whatever career they go into","Whatever career they choose to pursue","Whatever careers they choose","Whatever job they choose","Whatever profession they choose","Whichever career they pursue","No matter what career they pursue","Whatever career they decide on","Whatever career they end up in","Whatever career young people choose","Whatever they choose to do"],"explanation":"Whatever + 名词 + 主语 + 动词 = 不管什么…：Whatever career they choose 整块放句首，后半句才是主干。No matter what career… 也对。","subSkill":"relative_clauses_with_whoever_whatever"},{"id":"gen-5-5-109","type":"fill","instruction":"〔写作 Task 2〕用括号里的动词补全。","sentence":"Students who ___ (spend) more than three hours a day online tend to sleep less, which ___ (affect) their concentration in class.","acceptableAnswers":["spend","affects"],"blankAnswers":[["spend"],["affects","can affect","may affect","in turn affects","often affects","could affect"]],"explanation":"① who 指 students（复数）→ spend。② which 指「睡得少」这件事（单数）→ affects。","subSkill":"sentential_relative_which_referring_to_clause"}]},"mission":{"title":"写作 Task 2 段落：越来越多的人独自生活","description":"写一个雅思 Task 2 主体段（3 句）：先说哪类人选择独居、为什么，再说独居带来的一个问题，最后给出你的总体判断（写法自选）。至少用对本单元的 2 种写法，不必每句都用从句。AI 老师会按雅思「语法多样性与准确性」给你反馈。","scenario":"题目：In many countries, a growing number of people are choosing to live alone. Why is this happening, and is it a positive or negative development?<br>你只写正文里的一段。可以写不同的人群：刚工作的年轻人、子女在外地的老人、离婚的人……用你熟悉的城市或家乡举例。","grammarType":"non_defining_relative_with_quantifiers_many_of_which","scaffolds":[{"prefix":"One reason for this trend is that more people can now afford to live on their own.","suffix":"","hint":"补充说明这群人，一句话说完：…, many / most of whom + 动词（其中很多人…）","grammarCheck":"non_defining_relative_with_quantifiers_many_of_which","example":"Big cities attract millions of young graduates, many of whom rent small flats on their own rather than share with strangers."},{"prefix":"However, living alone can have serious drawbacks.","suffix":"","hint":"说一个后果：用 , which … 指前面整件事（这就意味着…）","grammarCheck":"sentential_relative_which_referring_to_clause","example":"Many older people now live hundreds of kilometres from their children, which means that a minor fall can leave them without help for days."},{"prefix":"On balance, I believe the trend is positive, as long as no one is left isolated.","suffix":"","hint":"说怎么做到这一点，结构自选：可以用 people living alone / those who …，也可以用 whoever …，或者干脆不用从句。","grammarCheck":"reduced_relative_clauses_with_participles","example":"Local councils could open community centres offering cheap meals and weekly activities for residents living on their own."}]},"discover":{"story":{"title":"写作 Task 2 范文节选：出国留学，值不值？","text":"读的时候想一想：作者认为出国留学的好处和代价分别是什么？蓝色的句子下面会逐句问你。\nQuestion: More and more young people are choosing to study abroad. Do the advantages of this trend outweigh the disadvantages?\nStudying abroad clearly brings benefits, but not every student gains equally. Students who share a flat with local people tend to make the fastest progress in English, because they have to use the language all day. Living independently in a new country also teaches young people to manage money and solve problems on their own.\nThe costs, however, are considerable. Universities in English-speaking countries now depend heavily on international students, many of whom pay up to three times as much as local students. For comfort and to save money, these students often share flats with friends from home and speak their own language every day, which means that their English improves surprisingly little.\nThe risks are greatest for younger students, and the age at which students first go abroad has been falling. Children sent abroad at fifteen or sixteen often struggle with loneliness, and some return home without the qualifications their parents had hoped for. On balance, studying abroad is worthwhile for mature, motivated students, but parents should think carefully before sending a teenager overseas alone.","highlights":["Students who share a flat with local people","many of whom pay up to three times as much","speak their own language every day","which means that their English improves surprisingly little","the age at which students first go abroad","Children sent abroad at fifteen or sixteen","the qualifications their parents had hoped for"]},"questions":[{"question":"第一段：<em>Students who share a flat with local people tend to make the fastest progress in English…</em><br>According to the writer, whose English improves fastest?","options":["All students who study abroad","Students who live with local people","Local people who live with students"],"correctIndex":1,"nudge":"who share a flat with local people 紧跟在 Students 后面：作者在说所有学生，还是挑出其中一类？","explanation":"只是和当地人合租的那一部分。<br><strong>规则 ①</strong>：名词后面直接跟 who / which（不加逗号）→ 说明「是哪一些」；把它删掉，意思就变了。","subSkill":"defining_vs_non_defining_relative_clauses"},{"question":"如果在原句里加两个逗号：<br><em>Students, who share a flat with local people, tend to make the fastest progress.</em><br>What would the sentence mean then?","options":["The same: only some students do this.","It says all students live with local people.","It advises students to live with local people."],"correctIndex":1,"nudge":"两个逗号像一对括号：把 , who share a flat with local people, 整个拿掉，剩下的 Students 指的是哪些学生？","explanation":"加了逗号，这部分只是顺带补充：Students 指所有留学生，等于说他们全都和当地人合租。<br><strong>规则 ②</strong>：有逗号 → 补充说明，指前面说到的全部；逗号后面不用 that。","subSkill":"defining_vs_non_defining_relative_clauses"},{"question":"第二段：<em>Universities … now depend heavily on international students, many of whom pay up to three times as much as local students.</em><br>Who pays up to three times as much?","options":["Many of the international students","Every one of the international students","Quite a lot of the local students"],"correctIndex":0,"nudge":"whom 指人：往回找逗号前面紧挨着的那群人。再看 whom 前面还有 many of。","explanation":"其中很多国际学生（不是全部）。<br><strong>规则 ③</strong>：名词, many / most of + whom（人）/ which（物）+ 动词 → 「其中…」，一句说完。别写 , many of them pay…","subSkill":"non_defining_relative_with_quantifiers_many_of_which"},{"question":"第二段：<em>…these students often share flats with friends from home and speak their own language every day, which means that their English improves surprisingly little.</em><br>Why does their English improve so little, according to the writer?","options":["Their own language is very different from English.","Local people are not willing to talk to them.","They live and talk mainly with people from home."],"correctIndex":2,"nudge":"which 紧跟在 their own language every day 后面。是「母语」本身让英语进步小，还是逗号前面说的那一整件事？","explanation":"和同乡合住、天天说母语：which 指前面这一整件事。<br><strong>规则 ④</strong>：逗号后的 which 可指前面一整句，动词用单数（which means）。别写 , this means…（两句硬连）。","subSkill":"sentential_relative_which_referring_to_clause"},{"question":"第三段：<em>Children sent abroad at fifteen or sixteen often struggle with loneliness…</em><br>How did these children end up abroad?","options":["Their parents decided to send them.","They decided to go on their own.","They emigrated with their whole family."],"correctIndex":0,"nudge":"sent 是 send 的过去分词。试着还原成 Children who are ___ abroad…：是孩子自己要去，还是别人把他们送去？","explanation":"被父母送出国（= who are sent abroad）。<br><strong>规则 ⑤</strong>：名词 + doing → 自己在做；名词 + done → 被…（children sent abroad）。","subSkill":"reduced_relative_clauses_with_participles"},{"question":"你来试试：作文里想说「我有 40 个大学同学，其中大多数在位于上海的外企工作」，哪句对？","options":["I have 40 university classmates, most of them work for foreign firms located in Shanghai.","I have 40 university classmates, most of whom work for foreign firms locating in Shanghai.","I have 40 university classmates, most of whom work for foreign firms located in Shanghai."],"correctIndex":2,"nudge":"分两步想：逗号后面还能再接一个完整的句子吗？（规则 ③）公司是自己在做事，还是被设在那里？（规则 ⑤）","explanation":"most of whom：同学是人，一句说完（规则 ③）。located in = which are located in，别写 locating（规则 ⑤）。most of them 得另起一句。","subSkill":"non_defining_relative_with_quantifiers_many_of_which"}],"tip":"【加信息：先分清是哪些，再一句说完】\n\n① 名词后直接跟 who / which（无逗号）→ 说明「是哪一些」，删掉意思就变\n② 加逗号 → 只是补充，指前面说到的全部；逗号后不用 that\n③ 名词, many / most of + whom（人）/ which（物）+ 动词 → 「其中…」，一句说完\n④ 逗号后的 which 可指前面整件事，动词用单数：which means / which has led to\n⑤ 名词 + doing → 自己在做；名词 + done → 被…：people living alone / food wasted by households\n⑥ 介词跟着原搭配走：work with colleagues → the colleagues with whom they work；介词后不用 that\n⑦ who / which 作主语不能省；从句里不再加 it / them / their：children whose parents…\n另外：Whoever = 任何…的人；Whatever + 名词 = 不管什么…\n\n【例句】\n✔ The college has 2,000 students, half of whom come from rural areas.（其中一半）\n✔ Many graduates still live with their parents, which helps them save for a home.（which = 整件事）\n\n【常见错误】\n✘ There are many people think that … → many people who think（漏了 who，见 ⑦）\n✘ I have two brothers, both of them are doctors. → both of whom are doctors（见 ③）\n✘ Rents keep rising, this makes life hard for young people. → , which makes …（见 ④）\n✘ Products making in China … → Products made in China（见 ⑤）\n✘ students who's parents work abroad → students whose parents（见 ⑦）"}},"6":{"discover":{"story":{"title":"写作范文节选：渔村变成了度假村","text":"读的时候想一想：这个渔村有哪些变化？每个变化带来了什么？蓝色的句子下面会逐句问你。\nTask 1: The maps below show the village of Westhaven in 2000 and today. Summarise the information by selecting and reporting the main features.（地图略）\nThe maps illustrate how the fishing village of Westhaven has changed since 2000. Overall, it has been transformed from a quiet fishing community into a small tourist resort.\nIn 2000, the village consisted of a harbour, a fish market, about twenty houses and an area of farmland. Located beside the harbour, the fish market has since been turned into a seafood restaurant. A coastal road has also been built, linking the village to the nearby town of Carlton. To the north of the houses, the farmland has been replaced by a hotel and a car park.\nTask 2: Some people believe that tourism does more harm than good to local communities. To what extent do you agree or disagree?\nHaving lost their traditional jobs, many fishermen in villages like Westhaven now earn a living from tourism. However, holiday homes have pushed up house prices, forcing young families to move away. If managed carefully, tourism can support such villages without driving local people out.","highlights":["Located beside the harbour","the fish market","linking the village to the nearby town of Carlton","Having lost their traditional jobs","many fishermen","If managed carefully","tourism can support such villages"]},"questions":[{"question":"第二段：<em>Located beside the harbour, the fish market has since been turned into a seafood restaurant.</em><br>What was beside the harbour in 2000, and what is there now?","options":["A fish market; now a seafood restaurant.","Nothing; now a fish market.","A seafood restaurant; now a fish market."],"correctIndex":0,"nudge":"Located beside the harbour 自己没有主语。往逗号后面看：位于港口旁边的是哪个名词？再看 turned into：哪个在前、哪个在后？","explanation":"港口旁原来是鱼市，后来改成了海鲜餐厅。Located 只说位置，没有「搬过去」的意思。<br><strong>规则 ①</strong>：句首的分词短语，说的就是逗号后面的主语：位于港口旁的，是 the fish market。","subSkill":"dangling_participle_avoidance"},{"question":"比较两种写法：<br>A. <em>Located</em> beside the harbour, the fish market …<br>B. <em>Locating</em> beside the harbour, the fish market …<br>Which one tells us where the fish market is?","options":["Only A","Only B","Both of them"],"correctIndex":0,"nudge":"鱼市会自己去 locate（给别的东西选地方）吗？还是它被建在了那里？","explanation":"A。鱼市不会自己选地方，它是被建在港口旁的 → Located。Locating 成了鱼市自己在找位置。<br><strong>规则 ②</strong>：主语是被做的 → done（Located、Built）；主语自己做、或自己处在某种状态 → doing（Facing、Linking）。","subSkill":"participle_active_vs_passive"},{"question":"第二段：<em>A coastal road has also been built, linking the village to the nearby town of Carlton.</em><br>Is the village connected to Carlton today? What connects them?","options":["Yes, but they were linked before the road.","No, the road doesn't reach Carlton yet.","Yes, the new road connects them."],"correctIndex":2,"nudge":"linking 前面有逗号。是什么在「连接」村子和镇子？先修路，还是先连通？","explanation":"路修好了，村子和镇子就连起来了：linking 接着说修路带来的结果。<br><strong>规则 ③</strong>：句尾的「, doing」= and it / this …，说前面这件事带来的结果。Task 2 段里的 forcing … 也是这样。","subSkill":"present_participle_clauses_for_result_reason"},{"question":"Task 2 段：<em>Having lost their traditional jobs, many fishermen in villages like Westhaven now earn a living from tourism.</em><br>Why do these fishermen now work in tourism?","options":["Tourism pays more than fishing.","Their fishing jobs will soon end.","Their old jobs have already gone."],"correctIndex":2,"nudge":"Having lost 说的事，发生在 now earn 之前还是之后？","explanation":"原来的工作先没了，现在才靠旅游业：Having lost 既说先后，也带出原因。<br><strong>规则 ④</strong>：Having done → 这件事在主句之前就已经发生；被动写 Having been done。","subSkill":"perfect_participle_having_done"},{"question":"Task 2 段：<em>If managed carefully, tourism can support such villages without driving local people out.</em><br>Does the writer think tourism is good for these villages?","options":["Yes, if it is managed well.","Yes, it always helps them.","No, not even if managed well."],"correctIndex":0,"nudge":"If managed carefully 是个条件。被管理的是什么？条件做不到，作者还这么说吗？","explanation":"有前提：管理得好才有好处。If managed = If it is managed，被管理的就是主语 tourism。<br><strong>规则 ⑤</strong>：if / once / although + done = 省掉了「主语 + be」，省掉的主语就是主句主语。","subSkill":"past_participle_clauses_for_condition_concession"},{"question":"你来试试：想说「这座灯塔建于 1890 年，如今吸引了大批游客」。Which sentence is correct?","options":["Built in 1890, large numbers of tourists now visit the lighthouse.","Built in 1890, the lighthouse now attracts large numbers of tourists.","Building in 1890, the lighthouse now attracts large numbers of tourists."],"correctIndex":1,"nudge":"先问：是谁被建的？再看逗号后面的主语是不是它。用规则 ① 和 ②。","explanation":"灯塔是被建的 → Built（规则 ②）；被建的是灯塔，逗号后的主语就得是 the lighthouse（规则 ①）。第一句成了「游客建于 1890 年」；Building 成了灯塔自己在盖房子。","subSkill":"dangling_participle_avoidance"}],"tip":"【先问：分词说的是谁？谁在做？】\n\n① 句首的分词短语，说的是逗号后面的主语\n② 主语被做 → done（Located、Built、Compared）；主语自己做或自己处在某状态 → doing（Linking、Facing、Lying）\n③ 句尾「, doing」→ 前面这件事带来的结果\n④ Having done → 比主句先发生；被动写 Having been done\n⑤ if / once / although + done = 省掉了「主语 + be」，主语同主句\n⑥ after / before 后面接 doing；被做写 being done\n⑦ with + 名词 + doing / done → 交代背景或原因\n逗号不能连两个完整的句子：, this causes … → , causing …\n\n【例句】\n✔ Located beside the harbour, the fish market has been turned into a restaurant.（鱼市位于港口旁）\n✔ Holiday homes have pushed up house prices, forcing young families to move away.（结果）\n\n【常见错误】\n✘ **Locating** in the city centre, the hotel is popular. → Located（酒店是被建在那里的，见 ②）\n✘ Built in 1890, **tourists** visit the lighthouse. → the lighthouse attracts tourists（被建的是灯塔，见 ①）\n✘ Many factories closed, **led** to job losses. → , leading to（见 ③）\n✘ After **washed**, the wool is dried. → After being washed（见 ⑥）"},"mission":{"title":"写作 Task 1 地图题：河边旧厂区的变化","description":"写一篇雅思 Task 1 地图题的总览和正文（3 句）：先写总体变化，再写两处具体变化（第 3 句写法自选）。每用一个分词短语，先问自己：它说的是逗号后面的谁？是自己做还是被做？至少用对本单元的 2 种写法，不必每句都用。AI 老师会按雅思「语法多样性与准确性」给你反馈。","scenario":"题目：The maps below show the riverside area of Ashford in 1990 and today. Summarise the information by selecting and reporting the main features.<br>地图信息：1990 年，河北岸有一座造纸厂、两座仓库，东边是一片农田；南岸是镇中心，两岸之间没有桥。今天：造纸厂被拆，建起了三栋公寓楼；一座仓库改成了艺术中心，另一座拆了；东边的农田变成了沿河公园；新修了一座人行桥，连通北岸和镇中心。<br>你只写总览和正文的 3 句。","grammarType":"present_participle_clauses_for_result_reason","scaffolds":[{"prefix":"The maps illustrate how the riverside area of Ashford has changed since 1990.","suffix":"","hint":"写总览：这一带从什么变成了什么？可以在句尾用 with + 名词 + done 交代最大的变化。","grammarCheck":"absolute_participial_constructions","example":"Overall, the area has been transformed from an industrial zone into a residential and leisure district, with the paper mill replaced by apartment blocks."},{"prefix":"In 1990, the north bank was dominated by a paper mill and two warehouses.","suffix":"","hint":"写仓库的变化：可以用 Located / Built … 开头。先想清楚逗号后的主语是谁，它是被做，还是自己做。","grammarCheck":"participle_active_vs_passive","example":"Located next to the former paper mill, one of the warehouses has since been converted into an arts centre, while the other has been demolished."},{"prefix":"The farmland to the east has been turned into a riverside park.","suffix":"","hint":"写新修的人行桥和它带来的变化，结构自选：可以在句尾用 , doing 说结果，也可以用 which，或者干脆写两个短句。","grammarCheck":"present_participle_clauses_for_result_reason","example":"In addition, a footbridge has been built across the river, linking the new housing to the town centre."}]},"levels":{"1":[{"id":"gen-6-1-100","type":"choice","instruction":"〔写作 Task 2〕读句子，回答问题。原句：The steel plant closed in 2015, leaving 3,000 workers without jobs.","sentence":"Why did 3,000 workers lose their jobs?","options":["They chose to resign.","The plant closed down.","They went on strike.","They found better jobs."],"correctIndex":1,"explanation":"leaving … 接在句尾，说前面「钢厂关闭」带来的结果：3,000 人没了工作。这里的 leave 是「使…处于某种状态」，不是工人「离开」。","subSkill":"present_participle_clauses_for_result_reason"},{"id":"gen-6-1-101","type":"choice","instruction":"〔口语 Part 2 · 考生常见错误〕照这句的字面意思回答。原句：Climbing up the mountain, the view became more and more beautiful.","sentence":"Literally, who or what is climbing the mountain?","options":["My friends and I.","The tour guide.","A group of tourists.","The view itself."],"correctIndex":3,"explanation":"句首分词说的是逗号后的主语 the view，字面成了「风景在爬山」。想说自己，主语要换成人：Climbing up the mountain, we enjoyed an increasingly beautiful view.","subSkill":"dangling_participle_avoidance"},{"id":"gen-6-1-102","type":"scenario","instruction":"读考生的回答，回答问题：When did the speaker realise they enjoyed looking after people?","context":"雅思口语 Part 1 · Work or studies","dialogue":[{"speaker":"examiner","text":"Examiner: Why did you choose to study nursing?"},{"speaker":"player","text":"Well, having volunteered at a local hospital one summer, I realised I really enjoyed looking after people."}],"options":["After volunteering at the hospital.","Before volunteering at the hospital.","After starting the nursing course.","While in hospital as a child."],"correctIndex":0,"explanation":"having volunteered → 志愿者先做过了，然后才发现自己喜欢照顾人，这也是他选护理的原因。","subSkill":"perfect_participle_having_done"},{"id":"gen-6-1-103","type":"choice","instruction":"〔写作 Task 1〕读句子，回答问题。原句：Once dried, the bricks are fired in a kiln at about 1,000°C.","sentence":"When are the bricks fired in the kiln?","options":["As soon as they are shaped.","After they have dried.","While they are drying.","Before they are dried."],"correctIndex":1,"explanation":"Once dried = Once they are dried：一晾干，就进窑烧。省掉的 they 就是主句的 the bricks。","subSkill":"past_participle_clauses_for_condition_concession"},{"id":"gen-6-1-104","type":"choice","instruction":"〔写作 Task 2〕读句子，回答问题。原句：With more young people living alone, demand for small flats has risen sharply.","sentence":"According to the writer, why has demand for small flats risen?","options":["More young people live alone.","Small flats have become cheaper.","More people are moving to cities.","Builders prefer to build them."],"correctIndex":0,"explanation":"With + 名词 + doing 交代背景或原因：独自居住的年轻人多了，所以小户型的需求大涨。living 说的是正在发生的趋势。","subSkill":"absolute_participial_constructions"},{"id":"gen-6-1-105","type":"scenario","instruction":"读考生的回答，回答问题：Why did the speaker spend a lot of time alone as a child?","context":"雅思口语 Part 1 · Reading","dialogue":[{"speaker":"examiner","text":"Examiner: Did you read much as a child?"},{"speaker":"player","text":"Yes, loads. Being an only child, I spent a lot of time on my own, so books were great company."}],"options":["His parents were often at work.","He didn't like playing with others.","He had no brothers or sisters.","His family lived far from town."],"correctIndex":2,"explanation":"Being an only child = Because I was an only child：句首的 Being … 说原因。说的是 I，和主句主语一致。","subSkill":"present_participle_clauses_for_result_reason"},{"id":"gen-6-1-107","type":"choice","instruction":"〔写作 Task 2〕读句子，回答问题。原句：Although criticised when it first opened, the art museum now attracts over a million visitors a year.","sentence":"How did people react when the museum first opened?","options":["It was popular from the start.","Many people criticised it.","Hardly anyone knew about it.","They were excited about it."],"correctIndex":1,"explanation":"Although criticised = Although it was criticised：刚开馆时挨了不少批评，现在却很受欢迎。被批评的是主语 the art museum。","subSkill":"past_participle_clauses_for_condition_concession"},{"id":"gen-6-1-108","type":"choice","instruction":"〔写作 Task 1〕读句子，回答问题。原句：Overall, the campus has expanded considerably, with most of the green space replaced by new buildings.","sentence":"What has happened to most of the green space?","options":["Most of it is still there.","It has all been kept as it is.","It is going to be built on.","Most of it has been built on."],"correctIndex":3,"explanation":"with + 名词 + done：大部分绿地已经被新楼取代了。replaced 是「已被取代」，不是「正准备」。Task 1 总览常这样交代最大的变化。","subSkill":"absolute_participial_constructions"}],"2":[{"id":"gen-6-2-100","type":"choice","instruction":"〔写作 Task 1〕想说「新体育中心位于公园边上」，选哪个开头？","sentence":"___ on the edge of the park, the new sports centre has replaced the old tennis courts.","options":["Locating","Having located","Located","It is located"],"correctIndex":2,"explanation":"体育中心是被建在那里的 → Located（= which is located；只说位置也可以用 Standing）。Locating、Having located 成了它自己去找位置；It is located … 是用逗号硬连两个句子。","subSkill":"participle_active_vs_passive"},{"id":"gen-6-2-101","type":"choice","instruction":"〔写作 Task 2〕句尾接的是前面这件事的结果。选出合适的形式。","sentence":"Many universities have moved their courses online, ___ to a sharp rise in the number of older students.","options":["leading","led","it led","and leading"],"correctIndex":0,"explanation":"句尾接结果 → , leading to。写 led，一句里就有了两个谓语；写 it led，是用逗号硬连两个句子；and leading 不成句。","subSkill":"present_participle_clauses_for_result_reason"},{"id":"gen-6-2-102","type":"choice","instruction":"〔口语 Part 2〕想说「我先在网上看了几十条评价，最后才订了那家民宿」。","sentence":"___ dozens of online reviews, I finally booked a small guesthouse near the old town.","options":["Being read","Having been read","Having read","Read"],"correctIndex":2,"explanation":"我先看评价，然后才订 → Having read（我自己看，先发生）。Read、Being read、Having been read 都成了「我被读」。","subSkill":"perfect_participle_having_done"},{"id":"gen-6-2-103","type":"choice","instruction":"〔写作 Task 2〕想说「工厂废水如果不经处理，就会污染附近的河流」。","sentence":"___, waste water from factories can pollute nearby rivers.","options":["If leaving untreated","If it left untreated","Unless treating","If left untreated"],"correctIndex":3,"explanation":"废水是被处理的 → If left untreated（= If it is left untreated）。leaving、treating 成了废水自己去留、去处理；If it left 少了 is，意思也变了。","subSkill":"past_participle_clauses_for_condition_concession"},{"id":"gen-6-2-104","type":"scenario","instruction":"考生想说「我是学生，预算很紧」。哪句意思准确？","context":"雅思口语 Part 1 · Eating out","dialogue":[{"speaker":"examiner","text":"Examiner: Do you often eat out?"}],"options":["Not really. Being a student, my budget is quite limited.","Not really. Being a student, eating out is too expensive.","Not really. Being a student, I'm on quite a tight budget.","Not really. Being a student, money is always tight for me."],"correctIndex":2,"explanation":"Being a student 说的是逗号后的主语，所以主语得是 I。其他三句成了「预算是学生」「下馆子是学生」「钱是学生」。也可以说 As a student, I …","subSkill":"dangling_participle_avoidance"},{"id":"gen-6-2-105","type":"fill","instruction":"〔写作 Task 2〕人口正在老龄化，医疗开支预计会上升。用括号里的动词填空。","sentence":"With the population ___ (age), healthcare costs are expected to rise.","explanation":"人口自己在变老，而且还在进行 → with + 名词 + ageing（美式拼作 aging）。with 后面不能接完整的句子，ages、has aged 都不行。","subSkill":"absolute_participial_constructions","acceptableAnswers":["ageing","aging","getting older","growing older","rapidly ageing","rapidly aging","now ageing","now aging"]},{"id":"gen-6-2-106","type":"choice","instruction":"〔写作 Task 1〕想说「茶叶采下来以后，铺在竹匾上晾干」。","sentence":"After ___, the tea leaves are spread out on bamboo trays to dry.","options":["being picked","picked","been picked","having picked"],"correctIndex":0,"explanation":"after 后面接名词或 doing；叶子是被采的 → after being picked（也可以说 Once picked）。After picked 是常见错；having picked 成了叶子去采别的东西。","subSkill":"participle_active_vs_passive"},{"id":"gen-6-2-107","type":"choice","instruction":"〔写作 Task 2〕手机在很多学校被禁了，青少年却照用不误。选出合适的开头。","sentence":"___ banned in many schools, mobile phones are still widely used by teenagers.","options":["If","Unless","Whenever","Although"],"correctIndex":3,"explanation":"前后意思相反 → Although banned（= Although they are banned）。If、Unless 说条件；Whenever 是「每当」。","subSkill":"past_participle_clauses_for_condition_concession"},{"id":"gen-6-2-108","type":"choice","instruction":"〔写作 Task 1〕图表比较男女做家务的时间：女性多得多。选出合适的开头。","sentence":"___ men, women spent far more time on housework in 2020.","options":["Comparing with","Compared with","Compare with","To compare with"],"correctIndex":1,"explanation":"女性是被拿来比较的 → Compared with（也说 Compared to）。Comparing with 是常见错，成了女性自己在比较。","subSkill":"participle_active_vs_passive"},{"id":"gen-6-2-109","type":"match","instruction":"〔写作 Task 1 · 地图〕按括号里的动词，逗号前该用 done 还是 doing？连线。","left":["___ (face) the sea, the new hotel …","___ (plant) with trees, the old car park …","___ (link) the two banks, the footbridge …","___ (convert) into flats, the old mill …"],"right":["the -ed form (done)","the -ing form (doing)"],"correctPairs":[[0,1],[1,0],[2,1],[3,0]],"explanation":"酒店自己面朝大海、桥自己连通两岸 → Facing、Linking；停车场是被种上树的、磨坊是被改成公寓的 → Planted、Converted。先问：主语自己做，还是被做？","subSkill":"participle_active_vs_passive"}],"3":[{"id":"gen-6-3-100","type":"fill","instruction":"〔写作 Task 2〕用句尾的 -ing 短语接上结果，去掉 and as a result。原句：The documentary exposed widespread corruption in the industry, and as a result it prompted a government inquiry.","sentence":"The documentary exposed widespread corruption in the industry, ___ a government inquiry.","acceptableAnswers":["prompting","thereby prompting","thus prompting","leading to","thereby leading to","thus leading to","triggering","thereby triggering","sparking","thereby sparking","provoking","resulting in","which prompted","which led to","which triggered","which sparked","which resulted in","thus triggering","thus sparking","thereby provoking","thus provoking","thereby resulting in","thus resulting in","which provoked","in turn prompting","eventually prompting","which in turn prompted","and this prompted","and this led to","which eventually prompted","and this triggered"],"explanation":"句尾 , prompting … 接着说前面这件事的结果，比 and as a result it prompted 简洁。thereby / thus 可加可不加；which prompted 也对。","subSkill":"present_participle_clauses_for_result_reason"},{"id":"gen-6-3-101","type":"fill","instruction":"〔写作 Task 1〕用分词开头，把两句合成一句。原句：The new hospital was built on the site of a former army base. It is now the largest building in the town.","sentence":"___ on the site of a former army base, the new hospital is now the largest building in the town.","acceptableAnswers":["Built","Constructed","Erected","Having been built","Having been constructed","Located","Situated","Standing","Newly built","Newly constructed","Having been erected","Sitting","Developed"],"explanation":"医院是被建的 → Built（= which was built）。写 Building 就成了医院自己在盖房子。只说位置，用 Located / Situated 也对。","subSkill":"participle_active_vs_passive"},{"id":"gen-6-3-102","type":"fill","instruction":"〔写作 Task 2〕是谁调查了这些上班族？改一改主句的主语。原句：Having surveyed 2,000 office workers, the results showed that most of them spend over six hours a day sitting down.","sentence":"Having surveyed 2,000 office workers, ___ found that most of them spend over six hours a day sitting down.","acceptableAnswers":["the researchers","researchers","the scientists","scientists","the investigators","investigators","the psychologists","psychologists","the experts","experts","the academics","academics","the analysts","analysts","the doctors","doctors","the economists","economists","the sociologists","sociologists","the organisers","organisers","the organizers","organizers","the health researchers","health researchers","the medical researchers","medical researchers","the study authors","study authors","the research team","a research team","the team","a team","the survey team","a survey team","the research group","a research group","the researcher","a researcher","the university","a university","the company","a company","the institute","a institute","the charity","a charity","the council","a council","the government","the ministry","the authors","the study's authors","the survey's authors","the report's authors","a team of researchers","the team of researchers","a group of researchers","a team of scientists","the team of scientists","we","they"],"explanation":"结果（results）不会自己去调查；Having surveyed 的主语必须是做调查的人：the researchers found…。主语对上了，句子才说得通。","subSkill":"dangling_participle_avoidance"},{"id":"gen-6-3-103","type":"reorder","instruction":"〔口语 Part 1〕排出这句：我在海边长大，所以一直很爱游泳。","words":["swimming.","by","Having","I","the","grown","loved","up","sea,","always","have"],"correctSentence":"Having grown up by the sea, I have always loved swimming.","acceptableSentences":["I have always loved swimming, having grown up by the sea."],"explanation":"Having grown up … 先发生，也是原因：从小在海边长大，所以一直爱游泳。主句主语 I 就是长大的人。","subSkill":"perfect_participle_having_done"},{"id":"gen-6-3-104","type":"fill","instruction":"〔写作 Task 1〕用 once + 过去分词把两步合成一句。原句：The honey is extracted from the combs. After that, it is filtered and poured into jars.","sentence":"___ from the combs, the honey is filtered and poured into jars.","acceptableAnswers":["Once extracted","Once removed","Once taken","When extracted","After being extracted","After being removed","Having been extracted","Having been removed","Extracted","After extraction","Once it has been extracted","Once it is extracted","Once it has been removed","After it has been extracted","After it is extracted","When removed","When it is extracted","When it has been extracted","After being taken","Having been taken","After removal","Following extraction","Once it is removed","After it has been removed","Once it's extracted","Once it's been extracted","Once it's removed","Once it's been removed"],"explanation":"Once extracted = Once it has been extracted：蜂蜜一取出来，就过滤、装瓶。省掉的主语就是主句的 the honey，蜂蜜是被取出的，所以用 done。","subSkill":"past_participle_clauses_for_condition_concession"},{"id":"gen-6-3-105","type":"fill","instruction":"〔写作 Task 2〕用 with 把原因并进句子。原句：More and more people work from home. As a result, many city-centre offices now stand empty.","sentence":"With more and more people ___ from home, many city-centre offices now stand empty.","acceptableAnswers":["working","now working","choosing to work","opting to work","deciding to work","starting to work","beginning to work","able to work","preferring to work","now choosing to work","now opting to work","now able to work","allowed to work","now allowed to work"],"explanation":"with + 名词 + doing 交代原因：越来越多的人在家办公。people 自己在 work，所以用 working，不能写 work 或 works。","subSkill":"absolute_participial_constructions"},{"id":"gen-6-3-106","type":"fill","instruction":"〔口语 Part 2〕用 Having 开头，把两件事按先后合成一句。原句：I had failed my driving test twice. I finally passed on my third attempt.","sentence":"___ my driving test twice, I finally passed on my third attempt.","acceptableAnswers":["Having failed","Having already failed","Having previously failed","After failing","After having failed","After I had failed","After I'd failed","After I failed","Despite having failed","Despite failing","Although I had failed","Though I had failed","Although I'd failed","Though I'd failed"],"explanation":"挂了两次在前，第三次通过在后 → Having failed（我自己考，主动）。After failing、After I had failed 也对。","subSkill":"perfect_participle_having_done"},{"id":"gen-6-3-107","type":"fill","instruction":"〔写作 Task 1〕用句尾的 -ing 短语把两句合成一句。原句：A footbridge has been added across the river. This makes it easier for students to reach the town centre.","sentence":"A footbridge has been added across the river, ___ it easier for students to reach the town centre.","acceptableAnswers":["making","thereby making","thus making","which makes","which has made","and this makes","and this has made","and that makes","and it makes","in turn making","and that has made","and it has made"],"explanation":"句尾 , making … 说加桥带来的结果。原文用 This makes 另起一句也对；但只用逗号连成 , this makes … 就错了。","subSkill":"present_participle_clauses_for_result_reason"},{"id":"gen-6-3-108","type":"fill","instruction":"〔写作 Task 2〕用 although + 过去分词，把从句缩短。原句：Although it was designed for adults, the app has become hugely popular with children.","sentence":"___ for adults, the app has become hugely popular with children.","acceptableAnswers":["Although designed","Though designed","While designed","Although originally designed","Though originally designed","While originally designed","Although intended","Though intended","Although originally intended","Despite being designed","Despite being intended","Originally designed","Originally intended","Although it was designed","Though it was designed","Although it was intended","Although it was originally designed","While intended","While originally intended","Though originally intended","Although meant","Though meant","Originally meant","Although initially designed","Though initially designed","Initially designed","Although primarily designed","Despite having been designed","Even though it was designed","While it was designed","Though it was intended","Although it was meant","Even though designed","Although designed originally"],"explanation":"Although designed = Although it was designed：省掉的 it was 指的就是主语 the app。app 是被设计出来的，所以用 designed。","subSkill":"past_participle_clauses_for_condition_concession"},{"id":"gen-6-3-109","type":"reorder","instruction":"〔口语 Part 1〕排出这句：考试快到了，我这阵子每天晚上都在复习。","words":["every","With","coming","I'm","evening.","exams","up,","studying","my"],"correctSentence":"With my exams coming up, I'm studying every evening.","acceptableSentences":["I'm studying every evening, with my exams coming up.","With my exams coming up, every evening I'm studying.","Every evening, with my exams coming up, I'm studying.","Every evening I'm studying, with my exams coming up."],"explanation":"With + 名词 + doing 交代背景：考试快到了（exams 自己在 come up）。主句说的是这阵子的安排。with 短语放句首、句尾都行。","subSkill":"absolute_participial_constructions"}],"4":[{"id":"gen-6-4-100","type":"error","instruction":"〔写作 Task 1 · 考生常见错误〕村子四周是农田。点出用错的部分。","words":["Surrounding","by farmland,","the village","has grown","into","a small town."],"errorIndex":0,"correction":"Surrounded","explanation":"村子是被农田围着的 → Surrounded by farmland。Surrounding 成了村子去包围别的东西。中文「四周是…」像主动，英文要用 done。","subSkill":"participle_active_vs_passive"},{"id":"gen-6-4-101","type":"error","instruction":"〔写作 Task 2 · 考生常见错误〕点出用错的部分。","words":["Online shopping","has grown","rapidly,","resulted in","the closure of","many small shops."],"errorIndex":3,"correction":"resulting in","explanation":"逗号后面接结果，用 resulting in。写成 resulted in，一个句子就有了两个谓语。也可以写 which has resulted in。","subSkill":"present_participle_clauses_for_result_reason"},{"id":"gen-6-4-102","type":"fill","instruction":"〔写作 Task 1 · 考生常见错误〕有一处写错了，在空里写出正确的说法。原句：After washed, the wool is dried and spun into yarn.","sentence":"After ___, the wool is dried and spun into yarn.","acceptableAnswers":["being washed","washing","being cleaned","cleaning","it is washed","it has been washed","it is cleaned","it has been cleaned","having been washed","being thoroughly washed","it's washed","it's been washed","it's cleaned","it's been cleaned","being rinsed","being scoured","scouring","rinsing"],"explanation":"after 后面不能直接跟 washed。羊毛是被洗的 → after being washed；也可以写 After it has been washed 或 Once washed。流程描述里不带宾语的 After washing（＝洗完这一步）也常见。","subSkill":"participle_active_vs_passive"},{"id":"gen-6-4-103","type":"choice","instruction":"〔写作 Task 1 · 考生常见写法〕这句成了「工人被晾干」，选出改对的句子。原句：After being dried, workers pack the noodles into bags.","options":["After dried, the noodles are packed into bags.","After being dried, workers pack them into bags.","After being dried, the noodles are packed into bags.","After drying the noodles, they are packed into bags."],"correctIndex":2,"explanation":"被晾干的是面条，就让面条作主语：the noodles are packed。After dried 漏了 being；workers 作主语还是「工人被晾干」；第 4 句 drying the noodles 的主语成了 they，面条晾面条。","subSkill":"dangling_participle_avoidance"},{"id":"gen-6-4-104","type":"fill","instruction":"〔写作 Task 2 · 考生常见错误〕逗号后面这半句写错了，在空里改正。原句：Many teenagers spend hours on their phones before bed, this affects the quality of their sleep.","sentence":"Many teenagers spend hours on their phones before bed, ___ the quality of their sleep.","acceptableAnswers":["affecting","reducing","harming","damaging","lowering","worsening","thereby affecting","thereby reducing","which affects","which reduces","which harms","which damages","which lowers","which worsens","which can affect","which can reduce","which can harm","which can damage","and this affects","and this reduces","and this harms","and that affects","thus affecting","thus reducing","thus harming","thereby harming","thereby damaging","thereby lowering","thereby worsening","impairing","thereby impairing","which impairs","which can impair","negatively affecting","adversely affecting","which negatively affects","which adversely affects","which may affect","which can lower","which can worsen","which in turn affects","and this can affect","and this can reduce","and that reduces","compromising","which compromises","disrupting","thereby disrupting","which disrupts"],"explanation":"逗号不能连两个完整的句子。改成 , affecting …（接结果），或 , which affects …；也可以把逗号换成句号，再写 This affects …。","subSkill":"present_participle_clauses_for_result_reason"},{"id":"gen-6-4-105","type":"error","instruction":"〔写作 Task 2 · 考生常见错误〕很多移民因为不会当地语言，很难找到工作。点出用错的部分。","words":["Don't knowing","the local language,","many migrants","struggle","to find","work."],"errorIndex":0,"correction":"Not knowing","explanation":"分词的否定直接在前面加 not → Not knowing（= Because they don't know）。英文没有 Don't knowing 这种写法。","subSkill":"present_participle_clauses_for_result_reason"},{"id":"gen-6-4-106","type":"error","instruction":"〔写作 Task 2 · 考生常见错误〕点出用错的部分。","words":["If","not storing","correctly,","vaccines","can quickly lose","their effectiveness."],"errorIndex":1,"correction":"not stored","explanation":"疫苗是被存放的 → If not stored correctly（= If they are not stored correctly）。not storing 成了疫苗自己去存放东西。","subSkill":"past_participle_clauses_for_condition_concession"},{"id":"gen-6-4-107","type":"choice","instruction":"〔写作 Task 2 · 考生常见写法〕这句成了「空气污染住在大城市」，选出改对的句子。原句：Living in a big city, air pollution is a daily concern.","options":["Living in a big city, people worry about air pollution every day.","Lived in a big city, people worry about air pollution every day.","Living in a big city, air pollution worries people every day.","Living in a big city, air pollution is a daily concern for people."],"correctIndex":0,"explanation":"住在大城市的是人，逗号后的主语就得是 people。Lived 应为 Living（人自己住）；后两句主语还是 air pollution。也可以写 For people living in big cities, air pollution is a daily concern.","subSkill":"dangling_participle_avoidance"},{"id":"gen-6-4-108","type":"error","instruction":"〔口语 Part 1 · 考生常见错误〕点出用错的部分。","words":["I","know Beijing","really well,","lived","there","for over five years."],"errorIndex":3,"correction":"having lived","explanation":"在北京住了五年多，所以很熟 → , having lived there …（先发生，也是原因）。只写 lived，一句里就有了两个谓语。也可以说 because I've lived there …。","subSkill":"perfect_participle_having_done"},{"id":"gen-6-4-109","type":"error","instruction":"〔写作 Task 2 · 考生常见错误〕越来越多学生用 AI 写论文。点出用错的部分。","words":["With","more students","uses","AI tools","to write essays,","many universities","have changed","how they assess work."],"errorIndex":2,"correction":"using","explanation":"with 后面不能接完整的句子。学生自己在用 → with + 名词 + using。也可以改成 As more students use AI tools, …。","subSkill":"absolute_participial_constructions"}],"5":[{"id":"gen-6-5-100","type":"fill","instruction":"〔写作 Task 2〕把结果并进同一句。原句：Many towns have closed their public libraries. As a result, children have fewer places to study after school.","sentence":"Many towns have closed their public libraries, ___ children with fewer places to study after school.","acceptableAnswers":["leaving","thereby leaving","which has left","which leaves","and this has left","and this leaves","thus leaving","in turn leaving","effectively leaving","and that has left","and that leaves"],"explanation":"leaving … 接在句尾，说关图书馆带来的结果。leave sb with sth = 使某人只剩下…。which has left 也对。","subSkill":"present_participle_clauses_for_result_reason"},{"id":"gen-6-5-103","type":"fill","instruction":"〔写作 Task 1〕补全这段地图描述，用括号里的动词。先想清楚每个动作是谁做的。","sentence":"Overall, the island has been developed for tourism, with much of its forest ___ (clear) for hotels.\n___ (build) on the west coast, the largest hotel overlooks the beach.\nA pier has also been added, ___ (allow) boats to bring visitors straight to the hotel.","acceptableAnswers":["cleared","Built","allowing"],"blankAnswers":[["cleared","having been cleared","now cleared","being cleared"],["Built","Having been built","Newly built"],["allowing","thereby allowing","which allows","which has allowed","thus allowing","and this allows","and this has allowed","which now allows"]],"explanation":"① 森林是被砍掉的 → cleared。② 酒店是被建的 → Built。③ 加了码头，结果是船能直接靠岸 → allowing。每一空先问：主语自己做，还是被做？","subSkill":"participle_active_vs_passive"},{"id":"gen-6-5-101","type":"fill","instruction":"〔口语 Part 1〕考官问：Why did you decide to study abroad? 补全考生的回答，用括号里的词。","sentence":"Well, ___ (offer) a full scholarship, I couldn't really say no.\nBut ___ (never / live) away from home before, I found the first few months really hard.","acceptableAnswers":["having been offered","having never lived"],"blankAnswers":[["having been offered","after being offered","after I was offered","after I had been offered","after I'd been offered","when I was offered","as I was offered","since I was offered","because I was offered","offered","being offered","having received","after receiving","having won","after winning","having been given","having been awarded"],["having never lived","never having lived","not having lived","having not lived","as I had never lived","since I had never lived","because I had never lived","as I'd never lived","since I'd never lived","because I'd never lived"]],"explanation":"① 奖学金是别人给我的，而且在先 → having been offered。② 以前从没离家住过，所以头几个月很难 → having never lived（never having lived 也对）。","subSkill":"perfect_participle_having_done"},{"id":"gen-6-5-104","type":"fill","instruction":"〔写作 Task 1〕补全这段生命周期描述，用括号里的动词。先想清楚每件事的先后。","sentence":"___ (hatch) in a river, young salmon stay in fresh water for up to three years before ___ (swim) out to sea.\n___ (grow) to full size there, they return to the same river to spawn.","acceptableAnswers":["Having hatched","swimming","Having grown"],"blankAnswers":[["Having hatched","After hatching","Once hatched","Hatched","After having hatched","Once they have hatched","After they have hatched","After they hatch","Once they hatch","Having been hatched"],["swimming","they swim"],["Having grown","After growing","After having grown","Once grown","Once they have grown","After they have grown","When they have grown","After they grow","Once they grow"]],"explanation":"① 先孵出，后在淡水生活 → Having hatched。② before 后面接 doing → swimming（写 before they swim 也对）。③ 先在海里长大，再回河里产卵 → Having grown。Once hatched、Once grown 也对。","subSkill":"perfect_participle_having_done"},{"id":"gen-6-5-102","type":"scenario","instruction":"考生想说「我在城里逛了一整天，到晚上累坏了」。哪个说法准确？","context":"雅思口语 Part 2 · 题卡：Describe a city you have visited … and explain how you felt about it","dialogue":[],"options":["Having walked around the city all day, my legs were completely exhausted by the evening.","Walked around the city all day, I was completely exhausted by the evening.","Having walked around the city all day, the evening left me completely exhausted.","Having walked around the city all day, I was completely exhausted by the evening."],"correctIndex":3,"explanation":"第 4 个准确：逛了一天的是 I，主句主语也是 I。第 1、3 个成了「腿逛了一天」「晚上逛了一天」；第 2 个 Walked 应为 Having walked。","subSkill":"dangling_participle_avoidance"},{"id":"gen-6-5-105","type":"fill","instruction":"〔写作 Task 2〕补全这段论证，用括号里的动词。","sentence":"Fast fashion has made clothes very cheap, ___ (lead) people to buy far more than they need.\n___ (produce) in huge quantities, these clothes are often thrown away within months.\nIf ___ (encourage) to repair them, consumers could cut this waste.","acceptableAnswers":["leading","Produced","encouraged"],"blankAnswers":[["leading","thereby leading","thus leading","in turn leading","which leads","which has led","and this leads","and this has led"],["Produced","Mass-produced","Having been produced","Mass produced","Being produced"],["encouraged","they were encouraged","they are encouraged"]],"explanation":"① 衣服变便宜带来的结果 → leading。② 衣服是被生产的 → Produced。③ If encouraged = If they were encouraged，被鼓励的是主语 consumers。","subSkill":"present_participle_clauses_for_result_reason"},{"id":"gen-6-5-106","type":"fill","instruction":"〔写作 Task 2〕把原因并进同一句。原句：Most of the farm's land has been covered with solar panels. As a result, it now produces more electricity than food.","sentence":"With most of its land ___ with solar panels, the farm now produces more electricity than food.","acceptableAnswers":["covered","now covered","having been covered","already covered","filled","now filled"],"explanation":"土地是被太阳能板盖住的 → with + 名词 + covered。with 后面不能写 has been covered（那是完整的句子），也不能写 covering（成了土地去盖别的）。","subSkill":"absolute_participial_constructions"},{"id":"gen-6-5-107","type":"fill","instruction":"〔口语 Part 3〕考官问：Why do some people prefer to live in the countryside? 补全考生的回答。","sentence":"Well, ___ (bring up) in a small village myself, I can understand that.\nLife there is much slower, ___ (give) people more time for their families.","acceptableAnswers":["having been brought up","giving"],"blankAnswers":[["having been brought up","brought up","as I was brought up","since I was brought up","because I was brought up","having been raised","having grown up"],["giving","which gives","and this gives","and that gives","thus giving","thereby giving","which in turn gives"]],"explanation":"① 我是被父母带大的，而且在先 → having been brought up（brought up 也对）。② 节奏慢带来的结果 → giving。两处的主语都对得上。","subSkill":"perfect_participle_having_done"},{"id":"gen-6-5-108","type":"fill","instruction":"〔口语 Part 2〕题卡：Describe a historic building you have visited。补全这段描述，用括号里的动词。","sentence":"___ (damage) in a fire in 1990, the castle was later restored and opened to the public.\n___ (stand) on a hill above the town, it is now the area's most popular attraction.","acceptableAnswers":["Damaged","Standing"],"blankAnswers":[["Damaged","Badly damaged","Severely damaged","Having been damaged","Having been badly damaged","Having been severely damaged","After being damaged","After being badly damaged","After it was damaged","After it was badly damaged","After it had been damaged","After it had been badly damaged"],["Standing","Sitting","Perched","Located","Situated","Set"]],"explanation":"① 城堡是被烧坏的，而且在修复之前 → Damaged（Having been damaged 也对）。② 城堡自己立在山上 → Standing（Located、Perched 也对）。","subSkill":"participle_active_vs_passive"}]}},"7":{"levels":{"1":[{"id":"gen-7-1-100","type":"choice","instruction":"〔口语 Part 2〕两年前老师预测我会轻松通过考试，结果我没过。空格填哪个？","sentence":"Two years ago, my teacher told me that I ___ the exam easily, but I failed.","options":["will pass","had passed","would pass","would have passed"],"correctIndex":2,"explanation":"老师的原话是 You will pass easily。考试现在已经是过去的事，转述时 will 退成 would（后来过没过都一样）。had passed 成了「已经过了」；would have passed 是「本来会过」的假设。","subSkill":"backshift_in_complex_reported_speech"},{"id":"gen-7-1-101","type":"match","instruction":"〔写作 Task 2〕只看转述动词：作者把后面的内容当作事实，还是只当作别人的说法？连线。","left":["Studies have shown that…","Many parents assume that…","As doctors point out, …","Some companies claim that…"],"right":["The writer treats it as a fact.","It is only someone else's view."],"correctPairs":[[0,0],[1,1],[2,0],[3,1]],"explanation":"show、point out 带着「这是事实」的意思，作者认同；assume（想当然地认为）、claim（声称）只是对方的说法，作者没认可，后面常接反驳。","subSkill":"academic_reporting_with_that_clauses"},{"id":"gen-7-1-102","type":"choice","instruction":"〔口语 Part 1〕读句子，回答问题。原句：My cousin told me he works for a bank.","sentence":"Does the speaker's cousin still work for a bank?","options":["It isn't clear from this.","Yes, he still works there.","No, he left the bank before."],"correctIndex":1,"explanation":"还在。told 是过去，但 works 没有退成 worked：说话人把它当作现在仍然成立的事。要是写 worked，就听不出他现在还在不在了。","subSkill":"no_backshift_for_general_truths"},{"id":"gen-7-1-103","type":"choice","instruction":"〔口语 Part 2〕读句子，回答问题。原句：The doctor asked me whether I had ever had an operation.","sentence":"What were the doctor's actual words?","options":["Would you ever have an operation?","Why did you have an operation?","Will you have an operation?","Have you ever had an operation?"],"correctIndex":3,"explanation":"whether 说明原话是「是不是」的问题，不是 why 问句；had ever had 是 have ever had 往后退了一步，问的是以前的经历；would ever have 问的是将来。","subSkill":"reporting_questions_and_imperatives"},{"id":"gen-7-1-104","type":"scenario","instruction":"读考生的回答，回答问题：Whose view does the candidate agree with?","context":"雅思口语 Part 3 · Technology and children","dialogue":[{"speaker":"examiner","text":"Examiner: Some people say children today spend too much time on screens. What's your view?"},{"speaker":"player","text":"Well, many parents claim that tablets are ruining their children's concentration, but as teachers often point out, the real problem is how the devices are used."}],"options":["The parents' view","The teachers' view","Both views equally","Neither of the two"],"correctIndex":1,"explanation":"claim 只是转述家长的说法，考生没有认可；as teachers point out 表示考生认同老师：问题在怎么用，不在设备本身。","subSkill":"reporting_verbs_with_varied_patterns_claim_argue_suggest"},{"id":"gen-7-1-105","type":"choice","instruction":"〔口语 Part 2〕读句子，回答问题。原句：Before my first job interview, my sister told me not to talk too much about money.","sentence":"What did the speaker's sister actually say?","options":["You didn't talk too much about money.","I won't talk too much about money.","Don't talk too much about money.","Why do you talk so much about money?"],"correctIndex":2,"explanation":"told me not to do = 叫我别做，原话是祈使句 Don't talk…。转述命令或劝告：tell / ask + 人 + (not) to do。","subSkill":"reporting_questions_and_imperatives"},{"id":"gen-7-1-106","type":"choice","instruction":"〔写作 Task 2〕读句子，回答问题。原句：Supporters of mass tourism admit that it can damage local culture.","sentence":"What do supporters of mass tourism say about local culture?","options":["They accept tourism can harm it.","They deny tourism harms it.","They say the harm is overstated.","They do not mention it."],"correctIndex":0,"explanation":"admit = 承认（对自己一方不利的事）：连支持者也承认有坏处。作者引用对方的让步，自己的观点就更有说服力。","subSkill":"reporting_verbs_with_varied_patterns_claim_argue_suggest"},{"id":"gen-7-1-107","type":"choice","instruction":"〔写作 Task 2〕读句子，回答问题。原句：In 2015, the council announced that the new library would open the following year. It finally opened in 2019.","sentence":"Did the new library open on schedule?","options":["Yes, it opened as planned.","Yes, it opened a year early.","No, it never opened at all.","No, it was three years late."],"correctIndex":3,"explanation":"would open 是当年说的「将来」：计划 the following year，也就是 2016 年。实际 2019 年才开，晚了三年。转述时 will 退成 would，next year 变成 the following year。","subSkill":"backshift_in_complex_reported_speech"},{"id":"gen-7-1-108","type":"match","instruction":"〔写作 Task 2〕同一个 suggest，意思不同。看后面的动词：在说发现了什么，还是在提建议？连线。","left":["The survey suggests that the average teenager sleeps too little.","The report suggests that every school start later.","The data suggest that online shopping has risen sharply.","The author suggests that each family eat dinner together."],"right":["It reports a finding.","It gives advice."],"correctPairs":[[0,0],[1,1],[2,0],[3,1]],"explanation":"sleeps、has risen 是正常时态 → suggest = 表明。start、eat 用原形，主语是单数也不加 -s → suggest = 建议，相当于 should start / should eat。","subSkill":"reporting_verbs_with_varied_patterns_claim_argue_suggest"}],"2":[{"id":"gen-7-2-100","type":"choice","instruction":"〔写作 Task 2〕想说「一些经济学家提出，政府应该给小企业减税」。选出合适的形式。","sentence":"Some economists suggest ___ taxes for small businesses.","options":["the government to reduce","for the government to reduce","that the government reduce","to reduce"],"correctIndex":2,"explanation":"suggest 后面接 that + 人 + (should) 原形：that the government (should) reduce。suggest 不接「人 + to do」，for … to do 也不对；to reduce 不但不对，还丢了「政府」。","subSkill":"reporting_verbs_with_varied_patterns_claim_argue_suggest"},{"id":"gen-7-2-101","type":"choice","instruction":"〔写作 Task 2〕读完整句，选出和后半句搭配的动词。","sentence":"Some business leaders ___ that working from home makes staff lazy, but there is little evidence for this.","options":["have shown","point out","have proved","claim"],"correctIndex":3,"explanation":"作者不认同 → claim（声称），只转述对方的说法。have shown、point out、have proved 都把内容当作事实，和后半句「没什么证据」矛盾。","subSkill":"reporting_verbs_with_varied_patterns_claim_argue_suggest"},{"id":"gen-7-2-102","type":"choice","instruction":"〔写作 Task 2〕想说「部长最终承认，这个项目花了原定预算的两倍」。选出合适的动词。","sentence":"The minister finally ___ that the project had cost twice its original budget.","options":["admitted","claimed","insisted","denied"],"correctIndex":0,"explanation":"admit = 承认（对自己不利的事），finally 也说明他之前不愿说。claimed 是「声称」，insisted 是「坚持说」，都没有让步的意思；denied 是否认，意思反了。","subSkill":"reporting_verbs_with_varied_patterns_claim_argue_suggest"},{"id":"gen-7-2-103","type":"choice","instruction":"〔口语 Part 1〕想说「新同学问我为什么选这个专业」。选出合适的形式。","sentence":"A new classmate asked me ___ this course.","options":["why did I choose","why I chose","why do I choose","why I choose"],"correctIndex":1,"explanation":"原话 Why did you choose this course? 转述时去掉 did、主语放前面：why I chose（也可以 why I had chosen）。why I choose 时间不对：选专业在提问之前。","subSkill":"reporting_questions_and_imperatives"},{"id":"gen-7-2-104","type":"scenario","instruction":"考生想说「教练叫我别放弃」。选出准确的一句。","context":"雅思口语 Part 2 · 题卡：Describe a time when you almost gave up","dialogue":[],"options":["My coach told me don't give up.","My coach said me not to give up.","My coach told to me not give up.","My coach told me not to give up."],"correctIndex":3,"explanation":"tell + 人 + not to do：told me not to give up。don't give up 是原话，不能直接搬进转述；said 后面不直接跟人；told to me 也不对。","subSkill":"reporting_questions_and_imperatives"},{"id":"gen-7-2-105","type":"choice","instruction":"〔写作 Task 2〕想说「早在 1980 年代，研究人员就发现二手烟伤害不吸烟的人」。选出最合适的形式。","sentence":"As early as the 1980s, researchers found that second-hand smoke ___ non-smokers.","options":["harms","will harm","had harmed","would harm"],"correctIndex":0,"explanation":"这是今天依然成立的事实，可以不退时态：harms。had harmed 成了「发现之前就伤害过」；would harm 像是当时的预测；will harm 时间对不上。","subSkill":"no_backshift_for_general_truths"},{"id":"gen-7-2-106","type":"choice","instruction":"〔口语 Part 2〕想说「去年夏天朋友告诉我，她当时正在找工作」。选出合适的形式。","sentence":"Last summer my friend told me that she ___ for a new job.","options":["is looking","was looking","had looked","would look"],"correctIndex":1,"explanation":"原话 I'm looking for a new job → 退一步 was looking（当时正在找）。had looked 成了「更早找过」；would look 是将来；is looking 说成了现在还在找。","subSkill":"backshift_in_complex_reported_speech"},{"id":"gen-7-2-107","type":"choice","instruction":"〔写作 Task 2〕想说「有人认为，动物园已经没有存在的必要了」。选出合适的开头。","sentence":"___ zoos are no longer necessary.","options":["Some people argue that","According to some people's opinion,","As some people argue that","Some people are argued that"],"correctIndex":0,"explanation":"Some people argue that + 完整句子。According to 后面直接接人或来源，不加 opinion；As … argue 后面不再加 that；被动的转述要写成 It is often argued that…，不能写 Some people are argued that。","subSkill":"academic_reporting_with_that_clauses"},{"id":"gen-7-2-108","type":"choice","instruction":"〔口语 Part 2〕想说「我爸爸坚持要我学医，尽管我想学美术」。选出合适的形式。","sentence":"My father insisted ___ medicine, even though I wanted to study art.","options":["me to study","that I study","to me to study","me studying"],"correctIndex":1,"explanation":"insist 后面接 that + 人 + (should) 原形，或 insist on my studying。insist 不接「人 + to do」，这是「坚持要我…」的直译。","subSkill":"reporting_verbs_with_varied_patterns_claim_argue_suggest"},{"id":"gen-7-2-109","type":"match","instruction":"〔口语 Part 2〕两句只差一个词。她住在利兹，是说话的时候，还是更早？连线。","left":["She told me she lived in Leeds.","She told me she had lived in Leeds."],"right":["She lived there when she said it.","She had lived there before then."],"correctPairs":[[0,0],[1,1]],"explanation":"lived 是 live 退一步：原话 I live in Leeds，她当时就住那里。had lived 是 lived / have lived 退一步：说的是更早的经历。","subSkill":"backshift_in_complex_reported_speech"}],"3":[{"id":"gen-7-3-100","type":"fill","instruction":"〔口语 Part 2〕把导师的原话转述出来。原句：My tutor said, \"You have improved a lot, and you will get a 7 if you keep practising.\"","sentence":"My tutor told me that I ___ a lot and that I ___ a 7 if I kept practising.","acceptableAnswers":["had improved","would get"],"blankAnswers":[["had improved","'d improved","had really improved"],["would get","'d get","would achieve","would score"]],"explanation":"导师说的是当时和将来：have improved → had improved，will get → would get。if 那半句也跟着退了：keep → kept。","subSkill":"backshift_in_complex_reported_speech"},{"id":"gen-7-3-101","type":"fill","instruction":"〔写作 Task 2〕用 suggest 改写，意思不变。原句：Some experts say that employers should give new fathers at least a month of paid leave.","sentence":"Some experts suggest ___ new fathers at least a month of paid leave.","acceptableAnswers":["that employers give","that employers should give","employers give","employers should give","that employers offer","that employers should offer","employers offer","employers should offer","that employers grant","that employers should grant","employers grant","employers should grant","that companies give","that companies should give","companies give","companies should give","that companies offer","that companies should offer","companies offer","companies should offer","that companies grant","that companies should grant","companies grant","companies should grant","giving","offering","granting"],"explanation":"suggest + that + 人 + (should) 原形：that employers (should) give；也可以 suggest giving…。别写 suggest employers to give。","subSkill":"reporting_verbs_with_varied_patterns_claim_argue_suggest"},{"id":"gen-7-3-102","type":"fill","instruction":"〔口语 Part 2〕把面试官的问题放进句子里。原句：The interviewer asked, \"Why did you leave your last job?\"","sentence":"The interviewer asked me ___ my last job.","acceptableAnswers":["why I had left","why I left","why I'd left","why I had quit","why I quit","why I'd quit","why I had decided to leave","why I decided to leave","why I'd decided to leave"],"explanation":"转述问题用陈述语序：why I had left（或 why I left），去掉 did，不倒装。离职在面试之前，用 had left 最清楚。","subSkill":"reporting_questions_and_imperatives"},{"id":"gen-7-3-103","type":"fill","instruction":"〔写作 Task 2〕把问句改成转述，放进句子里。原句：Many people now ask: \"Is a university degree still worth the cost?\"","sentence":"Many people now question ___ still worth the cost.","acceptableAnswers":["whether a university degree is","if a university degree is","whether a degree is","if a degree is","whether university degrees are","whether degrees are","if university degrees are","whether a college degree is","whether a university education is","whether going to university is","whether university education is","if university education is","if a university education is","if degrees are","if a college degree is","if going to university is","whether or not a university degree is","whether or not a degree is","whether higher education is","if higher education is","whether getting a degree is","if getting a degree is"],"explanation":"「是不是」的问题转述用 whether（或 if），后面按陈述语序：whether a university degree is…，不写 whether is a degree…，问号也去掉。","subSkill":"reporting_questions_and_imperatives"},{"id":"gen-7-3-104","type":"fill","instruction":"〔口语 Part 2〕用 warn 转述医生的话。原句：The doctor said to me, \"Don't lift anything heavy for a month.\"","sentence":"The doctor warned me ___ anything heavy for a month.","acceptableAnswers":["not to lift","not to carry","not to pick up","to not lift","to avoid lifting","against lifting","against carrying","to not carry","to avoid carrying","against picking up","to avoid picking up"],"explanation":"warn / tell + 人 + not to do：warned me not to lift（也可以 warned me against lifting）。原话的 Don't lift 不能直接搬进转述。","subSkill":"reporting_questions_and_imperatives"},{"id":"gen-7-3-105","type":"fill","instruction":"〔写作 Task 2〕作者认同这项研究的结论，把两句合成一句。原句：Researchers studied 5,000 teenagers. Result: those who sleep less get lower grades.","sentence":"A study of 5,000 teenagers ___ those who sleep less get lower grades.","acceptableAnswers":["has shown that","shows that","showed that","has clearly shown that","clearly shows that","has shown","shows","showed","finds that","finds","found that","found","has found that","has found","demonstrates that","demonstrates","demonstrated that","demonstrated","has demonstrated that","has demonstrated","reveals that","reveals","revealed that","revealed","has revealed that","has revealed","proves that","proves","proved that","proved","has proved that","has proved","has proven that","has proven","confirms that","confirms","confirmed that","confirmed","has confirmed that","has confirmed","indicates that","indicates","indicated that","indicated","has indicated that","has indicated","suggests that","suggests","suggested that","suggested","has suggested that","has suggested","clearly shows","clearly showed that","clearly showed","has clearly shown"],"explanation":"作者认同 → 用 show / find / demonstrate 这类把结论当作事实的动词：A study … has shown that…；别用 claim。get 不用退：结论今天仍然成立。","subSkill":"academic_reporting_with_that_clauses"},{"id":"gen-7-3-106","type":"fill","instruction":"〔写作 Task 2〕把政府当年的承诺转述出来。原句：In 2018 the government said, \"We will build 50 new hospitals by 2025.\"","sentence":"In 2018 the government promised that it ___ 50 new hospitals by 2025.","acceptableAnswers":["would build","'d build","would have built","would construct","would open","was going to build"],"explanation":"承诺是 2018 年做的，原话 will build → 退一步 would build。原话的 we 已经换成了 it，动词也要跟着换到过去的视角。","subSkill":"backshift_in_complex_reported_speech"},{"id":"gen-7-3-107","type":"fill","instruction":"〔写作 Task 2〕改成「人 + 转述动词 + that」，作者暂不表态。原句：According to some economists, robots will create more jobs than they destroy.","sentence":"Some economists ___ robots will create more jobs than they destroy.","acceptableAnswers":["argue that","claim that","believe that","predict that","maintain that","contend that","suggest that","think that","say that","expect that","insist that","are convinced that","have argued that","have claimed that","have predicted that","have suggested that","forecast that","argue","claim","believe","predict","maintain","contend","suggest","think","say","expect","insist","forecast","are confident that","assume that","estimate that","hold that","reckon that","feel that","feel","state that","state","would argue that","have long argued that","are optimistic that"],"explanation":"人 + argue / claim / predict + that + 完整句子，一眼看出是谁在主张什么。作者暂不表态，就别用 point out 或 show，它们表示认同。","subSkill":"academic_reporting_with_that_clauses"},{"id":"gen-7-3-108","type":"fill","instruction":"〔写作 Task 2〕用 accuse 改写。原句：Many people say that fast-fashion brands are wasting natural resources.","sentence":"Many people accuse fast-fashion brands ___ natural resources.","acceptableAnswers":["of wasting","of squandering","of misusing","of overusing","of depleting"],"explanation":"accuse + 人 + of doing：accuse brands of wasting。不说 accuse … for / to waste。类似的还有 blame … for doing。","subSkill":"reporting_verbs_with_varied_patterns_claim_argue_suggest"},{"id":"gen-7-3-109","type":"reorder","instruction":"〔写作 Task 2〕排出这句：批评者质疑禁用塑料袋是否真能减少浪费。","words":["plastic","Critics","will","bag","whether","reduce","question","the","ban","really","waste."],"correctSentence":"Critics question whether the plastic bag ban will really reduce waste.","acceptableSentences":["Critics question whether the plastic bag ban really will reduce waste."],"explanation":"question whether + 陈述语序：whether the plastic bag ban will…，主语在前，不把 will 提到主语前面。","subSkill":"reporting_questions_and_imperatives"}],"4":[{"id":"gen-7-4-100","type":"fill","instruction":"〔口语 Part 2 · 考生常见错误〕有一处动词形式错了，在空里写出正确的形式。原句：Last year my parents promised that they will buy me a laptop if I passed the exam.","sentence":"Last year my parents promised that they ___ me a laptop if I passed the exam.","acceptableAnswers":["would buy","'d buy","would get","'d get"],"explanation":"承诺是去年的事，后面的 passed 也退了，will 要跟着退成 would。讲过去的故事时，漏改 will 是很常见的错。","subSkill":"backshift_in_complex_reported_speech"},{"id":"gen-7-4-101","type":"fill","instruction":"〔口语 Part 2 · 考生常见错误〕保留 suggested，把后半句改对。原句：My careers adviser suggested me to take a gap year before university.","sentence":"My careers adviser suggested ___ a gap year before university.","acceptableAnswers":["that I take","that I should take","I take","I should take","taking","my taking","that I took","I took"],"explanation":"suggest 不接「人 + to do」：suggested that I (should) take，或 suggested taking。想用「人 + to do」，就换动词：advised me to take。","subSkill":"reporting_verbs_with_varied_patterns_claim_argue_suggest"},{"id":"gen-7-4-102","type":"error","instruction":"〔口语 Part 2 · 考生常见错误〕点出用错的部分。","words":["When we first met,","she asked me","where","was I from","and what I was studying."],"errorIndex":3,"correction":"I was from","explanation":"转述问题用陈述语序：where I was from，主语在前。后半句 what I was studying 的语序就是对的。","subSkill":"reporting_questions_and_imperatives"},{"id":"gen-7-4-103","type":"error","instruction":"〔口语 Part 2 · 考生常见错误〕点出用错的部分。","words":["Before the exam,","my teacher","told me","don't panic","if I got stuck","on a question."],"errorIndex":3,"correction":"not to panic","explanation":"转述劝告：told me not to panic。don't panic 是原话的祈使句，不能直接搬进来；if I got stuck 退了时态，是对的。","subSkill":"reporting_questions_and_imperatives"},{"id":"gen-7-4-104","type":"error","instruction":"〔写作 Task 2 · 考生常见错误〕点出用错的部分。","words":["Some people","argue that","is unfair","to charge visitors","for entering","national museums."],"errorIndex":2,"correction":"it is unfair","explanation":"that 后面要接完整的句子，主语不能省：argue that it is unfair to charge…。it 指后面的 to charge visitors…。","subSkill":"academic_reporting_with_that_clauses"},{"id":"gen-7-4-105","type":"error","instruction":"〔口语 Part 2 · 考生常见错误〕点出用错的部分。","words":["On my first day,","my new manager","told that","we could","leave early","on Fridays."],"errorIndex":2,"correction":"told us that","explanation":"tell 后面要跟人：told us that…；不提人就用 said that…。could 是原话 can 退了一步，是对的。","subSkill":"reporting_verbs_with_varied_patterns_claim_argue_suggest"},{"id":"gen-7-4-106","type":"error","instruction":"〔口语 Part 2 · 考生常见错误〕点出用错的部分。","words":["When I was little,","my father","often","said me","that hard work","always pays off."],"errorIndex":3,"correction":"told me","explanation":"say 后面不直接跟人：told me that…（或 said to me that…）。pays off 不用退成 paid off：这是至今成立的道理。","subSkill":"reporting_verbs_with_varied_patterns_claim_argue_suggest"},{"id":"gen-7-4-107","type":"error","instruction":"〔口语 Part 2 · 考生常见错误〕点出用错的部分。","words":["My teacher","explained me","why","my answer","was wrong."],"errorIndex":1,"correction":"explained to me","explanation":"explain 后面不直接跟人：explained to me why…（和 say 一样）。why my answer was wrong 是陈述语序，was 也跟着退了，都对。","subSkill":"reporting_verbs_with_varied_patterns_claim_argue_suggest"},{"id":"gen-7-4-108","type":"fill","instruction":"〔写作 Task 2 · 考生常见错误〕保留 denied，把后半句改对。原句：The company denied to sell its customers' data to advertisers.","sentence":"The company denied ___ its customers' data to advertisers.","acceptableAnswers":["selling","having sold","that it sold","that it had sold","that it was selling","that it had been selling","it sold","it had sold","that they sold","that they had sold","that it ever sold","ever selling","ever having sold","that it had ever sold","it had ever sold","having ever sold","it was selling","it had been selling","they sold","they had sold","that they were selling","that they had been selling"],"explanation":"deny 后面接 doing 或 that 从句：denied selling / denied that it had sold，不接 to do。想说「拒绝卖」用 refused to sell。","subSkill":"reporting_verbs_with_varied_patterns_claim_argue_suggest"},{"id":"gen-7-4-109","type":"choice","instruction":"〔写作 Task 2 · 考生常见写法〕这是「根据我的观点」的直译，选出自然的写法。原句：According to my opinion, school uniforms should be optional.","sentence":"___ school uniforms should be optional.","options":["According to me,","As my opinion,","To my opinion,","In my opinion,"],"correctIndex":3,"explanation":"说自己的看法用 In my opinion / I believe that…。According to 用来引别人或资料：According to the report, …，不跟 my opinion，也不跟 me。","subSkill":"academic_reporting_with_that_clauses"}],"5":[{"id":"gen-7-5-100","type":"fill","instruction":"〔写作 Task 2〕补全这段论证，用括号里的动词。先想清楚：谁在说、什么时候说的、作者认不认同。","sentence":"Supporters of homework ___ (argue) that it teaches children to work independently. However, a 2006 review of research ___ (find) that homework does little to improve primary pupils' results. As many teachers ___ (point out), young children need time to play.","acceptableAnswers":["argue","found","point out"],"blankAnswers":[["argue","have argued","often argue","have long argued","would argue","'d argue","have often argued"],["found","has found"],["point out","have pointed out","pointed out","rightly point out","have rightly pointed out","often point out","have often pointed out","rightly pointed out"]],"explanation":"① argue：他们现在的观点，用现在时。② found：2006 年的研究，用过去时；后面 does 不退，作者认为结论至今成立。③ point out：作者认同，拿来支持自己的论点。","subSkill":"academic_reporting_with_that_clauses"},{"id":"gen-7-5-101","type":"fill","instruction":"〔口语 Part 2 · 题卡：Describe a piece of advice you received〕用括号里的词补全。","sentence":"When I was sixteen, I told my uncle that I ___ (want) to leave school. He didn't get angry; he just asked me what I ___ (plan) to do instead and advised me ___ (talk) to my teachers first.","acceptableAnswers":["wanted","planned","to talk"],"blankAnswers":[["wanted"],["planned","was planning","had planned"],["to talk","to speak"]],"explanation":"① 原话 I want… → wanted。② 原问题 What do you plan to do? → 陈述语序 what I planned（或 was planning）。③ advise + 人 + to do：advised me to talk。","subSkill":"reporting_questions_and_imperatives"},{"id":"gen-7-5-102","type":"scenario","instruction":"考生认同医生，不认同广告。哪个回答把这层态度说清楚了？","context":"雅思口语 Part 3 · Health advice","dialogue":[{"speaker":"examiner","text":"Examiner: Why do many people ignore advice from health experts?"}],"options":["Adverts point out that diet pills work, but doctors claim they don't.","Adverts prove that diet pills work, but doctors admit they don't.","Adverts claim that diet pills work, but doctors point out they don't.","Adverts have shown that diet pills work, but doctors claim they don't."],"correctIndex":2,"explanation":"认同医生 → point out（当作事实）；不认同广告 → claim（只是声称）。把 point out、prove、show 用在广告上，等于替广告背书，态度就反了。","subSkill":"reporting_verbs_with_varied_patterns_claim_argue_suggest"},{"id":"gen-7-5-103","type":"fill","instruction":"〔写作 Task 2〕把口语化的三句合成一句。原句：Some people think online degrees are good. Other people are not sure. They ask: Do online degrees really help graduates find jobs?","sentence":"While some people value online degrees, others ___ really help graduates find jobs.","acceptableAnswers":["question whether they","question whether online degrees","question whether such degrees","question whether these degrees","doubt whether they","doubt whether online degrees","doubt whether such degrees","doubt whether these degrees","wonder whether they","wonder whether online degrees","wonder whether such degrees","wonder whether these degrees","question if they","question if online degrees","question if such degrees","question if these degrees","doubt if they","doubt if online degrees","doubt if such degrees","doubt if these degrees","wonder if they","wonder if online degrees","wonder if such degrees","wonder if these degrees","ask whether they","ask whether online degrees","ask whether such degrees","ask whether these degrees","ask if they","ask if online degrees","ask if such degrees","ask if these degrees","are not sure whether they","are not sure whether online degrees","are not sure whether such degrees","are not sure whether these degrees","are unsure whether they","are unsure whether online degrees","are unsure whether such degrees","are unsure whether these degrees","are not sure if they","are not sure if online degrees","are not sure if such degrees","are not sure if these degrees","are unsure if they","are unsure if online degrees","are unsure if such degrees","are unsure if these degrees","doubt that they","doubt that online degrees","doubt that such degrees","doubt that these degrees","are not convinced that they","are not convinced that online degrees","are not convinced that such degrees","are not convinced that these degrees","are not convinced they","are not convinced online degrees","are not convinced such degrees","are not convinced these degrees","remain unconvinced that they","remain unconvinced that online degrees","remain unconvinced that such degrees","remain unconvinced that these degrees","are less sure whether they","are less sure whether online degrees","are less sure whether such degrees","are less sure whether these degrees","are sceptical about whether they","are sceptical about whether online degrees","are sceptical about whether such degrees","are sceptical about whether these degrees","are skeptical about whether they","are skeptical about whether online degrees","are skeptical about whether such degrees","are skeptical about whether these degrees","doubt they","doubt online degrees","doubt such degrees","doubt these degrees","are doubtful whether they","are doubtful whether online degrees","are doubtful whether such degrees","are doubtful whether these degrees","are doubtful that they","are doubtful that online degrees","are doubtful that such degrees","are doubtful that these degrees","have doubts about whether they","have doubts about whether online degrees","have doubts about whether such degrees","have doubts about whether these degrees","are unconvinced that they","are unconvinced that online degrees","are unconvinced that such degrees","are unconvinced that these degrees","are uncertain whether they","are uncertain whether online degrees","are uncertain whether such degrees","are uncertain whether these degrees","are sceptical that they","are sceptical that online degrees","are sceptical that such degrees","are sceptical that these degrees","are skeptical that they","are skeptical that online degrees","are skeptical that such degrees","are skeptical that these degrees"],"explanation":"Do … help…? 转述成 whether they really help，按陈述语序，去掉 do。question / doubt whether 本身就带着怀疑，比 They ask: … 紧凑得多。","subSkill":"reporting_questions_and_imperatives"},{"id":"gen-7-5-104","type":"fill","instruction":"〔写作 Task 2〕用括号里的动词补全。想一想：哪件事今天还在继续？","sentence":"In 2019, scientists warned that the Arctic ___ (warm) faster than the rest of the planet and that its summer ice ___ (disappear) by 2050.","acceptableAnswers":["is warming","will disappear"],"blankAnswers":[["is warming","was warming","has been warming","had been warming","warms","warmed","is heating up","was heating up","has been heating up"],["will disappear","would disappear","could disappear","might disappear","may disappear","will have disappeared","would have disappeared","will be gone","would be gone"]],"explanation":"warned 是过去，但北极变暖今天还在继续 → is warming 更清楚（was warming 也对）；2050 年还没到 → will disappear 也可以不退（would disappear 也对）。不退时态，读者一眼看出作者认为这仍然成立。","subSkill":"no_backshift_for_general_truths"},{"id":"gen-7-5-105","type":"fill","instruction":"〔写作 Task 2〕补全这段论证，用括号里的动词。注意谁在说、什么时候说的。","sentence":"Residents of many popular cities ___ (complain) that tourists push up rents. In 2017, one European city announced that it ___ (limit) the number of new hotels. The evidence so far ___ (suggest) that such limits help if short-term rentals are also controlled.","acceptableAnswers":["complain","would limit","suggests"],"blankAnswers":[["complain","have complained","often complain","have long complained"],["would limit","was going to limit","would be limiting","was limiting","'d limit"],["suggests","has suggested","seems to suggest","does suggest","would suggest","appears to suggest"]],"explanation":"① complain：现在的普遍情况。② 2017 年宣布的「将来」，will limit → would limit。③ evidence 不可数，谓语用单数 suggests；这里 suggest = 表明，用正常时态。","subSkill":"backshift_in_complex_reported_speech"},{"id":"gen-7-5-106","type":"fill","instruction":"〔写作 Task 2〕作者想说：连反对核电的人也不否认这一点。补上一个动词。原句：People who oppose nuclear power also say this: it produces very little carbon dioxide.","sentence":"Even critics of nuclear power ___ that it produces very little carbon dioxide.","acceptableAnswers":["admit","accept","acknowledge","concede","agree","recognise","recognize","grant","have admitted","have accepted","have acknowledged","have conceded","have agreed","have recognised","have recognized","would admit","would agree","would accept","would acknowledge","would concede","admitted","accepted","acknowledged","conceded","agreed","recognised","recognized","readily admit","readily accept","readily acknowledge","readily agree","do not deny","cannot deny","will admit","will concede","will acknowledge","will accept","will agree","have to admit","have to accept","must admit","must accept","readily concede","freely admit"],"explanation":"Even critics … admit / accept / acknowledge that…：连反对者都承认，这个让步让论证更可信。别用 claim，它表示作者不认同。","subSkill":"reporting_verbs_with_varied_patterns_claim_argue_suggest"},{"id":"gen-7-5-107","type":"fill","instruction":"〔写作 Task 2 · 开头段〕合成一句：先转述对方的观点，再给出自己的立场。原句：Some people argue that video games waste young people's time. I believe they can also teach problem-solving skills.","sentence":"___ video games waste young people's time, I believe they can also teach problem-solving skills.","acceptableAnswers":["While some people argue that","While some people claim that","While some people believe that","While some people think that","While some people may argue that","While some people may claim that","While some people feel that","While some people maintain that","While some people say that","While some people insist that","While some argue that","While some claim that","While some believe that","While some think that","While some may argue that","While some may claim that","While some feel that","While some maintain that","While some say that","While some insist that","While many people argue that","While many people claim that","While many people believe that","While many people think that","While many people may argue that","While many people may claim that","While many people feel that","While many people maintain that","While many people say that","While many people insist that","Although some people argue that","Although some people claim that","Although some people believe that","Although some people think that","Although some people may argue that","Although some people may claim that","Although some people feel that","Although some people maintain that","Although some people say that","Although some people insist that","Although some argue that","Although some claim that","Although some believe that","Although some think that","Although some may argue that","Although some may claim that","Although some feel that","Although some maintain that","Although some say that","Although some insist that","Although many people argue that","Although many people claim that","Although many people believe that","Although many people think that","Although many people may argue that","Although many people may claim that","Although many people feel that","Although many people maintain that","Although many people say that","Although many people insist that","Though some people argue that","Though some people claim that","Though some people believe that","Though some people think that","Though some people may argue that","Though some people may claim that","Though some people feel that","Though some people maintain that","Though some people say that","Though some people insist that","Though some argue that","Though some claim that","Though some believe that","Though some think that","Though some may argue that","Though some may claim that","Though some feel that","Though some maintain that","Though some say that","Though some insist that","Though many people argue that","Though many people claim that","Though many people believe that","Though many people think that","Though many people may argue that","Though many people may claim that","Though many people feel that","Though many people maintain that","Though many people say that","Though many people insist that","Even though some people argue that","Even though some people claim that","Even though some people believe that","Even though some people think that","Even though some people may argue that","Even though some people may claim that","Even though some people feel that","Even though some people maintain that","Even though some people say that","Even though some people insist that","Even though some argue that","Even though some claim that","Even though some believe that","Even though some think that","Even though some may argue that","Even though some may claim that","Even though some feel that","Even though some maintain that","Even though some say that","Even though some insist that","Even though many people argue that","Even though many people claim that","Even though many people believe that","Even though many people think that","Even though many people may argue that","Even though many people may claim that","Even though many people feel that","Even though many people maintain that","Even though many people say that","Even though many people insist that","Whereas some people argue that","Whereas some people claim that","Whereas some people believe that","Whereas some people think that","Whereas some people may argue that","Whereas some people may claim that","Whereas some people feel that","Whereas some people maintain that","Whereas some people say that","Whereas some people insist that","Whereas some argue that","Whereas some claim that","Whereas some believe that","Whereas some think that","Whereas some may argue that","Whereas some may claim that","Whereas some feel that","Whereas some maintain that","Whereas some say that","Whereas some insist that","Whereas many people argue that","Whereas many people claim that","Whereas many people believe that","Whereas many people think that","Whereas many people may argue that","Whereas many people may claim that","Whereas many people feel that","Whereas many people maintain that","Whereas many people say that","Whereas many people insist that","While some people argue","While some people claim","While some people believe","While some people think","Although some people argue","Although some people claim","Although some people believe","Although some people think","While critics argue that","While critics claim that","Although critics argue that","Although critics claim that","While it is often argued that","Although it is often argued that","While it is argued that","While it is sometimes argued that","While it is often claimed that","Although it is often claimed that","While many argue that","Although many argue that","While some critics argue that","While some people complain that","While some people contend that","While some people may believe that","While some people may think that","While some people may say that","Although some people may think that","Whilst some people argue that","Whilst some people claim that","Whilst some people believe that","Whilst some people think that","Whilst some people may argue that","Whilst some people may claim that","Whilst some people feel that","Whilst some people maintain that","Whilst some people say that","Whilst some people insist that","Whilst some argue that","Whilst some claim that","Whilst some believe that","Whilst some think that","Whilst some may argue that","Whilst some may claim that","Whilst some feel that","Whilst some maintain that","Whilst some say that","Whilst some insist that","Whilst many people argue that","Whilst many people claim that","Whilst many people believe that","Whilst many people think that","Whilst many people may argue that","Whilst many people may claim that","Whilst many people feel that","Whilst many people maintain that","Whilst many people say that","Whilst many people insist that","Whilst some people argue","Whilst some people claim","Whilst some people believe","Whilst some people think","Whilst critics argue that","Whilst critics claim that","Whilst it is often argued that","Whilst it is argued that","Whilst it is sometimes argued that","Whilst it is often claimed that","Whilst many argue that","Whilst some critics argue that","Whilst some people complain that","Whilst some people contend that","Whilst some people may believe that","Whilst some people may think that","Whilst some people may say that"],"explanation":"While / Although some people argue that…，先转述，再在主句亮出立场。比两个分开的句子紧凑，读者也一眼看出你的态度。","subSkill":"academic_reporting_with_that_clauses"},{"id":"gen-7-5-108","type":"fill","instruction":"〔口语 Part 2 · 题卡：Describe some surprising news you received〕用括号里的词补全。原句：\"I'm moving to Canada next month. Will you visit me?\"","sentence":"Last spring my best friend called to tell me that she ___ (move) to Canada the following month, and she asked whether I ___ (visit) her there.","acceptableAnswers":["was moving","would visit"],"blankAnswers":[["was moving","was going to move","would be moving","would move","was going to be moving"],["would visit","'d visit","would come and visit","would come to visit","would come visit","would come over and visit","would come over to visit"]],"explanation":"① I'm moving… → was moving，next month 变成 the following month。② Will you visit me? → whether I would visit，陈述语序，will 退成 would。","subSkill":"backshift_in_complex_reported_speech"}]},"mission":{"title":"写作 Task 2 段落：转述双方观点，再亮出立场","description":"写一个雅思 Task 2 主体段（3 句）：先转述一方的观点，再转述另一方，最后给出你的评价。至少用对本单元的 2 种写法（选对态度的转述动词、whether 转述问题、suggest that … 等），不必每句都用。AI 老师会按雅思「语法多样性与准确性」给你反馈。","scenario":"题目：Some people think that university education should be free for everyone. Others believe that students should pay for their own studies. Discuss both views and give your own opinion.<br>你只写正文里的一段。可以用你所在国家或城市的情况举例。","grammarType":"reporting_verbs_with_varied_patterns_claim_argue_suggest","scaffolds":[{"prefix":"People disagree about who should pay for higher education.","suffix":"","hint":"转述支持免费的一方：Supporters of free tuition argue that …；你认同的理由可以用 point out that …","grammarCheck":"reporting_verbs_with_varied_patterns_claim_argue_suggest","example":"Supporters of free tuition argue that talented students from poor families should never be put off by high fees."},{"prefix":"Others, however, see the issue differently.","suffix":"","hint":"转述另一方：可以用 claim that … / question whether … / warn that …；whether 后面用陈述语序。","grammarCheck":"reporting_questions_and_imperatives","example":"Critics question whether taxpayers should fund degrees that mainly benefit the graduates themselves."},{"prefix":"Both arguments have some merit.","suffix":"","hint":"给出你的评价，结构自选：可以引用研究（Research shows that …），用对方的让步加强论证（Even critics admit that …），或者提一条建议（I would suggest that the government (should) …）。","grammarCheck":"academic_reporting_with_that_clauses","example":"However, research shows that graduates pay far more tax over their working lives, so I would suggest that the state cover most of the cost."}]},"discover":{"story":{"title":"写作 Task 2 范文节选：四天工作制，该不该推行？","text":"读的时候想一想：作者转述了哪几方的观点？他认同谁、怀疑谁？蓝色的句子下面会逐句问你。\nQuestion: Some people believe that a four-day working week would benefit both employees and employers. To what extent do you agree or disagree?\nSupporters of a four-day week argue that people who work fewer hours are not only happier but also more productive. In well-known trials of a shorter working week in Iceland, researchers reported that most workplaces had kept the same level of output and that staff felt far less stressed. One economist also pointed out that tired employees make more mistakes, so longer hours do not necessarily mean that more work gets done.\nCritics, however, claim that the idea only works in offices. This seems exaggerated, since the Icelandic trials also included hospitals and nurseries. Even so, supporters admit that the model is harder to apply in shops and factories. A more serious concern is cost: critics question whether small businesses can afford to hire extra staff to cover the missing day.\nOn balance, I believe that the benefits outweigh the costs, but the change should be gradual. Many experts suggest that each company test the idea for six months before making a final decision. Governments could also offer tax breaks to companies that take part. A shorter week will not solve every problem, but it deserves a fair trial.","highlights":["researchers reported that","had kept the same level of output","staff felt far less stressed","pointed out that tired employees make more mistakes","claim that the idea only works in offices","supporters admit that the model is harder to apply","question whether small businesses can afford","suggest that each company test the idea"]},"questions":[{"question":"第一段：<em>…researchers reported that most workplaces had kept the same level of output and that staff felt far less stressed.</em><br>When did staff feel far less stressed?","options":["Before the trials began","At the time of the trials","Now, as the writer is writing"],"correctIndex":1,"nudge":"reported 是研究人员过去说的话。先还原他们的原话：Staff ___ far less stressed. 原话里这个动词是什么时态？","explanation":"试验进行的时候（研究人员报告的就是那时的情况）。原话是 Staff feel far less stressed，放在过去的 reported 后面，就往后退一步。<br><strong>规则 ①</strong>：转述过去说的话，内容往后退一步：feel → felt，have kept → had kept，will → would。","subSkill":"backshift_in_complex_reported_speech"},{"question":"比较原文这半句的两种写法：<br>A. One economist pointed out that tired employees <em>make</em> more mistakes.<br>B. One economist pointed out that tired employees <em>made</em> more mistakes.<br>Which one shows that the writer thinks this is still true today?","options":["Sentence A","Sentence B","Both of them equally"],"correctIndex":0,"nudge":"pointed out 是过去，但后面那半句说的是一条规律。哪种写法把它说成「现在也是这样」？","explanation":"A。make 是现在时：作者把它当作今天仍然成立的事实，拿来支持论点。B 退成 made 也不算错，但听起来像只在说当时。<br><strong>规则 ②</strong>：内容现在仍然成立，可以不退：pointed out that tired employees make…","subSkill":"no_backshift_for_general_truths"},{"question":"第一段说 One economist <em>pointed out</em> that…，第二段说 Critics <em>claim</em> that…。<br>Which of the two views does the writer accept?","options":["Only the critics' view","Both views equally","The economist's view"],"correctIndex":2,"nudge":"看第二段 claim 后面紧接的一句：This seems exaggerated… 作者是在同意，还是在反驳？","explanation":"经济学家的说法。point out 是「指出一个事实」，作者认同；claim 只是「声称」，作者紧接着就反驳了。<br><strong>规则 ③</strong>：转述动词带着作者的态度：point out / show → 认同；claim → 只是对方的说法；admit → 对方也承认。","subSkill":"reporting_verbs_with_varied_patterns_claim_argue_suggest"},{"question":"第二段：<em>…critics question whether small businesses can afford to hire extra staff to cover the missing day.</em><br>Do the critics think small businesses can afford extra staff?","options":["Yes, they are sure they can.","They doubt that they can.","They have no view on it."],"correctIndex":1,"nudge":"question 在这里是动词，question whether… 就是「对…提出疑问」。批评者是在肯定，还是在怀疑？","explanation":"怀疑雇不起。question whether = 质疑是不是…。<br>对比直接问：<em>Can small businesses afford…?</em>（can 在主语前）→ 转述：whether small businesses can afford（主语在前）。<br><strong>规则 ④</strong>：转述问题用 whether / if / why…，后面按陈述句语序，不写 whether can small businesses afford。","subSkill":"reporting_questions_and_imperatives"},{"question":"第三段：<em>Many experts suggest that each company test the idea for six months before making a final decision.</em><br>What do the experts mean?","options":["Each company should try it out for six months.","Each company has already tried it for six months.","All companies should switch to it straight away."],"correctIndex":0,"nudge":"注意 test 没有加 -s，也不是 tested。专家是在描述已经发生的事，还是在出主意？","explanation":"建议每家企业先试半年再定。test 用原形（each company 后面也不加 -s），说明这是「建议去做」的事；要是写 tested，suggest 就成了「表明」。<br><strong>规则 ⑤</strong>：suggest / recommend + that + 人 + (should) 原形；别写 suggest each company to test。","subSkill":"reporting_verbs_with_varied_patterns_claim_argue_suggest"},{"question":"你来试试：口语 Part 2 讲一次面试。想说「面试官问我为什么想学法律」，哪句最准确？","options":["The interviewer asked me why did I want to study law.","The interviewer asked me why I had wanted to study law.","The interviewer asked me why I wanted to study law."],"correctIndex":2,"nudge":"先用规则 ④ 排好语序，再用规则 ① 想：面试官的原话是 Why do you want to study law? 往后退一步是什么？","explanation":"原话 Why do you want…? → 陈述语序 why I want（规则 ④）→ 退一步 wanted（规则 ①）。had wanted 退了两步，成了「面试之前曾经想」。","subSkill":"reporting_questions_and_imperatives"}],"tip":"【转述别人的话：先看时间，再看态度】\n\n① 转述过去说的话，内容往后退一步：feel → felt，have kept → had kept，will → would\n② 内容现在仍然成立，可以不退：pointed out that tired employees make…\n③ 动词带态度：point out / show → 作者认同；claim → 只是对方的说法；admit → 对方也承认\n④ 转述问题：whether / why … + 陈述语序，句末用句号：asked why I wanted…，不写 why did I want\n⑤ suggest / recommend / insist + that + 人 + (should) 原形；suggest 也可接 doing：suggested applying\n⑥ tell / ask / advise / warn + 人 + (not) to do\n⑦ suggest 表示「表明」→ 正常时态；表示「建议」→ (should) 原形\n另外：say / explain 后面不直接跟人（said to me that…，explained to me why…）；deny / admit + doing；accuse + 人 + of doing\n\n【例句】\n✔ Researchers reported that most workplaces had kept the same level of output.（过去说的 → 退一步）\n✔ Critics question whether small businesses can afford extra staff.（问题 → 陈述语序）\n✔ She asked me where I was from.（转述的问题，句末用句号，不加 ?）\n\n【常见错误】\n✘ My tutor suggested **me to apply**. → suggested that I (should) apply / advised me to apply（见 ⑤⑥）\n✘ She asked me where **was I** from. → where I was from（见 ④）\n✘ My teacher told me **don't panic**. → told me not to panic（见 ⑥）\n✘ My grandmother **said me** that… → told me that… / said to me that…"}},"8":{"levels":{"1":[{"id":"gen-8-1-100","type":"choice","instruction":"〔口语 Part 1〕事实：我以前午饭后常喝咖啡，去年起不喝了。空格填哪个，才符合事实？","sentence":"Last year I ___ coffee after lunch because it was keeping me awake at night.","options":["stopped to drink","stopped drinking","kept drinking","stopped drink"],"correctIndex":1,"explanation":"去年起不喝了 → stopped drinking（不再做）。stopped to drink 是「停下手头的事去喝一杯」，意思正好反了；kept drinking 是一直在喝。","subSkill":"verbs_taking_both_with_meaning_change"},{"id":"gen-8-1-101","type":"choice","instruction":"〔口语 Part 3〕这些上班族现在还在网上开会吗？","sentence":"Most office workers are used to having meetings online.","options":["No, they only did that in the past.","Yes, but they still find it strange.","No, but they are planning to start.","Yes, and it feels normal to them."],"correctIndex":3,"explanation":"are used to having = 已经习惯了，现在就这样。used to have 才是「以前常常，现在不了」；还在适应要说 are getting used to having。","subSkill":"gerund_vs_infinitive_meaning_difference"},{"id":"gen-8-1-102","type":"choice","instruction":"〔口语 Part 3〕考生说，现在很多学生怎么备考？","sentence":"A lot of students now prepare for exams by watching short videos instead of reading their textbooks.","options":["They use textbooks, not videos.","They watch videos, then read textbooks.","They watch videos and skip textbooks.","They watch videos while reading textbooks."],"correctIndex":2,"explanation":"by watching = 靠看视频；instead of reading = 而不是看课本。by、instead of 是介词，后面接 doing，说的是方法和取舍。","subSkill":"preposition_plus_doing"},{"id":"gen-8-1-103","type":"choice","instruction":"〔写作 Task 2〕作者认为，谁该做什么？","sentence":"Many elderly people need to be shown how to use online banking safely.","options":["Someone should show older people.","Older people should teach others.","Older people will learn it alone.","Older people should avoid it."],"correctIndex":0,"explanation":"need to be shown = 需要「被」教：老人是学的一方，教的是别人。写成 need to show，就成了老人去教别人。","subSkill":"perfect_and_passive_infinitives"},{"id":"gen-8-1-104","type":"choice","instruction":"〔口语 Part 3〕考生说的这个变化，发生了吗？","sentence":"Food delivery apps seem to have changed the way young people eat.","options":["Not yet, but it probably will.","It did, but things went back to normal.","Probably yes; it looks that way.","It will definitely happen soon."],"correctIndex":2,"explanation":"seem to have changed = 看来已经改变了（to have done 说已经发生的事）。考生用 seem，表示不完全肯定。seem to change 才是说一般情况。","subSkill":"perfect_and_passive_infinitives"},{"id":"gen-8-1-105","type":"scenario","instruction":"考生给了什么建议？","context":"雅思口语 Part 3 · Technology and sleep","dialogue":[{"speaker":"examiner","text":"Examiner: What can people do if they find it hard to switch off at night?"},{"speaker":"player","text":"Well, they could try reading a paper book for twenty minutes instead of scrolling through their phones. It certainly worked for me."}],"options":["Force yourself to finish a whole book.","Read a paper book and see if it helps.","Read a book and use your phone at once.","Read during the day and use your phone at night."],"correctIndex":1,"explanation":"try reading = 换个办法试试，看有没有用；后面 It worked for me 说明有效。try to read 才是「努力想读」，暗示可能读不下去。","subSkill":"verbs_taking_both_with_meaning_change"},{"id":"gen-8-1-106","type":"match","instruction":"〔口语 Part 2〕每句说的是哪件事？连线。","left":["I stopped to chat with Tom.","I stopped chatting with Tom.","I remember telling Tom.","I must remember to tell Tom."],"right":["I no longer chatted with Tom.","I haven't told Tom yet, but I need to.","I paused and had a quick chat with Tom.","I told Tom before, and I can recall it."],"correctPairs":[[0,2],[1,0],[2,3],[3,1]],"explanation":"doing 说本来在做或已经做过的事：stopped chatting 不聊了，remember telling 记得说过。to do 说接下来要做的事：停下来去聊、记着要去说。","subSkill":"verbs_taking_both_with_meaning_change"},{"id":"gen-8-1-107","type":"choice","instruction":"〔写作 Task 2〕作者批评政府什么？","sentence":"The government's failure to invest in rural schools has widened the gap between urban and rural schools.","options":["It invested, but the money was wasted.","Rural schools turned the investment down.","It invested far too much money.","It didn't put money into rural schools."],"correctIndex":3,"explanation":"failure to invest = 没有投资（该做的没做），不是「投资失败」。the government's failure to do 是 Task 2 批评政策时很好用的名词短语。","subSkill":"complex_noun_phrase_with_gerund"},{"id":"gen-8-1-108","type":"choice","instruction":"〔口语 Part 2〕考生家吃饭的时候看手机吗？","sentence":"Not having phones at the dinner table has made my family much closer.","options":["Yes, and it has brought them closer.","No, and they have become closer.","Only the parents use their phones.","Yes, but only at the weekend."],"correctIndex":1,"explanation":"主语是 Not having phones at the dinner table（吃饭时不碰手机）这一件事：他们不看手机，一家人更亲近了。动词用单数 has made。","subSkill":"gerunds_as_subjects_in_formal_writing"}],"2":[{"id":"gen-8-2-100","type":"choice","instruction":"〔写作 Task 2〕想说「高房价让很多年轻人买不起房」。","sentence":"High property prices prevent many young people ___ a home of their own.","options":["to buy","into buying","from buying","for buying"],"correctIndex":2,"explanation":"prevent / stop + 人 + from doing：from 是介词，后面接 doing。prevent sb to do 是常见的错。","subSkill":"preposition_plus_doing"},{"id":"gen-8-2-101","type":"choice","instruction":"〔口语 Part 1〕想说「我老是忘了给手机充电」。","sentence":"I always forget ___ my phone, so it often dies by the afternoon.","options":["to charge","charging","charge","having charged"],"correctIndex":0,"explanation":"该做的事没做 → forget to charge。forget doing 指忘了做过的事，多用在 I'll never forget meeting her 这样的回忆里。","subSkill":"verbs_taking_both_with_meaning_change"},{"id":"gen-8-2-102","type":"choice","instruction":"〔口语 Part 3〕想说「很多人周末尽量不去想工作」。","sentence":"Many people try to avoid ___ about work at the weekend.","options":["to think","think","to thinking","thinking"],"correctIndex":3,"explanation":"avoid 后面接 doing：avoid thinking。consider、suggest、keep、can't resist 也接 doing。前面的 try to 表示「尽量」。","subSkill":"verb_patterns_doing_or_to_do"},{"id":"gen-8-2-103","type":"choice","instruction":"〔写作 Task 2〕想说「很多家庭负担不起送孩子上私立学校」。","sentence":"Many families cannot afford ___ their children to private schools.","options":["sending","to send","send","for sending"],"correctIndex":1,"explanation":"「负担得起做某事」→ afford to do：cannot afford to send。decide、plan、refuse、tend 也接 to do。","subSkill":"verb_patterns_doing_or_to_do"},{"id":"gen-8-2-104","type":"choice","instruction":"〔口语 Part 1〕想说「我很期待毕业后自己一个人住」。","sentence":"I'm really looking forward to ___ on my own after I graduate.","options":["living","live","be living","have lived"],"correctIndex":0,"explanation":"look forward to 里的 to 是介词，后面接 doing：looking forward to living。写成 to live 是最常见的错。","subSkill":"preposition_plus_doing"},{"id":"gen-8-2-105","type":"choice","instruction":"〔写作 Task 2〕想说「这个问题应该由政府来解决」。","sentence":"This problem needs ___ by the government, not by individual families.","options":["to solve","to be solving","to have solved","to be solved"],"correctIndex":3,"explanation":"问题是「被」解决的 → needs to be solved。needs to solve 成了「问题去解决别的事」，这是很常见的错。","subSkill":"perfect_and_passive_infinitives"},{"id":"gen-8-2-106","type":"choice","instruction":"〔口语 Part 2〕想说「小时候我每个周末都和爷爷下棋，现在不下了」。","sentence":"When I was a child, I ___ chess with my grandfather every weekend.","options":["was used to playing","am used to playing","used to play","used to playing"],"correctIndex":2,"explanation":"以前常常、现在不了 → used to play。be used to playing 是「习惯于」，说的是一种状态，不说过去常做的事。","subSkill":"gerund_vs_infinitive_meaning_difference"},{"id":"gen-8-2-107","type":"match","instruction":"〔口语 Part 2〕两句只差一处。考生和室友谈了吗？连线。","left":["I tried to talk to my roommate about the noise.","I tried talking to my roommate about the noise."],"right":["I did talk, to see if it would help.","I made an effort, but may have failed."],"correctPairs":[[0,1],[1,0]],"explanation":"try to talk = 努力想谈，可能没谈成（比如室友不理他）；try talking = 真的谈了，试试这个办法能不能解决噪音。","subSkill":"verbs_taking_both_with_meaning_change"},{"id":"gen-8-2-108","type":"choice","instruction":"〔写作 Task 2〕想说「很多学生缺乏独立思考的能力」。","sentence":"Many students lack the ability ___ independently.","options":["of thinking","to think","for thinking","in thinking"],"correctIndex":1,"explanation":"ability 后面接 to do：the ability to think。failure、decision 也一样。the ability of thinking 是「…的能力」直译。","subSkill":"complex_noun_phrase_with_gerund"},{"id":"gen-8-2-109","type":"choice","instruction":"〔口语 Part 3〕想说「在社交媒体上一泡好几个小时，会让青少年更不自信」。","sentence":"Spending hours on social media ___ many teenagers less confident.","options":["make","are making","have made","makes"],"correctIndex":3,"explanation":"主语是 Spending hours on social media 这一件事，动词用单数 makes。别被前面的 hours 带成复数 make。","subSkill":"gerunds_as_subjects_in_formal_writing"}],"3":[{"id":"gen-8-3-100","type":"fill","instruction":"〔写作 Task 2〕不用 It，用这个动作本身作主语。原句：It is not easy to stick to a new habit for more than a month.","sentence":"___ to a new habit for more than a month is not easy.","acceptableAnswers":["Sticking","Keeping","To stick","Adhering","Committing"],"explanation":"动作作主语，用 doing 开头：Sticking to a new habit … is not easy。To stick… 开头不算错，但听起来生硬，现代英语很少这样用。","subSkill":"gerunds_as_subjects_in_formal_writing"},{"id":"gen-8-3-101","type":"fill","instruction":"〔口语 Part 1〕把两句合成一句。原句：I used to play online games at weekends. I don't do that any more.","sentence":"I've ___ online games at weekends.","acceptableAnswers":["stopped playing","given up playing","quit playing","given up","quit","cut out"],"explanation":"不再做 → stop doing：I've stopped playing…。别写 stopped to play（那是停下来去玩）。give up / quit 后面也接 doing。","subSkill":"verbs_taking_both_with_meaning_change"},{"id":"gen-8-3-102","type":"fill","instruction":"〔写作 Task 2〕改写，让 personal data 作主语，用括号里的动词。原句：Companies need to protect users' personal data more carefully.","sentence":"Users' personal data needs ___ (protect) more carefully.","acceptableAnswers":["to be protected","protecting"],"explanation":"数据是「被」保护的 → needs to be protected。英式英语也说 needs protecting。needs to protect 是错的。","subSkill":"perfect_and_passive_infinitives"},{"id":"gen-8-3-103","type":"fill","instruction":"〔口语 Part 1〕用 used to 说出「我不习惯边听音乐边学习」。","sentence":"I'm not ___ with music on.","acceptableAnswers":["used to studying","used to working","used to revising","used to learning","used to reading","used to doing homework","used to doing my homework","accustomed to studying","accustomed to working","used to concentrating","used to focusing","used to doing my work","used to doing schoolwork","used to doing my revision","used to doing any work"],"explanation":"「习惯于」→ be used to + doing，这里的 to 是介词：I'm not used to studying…。to 后面写原形 study，是最常见的错。","subSkill":"preposition_plus_doing"},{"id":"gen-8-3-104","type":"reorder","instruction":"〔口语 Part 3〕排出这句话：边工作边吃零食的习惯，可能导致体重增加。","words":["can","The","while","habit","to","of","working","snacking","lead","weight","gain."],"correctSentence":"The habit of snacking while working can lead to weight gain.","explanation":"habit 后面接 of + doing：the habit of snacking。while working 说什么时候吃。lead to 后面接名词 weight gain。","subSkill":"complex_noun_phrase_with_gerund"},{"id":"gen-8-3-105","type":"fill","instruction":"〔口语 Part 2〕用 suggested 转述老师的建议。原句：My teacher said, 'Why don't you keep a vocabulary notebook?'","sentence":"My teacher suggested ___ a vocabulary notebook.","acceptableAnswers":["keeping","that I keep","that I should keep","I keep","I should keep","that I kept","I kept","starting","using","that I start","I start","that I should start","I should start","that I started","I started","that I use","I use","that I should use","I should use","that I used","I used","my keeping"],"explanation":"suggest 后面接 doing 或 that 从句：suggested keeping / that I (should) keep。不能说 suggested me to keep。","subSkill":"verb_patterns_doing_or_to_do"},{"id":"gen-8-3-106","type":"fill","instruction":"〔口语 Part 3〕用 Online courses 作主语，保留 seem 改写这句。原句：It seems that online courses have made education much cheaper.","sentence":"Online courses ___ education much cheaper.","acceptableAnswers":["seem to have made","appear to have made"],"explanation":"原句 have made 说已经发生的变化，放到 seem 后面要写成 to have made。写 seem to make 就成了一般情况，时间对不上。","subSkill":"perfect_and_passive_infinitives"},{"id":"gen-8-3-107","type":"fill","instruction":"〔写作 Task 2〕把前半句改成名词短语作主语。原句：The city failed to plan for population growth, and this has caused a serious housing shortage.","sentence":"The city's ___ for population growth has caused a serious housing shortage.","acceptableAnswers":["failure to plan","failing to plan","inability to plan","failure to plan ahead","failing to plan ahead","failure to prepare","failing to prepare","inability to prepare","failure to provide","failing to provide","lack of planning","lack of preparation"],"explanation":"fail to do 变成名词 → failure to do：the city's failure to plan。别写 failure of planning。一个名词短语装下整件事。","subSkill":"complex_noun_phrase_with_gerund"},{"id":"gen-8-3-108","type":"fill","instruction":"〔口语 Part 3〕用 The key to 改写。原句：If you want to remember new words, the most important thing is to review them regularly.","sentence":"The key to ___ new words is reviewing them regularly.","acceptableAnswers":["remembering","memorising","memorizing","learning","retaining","mastering","acquiring","recalling"],"explanation":"the key to 里的 to 是介词，后面接 doing：the key to remembering。别写 the key to remember。","subSkill":"preposition_plus_doing"},{"id":"gen-8-3-109","type":"reorder","instruction":"〔口语 Part 3〕排出这句话：很多青少年每天花好几个小时刷短视频。","words":["scrolling","Many","every","spend","short","teenagers","day.","hours","through","videos"],"correctSentence":"Many teenagers spend hours scrolling through short videos every day.","acceptableSentences":["Every day many teenagers spend hours scrolling through short videos.","Many teenagers spend hours every day scrolling through short videos."],"explanation":"「花时间做某事」→ spend + 时间 + doing：spend hours scrolling。中文说「花时间去刷」，但英文不能写 spend hours to scroll。","subSkill":"verb_patterns_doing_or_to_do"}],"4":[{"id":"gen-8-4-100","type":"error","instruction":"〔口语 Part 3 · 考生常见错误〕点出用错的部分。","words":["Learn","a new language","takes","a lot of","patience,","especially for adults."],"errorIndex":0,"correction":"Learning","explanation":"动作作主语要用 doing：Learning a new language takes…。Learn 开头像是叫人「去学」，后面再接 takes 就不通了。","subSkill":"gerunds_as_subjects_in_formal_writing"},{"id":"gen-8-4-101","type":"error","instruction":"〔口语 Part 1 · 考生常见错误〕点出用错的部分。","words":["Since I started","working from home,","I've had","great difficulty","to concentrate","in the afternoons,","so now I try","to work","in a café."],"errorIndex":4,"correction":"concentrating","explanation":"difficulty 后接 doing（可加 in）：have difficulty concentrating。要用 to do，就换成 find it hard to concentrate。","subSkill":"verb_patterns_doing_or_to_do"},{"id":"gen-8-4-102","type":"fill","instruction":"〔口语 Part 2 · 考生常见错误〕有一处用错了，在空里写出正确的说法。原句：My parents suggested me to study medicine.","sentence":"My parents suggested ___ medicine.","acceptableAnswers":["that I study","that I should study","I study","I should study","studying","that I studied","I studied","doing","that I do","I do","that I should do","reading","that I read","my studying"],"explanation":"suggest 不接「人 + to do」：suggested that I (should) study / suggested studying。要用「人 + to do」就换成 advise。","subSkill":"verb_patterns_doing_or_to_do"},{"id":"gen-8-4-103","type":"error","instruction":"〔写作 Task 2 · 考生常见错误〕点出用错的部分。","words":["In my view,","food waste","needs","to tackle","urgently","if we want","to feed","a growing population."],"errorIndex":3,"correction":"to be tackled","explanation":"食物浪费是「被」处理的 → needs to be tackled。needs to tackle 意思成了「食物浪费要去处理别的东西」。","subSkill":"perfect_and_passive_infinitives"},{"id":"gen-8-4-104","type":"error","instruction":"〔口语 Part 2 · 考生常见错误〕点出用错的部分。","words":["Studying abroad","made me","to appreciate","my parents more,","and now","I try","to call them","every week."],"errorIndex":2,"correction":"appreciate","explanation":"make + 人 + 动词原形，不加 to：made me appreciate。let 也一样。中文「让我…」很容易带出 to。","subSkill":"verb_patterns_doing_or_to_do"},{"id":"gen-8-4-105","type":"error","instruction":"〔口语 Part 1 · 考生常见错误〕他现在每天六点起床，早就习惯了。点出用错的部分。","words":["Because of","my job,","I'm","used to","get up","at six","every morning."],"errorIndex":4,"correction":"getting up","explanation":"「已经习惯」→ be used to + doing：I'm used to getting up…，这里的 to 是介词。去掉 I'm 写 I used to get up，意思就成了「以前常常」。","subSkill":"preposition_plus_doing"},{"id":"gen-8-4-106","type":"fill","instruction":"〔写作 Task 2 · 考生常见错误〕有一处用错了，在空里写出正确的说法。原句：Stricter rules on plastic packaging would contribute to reduce the amount of plastic in our oceans.","sentence":"Stricter rules on plastic packaging would contribute to ___ the amount of plastic in our oceans.","acceptableAnswers":["reducing","cutting","lowering","decreasing","limiting","cutting down","bringing down","a reduction in","a decrease in","a fall in","a drop in","a cut in"],"explanation":"contribute to 里的 to 是介词，后接 doing 或名词：contribute to reducing / a reduction in。lead to 也一样。","subSkill":"preposition_plus_doing"},{"id":"gen-8-4-107","type":"error","instruction":"〔口语 Part 3 · 考生常见错误〕点出用错的部分。","words":["Playing","video games","for hours","are","bad for","teenagers'","eyesight."],"errorIndex":3,"correction":"is","explanation":"主语是 Playing video games 这一件事，不是 games，动词用单数 is。","subSkill":"gerunds_as_subjects_in_formal_writing"},{"id":"gen-8-4-108","type":"fill","instruction":"〔写作 Task 2 · 考生常见错误〕有一处用错了，在空里写出正确的形式。原句：More and more young families are considering to move to smaller cities these days.","sentence":"More and more young families are considering ___ to smaller cities these days.","acceptableAnswers":["moving","relocating"],"explanation":"consider 后面接 doing：are considering moving。同类的还有 avoid、suggest、mind、keep、spend time。","subSkill":"verb_patterns_doing_or_to_do"},{"id":"gen-8-4-109","type":"error","instruction":"〔口语 Part 1 · 考生常见错误〕点出用错的部分。","words":["I think","the science museum","in my city","is","worth","to visit,","if you want","to learn about space."],"errorIndex":5,"correction":"visiting","explanation":"worth 后面接 doing：is worth visiting。worth 本身就是「值得做」，不用再加 to。","subSkill":"verb_patterns_doing_or_to_do"}],"5":[{"id":"gen-8-5-100","type":"fill","instruction":"〔口语 Part 3〕把两句合成一句，不用 This。原句：Some teenagers compare themselves with influencers online. This often makes them unhappy with their appearance.","sentence":"___ themselves with influencers online often ___ teenagers unhappy with their appearance.","acceptableAnswers":["Comparing","makes"],"blankAnswers":[["Comparing","Constantly comparing","Always comparing","Frequently comparing"],["makes","leaves"]],"explanation":"Comparing themselves… 这个动作作主语，动词用单数 makes。一句说完，比 Some teenagers…. This makes… 更紧凑。","subSkill":"gerunds_as_subjects_in_formal_writing"},{"id":"gen-8-5-101","type":"fill","instruction":"〔写作 Task 2〕用 underestimate 把原句改得更紧凑。原句：Many office workers do not realise how important it is to take regular breaks, or how risky it is to sit at a desk all day.","sentence":"Many office workers underestimate both the importance ___ regular breaks and the risks ___ at a desk all day.","acceptableAnswers":["of taking","of sitting"],"blankAnswers":[["of taking","of having"],["of sitting","of staying","of working"]],"explanation":"importance / risk 后面都接 of + doing：the importance of taking、the risks of sitting。两个名词短语代替两个从句，句子更紧凑。","subSkill":"complex_noun_phrase_with_gerund"},{"id":"gen-8-5-102","type":"scenario","instruction":"考生想说「我习惯了把号码存在手机里，可我记得小时候能背出几十个号码」。哪个回答意思准确？","context":"雅思口语 Part 3 · Technology and memory","dialogue":[{"speaker":"examiner","text":"Examiner: Has technology affected people's memory?"}],"options":["I'm used to save numbers on my phone, but I remember knowing dozens by heart as a kid.","I used to save numbers on my phone, but I remember knowing dozens by heart as a kid.","I'm used to saving numbers on my phone, but I remember knowing dozens by heart as a kid.","I'm used to saving numbers on my phone, but I remember to know dozens by heart as a kid."],"correctIndex":2,"explanation":"现在的习惯 → I'm used to saving；小时候背过号码 → remember knowing（回忆做过的事）。used to save 是「以前常存」。","subSkill":"gerund_vs_infinitive_meaning_difference"},{"id":"gen-8-5-103","type":"fill","instruction":"〔写作 Task 2〕补全这段论证，用括号里的动词。先看每个空在句子里起什么作用。","sentence":"Smartphones are not harmful in themselves. ___ (give) a ten-year-old unlimited internet access is risky, so young children need ___ (supervise) online. However, banning phones completely would prevent them from ___ (use) useful learning apps.","acceptableAnswers":["Giving","to be supervised","using"],"blankAnswers":[["Giving","To give"],["to be supervised","to be closely supervised","supervising"],["using"]],"explanation":"① 动作作主语 → Giving…。② 孩子是被看管的 → need to be supervised。③ from 是介词 → prevent them from using。","subSkill":"gerunds_as_subjects_in_formal_writing"},{"id":"gen-8-5-104","type":"fill","instruction":"〔写作 Task 2〕用 The internet 作主语改写，更正式。原句：People say that the internet has changed the way we read.","sentence":"The internet is said ___ the way we read.","acceptableAnswers":["to have changed","to have transformed","to have altered","to have reshaped","to have revolutionised","to have revolutionized","to have fundamentally changed","to have completely changed"],"explanation":"原句 has changed 说已经发生的事 → is said to have changed。写 to change 就成了一般情况，时间对不上。","subSkill":"perfect_and_passive_infinitives"},{"id":"gen-8-5-105","type":"fill","instruction":"〔口语 Part 3〕考官问：Why do some young people find it hard to save money? 补全回答，每空填一个动作。","sentence":"A lot of them can't resist ___ things online, and they tend ___ how quickly small purchases add up.","acceptableAnswers":["buying","to forget"],"blankAnswers":[["buying","ordering","purchasing","shopping for","buying new"],["to forget","to underestimate","to ignore","to overlook","not to notice","not to realise","not to realize","to lose track of","to lose sight of"]],"explanation":"can't resist 后接 doing：can't resist buying；tend 后接 to do：tend to forget。这类搭配要一个个记，写错很显眼。","subSkill":"verb_patterns_doing_or_to_do"},{"id":"gen-8-5-106","type":"fill","instruction":"〔口语 Part 3〕考官问：What's the best way to learn a foreign language? 用括号里的动词补全回答。","sentence":"When it comes to ___ (learn) a language, I think nothing beats ___ (talk) to native speakers.","acceptableAnswers":["learning","talking"],"blankAnswers":[["learning"],["talking","speaking","chatting"]],"explanation":"when it comes to 里的 to 是介词 → learning；beats 后面要接名词，动作就写成 talking。","subSkill":"preposition_plus_doing"},{"id":"gen-8-5-107","type":"fill","instruction":"〔写作 Task 2〕把条件句改成一个更紧凑的句子。原句：If teenagers have a part-time job, they can learn how to manage money.","sentence":"___ a part-time job can teach teenagers ___ money.","acceptableAnswers":["Having","how to manage"],"blankAnswers":[["Having","Doing","Taking","Getting","Holding","Taking on","Working"],["how to manage","to manage","how to handle","to handle","how to save","to save","how to look after","to look after","how to deal with","about managing"]],"explanation":"动作作主语 → Having a part-time job…；teach 后面接「人 + (how) to do」：teach teenagers (how) to manage money。","subSkill":"gerunds_as_subjects_in_formal_writing"},{"id":"gen-8-5-108","type":"fill","instruction":"〔口语 Part 2 · 结束追问〕你讲了一项学了很久的技能。考官：Was it worth it? 用括号里的动词补全回答。","sentence":"Definitely. I only regret ___ (not / start) earlier, and I'll never forget ___ (play) my first full song for my family.","acceptableAnswers":["not starting","playing"],"blankAnswers":[["not starting","not having started","not starting it","not having started it","that I didn't start","that I hadn't started"],["playing","having played"]],"explanation":"后悔「没做」→ regret not starting；永远记得做过的事 → never forget playing。两处说的都是已经发生的事，所以都用 doing。","subSkill":"verbs_taking_both_with_meaning_change"}]},"mission":{"title":"写作 Task 2 段落：科技让学习更轻松了吗？","description":"写一个雅思 Task 2 主体段（3 句）：先说科技带来的一种新学习方式，再说它的一个问题，最后提一条建议（写法自选）。至少用对本单元的 2 种写法（动作作主语、名词 + to do / of doing、need to be done 等），不必每句都用。AI 老师会按雅思「语法多样性与准确性」给你反馈。","scenario":"题目：Some people believe that technology has made learning easier, while others think it has made students lazier. Discuss both views and give your own opinion.<br>你只写正文里的一段。可以写网课、学习 App、AI 工具、电子词典……用你自己或身边人的经历举例。","grammarType":"gerunds_as_subjects_in_formal_writing","scaffolds":[{"prefix":"Technology has clearly changed the way students learn.","suffix":"","hint":"用一个动作作主语，说一种新的学习方式：Using / Watching / Looking up … + 单数动词。","grammarCheck":"gerunds_as_subjects_in_formal_writing","example":"Looking up an unfamiliar word with an app takes only seconds, so students can read far more widely than before."},{"prefix":"However, this convenience comes at a price.","suffix":"","hint":"说一个问题：可以用 the habit of doing / students' failure to do / instead of doing。","grammarCheck":"complex_noun_phrase_with_gerund","example":"Many students have got into the habit of copying answers from AI tools instead of working problems out for themselves."},{"prefix":"Schools therefore have an important role to play.","suffix":"","hint":"提一条建议，结构自选：可以用 Students need to be taught …，也可以用 … should avoid doing / encourage students to …，或者干脆用简单句。","grammarCheck":"perfect_and_passive_infinitives","example":"Students need to be taught when technology helps them learn and when it simply does the thinking for them."}]},"discover":{"story":{"title":"口语 Part 3 示范问答：手机、习惯和学习","text":"读的时候想一想：考生觉得手机对学习有什么影响？他自己改掉了什么习惯？蓝色的句子下面会逐句问你。\nPart 3 · Topic: Habits, technology and learning\nExaminer: Do you think smartphones have made it harder for young people to concentrate?\nCandidate: To some extent, yes. Checking messages every few minutes has become a habit for a lot of students, and breaking the habit of reaching for the phone isn't easy. I stopped using social media during my exams last year, and I was amazed at how much more I got done. So I'd say the real problem isn't the phone itself; it's our failure to put it away.\nExaminer: How has technology changed the way people learn?\nCandidate: Quite dramatically. My parents learned English from a single textbook, but people my age are used to learning from videos and apps. If we don't understand something, we just look it up. That's convenient, although it probably means we read less carefully than they did.\nExaminer: Should schools teach children how to manage their screen time?\nCandidate: I think they should. Children need to be taught this, just as they're taught to cross the road safely. Most teenagers I know wish they spent less time online, but nobody has ever shown them how to cut down.","highlights":["Checking messages every few minutes","has become a habit","breaking the habit of reaching for the phone","I stopped using social media","our failure to put it away","are used to learning from videos and apps","Children need to be taught this"]},"questions":[{"question":"第一个回答：<em>Checking messages every few minutes has become a habit for a lot of students…</em><br>What has become a habit?","options":["The new messages they get all day","Looking at messages all the time","Students who check their phones"],"correctIndex":1,"nudge":"has 前面一直到 minutes，整串都是主语。它说的是一样东西，还是一件事？","explanation":"是「每隔几分钟看一眼消息」这个动作。<br><strong>规则 ①</strong>：把一个动作当主语，用 doing 开头：Checking messages…。整串算一件事，动词用单数 has。","subSkill":"gerunds_as_subjects_in_formal_writing"},{"question":"第一个回答：<em>I stopped using social media during my exams last year, and I was amazed at how much more I got done.</em><br>Did he use social media during his exams?","options":["Yes, but less than usual.","Yes, he took breaks to check it.","No, he didn't use it at all."],"correctIndex":2,"nudge":"再看后半句：他 got much more done。如果考试时还在刷，效率会高这么多吗？","explanation":"不刷了，所以效率高了很多。<br><strong>规则 ②</strong>：stop doing = 不再做（本来在做的事）；stop to do = 停下手头的事，去做另一件。stopped to use 就成了「停下来去刷」。","subSkill":"verbs_taking_both_with_meaning_change"},{"question":"第一个回答：<em>…the real problem isn't the phone itself; it's our failure to put it away.</em><br>What is the real problem, in his view?","options":["Phones are too addictive.","We don't put our phones away.","Schools don't take phones away."],"correctIndex":1,"nudge":"注意 isn't the phone itself：他先排除了一个原因。put it away 是「把它收起来」；failure 是做到了，还是没做到？","explanation":"问题在我们自己：没能把手机收起来。<br><strong>规则 ③</strong>：有些名词后接 to do：our failure to put it away；有些接 of doing：the habit of reaching for the phone（第一个回答）。","subSkill":"complex_noun_phrase_with_gerund"},{"question":"第二个回答：比较原文和改写：<br>A. People my age <em>are used to learning</em> from videos and apps.<br>B. People my age <em>used to learn</em> from videos and apps.<br>Which one says they learn this way <strong>now</strong>?","options":["Only A","Only B","Both"],"correctIndex":0,"nudge":"原文用 but 把父母那一代（过去）和 people my age 对比。A 里的 are 和 B 里的 used，哪个说的是现在？","explanation":"A：已经习惯了，现在就这样学。<br><strong>规则 ④</strong>：be used to 的 to 是介词，后接 doing（look forward to、contribute to 也一样）；used to do = 以前常常，现在不了。","subSkill":"preposition_plus_doing"},{"question":"第三个回答：<em>Children need to be taught this, just as they're taught to cross the road safely.</em><br>Who should do the teaching?","options":["The children themselves","Someone else, such as schools","Nobody; children learn it alone"],"correctIndex":1,"nudge":"need to be taught：孩子是教的人，还是被教的人？再看考官的问题：Should schools teach children…?","explanation":"孩子是被教的一方，教的是学校。<br><strong>规则 ⑤</strong>：主语是被做的 → to be done：need to be taught。写成 Children need to teach this，就成了孩子去教别人。","subSkill":"perfect_and_passive_infinitives"},{"question":"你来试试：口语 Part 1 想说「我已经不熬夜了，现在也习惯了早起」，哪句对？","options":["I've stopped to stay up late, and I'm used to getting up early now.","I've stopped staying up late, and I used to get up early now.","I've stopped staying up late, and I'm used to getting up early now."],"correctIndex":2,"nudge":"两件事分开想：熬夜是「不再做」还是「停下来去做」？早起是「以前常常」还是「现在习惯了」？用规则 ② 和 ④。","explanation":"不再熬夜 → stopped staying up（规则 ②）；现在习惯早起 → I'm used to getting up（规则 ④）。stopped to stay up 是停下来去熬夜；used to get up 是以前常早起。","subSkill":"verbs_taking_both_with_meaning_change"}],"tip":"【doing 还是 to do？先想意思】\n\n① 一个动作当主语 → doing 开头，动词用单数：Checking messages has…\n② stop doing = 不再做；stop to do = 停下来，去做另一件事\n③ failure / ability / decision + to do；habit / importance / risk + of doing\n④ 能直接接名词的 to 是介词，后接 doing：be used to / look forward to / contribute to\n⑤ 主语是被做的 → to be done；说已经发生的事 → seem to have done\n⑥ avoid / consider / suggest / have difficulty + doing；decide / afford / tend + to do\n⑦ remember / forget / regret doing → 已经做过的事；remember / forget to do → 要去做的事\n同类：try doing = 换个办法试试；try to do = 努力想做到\n\n【例句】\n✔ Checking messages every few minutes has become a habit for many students.（动作当主语，用 has）\n✔ Children need to be taught how to manage their screen time.（孩子是被教的）\n\n【常见错误】\n✘ Learn English is not easy. → Learning English is…（见 ①）\n✘ This would contribute to reduce waste. → contribute to reducing（见 ④）\n✘ This problem needs to solve. → needs to be solved（见 ⑤）\n✘ My teacher suggested me to read more. → suggested that I read more / suggested reading more（见 ⑥）\n✘ It made me to feel nervous. → made me feel（make + 人 + 原形，不加 to）"}},"9":{"levels":{"1":[{"id":"gen-9-1-100","type":"choice","instruction":"〔写作 Task 1〕读这句调查结果，回答问题。原句：Few of the students surveyed preferred online classes to face-to-face teaching.","sentence":"What is the writer's point?","options":["Online classes were popular with most students.","Some students preferred online classes, which is encouraging.","All of the students preferred online classes.","Online classes were unpopular with the students."],"correctIndex":3,"explanation":"Few 前面没有 a，强调「很少、几乎没有」，所以网课不受欢迎。写成 A few，意思就成了「有几个」，语气偏正面。","subSkill":"advanced_quantifiers_the_majority_a_number_of"},{"id":"gen-9-1-101","type":"choice","instruction":"〔写作 Task 1〕读句子，回答问题。原句：A number of respondents said they had never visited a museum.","sentence":"Roughly how many respondents does the writer mean?","options":["The total number of people who were surveyed","Some of them; no exact figure is given","Exactly one of the people surveyed","Nearly all of the people surveyed"],"correctIndex":1,"explanation":"A number of + 复数 = 「一些、若干」，没有给具体的数。想说那个数，要写 The number of respondents who … was 120。","subSkill":"advanced_quantifiers_the_majority_a_number_of"},{"id":"gen-9-1-102","type":"match","instruction":"〔写作 Task 2〕每句说的是一类人的普遍情况，还是研究里那些具体的人？连线。","left":["Older people tend to save more.","The students we interviewed slept six hours a night.","The older people in the study saved more.","Students need more sleep than adults."],"right":["People of this type in general","The specific people in the study"],"correctPairs":[[0,0],[1,1],[2,1],[3,0]],"explanation":"不加 the 的复数名词（older people、students）泛指一类人；加了 the，后面还有 in the study / we interviewed 限定，就是特指研究里的那些人。","subSkill":"generic_vs_specific_article_use"},{"id":"gen-9-1-103","type":"choice","instruction":"〔写作 Task 1〕这句比较了男女做家务的时间。原句：Women in the survey spent an average of four hours a day on housework, twice the figure for men.","sentence":"How long did the men spend on housework a day?","options":["About eight hours","About two hours","About four hours","About six hours"],"correctIndex":1,"explanation":"twice the figure for men = 是男性那个数字的两倍：女性 4 小时，男性约 2 小时。twice 放在 the 前面。","subSkill":"double_determiners_and_pre_determiners"},{"id":"gen-9-1-104","type":"choice","instruction":"〔写作 Task 2〕读句子，回答问题。原句：Most of the parents interviewed believed that homework should be limited.","sentence":"Whose opinion is this?","options":["Most parents in the country","Over half of those interviewed","Every parent who was interviewed","Only a few of the parents interviewed"],"correctIndex":1,"explanation":"Most of the parents interviewed = 被采访的家长里的大多数（特指），也就是一半以上。想泛指社会上的大多数家长，写 Most parents，不加 of the。","subSkill":"determiners_in_academic_noun_phrases"},{"id":"gen-9-1-105","type":"scenario","instruction":"〔口语 Part 1〕读考生的回答，回答问题：Does the candidate have much time to chat with the neighbours?","context":"雅思口语 Part 1 · Neighbours","dialogue":[{"speaker":"examiner","text":"Examiner: Do you often talk to your neighbours?"},{"speaker":"player","text":"Well, I know a few of them by name, but I have little time to chat because I work long hours."}],"options":["No, not much at all.","Yes, a little.","Yes, plenty.","No, because the neighbours are strangers."],"correctIndex":0,"explanation":"little time = 几乎没时间（强调少）；a little time 才是「有一点时间」。a few of them 说明考生认识几个邻居，并不是全不认识。","subSkill":"advanced_quantifiers_the_majority_a_number_of"},{"id":"gen-9-1-106","type":"choice","instruction":"〔写作 Task 2〕读议论文里的这句，回答问题。原句：Technology has changed the way people learn, but the technology used in many schools is out of date.","sentence":"What does the writer say is out of date?","options":["All modern technology","How people learn today","Most teaching methods","What many schools use"],"correctIndex":3,"explanation":"前半句 Technology 不加 the，泛指科技；后半句 the technology used in many schools 被后面的短语限定，特指学校里在用的那些。","subSkill":"article_omission_in_abstract_nouns"},{"id":"gen-9-1-107","type":"choice","instruction":"〔写作 Task 1〕看这句趋势描述，回答问题。原句：Between 2015 and 2020, there was little change in the proportion of people who owned a pet.","sentence":"What happened to the proportion of pet owners between 2015 and 2020?","options":["It rose a little.","It hardly changed.","It fell sharply.","It changed quite a lot."],"correctIndex":1,"explanation":"little change = 几乎没有变化。little 前面没有 a，强调少；想说「有一点小变化」，写 a slight change。","subSkill":"advanced_quantifiers_the_majority_a_number_of"},{"id":"gen-9-1-108","type":"choice","instruction":"〔写作 Task 2〕读句子，回答问题。原句：A good teacher can change the way a child feels about learning.","sentence":"Which teacher is the writer talking about?","options":["Any good teacher","The writer's own teacher","A teacher mentioned earlier","Every teacher at a school"],"correctIndex":0,"explanation":"A good teacher = 任何一位好老师（泛指这一类）。前文提过某位老师、读者知道是谁，才用 the teacher。","subSkill":"generic_vs_specific_article_use"}],"2":[{"id":"gen-9-2-100","type":"choice","instruction":"〔写作 Task 1〕想强调「支持新营业时间的人几乎没有」。","sentence":"___ respondents supported the sports centre's new opening hours.","options":["Few","A few","Little","A little"],"correctIndex":0,"explanation":"强调少、几乎没有 → Few。A few 是「有几个」，语气偏正面；little / a little 配不可数名词，不能修饰 respondents。","subSkill":"advanced_quantifiers_the_majority_a_number_of"},{"id":"gen-9-2-101","type":"choice","instruction":"〔写作 Task 1〕想说「做兼职的学生人数」这个数据涨了。","sentence":"___ of students who work part-time has risen sharply since 2015.","options":["A number","Number","The amount","The number"],"correctIndex":3,"explanation":"说一个数据 → The number of …，动词用单数 has。A number of 是「一些」，动词要用 have；amount 配不可数名词，不能配 students。","subSkill":"advanced_quantifiers_the_majority_a_number_of"},{"id":"gen-9-2-102","type":"choice","instruction":"〔写作 Task 1〕想说「有一些学生说，为了省钱有时不吃饭」。","sentence":"___ students said they sometimes skip meals to save money.","options":["The number of","An amount of","A number of","A great deal of"],"correctIndex":2,"explanation":"「有一些」→ A number of + 复数名词，动词用复数。The number of 说的是那个数；an amount of、a great deal of 只配不可数名词。","subSkill":"advanced_quantifiers_the_majority_a_number_of"},{"id":"gen-9-2-103","type":"choice","instruction":"〔口语 Part 1〕想说「我家乡大部分人都在茶叶行业工作」。","sentence":"___ people in my hometown work in the tea industry.","options":["Most of","Almost","Most","The most"],"correctIndex":2,"explanation":"泛指「大部分人」→ Most people。Most of 后面要有 the / my 等（most of the people I know）；Almost 是副词，不能直接修饰名词；The most 是「最多的」。","subSkill":"determiners_in_academic_noun_phrases"},{"id":"gen-9-2-104","type":"choice","instruction":"〔写作 Task 1〕想说「加拿大家庭的平均用水量是西班牙家庭的两倍」。","sentence":"On average, households in Canada used ___ water that households in Spain did.","options":["the twice amount of","twice the number of","twice the amount of","two times amount of"],"correctIndex":2,"explanation":"water 不可数 → amount；twice 放在 the 前面：twice the amount of water。number 只配可数名词；the twice、two times amount of 都不对。也可以说 twice as much water as。","subSkill":"double_determiners_and_pre_determiners"},{"id":"gen-9-2-105","type":"choice","instruction":"〔写作 Task 1〕想说「智能手表的销量出现了大幅增长」。","sentence":"In 2019, there was ___ in smartwatch sales.","options":["sharp increase","a sharp increase","the sharp increase","sharp increases"],"correctIndex":1,"explanation":"increase 在这里是单数可数名词，第一次提到 → a sharp increase。光写 sharp increase 是最常见的漏冠词；the 表示前面已经提过的那次增长。","subSkill":"determiners_in_academic_noun_phrases"},{"id":"gen-9-2-106","type":"choice","instruction":"〔写作 Task 1〕想说去市游泳池的人少了三分之一。","sentence":"The ___ of people using the city's swimming pools fell by a third.","options":["amount","quantity","level","number"],"correctIndex":3,"explanation":"people 可数 → number。amount 配不可数名词（the amount of water）；quantity 多指物品、物资的量，不用来数人；level 说的是程度，也不和 people 搭配。","subSkill":"countable_vs_uncountable_quantifiers"},{"id":"gen-9-2-107","type":"scenario","instruction":"〔口语 Part 3〕考生想说「总的来说孩子读书比以前少了，但我家附近的孩子读得挺多」。哪句准确？","context":"雅思口语 Part 3 · Reading","dialogue":[{"speaker":"examiner","text":"Examiner: Do you think children read less than they used to?"}],"options":["In general, the children read less now, but the children in my neighbourhood read a lot.","In general, children read less now, but the children in neighbourhood read a lot.","In general, children read less now, but the children in my neighbourhood read a lot."],"correctIndex":2,"explanation":"泛指所有孩子 → children，不加 the；the children read less 像在说某一群特定的孩子。我家附近的孩子是特指 → the children in my neighbourhood；neighbourhood 单数可数，不能光着。","subSkill":"generic_vs_specific_article_use"},{"id":"gen-9-2-108","type":"match","instruction":"〔写作 Task 2〕每个空说的是泛指的概念，还是特指的那一个？选出空里该填的。","left":["___ air pollution kills millions of people every year.","___ pollution level in my city is dangerously high in winter.","___ happiness cannot be bought with money.","___ happiness of a nation depends on more than its wealth."],"right":["(no article)","The"],"correctPairs":[[0,0],[1,1],[2,0],[3,1]],"explanation":"air pollution、happiness 泛指 → 不加冠词。pollution level 是单数可数名词，必须有 The；happiness of a nation 被 of 短语限定，特指 → The。","subSkill":"article_omission_in_abstract_nouns"}],"3":[{"id":"gen-9-3-100","type":"fill","instruction":"〔写作 Task 1〕用 majority 写出：一半以上的受访者每周去健身房。","sentence":"___ of the respondents ___ (go) to the gym every week.","acceptableAnswers":["The majority","go"],"blankAnswers":[["The majority","A majority"],["go"]],"explanation":"More than half = The majority。of 后面是复数 respondents，动词跟着用复数 go，不写 goes。","subSkill":"advanced_quantifiers_the_majority_a_number_of"},{"id":"gen-9-3-101","type":"fill","instruction":"〔写作 Task 1〕把两个数字合成一句。原句：In 2010, 60% of homes had a landline. By 2020, the figure was 30%.","sentence":"In 2010, 60% of homes had a landline, but by 2020 the figure had fallen to ___ 2010 level.","acceptableAnswers":["half the","half of the","just half the","only half the","just half of the","only half of the","exactly half the","exactly half of the","half its","half of its","just half its","only half its","exactly half its","50% of the","50% of its","50 per cent of the"],"explanation":"30% 是 60% 的一半 → half the 2010 level（half of the 也对）。half 放在 the 前面，不写 the half。","subSkill":"double_determiners_and_pre_determiners"},{"id":"gen-9-3-102","type":"reorder","instruction":"〔写作 Task 1〕排出这句：北部的失业率几乎是全国平均水平的两倍。","words":["was","the","national","The","almost","unemployment","twice","rate","in","the","north","average."],"correctSentence":"The unemployment rate in the north was almost twice the national average.","explanation":"twice 放在 the 前面：twice the national average。rate 是单数可数名词，前面要有 The；the north、the national average 都是读者知道的那一个。","subSkill":"double_determiners_and_pre_determiners","acceptableSentences":["In the north, the unemployment rate was almost twice the national average."]},{"id":"gen-9-3-103","type":"fill","instruction":"〔写作 Task 2〕用一个名词短语作主语改写。原句：When people are healthy, they are able to keep working for longer.","sentence":"___ allows people to keep working for longer.","acceptableAnswers":["Good health","Health","Better health","Being healthy","Staying healthy","Keeping healthy","Being in good health","Staying in good health","Good physical health","Physical health","A healthy lifestyle","Maintaining good health","Remaining healthy","Remaining in good health","Keeping fit","Staying fit","Being fit","Fitness","Physical fitness","Better physical health"],"explanation":"health 泛指「健康」这个概念，不加 the：Good health allows … 写成 The health，读者会问：谁的健康？","subSkill":"article_omission_in_abstract_nouns"},{"id":"gen-9-3-104","type":"fill","instruction":"〔写作 Task 1〕把动词加副词改成名词短语。原句：The price of coffee rose slightly in 2019.","sentence":"There was ___ in the price of coffee in 2019.","acceptableAnswers":["a slight rise","a slight increase","a small rise","a small increase","a modest rise","a modest increase","a marginal rise","a marginal increase","a minor rise","a minor increase","a slight upturn","a slight upward trend","a small upturn","a minimal rise","a minimal increase"],"explanation":"rise / increase 在这里是单数可数名词，前面要有 a：a slight rise。漏掉 a 是 Task 1 里最常见的冠词错误。","subSkill":"determiners_in_academic_noun_phrases"},{"id":"gen-9-3-105","type":"fill","instruction":"〔口语 Part 1〕把两句合成一句。原句：I have about thirty classmates. Over twenty of them come from my province.","sentence":"___ my classmates come from the same province as me.","acceptableAnswers":["Most of","The majority of","A majority of","More than half of","Over half of","Two-thirds of","Over two-thirds of","More than two-thirds of","Two thirds of","Over two thirds of","More than two thirds of","Over twenty of","More than twenty of","Over 20 of","More than 20 of"],"explanation":"my classmates 是特指（我的同学），前面要用 Most of：Most of my classmates（Over twenty of 也对）。没有 Most my classmates，也没有 Most of classmates。","subSkill":"double_determiners_and_pre_determiners"},{"id":"gen-9-3-106","type":"fill","instruction":"〔写作 Task 1〕把两句合成一句。原句：The Science Museum had 1.2 million visitors. None of the other four museums had as many.","sentence":"Of the five museums, the Science Museum attracted ___ number of visitors.","acceptableAnswers":["the largest","the highest","the greatest","the biggest"],"explanation":"最多 → the largest / the highest number of visitors。最高级前要有 the，考生常写成 highest number，漏了 the。","subSkill":"determiners_in_academic_noun_phrases"},{"id":"gen-9-3-107","type":"fill","instruction":"〔写作 Task 1〕把两句合成一句。原句：In 2010, 300 students chose German. In 2020, only 120 did.","sentence":"In 2020, ___ students chose German than in 2010.","acceptableAnswers":["fewer","far fewer","many fewer","a lot fewer","considerably fewer","significantly fewer","substantially fewer","markedly fewer","noticeably fewer","180 fewer","dramatically fewer","60% fewer","60 per cent fewer","60 percent fewer"],"explanation":"students 可数 → fewer。less 配不可数名词（less money、less time）；口语里常听到 less students，写作里会被当成错误。","subSkill":"countable_vs_uncountable_quantifiers"},{"id":"gen-9-3-108","type":"fill","instruction":"〔写作 Task 1〕把动词句改成以名词短语开头的句子。原句：Fewer young people own a home than ten years ago.","sentence":"___ of young people who own a home ___ fallen over the past ten years.","acceptableAnswers":["The proportion","has"],"blankAnswers":[["The proportion","The number","The percentage","The share","The total number"],["has"]],"explanation":"主语是 the proportion / the number（一个数），不是 young people，所以用单数 has。前面的 The 也不能漏。","subSkill":"advanced_quantifiers_the_majority_a_number_of"}],"4":[{"id":"gen-9-4-100","type":"error","instruction":"〔写作 Task 1 · 考生常见错误〕点出用错的部分。","words":["The number of","students","who study abroad","have increased","sharply","since 2010."],"errorIndex":3,"correction":"has increased","explanation":"主语是 The number（那个数），不是 students，所以用单数 has increased。考生常被紧挨着的 students 带偏。","subSkill":"advanced_quantifiers_the_majority_a_number_of"},{"id":"gen-9-4-101","type":"error","instruction":"〔口语 Part 1 · 考生常见错误〕点出用错的部分。","words":["Most of people","in my home city","prefer","to rent","rather than","buy a flat."],"errorIndex":0,"correction":"Most people","explanation":"Most of people 是「大多数的人」的直译。of 后面要有 the / my 等词才能特指；泛指城里大多数人 → Most people（或 Most of the people）。","subSkill":"determiners_in_academic_noun_phrases"},{"id":"gen-9-4-102","type":"fill","instruction":"〔写作 Task 1 · 考生常见错误〕第二句开头漏了一个词，在空里补上。原句：There was a sharp drop in hotel bookings in 2020. Drop was mainly caused by the pandemic.","sentence":"There was a sharp drop in hotel bookings in 2020. ___ drop was mainly caused by the pandemic.","acceptableAnswers":["The","This","That","The sharp","This sharp"],"explanation":"第二次提到，读者已经知道是哪一次下降 → The drop（或 This drop）。drop 是单数可数名词，不能光着用。","subSkill":"determiners_in_academic_noun_phrases"},{"id":"gen-9-4-103","type":"error","instruction":"〔写作 Task 2 · 考生常见错误〕点出用错的部分。","words":["In my view,","the education","is","the most valuable","investment","a country","can make."],"errorIndex":1,"correction":"education","explanation":"泛指「教育」这个概念，不加 the。the most valuable 的 the 没问题：最高级要加 the。","subSkill":"article_omission_in_abstract_nouns"},{"id":"gen-9-4-104","type":"error","instruction":"〔写作 Task 1 · 考生常见错误〕点出用错的部分。","words":["In 2022,","the majority of","the respondents","was","satisfied","with the new service."],"errorIndex":3,"correction":"were","explanation":"the majority of + 复数名词，动词跟着复数名词走 → were。the number of 才用单数。","subSkill":"advanced_quantifiers_the_majority_a_number_of"},{"id":"gen-9-4-105","type":"error","instruction":"〔写作 Task 2 · 考生常见错误〕房价高是年轻毕业生面临的几大难题之一。点出用错的部分。","words":["One of","the biggest","problem","facing","young graduates","is","the high cost of housing."],"errorIndex":2,"correction":"problems","explanation":"「几大难题之一」→ one of the biggest problems，of 后面要用复数。动词跟着 One 走，用 is 没错。","subSkill":"determiners_in_academic_noun_phrases"},{"id":"gen-9-4-106","type":"fill","instruction":"〔写作 Task 2 · 考生常见错误〕有一处写错了，改对这句的开头（空里连 has / have 一起写）。原句：Many researches have shown that sleep affects memory.","sentence":"___ shown that sleep affects memory.","acceptableAnswers":["Much research has","A lot of research has","Lots of research has","A great deal of research has","Research has","Plenty of research has","Extensive research has","Considerable research has","A large body of research has","A body of research has","Recent research has","Previous research has","Some research has","Many studies have","A number of studies have","Several studies have","Numerous studies have","Studies have","Some studies have","Various studies have","Recent studies have","A lot of studies have","Lots of studies have","Many research studies have","A large number of studies have","Many researchers have","Researchers have","A number of researchers have","Several researchers have","Scientists have","Many scientists have","Scientific research has","Medical research has","A growing body of research has","Research studies have","Numerous research studies have","Several research studies have","Many pieces of research have","Several pieces of research have","Many experiments have","Experiments have","Multiple studies have","Plenty of studies have"],"explanation":"research 不可数，没有 researches：Much research has shown …，或换成可数的 Many studies have shown …。information、advice 也一样。","subSkill":"countable_vs_uncountable_quantifiers"},{"id":"gen-9-4-107","type":"error","instruction":"〔写作 Task 1 · 考生常见错误〕点出用错的部分。","words":["Of the four countries,","Japan","had","highest proportion","of people","aged over 65."],"errorIndex":3,"correction":"the highest proportion","explanation":"最高级前要加 the：the highest proportion。proportion 是单数可数名词，本来也不能光着用。","subSkill":"determiners_in_academic_noun_phrases"},{"id":"gen-9-4-108","type":"choice","instruction":"〔口语 Part 3 · 考生常见说法〕原句：I think the children spend too much time on the phones these days. 选出改对的句子。","options":["I think children spend too much time on their phones these days.","I think the children spend too much time on their phones these days.","I think children spend too much time on the phones these days.","I think the children spend too much time on phone these days."],"correctIndex":0,"explanation":"泛指现在的孩子 → children，不加 the；手机是他们自己的 → their phones。the phones 听起来像在说某几部特定的手机。","subSkill":"generic_vs_specific_article_use"},{"id":"gen-9-4-109","type":"error","instruction":"〔口语 Part 2 · 考生常见错误〕活动因为人太少取消了。点出用错的部分。","words":["Unfortunately,","a few people","turned up","on the day,","so","the event","was cancelled."],"errorIndex":1,"correction":"very few people","explanation":"人太少才取消 → 强调少：very few people，或 only a few people。a few people 只是「来了几个人」，和 so … cancelled 接不上。","subSkill":"advanced_quantifiers_the_majority_a_number_of"}],"5":[{"id":"gen-9-5-100","type":"fill","instruction":"〔写作 Task 1〕补全这段休闲活动调查的描述，每空填一个词。","sentence":"Overall, watching TV was ___ most popular way to relax. ___ majority of respondents watched it every evening, while ___ proportion who read for pleasure ___ much lower, at just 18%.","acceptableAnswers":["the","The","the","was"],"blankAnswers":[["the"],["The","A"],["the"],["was","remained"]],"explanation":"① 最高级 → the most popular。② The majority of + 复数名词。③④ the proportion 是一个数 → 动词用单数 was。","subSkill":"advanced_quantifiers_the_majority_a_number_of"},{"id":"gen-9-5-101","type":"fill","instruction":"〔写作 Task 2〕这句有两处不准确，改对。原句：The people should protect the nature, because the nature gives us food and water.","sentence":"___ should protect ___, because it gives us food and water.","acceptableAnswers":["People","nature"],"blankAnswers":[["People","We","Humans","Human beings","Everyone","We all","All of us","Each of us","Society","Individuals","Governments","Humanity","Humankind","Mankind","Everybody","We humans","Every one of us","All people"],["nature","the environment","the natural world","the planet","the Earth","the earth","Earth","our planet","our environment","the natural environment","our natural environment"]],"explanation":"泛指「人们」「大自然」→ People、nature，不加 the。不过 the environment、the natural world 习惯带 the，写这两个也对。","subSkill":"article_omission_in_abstract_nouns"},{"id":"gen-9-5-102","type":"fill","instruction":"〔写作 Task 1〕把 many people 换成更准确的说法，让读者知道这是多数（约七成）。原句：Many people in the survey, about 70%, said they used social media every day.","sentence":"___ respondents said they used social media every day.","acceptableAnswers":["The majority of","A majority of","The majority of the","A large majority of","A clear majority of","Most","Most of the","Around 70% of","About 70% of","Roughly 70% of","Approximately 70% of","Some 70% of","Nearly 70% of","Almost 70% of","Around 70% of the","About 70% of the","Roughly 70% of the","Approximately 70% of the","70% of","70% of the","Around 70 per cent of","About 70 per cent of","Around 70 percent of","About 70 percent of","Seven in ten","Seven out of ten","Around seven in ten","About seven in ten","Roughly seven in ten","Nearly seven in ten","Over two-thirds of","More than two-thirds of","Over two-thirds of the","More than two-thirds of the","Around two-thirds of","About two-thirds of","Roughly two-thirds of","Around two thirds of","About two thirds of","Roughly two thirds of","Over two thirds of","More than two thirds of","Over two thirds of the","More than two thirds of the","Around 70 per cent of the","About 70 per cent of the","Roughly 70 per cent of","Nearly 70 per cent of","Almost 70 per cent of","Approximately 70 per cent of","70 per cent of","70 percent of","Approximately seven in ten","Almost seven in ten","Seven out of every ten","Around seven out of ten","About seven out of ten","Nearly seven out of ten"],"explanation":"The majority of、Around 70% of、Seven in ten 都比 many people 准确，读者一看就知道是多数。Most respondents 不加 of；用 Most of，后面要有 the。","subSkill":"advanced_quantifiers_the_majority_a_number_of"},{"id":"gen-9-5-103","type":"fill","instruction":"〔写作 Task 1〕补全这段饼图描述。不需要冠词的空，留空或写 -。","sentence":"In 1990, ___ food accounted for ___ largest share of household spending, at 31%. By 2020, however, ___ biggest expense was ___ housing, while spending on ___ clothing had fallen to just 5%.","acceptableAnswers":["不填","the","the","不填","不填"],"blankAnswers":[["不填"],["the"],["the"],["不填"],["不填"]],"explanation":"food、housing、clothing 泛指这一类开支，不加冠词；最高级 the largest share、the biggest expense 要加 the。","subSkill":"generic_vs_specific_article_use"},{"id":"gen-9-5-104","type":"fill","instruction":"〔口语 Part 3〕考官：Do people in your country cook at home less than they used to? 补全回答：在家做饭的人比以前少了，我们城市的外卖店也多了很多。","sentence":"Yes, I think ___ people cook at home these days, and ___ of takeaway shops in my city has grown a lot.","acceptableAnswers":["fewer","the number"],"blankAnswers":[["fewer","far fewer","many fewer","a lot fewer","fewer and fewer","significantly fewer","considerably fewer","noticeably fewer","substantially fewer"],["the number","the total number","the overall number"]],"explanation":"people 可数 → fewer，不说 less people。外卖店的数目 → the number of takeaway shops，主语是 number，所以动词用 has。","subSkill":"countable_vs_uncountable_quantifiers"},{"id":"gen-9-5-105","type":"scenario","instruction":"〔口语 Part 2〕考生想说「来的人不多，只有几个老同学，但大家都玩得很开心」。哪句说得准确？","context":"雅思口语 Part 2 · 题卡：Describe a party or gathering that you enjoyed","dialogue":[],"options":["Not many people came, just few old classmates, but all of us had great time.","Not many people came, just a few old classmates, but we all had a great time.","A few people didn't come, just the few old classmates, but we all had great fun.","Little people came, just a few old classmates, but the all of us had a great time."],"correctIndex":1,"explanation":"不多但有几个 → just a few old classmates；a great time 的 a 不能漏。Little 只配不可数名词；all of us 前面不加 the；A few people didn't come 意思反了。","subSkill":"advanced_quantifiers_the_majority_a_number_of"},{"id":"gen-9-5-106","type":"fill","instruction":"〔写作 Task 1 · 考生常见错误〕把这句改准确。原句：In 2015, number of tourists increased very much, it was biggest increase in the period.","sentence":"In 2015, there was ___ increase in ___ number of tourists, ___ largest in the whole period.","acceptableAnswers":["a sharp","the","the"],"blankAnswers":[["a sharp","a significant","a dramatic","a considerable","a substantial","a marked","a huge","a big","a large","a steep","a notable","a remarkable","an enormous","a massive","a rapid","a major","a great","a sudden","a striking","an impressive","a noticeable","a strong","a spectacular","an unprecedented","a pronounced","a tremendous","a record","a vast","an exceptional","a very large","a very big","a very sharp","a very significant","an","a drastic","a sizeable","a sizable","an extraordinary","an immense","an abrupt","a particularly sharp","a particularly large","an unusually large","an unusually sharp","an extremely sharp","an extremely large","a very rapid","a very steep","a very dramatic"],["the","the total"],["the","by far the"]],"explanation":"increase 是单数可数名词 → a sharp increase；说那个数 → the number of；最高级 → the largest。三处都不能光着。","subSkill":"determiners_in_academic_noun_phrases"},{"id":"gen-9-5-107","type":"fill","instruction":"〔写作 Task 1〕补全对比：第一空说「是…的一半」，第二空说「是…的三倍」。","sentence":"In 2005, only 12% of adults were learning a foreign language, ___ figure for 1995. By 2015, the proportion had risen to 36%, ___ 2005 level.","acceptableAnswers":["half the","three times the"],"blankAnswers":[["half the","half of the","just half the","only half the","exactly half the","just half of the","only half of the","exactly half of the"],["three times the","triple the","treble the","exactly three times the","three times as high as the","thrice the"]],"explanation":"half、three times 放在 the 前面：half the figure（half of the 也对）、three times the 2005 level。不写 the half，也不写 three times of。","subSkill":"double_determiners_and_pre_determiners"},{"id":"gen-9-5-108","type":"fill","instruction":"〔写作 Task 2〕把这句改准确。原句：The prison is not the best way to reduce the crime.","sentence":"___ is not ___ best way to reduce ___.","acceptableAnswers":["Prison","the","crime"],"blankAnswers":[["Prison","Imprisonment","Jail","A prison sentence","Sending people to prison","Putting people in prison","Sending offenders to prison","Putting offenders in prison","Sending criminals to prison","Putting criminals in prison","Locking people up","Locking criminals up","Locking offenders up","Incarceration","Jailing offenders","Jailing criminals","Imprisoning offenders","Imprisoning criminals","Locking up criminals","Locking up offenders","Putting criminals behind bars","Sending people to jail","Sending offenders to jail","A custodial sentence","A jail sentence"],["the"],["crime","crime rates","the crime rate","crime levels","the level of crime","levels of crime","the amount of crime","reoffending","re-offending","offending","criminal behaviour","criminal behavior","the rate of crime","rates of crime","criminal activity","the number of crimes","recidivism","reoffending rates","re-offending rates"]],"explanation":"泛指「坐牢」这种做法和「犯罪」→ Prison、crime，不加 the；best 是最高级，the 要留着。the crime rate 也对：rate 单数可数，要有 the。","subSkill":"article_omission_in_abstract_nouns"}]},"mission":{"title":"写作 Task 1：大家从哪里看新闻？","description":"写一段雅思 Task 1 的总览和正文（3 句）：先写总体情况，再写最年轻那组的细节，最后写最年长那组（写法自选）。每写一个数量，先问自己：说的是一个数，还是一些人？是泛指，还是图里的那一组？至少用对本单元的 2 种写法。AI 老师会按雅思「语法多样性与准确性」给你反馈。","scenario":"题目：The chart below shows the results of a survey in which 1,200 adults in Canada were asked where they mainly get their news. Summarise the information by selecting and reporting the main features.<br>图表信息（每组 400 人）：18–34 岁：社交媒体 58%，新闻网站 / App 27%，电视 12%，报纸 3%。35–59 岁：新闻网站 / App 41%，电视 33%，社交媒体 19%，报纸 7%。60 岁及以上：电视 52%，报纸 24%，新闻网站 / App 18%，社交媒体 6%。<br>你只写总览和正文的 3 句。","grammarType":"advanced_quantifiers_the_majority_a_number_of","scaffolds":[{"prefix":"The chart compares where three age groups mainly get their news.","suffix":"","hint":"写总览：总体上哪类来源最常见？哪一组最不一样？可以用 the most …、the majority of …。","grammarCheck":"determiners_in_academic_noun_phrases","example":"Overall, online sources were the most common choice for younger adults, while the majority of people aged 60 and over relied on television."},{"prefix":"Social media was by far the most popular source among 18–34-year-olds, at 58%.","suffix":"","hint":"接着写这组的其它来源：可以用 few / a few，或 the proportion who … was …。注意动词跟谁走。","grammarCheck":"advanced_quantifiers_the_majority_a_number_of","example":"By contrast, very few of them relied on newspapers, and the proportion who chose television was only 12%."},{"prefix":"The pattern for the oldest group was very different.","suffix":"","hint":"写 60 岁及以上这组，结构自选：可以用 more than twice / eight times the …，也可以用 the + 最高级，或者干脆写两个短句。","grammarCheck":"double_determiners_and_pre_determiners","example":"Over half of them relied mainly on TV, and the proportion who read newspapers, at 24%, was eight times the figure for the youngest group."}]},"discover":{"story":{"title":"写作范文：现金还有人用吗？（Task 1 + Task 2）","text":"读的时候想一想：哪个年龄段最离不开现金？作者为什么认为现金还不能取消？蓝色的句子下面会逐句问你。\nTask 1: The chart below shows the results of a survey in which 1,500 adults in New Zealand (aged 18–34, 35–59 and 60+) were asked how they usually pay in shops. Summarise the information by selecting and reporting the main features.\nThe chart compares the payment methods used by three age groups. Overall, cards are the most popular choice, while cash is used mainly by the oldest group.\nThe majority of respondents aged 18–34 pay with their phones, and very few still carry cash. Around 70% of respondents aged 35–59 pay mainly by bank card. In the oldest group, by contrast, almost half the respondents use cash every week, twice the proportion in the 35–59 group. When asked to explain their choice, a number of respondents mentioned security, but convenience was the reason given most often.\nTask 2: Some people think that cash will soon disappear completely. To what extent do you agree or disagree?\nCash use may be declining, but the number of shops that refuse cash is still small. More importantly, older people often rely on it to keep track of their spending, and many of them find mobile payments confusing. Cash also works when the internet is down or a phone battery dies. A cashless society would therefore leave some of the most vulnerable people behind, so governments should protect the right to pay in cash.","highlights":["very few still carry cash","almost half the respondents","twice the proportion","a number of respondents","the number of shops that refuse cash is still small","older people often rely on it","a cashless society"]},"questions":[{"question":"第二段：<em>The majority of respondents aged 18–34 pay with their phones, and very few still carry cash.</em><br>In the youngest group, do many people still carry cash?","options":["No, hardly any of them do.","No, not a single one of them does.","Yes, several of them do."],"correctIndex":0,"nudge":"看 very few still carry cash：few 前面没有 a。作者是在说「还有几个人带」，还是在强调「带的人少」？少，是不是就等于一个都没有？","explanation":"几乎没人带，但不是一个都没有。very few = 极少。<br><strong>规则 ①</strong>：few / little = 很少、几乎没有（强调少）；a few / a little = 有一些（强调有）。few 配可数名词，little 配不可数名词。","subSkill":"advanced_quantifiers_the_majority_a_number_of"},{"question":"第二段：<em>In the oldest group, by contrast, almost half the respondents use cash every week, twice the proportion in the 35–59 group.</em><br>Roughly what percentage of people in the 35–59 group use cash every week?","options":["About 75%","About 50%","About 25%"],"correctIndex":2,"nudge":"twice the proportion in the 35–59 group：谁是谁的两倍？最年长那组是 almost half。","explanation":"25% 左右：最年长那组（将近一半）是它的两倍。<br><strong>规则 ②</strong>：half、twice、all、both 放在 the 前面：half the respondents（half of the 也对）、twice the proportion。不写 the half、the twice。","subSkill":"double_determiners_and_pre_determiners"},{"question":"比较原文两处：<br>A. …<em>a number of respondents</em> mentioned security…<br>B. …<em>the number of shops</em> that refuse cash is still small…<br>Which one is about a figure, not about the people or shops themselves?","options":["A","B","Both of them"],"correctIndex":1,"nudge":"B 里「还很小」（is still small）的是什么：是商店，还是一个数？A 里提到安全的又是谁？","explanation":"B：拒收现金的店，数目还很小。A 是「有一些受访者」提到了安全。<br><strong>规则 ③</strong>：the number of … = 那个数，动词用单数（is）；a number of + 复数 = 一些…，动词用复数。","subSkill":"advanced_quantifiers_the_majority_a_number_of"},{"question":"Task 2 段：<em>More importantly, older people often rely on it to keep track of their spending…</em><br>Who does <em>older people</em> refer to here?","options":["Only the older respondents in the survey","Older people in general","A few older people the writer knows"],"correctIndex":1,"nudge":"older people 前面有没有 the？对比 Task 1 段的 the respondents。这段 Task 2 还在讲那次调查吗？","explanation":"泛指所有老年人，不只是调查里的那些人。<br><strong>规则 ④</strong>：泛指一类人、一类东西或抽象概念 → 不加 the（older people、cash、convenience）；读者知道是哪些 → the（the respondents）。少数词习惯带 the：the internet。","subSkill":"generic_vs_specific_article_use"},{"question":"Task 2 段：<em>A cashless society would therefore leave some of the most vulnerable people behind…</em><br>Is the writer talking about one particular society that already exists?","options":["No, any society without cash.","No, only New Zealand in the future.","Yes, a country where cash has already gone."],"correctIndex":0,"nudge":"society 前面用的是 a，不是 the。这段 Task 2 提到过新西兰吗？作者说的是哪一个社会？","explanation":"不是，指任何一个无现金社会，作者在设想。society 是单数可数名词，不能光着写 cashless society。<br><strong>规则 ⑤</strong>：单数可数名词不能光着用：泛指「任何一个」或第一次提到 → a / an；读者知道是哪一个 → the。最高级前也要 the（the most vulnerable）。","subSkill":"determiners_in_academic_noun_phrases"},{"question":"你来试试：想写「几乎没有年轻人认为现金重要，而且这样想的人数还在下降」。<br>Which sentence is correct?","options":["A few young people think cash is important, and the number is still falling.","Few young people think the cash is important, and the number is still falling.","Few young people think cash is important, and the number is still falling."],"correctIndex":2,"nudge":"先想：你要强调「少」还是「有」？这里的现金是泛指吗？用规则 ①④。","explanation":"强调少 → Few（规则 ①）；现金泛指 → cash，不加 the（规则 ④）。the number 是一个数，所以用 is（规则 ③）。","subSkill":"advanced_quantifiers_the_majority_a_number_of"}],"tip":"【先想清楚：说的是谁？是一个数，还是一些人？】\n\n① few / little = 几乎没有（强调少）；a few / a little = 有一些（few 配可数，little 配不可数）\n② half / twice / all / both 放在 the 前面：half the respondents（half of the 也对）\n③ the number of … = 那个数，动词用单数；a number of + 复数 = 一些…，动词用复数\n④ 泛指一类或抽象概念 → 不加 the（older people, cash）；读者知道是哪些 → the。固定带 the：the internet, the environment, the government, the elderly\n⑤ 单数可数名词不能光着：a sharp rise；最高级前加 the：the highest figure, the most popular\n⑥ the majority of + 复数名词 → 动词用复数；泛指说 most people，特指说 most of the respondents\n⑦ number / many / fewer 配可数；amount / much / less 配不可数。百分比、钱、时间用 less than（less than 20%）\nresearch、information、advice 不可数，没有复数。\n\n【例句】\n✔ Almost half the older respondents use cash, twice the proportion in the 35–59 group.\n✔ The number of shops that refuse cash is still small.\n\n【常见错误】\n✘ Number of tourists have risen. → The number of tourists has risen（见 ③）\n✘ Most of people prefer cards. → Most people / Most of the respondents（见 ⑥）\n✘ There was slight increase in sales. → a slight increase（见 ⑤）\n✘ The education is the key to success. → Education（见 ④）"}},"10":{"levels":{"1":[{"id":"gen-10-1-100","type":"choice","instruction":"〔写作 Task 1〕读句子，回答问题。原句：In 2020, Italy spent considerably less on scientific research than Germany did.","sentence":"Which country spent more, and was the difference large?","options":["Italy, by a large amount.","Germany, but only a little more.","Germany, by a large amount.","Both spent about the same."],"correctIndex":2,"explanation":"considerably less = 少得多：意大利花得少，德国花得多，差距很大。than Germany did 里的 did 代替 spent，不用重复动词。","subSkill":"degree_adverbs_with_adjectives_and_nouns"},{"id":"gen-10-1-101","type":"choice","instruction":"〔写作 Task 1〕读句子，回答问题。原句：The higher a household's income, the more often its members ate out.","sentence":"Which households ate out least often?","options":["The poorest households","The richest households","Middle-income households","All households equally"],"correctIndex":0,"explanation":"收入越高，外出就餐越多；反过来，收入最低的家庭最少出去吃。the + 比较级 …, the + 比较级 … 说两个变化同步。","subSkill":"double_comparatives_the_more_the_more"},{"id":"gen-10-1-102","type":"match","instruction":"〔写作 Task 1〕退休人士的爱好调查：每句说的差距是小，还是大？连线。","left":["Reading was almost as popular as gardening.","Golf was nowhere near as popular as gardening.","Reading was marginally more popular than cooking.","Walking was by far the most popular hobby."],"right":["The gap was small.","The gap was large."],"correctPairs":[[0,0],[1,1],[2,0],[3,1]],"explanation":"almost as … as 差一点就一样，marginally 只多一点 → 差距小。nowhere near as … as 远远不如，by far the most 遥遥领先 → 差距大。","subSkill":"degree_adverbs_with_adjectives_and_nouns"},{"id":"gen-10-1-103","type":"choice","instruction":"〔写作 Task 1〕读句子，回答问题。原句：In 2018, the science museum attracted twice as many visitors as it did in 2008.","sentence":"If the museum had 200,000 visitors in 2008, roughly how many did it have in 2018?","options":["About 100,000","About 220,000","About 400,000","About 600,000"],"correctIndex":2,"explanation":"twice as many … as = 是…的两倍：2008 年 20 万，2018 年约 40 万。as it did in 2008 里的 did 代替 attracted。","subSkill":"as_as_constructions_with_inversion"},{"id":"gen-10-1-104","type":"choice","instruction":"〔写作 Task 1〕读句子，回答问题。原句：In 2010, online sales were nowhere near as high as in-store sales.","sentence":"In 2010, were online sales close to in-store sales?","options":["Yes, they were almost equal.","Yes, slightly higher.","No, they were far higher.","No, they were far lower."],"correctIndex":3,"explanation":"nowhere near as … as = 远远不如：网上销售额比实体店低得多。和 almost as … as（差一点就一样）意思正好相反。","subSkill":"as_as_constructions_with_inversion"},{"id":"gen-10-1-105","type":"scenario","instruction":"〔口语 Part 2〕读考生的回答，回答问题：Has the speaker been anywhere more beautiful than Guilin?","context":"雅思口语 Part 2 · 题卡：Describe a beautiful place you have visited","dialogue":[{"speaker":"player","text":"I went to Guilin with my parents two years ago, and honestly, it's the most beautiful place I've ever been to. The mountains were even more impressive in real life than in photos."}],"options":["No, nowhere so far.","Yes, several places.","Yes, one or two.","The speaker doesn't remember."],"correctIndex":0,"explanation":"the most beautiful place I've ever been to = 到现在去过的地方里最美的，还没去过更美的。最高级 + have ever done = 到目前为止。","subSkill":"superlatives_with_present_perfect"},{"id":"gen-10-1-106","type":"choice","instruction":"〔写作 Task 1〕读句子，回答问题。原句：In 2019, women spent far more time on unpaid care work than did men.","sentence":"Who spent more time on unpaid care work?","options":["Men, by a long way","Women, but only slightly","Both about the same","Women, by a long way"],"correctIndex":3,"explanation":"than did men = than men did，把 did 放到主语前，更正式，意思不变。far more = 多得多：女性花的时间远多于男性。","subSkill":"comparative_clauses_with_ellipsis"},{"id":"gen-10-1-107","type":"choice","instruction":"〔写作 Task 1〕读句子，回答问题。原句：Among the languages the respondents spoke at home, Mandarin was the second most common.","sentence":"How many languages were more common than Mandarin?","options":["None","One","Two","We can't tell"],"correctIndex":1,"explanation":"the second most common = 排第二：只有一种语言比它更常见。the second + 最高级 说的就是第二名。","subSkill":"superlatives_in_data_description"},{"id":"gen-10-1-108","type":"choice","instruction":"〔写作 Task 1〕读句子，回答问题。原句：Hotel bookings fell sharply in 2020, as did airline ticket sales.","sentence":"What happened to airline ticket sales in 2020?","options":["They rose sharply.","They also fell sharply.","They hardly changed at all.","They fell, but slowly."],"correctIndex":1,"explanation":"as did airline ticket sales = 机票销量也一样大跌。did 代替 fell sharply，放在主语前，较正式；也可写 and so did …。","subSkill":"as_as_constructions_with_inversion"}],"2":[{"id":"gen-10-2-100","type":"choice","instruction":"〔写作 Task 1〕电价：2021 年每度 0.20 英镑，2022 年 0.34 英镑。选出合适的说法。","sentence":"Electricity prices in 2022 were ___ than in 2021.","options":["very higher","more higher","slightly higher","much higher"],"correctIndex":3,"explanation":"0.20 → 0.34，涨了七成，差距大 → much / far higher。slightly 是只高一点；very 不能修饰比较级；higher 前不能再加 more。","subSkill":"degree_adverbs_with_adjectives_and_nouns"},{"id":"gen-10-2-101","type":"choice","instruction":"〔写作 Task 1〕这家公司 2019 年卖出 4,000 辆电动汽车，2020 年 12,000 辆。选出合适的说法。","sentence":"In 2020, the company sold ___ electric cars as in 2019.","options":["three times as much","three times as many","as three times many","three times so many"],"correctIndex":1,"explanation":"12,000 是 4,000 的三倍；cars 可数 → three times as many … as。much 配不可数名词；倍数放在第一个 as 前面。","subSkill":"as_as_constructions_with_inversion"},{"id":"gen-10-2-102","type":"choice","instruction":"〔写作 Task 1〕想说「2021 年的申请人比以往任何一年都多得多」。","sentence":"There were ___ applicants in 2021 than in any previous year.","options":["many more","much more","very more","more many"],"correctIndex":0,"explanation":"applicants 可数 → many more（也可以 far more）。much more 配不可数名词，比如 much more money；very 不能修饰 more。","subSkill":"degree_adverbs_with_adjectives_and_nouns"},{"id":"gen-10-2-103","type":"choice","instruction":"〔写作 Task 1〕想说「阿根廷的人均肉类消费量远高于印度的人均消费量」。","sentence":"Meat consumption per person in Argentina was far higher than ___.","options":["India","that in India","those in India","it in India"],"correctIndex":1,"explanation":"消费量和消费量比 → than that in India（或 than in India）。than India 是拿消费量和国家比；consumption 单数，不用 those。","subSkill":"comparative_clauses_with_ellipsis"},{"id":"gen-10-2-104","type":"choice","instruction":"〔写作 Task 1〕想说「收入越高，人们越可能出国度假」。","sentence":"The higher people's income, ___ to take holidays abroad.","options":["the more they were likely","more likely they were","the more likely they were","the more likelier they were"],"correctIndex":2,"explanation":"越可能 → the more likely 连在一起，后面才是 they were。拆开写，句子就不通了；likelier 已是比较级，前面不能再加 more。","subSkill":"double_comparatives_the_more_the_more"},{"id":"gen-10-2-105","type":"choice","instruction":"〔写作 Task 1〕2015 年，风电占总发电量的 6%，煤电占 58%。选出合适的说法。","sentence":"In 2015, wind farms produced ___ as much electricity as coal-fired power stations.","options":["nowhere near","almost exactly","not quite","every bit"],"correctIndex":0,"explanation":"6% 对 58%，差得很远 → nowhere near as much … as。almost exactly 几乎一样，not quite 只差一点，every bit 完全一样。","subSkill":"as_as_constructions_with_inversion"},{"id":"gen-10-2-106","type":"scenario","instruction":"〔口语 Part 2〕考生想说「那是我吃过的最好吃的一顿饭」。哪句准确？","context":"雅思口语 Part 2 · 题卡：Describe a memorable meal you have had","dialogue":[],"options":["It was the best meal I've never had.","It was the best meal I ever have.","It was the best meal I've ever had.","It was the most good meal I've had."],"correctIndex":2,"explanation":"到现在为止吃过的最好的 → the best … I've ever had。never 是「从来没有」，意思反了；I ever have 时态不对；good 的最高级是 best。","subSkill":"superlatives_with_present_perfect"},{"id":"gen-10-2-107","type":"choice","instruction":"〔写作 Task 1〕想说「2000 年旅游业是这个岛遥遥领先的最大收入来源」。","sentence":"In 2000, tourism was ___ source of income on the island.","options":["by far largest","the by far largest","the most largest","by far the largest"],"correctIndex":3,"explanation":"遥遥领先 → by far the + 最高级（或 the largest source by far）。the 不能省，也不放在 by far 前面；largest 前不再加 most。","subSkill":"degree_adverbs_with_adjectives_and_nouns"},{"id":"gen-10-2-108","type":"choice","instruction":"〔写作 Task 1〕想说「2015 年城市居民看医生比农村居民更频繁」，不重复动词。","sentence":"In 2015, city residents visited their doctor more often than rural residents ___.","options":["did","were","does","was"],"correctIndex":0,"explanation":"前面的动词是 visited（一般过去时）→ 用 did 代替。were 只能代替 be 动词，比如 They were more active than we were。","subSkill":"comparative_clauses_with_ellipsis"},{"id":"gen-10-2-109","type":"match","instruction":"〔写作 Task 1〕每句都是 Spending on food was ___ spending on housing. 想表达右边的意思，空里该填左边哪个？连线。","left":["slightly higher than","far higher than","almost as high as","nowhere near as high as"],"right":["Food: much less than housing","Food: a little more than housing","Food: much more than housing","Food: a little less than housing"],"correctPairs":[[0,1],[1,2],[2,3],[3,0]],"explanation":"slightly / far + 比较级：多一点 / 多得多。almost as … as 差一点就一样，所以略少；nowhere near as … as 远远不如，所以少得多。","subSkill":"degree_adverbs_with_adjectives_and_nouns"}],"3":[{"id":"gen-10-3-100","type":"fill","instruction":"〔写作 Task 1〕把两个数字合成一句，说出倍数。原句：In 2012, the charity had 4,000 volunteers. In 2022, it had 8,000.","sentence":"In 2022, the charity had ___ volunteers ___ in 2012.","acceptableAnswers":["twice as many","as"],"blankAnswers":[["twice as many","two times as many","exactly twice as many"],["as","as it had","as it did"]],"explanation":"8,000 是 4,000 的两倍 → twice as many volunteers as。volunteers 可数，用 many；倍数放在第一个 as 前面。","subSkill":"as_as_constructions_with_inversion"},{"id":"gen-10-3-101","type":"fill","instruction":"〔口语 Part 3〕用 The … the … 改写，意思不变。原句：As people get older, they tend to sleep less.","sentence":"___ people get, ___ they tend to sleep.","acceptableAnswers":["The older","the less"],"blankAnswers":[["The older"],["the less","the fewer hours"]],"explanation":"年纪越大，睡得越少 → The older people get, the less they tend to sleep。两半句都是 the + 比较级，后面主语和动词照常写。","subSkill":"double_comparatives_the_more_the_more"},{"id":"gen-10-3-102","type":"reorder","instruction":"〔写作 Task 1〕排出这句：伦敦的平均房租比曼彻斯特的高得多。","words":["far","London","than","The","rent","in","higher","that","average","was","in","Manchester."],"correctSentence":"The average rent in London was far higher than that in Manchester.","explanation":"比的是房租和房租 → than that in Manchester（that = the average rent）。far 放在比较级 higher 前面，表示「高得多」。","subSkill":"comparative_clauses_with_ellipsis","acceptableSentences":["In London the average rent was far higher than that in Manchester."]},{"id":"gen-10-3-103","type":"fill","instruction":"〔写作 Task 1〕加一个修饰词，说出「只高一点点」。原句：Cinema attendance in 2019 was higher than in 2018, but only by about 1%.","sentence":"Cinema attendance in 2019 was ___ higher than in 2018.","acceptableAnswers":["slightly","marginally","a little","a bit","fractionally","somewhat","only slightly","just slightly","only marginally","a little bit","very slightly","only a little","just a little","only fractionally","very marginally","a tiny bit","a fraction"],"explanation":"只高一点 → slightly / marginally / a little + 比较级。差得多才用 much / far；very 不能直接修饰比较级。","subSkill":"degree_adverbs_with_adjectives_and_nouns"},{"id":"gen-10-3-104","type":"fill","instruction":"〔口语 Part 2〕把两句合成一句。原句：I have stayed in a lot of hotels. That one was the worst of all.","sentence":"It was the worst hotel I ___ in.","acceptableAnswers":["have ever stayed","'ve ever stayed","have stayed","'ve stayed","had ever stayed","ever stayed","had stayed","'d stayed","'d ever stayed","have ever been","'ve ever been","had ever been","have been"],"explanation":"住过的酒店里最差 → the worst hotel I've ever stayed in。最高级常配 have (ever) done，说「到现在为止」。","subSkill":"superlatives_with_present_perfect"},{"id":"gen-10-3-105","type":"fill","instruction":"〔写作 Task 1〕不重复动词，把两句合成一句。原句：In 2019, men spent 5 hours a week on sport and women spent 3 hours. In 2009, the gap was only 1 hour.","sentence":"In 2019, men spent more time on sport than women ___, and the gap was wider than it ___ in 2009.","acceptableAnswers":["did","was"],"blankAnswers":[["did"],["was","had been"]],"explanation":"第一空代替 spent → did；第二空代替 was wide → was（也可以 had been）。than 后面的助动词要和前面的动词对上。","subSkill":"comparative_clauses_with_ellipsis"},{"id":"gen-10-3-106","type":"reorder","instruction":"〔写作 Task 2〕排出这句：孩子花在屏幕上的时间越多，读书就越少。","words":["less","spend","The","they","on","children","the","screens,","time","more","read."],"correctSentence":"The more time children spend on screens, the less they read.","explanation":"前半句 the more + 名词（time）+ 主语 + 动词；后半句 the less 后面直接接主语和动词。两个 the 都不能少。","subSkill":"double_comparatives_the_more_the_more","acceptableSentences":["The less time children spend on screens, the more they read."]},{"id":"gen-10-3-107","type":"fill","instruction":"〔写作 Task 1〕用 as … as 改写，意思不变。原句：Spain received far fewer international students than the UK.","sentence":"Spain received ___ international students ___ the UK.","acceptableAnswers":["nowhere near as many","as"],"blankAnswers":[["nowhere near as many","not nearly as many","nothing like as many","not anywhere near as many"],["as","as did"]],"explanation":"far fewer … than → nowhere near as many … as。students 可数，用 many；as … as 中间放原级，不放 fewer。","subSkill":"as_as_constructions_with_inversion"},{"id":"gen-10-3-108","type":"fill","instruction":"〔写作 Task 1〕说出「遥遥领先的第一」。原句：Rice was the most common crop in the region. No other crop came close.","sentence":"Rice was ___ common crop in the region.","acceptableAnswers":["by far the most","easily the most","far and away the most","much the most","overwhelmingly the most"],"explanation":"遥遥领先 → by far the most（或 easily the most）。by far 放在 the 前面，或放句尾：the most common crop by far。","subSkill":"degree_adverbs_with_adjectives_and_nouns"},{"id":"gen-10-3-109","type":"fill","instruction":"〔写作 Task 1〕用 did 代替 rose sharply，把两句合成一句。原句：Coffee sales rose sharply in the 2010s. Sales of bottled water rose sharply too.","sentence":"Coffee sales rose sharply in the 2010s, ___ sales of bottled water.","acceptableAnswers":["as did","and so did","and so too did"],"explanation":"as did sales of bottled water = 瓶装水销量也一样大涨。did 代替 rose sharply，放到主语前面；也可以写 and so did …。","subSkill":"as_as_constructions_with_inversion"}],"4":[{"id":"gen-10-4-100","type":"error","instruction":"〔写作 Task 1 · 考生常见错误〕点出用错的部分。","words":["In 2020,","the average price","of a flat","in Shenzhen","was","very higher","than that","in Chengdu."],"errorIndex":5,"correction":"much higher","explanation":"very 不能修饰比较级 → much / far higher。than that in Chengdu 没错：that 指 the average price。","subSkill":"degree_adverbs_with_adjectives_and_nouns"},{"id":"gen-10-4-101","type":"error","instruction":"〔写作 Task 1 · 考生常见错误〕点出用错的部分。","words":["In 2015,","the unemployment rate","in the north","was","more than twice","as high as","the south."],"errorIndex":6,"correction":"that in the south.","explanation":"比的是失业率和失业率 → as high as that in the south（也可以 as in the south）。as high as the south 是拿失业率和地区比。","subSkill":"comparative_clauses_with_ellipsis"},{"id":"gen-10-4-102","type":"fill","instruction":"〔写作 Task 2 · 考生常见错误〕有一处写错了，在空里写出正确的说法。原句：The faster a city grows, more expensive housing becomes.","sentence":"The faster a city grows, ___ housing becomes.","acceptableAnswers":["the more expensive","the dearer","the costlier","the less affordable","the pricier","the more costly","the more unaffordable"],"explanation":"后半句也要有 the：the more expensive housing becomes。少了 the，就不是「越…越…」的句子了。","subSkill":"double_comparatives_the_more_the_more"},{"id":"gen-10-4-103","type":"fill","instruction":"〔写作 Task 1 · 考生常见错误〕想说「年纪越大越可能去投票」。有一处写错了，在空里写出正确的说法。原句：The older the respondents were, the more they were likely to vote in elections.","sentence":"The older the respondents were, ___ to vote in elections.","acceptableAnswers":["the more likely they were","the likelier they were"],"explanation":"越可能 → the more likely 连在一起，后面才是 they were：the more likely they were to vote。拆开写，句子就不通了。","subSkill":"double_comparatives_the_more_the_more"},{"id":"gen-10-4-104","type":"error","instruction":"〔口语 Part 2 · 考生常见错误〕点出用错的部分。","words":["It was","the most","exciting match","I have","never","watched","in my life."],"errorIndex":4,"correction":"ever","explanation":"看过的比赛里最精彩的 → the most exciting match I have ever watched。never 是「从来没有」，和最高级放在一起意思就反了。","subSkill":"superlatives_with_present_perfect"},{"id":"gen-10-4-105","type":"choice","instruction":"〔写作 Task 1 · 考生常见写法〕原句：In 2019, the island had twice as many tourists than in 2009. 选出改对的写法。","options":["twice as much tourists as","twice as many tourists as","twice more tourists as","as twice many tourists as"],"correctIndex":1,"explanation":"as … as 要成对：twice as many … as，不能 as … than。tourists 可数，用 many；倍数放在第一个 as 前面。","subSkill":"as_as_constructions_with_inversion","sentence":"In 2019, the island had ___ in 2009."},{"id":"gen-10-4-106","type":"fill","instruction":"〔写作 Task 1 · 考生常见错误〕有一处写错了，在空里写出正确的说法。原句：In 2020, there were much more female students than male students in the department.","sentence":"In 2020, there were ___ female students than male students in the department.","acceptableAnswers":["many more","far more","a lot more","considerably more","significantly more","substantially more","a great many more","a good many more","lots more","more","vastly more","markedly more","dramatically more","noticeably more"],"explanation":"students 可数 → many more / far more（多得多）。much more + 名词时只配不可数名词，比如 much more money。","subSkill":"degree_adverbs_with_adjectives_and_nouns"},{"id":"gen-10-4-107","type":"error","instruction":"〔写作 Task 1 · 考生常见错误〕点出用错的部分。","words":["One of","the most popular","destination","for Chinese tourists","in 2019","was","Thailand."],"errorIndex":2,"correction":"destinations","explanation":"one of the + 最高级 后面是复数名词：one of the most popular destinations（最受欢迎的几个之一）。","subSkill":"superlatives_in_data_description"},{"id":"gen-10-4-108","type":"choice","instruction":"〔口语 Part 1 · 考生常见写法〕原句：My hometown is as same as it was ten years ago. 选出改对的句子。","options":["My hometown is the same as it was ten years ago.","My hometown is same as it was ten years ago.","My hometown is as same as ten years ago.","My hometown is the same than it was ten years ago."],"correctIndex":0,"explanation":"「和…一样」→ the same as，the 不能少，也不说 as same as。same 后面接 as，不接 than。","subSkill":"as_as_constructions_with_inversion"},{"id":"gen-10-4-109","type":"error","instruction":"〔写作 Task 1 · 考生常见错误〕点出用错的部分。","words":["Japanese households","ate","far more fish","than","households in the UK","were","in 2018."],"errorIndex":5,"correction":"did","explanation":"前面的动词是 ate → 用 did 代替：than households in the UK did（也可以不写 did）。were 只能代替 be 动词。","subSkill":"comparative_clauses_with_ellipsis"}],"5":[{"id":"gen-10-5-100","type":"fill","instruction":"〔写作 Task 1〕补全这段描述：第一空说「遥遥领先、最大」，第二空说「低得多」，第三空想想比的是什么，第四空说「差得远」。","sentence":"In 2020, Norway generated ___ share of its electricity from renewables (98%).\nSweden's figure was ___ lower, at 67%.\nGermany's share, at 45%, was less than half ___ of Norway, and Poland's 17% was ___ as high as Germany's.","acceptableAnswers":["by far the largest","considerably","that","nowhere near"],"blankAnswers":[["by far the largest","by far the highest","by far the biggest","by far the greatest","easily the largest","easily the highest","easily the biggest","far and away the largest","far and away the highest","far and away the biggest","much the largest"],["considerably","much","far","significantly","substantially","a lot","markedly","a great deal","a good deal","dramatically"],["that","the share","of that","the figure"],["nowhere near","not nearly","nothing like","not anywhere near","less than half","not even half","under half","well under half","just over a third","only about a third","about a third","roughly a third","around a third","little more than a third","only just over a third","not half"]],"explanation":"① by far the largest：98% 遥遥领先。② much lower：98% 对 67%。③ that：比例和比例比。④ nowhere near：17% 对 45%。","subSkill":"degree_adverbs_with_adjectives_and_nouns"},{"id":"gen-10-5-101","type":"fill","instruction":"〔写作 Task 1〕用倍数把三句改成一句，说得更精确。原句：In 2012, 20% of households had a tablet. In 2022, the figure was 60%. It increased a lot.","sentence":"By 2022, the proportion of households with a tablet was ___ it had been in 2012.","acceptableAnswers":["three times as high as","three times what","triple what","treble what","three times as large as","three times as great as","three times as big as","three times higher than","three times larger than","three times greater than"],"explanation":"60% 是 20% 的三倍 → three times as high as（或 three times what）it had been。比 increased a lot 精确得多。","subSkill":"as_as_constructions_with_inversion"},{"id":"gen-10-5-102","type":"fill","instruction":"〔写作 Task 2〕不用 if，把这句改得更紧凑。原句：If a city has more green space, its residents are usually happier.","sentence":"___ green space a city has, ___ its residents usually are.","acceptableAnswers":["The more","the happier"],"blankAnswers":[["The more"],["the happier","the more content","the more satisfied","the more contented"]],"explanation":"绿地越多，居民越快乐 → The more green space …, the happier …。前半句 the more + 名词，后半句 the + 比较级，两个 the 都要有。","subSkill":"double_comparatives_the_more_the_more"},{"id":"gen-10-5-103","type":"scenario","instruction":"〔口语 Part 2〕考生想说「这是我读过的最好的几本书之一，比电影精彩得多」。哪句把意思说准确了？","context":"雅思口语 Part 2 · 题卡：Describe a book you have enjoyed reading","dialogue":[],"options":["It's the best book I've ever read, and far more gripping than the film.","It's one of the best book I've ever read, and far more gripping than the film.","It's one of the best books I've ever read, and far more gripping than the film.","It's one of the best books I've ever read, though the film is almost as gripping."],"correctIndex":2,"explanation":"第 3 个准确：one of the best books =「之一」，要用复数；far more = 精彩得多。the best book 是唯一最好；almost as 是电影差不多一样好。","subSkill":"superlatives_with_present_perfect"},{"id":"gen-10-5-104","type":"fill","instruction":"〔写作 Task 1〕这句有两处不准确，改对。原句：Average salaries in Zurich were very higher than Paris.","sentence":"Average salaries in Zurich were ___ than ___ in Paris.","acceptableAnswers":["much higher","those"],"blankAnswers":[["much higher","far higher","considerably higher","significantly higher","substantially higher","a lot higher","markedly higher","a great deal higher","dramatically higher","vastly higher","higher","a good deal higher","very much higher","noticeably higher"],["those","salaries","average salaries","the salaries","the average salaries"]],"explanation":"① very 不能修饰比较级 → much / far higher。② 比的是工资和工资，salaries 是复数 → than those in Paris。","subSkill":"comparative_clauses_with_ellipsis"},{"id":"gen-10-5-105","type":"fill","instruction":"〔写作 Task 1〕补全这段电子书销量的描述：第一空接在 a fifth 后面，第二空说「越…越多」，第三空说「差一点就一样高」。","sentence":"In 2010, e-book sales were only a fifth ___ print sales. The cheaper e-readers became, ___ e-books people bought, and by 2020 e-book sales were ___ as print sales.","acceptableAnswers":["as high as","the more","almost as high"],"blankAnswers":[["as high as","of","as large as","as great as","as big as","the size of","the level of","the value of"],["the more"],["almost as high","nearly as high","almost as large","nearly as large","almost as great","nearly as great","almost as big","nearly as big","not quite as high","not quite as large","almost the same","nearly the same","very nearly as high","virtually as high","practically as high","not quite as great","not quite as big"]],"explanation":"① a fifth as high as（或 a fifth of）= 五分之一。② 越便宜买得越多 → the more。③ 差一点就一样 → almost as high。","subSkill":"as_as_constructions_with_inversion"},{"id":"gen-10-5-106","type":"fill","instruction":"〔口语 Part 3〕考官：Are people today healthier than in the past? 补全考生的回答，每空填一个词。","sentence":"In some ways, yes. We live much longer than our grandparents ___, but we're nowhere near as active as they ___ at our age.","acceptableAnswers":["did","were"],"blankAnswers":[["did","lived"],["were"]],"explanation":"第一空代替 lived → did；第二空代替 were active → were。助动词要跟前面的动词对上：live → did，be active → were。","subSkill":"comparative_clauses_with_ellipsis"},{"id":"gen-10-5-107","type":"fill","instruction":"〔口语 Part 2 · 结束追问〕考官：Would you like to go back there? 补全回答：那是我去过最热闹的城市，吃的也比想象的好得多。","sentence":"Definitely. It's ___ city I've ___ been to, and the food was ___ better than I'd expected.","acceptableAnswers":["the liveliest","ever","much"],"blankAnswers":[["the liveliest","the most lively","the busiest","the most vibrant","the most bustling","the most energetic"],["ever"],["much","far","a lot","way","so much","considerably","a great deal","a good deal","significantly","a whole lot","miles","loads"]],"explanation":"① the liveliest（或 the most lively）。② 去过的里面最… → I've ever been to。③ 好得多 → much / far better，不用 very。","subSkill":"superlatives_with_present_perfect"},{"id":"gen-10-5-108","type":"fill","instruction":"〔写作 Task 1〕说出 Canada 的排名：第二，仅次于俄罗斯。原句：Among the five countries in the chart, Canada exported more wheat than all the others except Russia.","sentence":"Canada was ___ wheat exporter, after Russia.","acceptableAnswers":["the second largest","the second-largest","the second biggest","the second-biggest","the second greatest"],"explanation":"排第二 → the second largest + 名词（the second + 最高级）。不说 the second large，也不说 the most second。","subSkill":"superlatives_in_data_description"},{"id":"gen-10-5-109","type":"fill","instruction":"〔写作 Task 1〕把「高得多」说得更精确：高了几倍？原句：In 2017, Spain's unemployment rate (16%) was much higher than Germany's (4%).","sentence":"In 2017, Spain's unemployment rate was ___ Germany.","acceptableAnswers":["four times that of","four times as high as that of","four times that in","four times as high as that in","four times as high as in","four times the rate in","four times the rate of","four times higher than that of","four times higher than that in","four times higher than in","quadruple that of","quadruple that in","4 times that of","4 times as high as that of","4 times as high as in"],"explanation":"16% 是 4% 的四倍 → four times that of Germany（或 four times as high as that of）。失业率和失业率比，要有 that。","subSkill":"comparative_clauses_with_ellipsis"}]},"mission":{"title":"写作 Task 1：五个国家的人均用水量","description":"写一段雅思 Task 1 的总览和正文（3 句）：先写总体情况，再拿用水最多的国家和别国比，最后写其余几个国家（写法自选）。每写一个比较，先问自己：差得多还是差一点？比的是不是同一类东西？至少用对本单元的 2 种写法。AI 老师会按雅思「语法多样性与准确性」给你反馈。","scenario":"题目：The chart below shows the average amount of water used per person per day in five countries in 2020. Summarise the information by selecting and reporting the main features, and make comparisons where relevant.<br>图表信息（升 / 人 / 天）：美国 370，加拿大 250，英国 145，西班牙 135，印度 85。<br>你只写总览和正文的 3 句。","grammarType":"degree_adverbs_with_adjectives_and_nouns","scaffolds":[{"prefix":"The chart compares how much water people in five countries used each day in 2020.","suffix":"","hint":"写总览：哪个国家遥遥领先？哪个最少？可以用 by far the most …，也可以用 the + 最高级。","grammarCheck":"degree_adverbs_with_adjectives_and_nouns","example":"Overall, people in the USA used by far the most water, while those in India used the least."},{"prefix":"Looking at the details, Americans used around 370 litres per person per day.","suffix":"","hint":"拿美国和加拿大、英国比：差多少？much / far + 比较级，或 twice as high as；记得 that of。","grammarCheck":"as_as_constructions_with_inversion","example":"This was considerably higher than the figure for Canada (250 litres) and more than twice as high as that of the UK (145 litres)."},{"prefix":"The other three countries used much less water.","suffix":"","hint":"结构自选：写英国、西班牙和印度。可以用 slightly / only a little + 比较级，nowhere near as … as，也可以写两个短句。","grammarCheck":"comparative_clauses_with_ellipsis","example":"The UK's figure was only slightly higher than Spain's, while people in India used just 85 litres, considerably less than in any other country and nowhere near as much as in the USA."}]},"discover":{"story":{"title":"写作 Task 1 范文节选：哪个年龄段最爱运动？","text":"读的时候想一想：哪个年龄段的人运动最少？15 年里哪一组变化最大？蓝色的句子下面会逐句问你。\nTask 1: The chart below shows the percentage of adults in four age groups in Australia who exercised regularly in 2005 and 2020. Summarise the information by selecting and reporting the main features, and make comparisons where relevant.\nThe chart compares the proportion of Australian adults in four age groups who exercised regularly in 2005 and 2020. Overall, the older people were, the less likely they were to exercise, although the gap between young and old narrowed over the period.\nIn 2005, 18–29-year-olds were by far the most active group: almost 70% of them exercised regularly, compared with fewer than one in five people aged 65 and over, a gap of more than 50 percentage points. The figure for the 45–64 group, at 35%, was considerably lower than that of the 30–44 group (46%).\nBy 2020, the picture had changed, mainly because older adults had become far more active than before. People aged 45–64 had also become more active, and their figure was now only slightly lower than that of 30–44-year-olds. The proportion of over-65s who exercised regularly had risen to 36%, twice as high as in 2005. Even so, the over-65s were still nowhere near as active as the youngest adults, whose figure stayed at around 70% throughout the period.","highlights":["the older people were","the less likely they were to exercise","by far the most active group","considerably lower than that of the 30–44 group","twice as high as in 2005","nowhere near as active as"]},"questions":[{"question":"第一段：<em>Overall, the older people were, the less likely they were to exercise…</em><br>In general, which age group exercised the least?","options":["The youngest group","The oldest group","The 30–44 group"],"correctIndex":1,"nudge":"older 和 less likely 是一起变的：年纪往上走，运动的可能往哪走？","explanation":"最年长的那组：年纪越大，越不可能经常运动。<br><strong>规则 ①</strong>：the + 比较级 …, the + 比较级 … = 越…越…：一个变，另一个跟着变。两半句都要有 the。","subSkill":"double_comparatives_the_more_the_more"},{"question":"第二段：<em>In 2005, 18–29-year-olds were by far the most active group…</em><br>How did this group compare with the other three?","options":["Much more active than any of them","Slightly more active than the 30–44s","About as active as the 30–44s"],"correctIndex":0,"nudge":"by far 是在强调差距大，还是差距小？对照同一句后面的数字：almost 70%。第二名 30–44 岁组是多少？","explanation":"高得多：将近 70%，第二名只有 46%。<br><strong>规则 ②</strong>：差得多 → by far + 最高级，或 much / far + 比较级；差一点 → slightly。比较级前不用 very。","subSkill":"degree_adverbs_with_adjectives_and_nouns"},{"question":"第二段：<em>The figure for the 45–64 group, at 35%, was considerably lower than that of the 30–44 group (46%).</em><br>What does <em>that</em> stand for here?","options":["The 45–64 age group","Regular exercise in general","The percentage"],"correctIndex":2,"nudge":"把 that 换成每个选项读一读：…lower than the ___ of the 30–44 group。哪个读得通？","explanation":"that = the figure，35% 和 46% 比。<br><strong>规则 ③</strong>：同类相比：than that of / that in Y（复数 those），或 than Y's；不写 than Y。","subSkill":"comparative_clauses_with_ellipsis"},{"question":"第三段：<em>The proportion of over-65s who exercised regularly had risen to 36%, twice as high as in 2005.</em><br>Roughly what was this group's figure in 2005?","options":["About 18%","About 34%","About 72%"],"correctIndex":0,"nudge":"twice as high as in 2005：2020 年的 36% 是 2005 年的几倍？第二段也有线索：fewer than one in five。","explanation":"约 18%：2020 年的 36% 是它的两倍。<br><strong>规则 ④</strong>：倍数 → twice / three times / half + as + 原级 + as …；和哪一年比，就写 as in 2005。","subSkill":"as_as_constructions_with_inversion"},{"question":"第三段：<em>Even so, the over-65s were still nowhere near as active as the youngest adults…</em><br>By 2020, had the over-65s caught up with the youngest group?","options":["Yes, they were just as active.","Almost: the gap was very small.","No, they were still far behind."],"correctIndex":2,"nudge":"nowhere near 是「很接近」还是「差得远」？对照数字：36% 和将近 70%。","explanation":"没有，还差得远：36% 对将近 70%。<br><strong>规则 ⑤</strong>：nowhere near as … as = 远远不如；almost as … as = 差一点就一样；just as … as = 一样。","subSkill":"as_as_constructions_with_inversion"},{"question":"你来试试：想写「2020 年，女性经常运动的比例只比男性略低一点」。<br>Which sentence is correct?","options":["In 2020, the figure for women was slightly lower than men.","In 2020, the figure for women was slightly lower than that of men.","In 2020, the figure for women was considerably lower than that of men."],"correctIndex":1,"nudge":"先想两件事：差得多还是差一点？女性的比例在和什么比？用规则 ② 和 ③。","explanation":"差一点 → slightly（规则 ②）；比例和比例比 → than that of men（规则 ③）。than men 是拿比例和人比；considerably 是差得多，和「略低」不符。","subSkill":"comparative_clauses_with_ellipsis"}],"tip":"【比较：先想差多少，再想谁和谁比】\n\n① the + 比较级 …, the + 比较级 … = 越…越…，两个 the 都要有\n② 差得多：much / far / considerably + 比较级，by far + 最高级；差一点：slightly；不用 very\n③ 同类相比：X 的数字比 Y 的数字 → than that of / that in Y（复数 those），或 than in Y、than Y's；不写 than Y\n④ 倍数：twice / three times / half + as + 原级 + as\n⑤ nowhere near as … as = 远远不如；almost as … as = 差一点就一样\n⑥ 可数复数：many more / far fewer；不可数：much more / far less\n⑦ 最高级：the best … I have ever …；the second largest；one of the + 最高级 + 复数\nthan / as 后面不重复动词，用助动词或 be：than men did，than it was in 2005；更正式：…, as did house prices。\n\n【例句】\n✔ The older people were, the less likely they were to exercise.\n✔ The figure for the 45–64 group was considerably lower than that of the 30–44 group.\n\n【常见错误】\n✘ Prices were very higher than in 2010. → much / far higher（见 ②）\n✘ The rate in Spain was higher than Italy. → than that in Italy / than in Italy / than Italy's（见 ③）\n✘ The richer a country is, more energy it uses. → the more energy（见 ①）\n✘ It was the best trip I have never had. → ever（见 ⑦）"}},"11":{"levels":{"1":[{"id":"gen-11-1-100","type":"choice","instruction":"〔写作 Task 2〕大多数读者选的是电子书吗？原句：Although e-books are much cheaper, most readers still prefer printed books.","sentence":"Do most readers choose e-books?","options":["Yes, because they are cheaper.","No, most of them still don't.","Yes, but only the cheaper ones.","No, because e-books cost more."],"correctIndex":1,"explanation":"Although 先承认「电子书便宜得多」，主句说出没想到的结果：大多数读者还是选纸质书。still 加强了这种「出乎意料」。","subSkill":"concession_clauses_although_while_whereas"},{"id":"gen-11-1-101","type":"choice","instruction":"〔写作 Task 2〕现在上大学是免费的吗？原句：Even if university were free, many rural students would still struggle with the cost of living in a big city.","sentence":"Is university free at the moment?","options":["Yes, it has been free for years.","Only for students from rural areas.","No, the writer is imagining it.","Yes, but only in big cities."],"correctIndex":2,"explanation":"Even if + were =「就算…」，是假设：大学现在并不免费。说事实要用 even though：Even though university is free, …（大学真的免费）。","subSkill":"concession_clauses_although_while_whereas"},{"id":"gen-11-1-102","type":"choice","instruction":"〔写作 Task 2〕哪类人主要用社交媒体看新闻？原句：Whereas young people mainly use social media for entertainment, older users tend to rely on it for news.","sentence":"Which group mainly uses social media to follow the news?","options":["Older users","Young people","Both groups equally","Neither group"],"correctIndex":0,"explanation":"whereas 把两类人并排对比：年轻人主要用来娱乐，而年长用户主要看新闻。这里没有「出乎意料」的意思，只是 A 这样、B 那样。","subSkill":"concession_clauses_although_while_whereas"},{"id":"gen-11-1-103","type":"choice","instruction":"〔写作 Task 2〕博物馆为什么只好限制参观人数？原句：After the museum stopped charging for entry, it became so crowded that it had to limit visitor numbers.","sentence":"Why did the museum have to limit visitor numbers?","options":["It wanted to charge for entry again.","Too few people came after it became free.","It could not afford to stay open.","Too many people came once entry was free."],"correctIndex":3,"explanation":"so crowded that … = 拥挤到…的程度：免费以后人太多，所以只好限流。that 后面是前面那件事的结果。","subSkill":"result_clauses_such_that_so_that"},{"id":"gen-11-1-104","type":"choice","instruction":"〔写作 Task 2〕作者认为，很多家庭不在家做饭，主要是因为什么？原句：It is not the price of fresh food but the lack of time that stops many families from cooking at home.","sentence":"According to the writer, what mainly stops families from cooking?","options":["The high price of fresh food","Not having enough time","Not knowing how to cook","Both price and time equally"],"correctIndex":1,"explanation":"It is not A but B that … 强调 B：真正让人不做饭的是没时间，不是菜价。It is … that 把重点单独拎出来，相当于「正是…」。","subSkill":"cleft_sentences_for_emphasis_it_is_what"},{"id":"gen-11-1-105","type":"scenario","instruction":"考生认为，很多人不去做志愿者，主要是因为什么？","context":"雅思口语 Part 3 · Volunteering","dialogue":[{"speaker":"examiner","text":"Examiner: Why don't more people do volunteer work?"},{"speaker":"player","text":"I don't think it's a lack of interest, really. What stops most people is that they don't know how to get started."}],"options":["They aren't interested in helping.","They are too busy with their jobs.","They don't know how to start.","It would cost them too much money."],"correctIndex":2,"explanation":"What stops most people is that … = 让大多数人没去做的原因是…：重点在 is 后面：不知道怎么开始。前一句已经排除了「没兴趣」。","subSkill":"cleft_sentences_for_emphasis_it_is_what"},{"id":"gen-11-1-106","type":"choice","instruction":"〔写作 Task 2〕作者觉得在家办公全是好处吗？原句：Working from home saves employees hours of commuting. Having said that, many of them miss the social side of office life.","sentence":"Does the writer think working from home is entirely positive?","options":["No, there is a downside too.","Yes, it has no real drawbacks.","No, it wastes employees' time.","Yes, employees prefer it."],"correctIndex":0,"explanation":"Having said that = 话虽如此：先肯定前一句（省通勤时间），再引出另一面（想念同事）。放在句首，把两句自然连起来。","subSkill":"fronted_adverbial_clauses_for_cohesion"},{"id":"gen-11-1-107","type":"choice","instruction":"〔写作 Task 2〕作者怎么看电子游戏？原句：There is little evidence that video games make children violent. On the contrary, some studies suggest that they can improve problem-solving skills.","sentence":"What is the writer's view of video games?","options":["They usually make children violent.","They are harmful but sometimes useful.","They have no effect on children.","They may actually help children."],"correctIndex":3,"explanation":"On the contrary = 恰恰相反：先否定「游戏让孩子暴力」，再说相反的情况：游戏可能还有好处。它不是用来对比两类人的。","subSkill":"fronted_adverbial_clauses_for_cohesion"},{"id":"gen-11-1-108","type":"match","instruction":"〔口语 Part 2〕每句里，课程到底免不免费？连线。","left":["Even though the course was free, few of my colleagues signed up.","Even if the course had been free, few of my colleagues would have signed up."],"right":["The course was free.","The course was not free."],"correctPairs":[[0,0],[1,1]],"explanation":"even though + 事实：课程真的免费，可还是没几个人报名。even if + had been 是假设：其实不免费，就算免费也没几个人会报。","subSkill":"concession_clauses_although_while_whereas"}],"2":[{"id":"gen-11-2-110","type":"choice","instruction":"〔写作 Task 2〕想说后一句是前一句带来的结果：网购发展很快，很多小店只好关门。","sentence":"Online shopping has grown rapidly in recent years. ___ many small shops on the high street have been forced to close.","options":["Even so,","In other words,","On the contrary,","As a result,"],"correctIndex":3,"explanation":"后一句是前一句的结果 → As a result,（= Consequently,）。Even so 是「尽管如此」；In other words 是换个说法；On the contrary 只用来否定前面的说法。","subSkill":"fronted_adverbial_clauses_for_cohesion"},{"id":"gen-11-2-101","type":"choice","instruction":"〔写作 Task 2〕想说「尽管工作时间长，很多毕业生还是想进大型科技公司」。","sentence":"___ the long working hours, many graduates are keen to work for large technology companies.","options":["Although","Despite of","Whereas","Despite"],"correctIndex":3,"explanation":"后面是名词短语（the long working hours），没有动词 → Despite（= In spite of）。Despite 后面不加 of；Although 后面要接完整的句子；Whereas 是并排对比两件事。","subSkill":"concession_clauses_although_while_whereas"},{"id":"gen-11-2-102","type":"choice","instruction":"〔写作 Task 1〕想把两项开支的变化并排对比：住房开支涨了，食品开支略降。","sentence":"Between 2010 and 2020, household spending on housing rose by 20%, ___ spending on food fell slightly.","options":["on the contrary","therefore","despite","whereas"],"correctIndex":3,"explanation":"两组数据并排对比 → whereas（= while）。on the contrary 用来否定前面的说法，也不能这样连两个分句；therefore 表示结果；despite 后面不接句子。","subSkill":"concession_clauses_although_while_whereas"},{"id":"gen-11-2-103","type":"choice","instruction":"〔写作 Task 2〕想说「塑料污染已经严重到政府没法再忽视」。","sentence":"Plastic pollution has become ___ serious problem that governments can no longer ignore it.","options":["so","such a","a so","a such"],"correctIndex":1,"explanation":"后面是「形容词 + 可数名词单数」（serious problem）→ such a，a 放在 such 后面。so 后面直接接形容词（so serious that…）；a so、a such 是常见的错误语序。","subSkill":"result_clauses_such_that_so_that"},{"id":"gen-11-2-104","type":"choice","instruction":"〔写作 Task 2〕想说「有些学校附近快餐店多到学生几乎天天吃垃圾食品」。","sentence":"There are ___ fast-food outlets near some schools that pupils eat junk food almost every day.","options":["such many","too many","so many","such a lot"],"correctIndex":2,"explanation":"many / much / few / little 前面用 so：so many outlets that…。such many 不存在；too many 后面不接 that 从句；such a lot 后面少了 of。","subSkill":"result_clauses_such_that_so_that"},{"id":"gen-11-2-105","type":"choice","instruction":"〔写作 Task 2〕想说「体育中心晚上应该开得晚一些，目的是让白天上班的人也能去」。","sentence":"Sports centres should stay open later in the evenings ___ people who work during the day can use them.","options":["so that","in order to","so as","therefore"],"correctIndex":0,"explanation":"说目的 → so that + 从句（常和 can 连用）。in order to 后面接动词原形，so as 还缺 to，都不能接从句；therefore 表示结果，不能这样连两句。","subSkill":"result_clauses_such_that_so_that"},{"id":"gen-11-2-106","type":"match","instruction":"〔写作 Task 2〕四句的意思都是「学费高，课程还是满员」。每个空该填哪个词？连线。","left":["___ the high fees, the course is always full.","___ the fees are high, the course is always full.","The fees are high. ___, the course is always full.","___ being expensive, the course is always full."],"right":["Despite","Although","However"],"correctPairs":[[0,0],[1,1],[2,2],[3,0]],"explanation":"名词或 -ing 前 → Despite；完整的句子前 → Although；另起一句、后面带逗号 → However。三个词意思相近，用法不一样。","subSkill":"concession_clauses_although_while_whereas"},{"id":"gen-11-2-107","type":"choice","instruction":"〔写作 Task 2〕想强调「解决这个问题的关键在父母，不在学校」。选出意思准确的一句。","options":["It is not parents but schools that hold the key to solving this problem.","It is parents, not schools, that hold the key to solving this problem.","Parents and schools both hold the key to solving this problem.","What holds the key to solving this problem is schools, not parents."],"correctIndex":1,"explanation":"关键在父母 → It is parents, not schools, that …。第 1、4 句把重点放在了学校，意思反了；第 3 句说两者都是，没有强调。","subSkill":"cleft_sentences_for_emphasis_it_is_what"},{"id":"gen-11-2-108","type":"choice","instruction":"〔口语 Part 3〕想强调「老人最需要的是有人陪，不是更多的药」。","options":["What do older people need most is company, not more medicine.","The thing what older people need most is company, not more medicine.","What older people need most is company, not more medicine.","Older people need most is company, not more medicine."],"correctIndex":2,"explanation":"What older people need most（老人最需要的东西）当主语，重点放在 is 后面。What 从句里是陈述语序，不加 do；也不说 the thing what。","subSkill":"cleft_sentences_for_emphasis_it_is_what"},{"id":"gen-11-2-109","type":"scenario","instruction":"〔口语 Part 3〕考生想说「主要原因是这类工作很稳定」。哪句准确？","context":"雅思口语 Part 3 · Jobs","dialogue":[{"speaker":"examiner","text":"Examiner: Why do so many young people in your country want to work for the government?"}],"options":["The main reason is because of these jobs are very secure.","The main reason is that these jobs are very secure.","Because these jobs are very secure is the main reason.","The main reason is what these jobs are very secure."],"correctIndex":1,"explanation":"The reason is + that + 完整的句子。because of 后面只接名词；because 从句一般不当主语；后面是完整的句子，用 that，不用 what。","subSkill":"noun_clauses_as_subject_and_complement"}],"3":[{"id":"gen-11-3-100","type":"fill","instruction":"〔写作 Task 2〕用一个介词短语开头，把两句合成一句。原句：Tourism brings in a lot of money. However, it can damage local culture.","sentence":"___ the money it brings in, tourism can damage local culture.","acceptableAnswers":["Despite","In spite of","For all","Despite all","In spite of all","Notwithstanding","Regardless of","Even with","With all"],"explanation":"the money it brings in 是名词短语 → Despite / In spite of（For all 也很地道），Despite 后面不加 of。用 Although 就要接完整的句子：Although it brings in a lot of money, …","subSkill":"concession_clauses_although_while_whereas"},{"id":"gen-11-3-101","type":"fill","instruction":"〔写作 Task 2〕用 Despite 改写，意思不变。原句：Although the factory paid low wages, it never had trouble finding workers.","sentence":"Despite ___ low wages, the factory never had trouble finding workers.","acceptableAnswers":["paying","its","the","offering","having paid","having offered","paying such","paying very","its very","its relatively","the relatively","paying relatively","offering relatively","offering only","paying only","offering such","offering very","offering extremely","paying extremely","its extremely","the very","the extremely"],"explanation":"Despite 后面不能接 the factory paid 这样的句子，要换成 -ing（paying）或名词短语（its low wages）。主语都是工厂，所以用 paying 不会有歧义。","subSkill":"concession_clauses_although_while_whereas"},{"id":"gen-11-3-102","type":"fill","instruction":"〔写作 Task 2〕用 such 改写，意思不变。原句：The flood damage was so severe that the town took ten years to recover.","sentence":"The flood caused ___ damage that the town took ten years to recover.","acceptableAnswers":["such severe","such serious","such extensive","such terrible","such heavy","such great","such widespread","such enormous","such massive","such huge","such significant","such devastating","such major","such catastrophic","such considerable","such substantial","such","such a lot of","so much","such a great deal of","such extreme","such immense","such tremendous","such vast"],"explanation":"damage 不可数，前面不加 a：such severe damage that…。such a severe damage 是常见错误；so 后面接形容词（so severe），不能直接接名词。","subSkill":"result_clauses_such_that_so_that"},{"id":"gen-11-3-103","type":"reorder","instruction":"〔写作 Task 2〕排出这句：这个应用传得太快，学校只好出台新规定。","words":["introduce","so","The","schools","that","rules.","quickly","app","to","spread","had","new"],"correctSentence":"The app spread so quickly that schools had to introduce new rules.","explanation":"so + 副词（quickly）+ that + 结果：传得太快 → 学校出台规定。quickly 修饰动词 spread，所以用 so，不用 such。spread quickly, so that … 也对，但 so quickly that 更能说出「太快」。","subSkill":"result_clauses_such_that_so_that","acceptableSentences":["The app spread quickly so that schools had to introduce new rules."]},{"id":"gen-11-3-104","type":"fill","instruction":"〔写作 Task 2〕改写这句，突出「经常锻炼」，而不是昂贵的饮食。原句：Regular exercise, not an expensive diet, makes the biggest difference to health.","sentence":"___ regular exercise, not an expensive diet, ___ makes the biggest difference to health.","acceptableAnswers":["It is","that"],"blankAnswers":[["It is","It's"],["that","which"]],"explanation":"It is + 要强调的部分 + that + 其余部分 =「正是…」。动词仍和 regular exercise 一致，用 makes。不要漏掉 that。","subSkill":"cleft_sentences_for_emphasis_it_is_what"},{"id":"gen-11-3-105","type":"fill","instruction":"〔写作 Task 2〕改写这句，把重点 confidence 放到句末。原句：Many students lack confidence, not ability.","sentence":"___ many students lack ___ confidence, not ability.","acceptableAnswers":["What","is"],"blankAnswers":[["What","All","All that","The thing","The thing that","The one thing","The one thing that","The only thing","The only thing that"],["is"]],"explanation":"What many students lack（学生缺的东西）当主语，用单数 is，重点 confidence 放到句末。What 从句里是陈述语序，不写 What do many students lack。","subSkill":"cleft_sentences_for_emphasis_it_is_what"},{"id":"gen-11-3-106","type":"fill","instruction":"〔口语 Part 3〕把问题变成句子的一部分。原句：How can we encourage people to recycle more? That is the real question.","sentence":"The real question is ___ encourage people to recycle more.","acceptableAnswers":["how we can","how to","how we could","how we might","how we should","how we can best","how best to","how governments can","how the government can","how society can","how cities can","how councils can","how we are going to","how we","how you can","how you","how we're going to","how governments should","how the government should","how society should","how best we can","how governments could","how the government could"],"explanation":"问句放进句子里当表语，用陈述语序：how we can …，不是 how can we …。也可以说 how to encourage …。","subSkill":"noun_clauses_as_subject_and_complement"},{"id":"gen-11-3-107","type":"fill","instruction":"〔写作 Task 2〕第二句是原因。把两句合成一句。原句：Many graduates leave their hometowns. They cannot find suitable jobs there.","sentence":"The main reason many graduates leave their hometowns ___ they cannot find suitable jobs there.","acceptableAnswers":["is that","is simply that","is mainly that","is mostly that","is probably that","is usually that","is often that","is just that","is","is the fact that","is largely that","is primarily that","is basically that"],"explanation":"The reason … is that + 完整的句子，that 从句作表语。写作里不写 is because：reason 已经是「原因」，再加 because 就重复了。","subSkill":"noun_clauses_as_subject_and_complement"},{"id":"gen-11-3-108","type":"fill","instruction":"〔写作 Task 2〕不用 But，换一个更正式的开头，把两句连起来。原句：Fast fashion is cheap and convenient. But it creates huge amounts of waste.","sentence":"Fast fashion is cheap and convenient. ___, it creates huge amounts of waste.","acceptableAnswers":["However","Nevertheless","Nonetheless","Even so","Despite this","In spite of this","Despite that","In spite of that","That said","Having said that","That being said","Yet","Still","On the other hand","At the same time","Unfortunately","Sadly","Regrettably","Despite these advantages","Despite these benefits","In spite of these advantages","In spite of these benefits","Despite this fact","All the same","Be that as it may","Notwithstanding this","For all that"],"explanation":"However / Nevertheless / Despite this 放在句首、后面加逗号，转折更正式。Despite this 的 this 指前一句「便宜方便」。","subSkill":"fronted_adverbial_clauses_for_cohesion"},{"id":"gen-11-3-109","type":"reorder","instruction":"〔写作 Task 2〕排出这句：直到 2015 年，这个国家才禁止在餐馆吸烟。","words":["the","smoking","It","until","in","that","was","banned","2015","restaurants.","not","country"],"correctSentence":"It was not until 2015 that the country banned smoking in restaurants.","explanation":"「直到…才」→ It was not until + 时间 + that + 句子。that 后面用正常语序（the country banned），不用倒装。","subSkill":"cleft_sentences_for_emphasis_it_is_what"}],"4":[{"id":"gen-11-4-100","type":"choice","instruction":"〔写作 Task 2 · 考生常见写法〕原句：Although nuclear power is clean, but many people are afraid of it. 选出改对的句子。","options":["Although nuclear power is clean, many people are afraid of it.","Despite nuclear power is clean, many people are afraid of it.","Even nuclear power is clean, many people are afraid of it.","Nuclear power is clean, however, many people are afraid of it."],"correctIndex":0,"explanation":"「虽然…但是」只用一个连接词：Although …, many people … 或 … is clean, but …。Despite 后面不接句子；Even 不能单独引出从句（要用 Even though）；however 不能用逗号连两句。","subSkill":"concession_clauses_although_while_whereas"},{"id":"gen-11-4-101","type":"fill","instruction":"〔写作 Task 2 · 考生常见错误〕有一处用错了，改对这句的开头。原句：Despite the government has spent billions on hospitals, waiting lists are still growing.","sentence":"___ billions on hospitals, waiting lists are still growing.","acceptableAnswers":["Although the government has spent","Even though the government has spent","Though the government has spent","While the government has spent","Whilst the government has spent","Although the government has been spending","Even though the government has been spending","Although the government spent","Even though the government spent","Although governments have spent","Even though governments have spent","Despite the government having spent","Despite the government spending","Despite the government's spending","In spite of the government having spent","In spite of the government spending","In spite of the government's spending","Despite the fact that the government has spent","In spite of the fact that the government has spent","Despite the government's having spent","Despite governments spending","Despite governments having spent","In spite of governments spending","In spite of governments having spent","Despite the fact the government has spent","Despite the fact that the government spent","In spite of the fact the government has spent","In spite of the fact that the government spent","Despite the fact that governments have spent","While governments have spent","Though governments have spent","Whilst governments have spent","While the government spent","Though the government spent","Whilst the government spent","Although the government is spending","Even though the government is spending","While the government is spending","Though the government is spending"],"explanation":"Despite 后面是名词或 -ing，不接「主语 + 动词」：改成 Although the government has spent …，或 Despite the government having spent …。","subSkill":"concession_clauses_although_while_whereas"},{"id":"gen-11-4-102","type":"choice","instruction":"〔写作 Task 2 · 考生常见写法〕原句：Many people think zoos are cruel, however, they help to protect endangered species. 标点有问题，选出正确的写法。","options":["; however,",", however,",", however",", although,"],"correctIndex":0,"explanation":"however 是副词，不能用逗号把两句连起来：前面用分号或句号，后面加逗号。although 是连词，后面不加逗号。","subSkill":"fronted_adverbial_clauses_for_cohesion","sentence":"Many people think zoos are cruel___ they help to protect endangered species."},{"id":"gen-11-4-103","type":"error","instruction":"〔口语 Part 3 · 考生常见错误〕点出用错的部分。","words":["For many parents,","choosing a secondary school","is","so a difficult decision","that","they","lose sleep","over it."],"errorIndex":3,"correction":"such a difficult decision","explanation":"decision 是名词，前面用 such a + 形容词：such a difficult decision that…。so 后面直接接形容词：so difficult that…。也可以说 so difficult a decision（更正式）。","subSkill":"result_clauses_such_that_so_that"},{"id":"gen-11-4-110","type":"choice","instruction":"〔写作 Task 2 · 考生常见写法〕原句：Local families are leaving the city centre. Because rents have risen sharply. 选出改对的写法。","options":["Because rents have risen sharply, so local families are leaving the city centre.","Because rents have risen sharply. Local families are leaving the city centre.","Local families are leaving the city centre because rents have risen sharply.","Local families are leaving the city centre, because of rents have risen sharply."],"correctIndex":2,"explanation":"because 引出的半句不能单独成句，要和主句连起来：…city centre because rents…，或放句首加逗号。because 和 so 只用一个；because of 后面只接名词。","subSkill":"fronted_adverbial_clauses_for_cohesion"},{"id":"gen-11-4-105","type":"fill","instruction":"〔写作 Task 2 · 考生常见错误〕有一处错，在空里改对。原句：Researchers are still trying to understand why do some people find it so hard to lose weight.","sentence":"Researchers are still trying to understand why ___ find it so hard to lose weight.","acceptableAnswers":["some people","certain people","some individuals"],"explanation":"问句放进句子里，要用陈述语序，也不加 do：why some people find …，不是 why do some people find …。","subSkill":"noun_clauses_as_subject_and_complement"},{"id":"gen-11-4-106","type":"choice","instruction":"〔写作 Task 2 · 考生常见写法〕这里只是对比两代人，原来的连接词用错了。原句：Older people tend to save their money. On the contrary, young people are more likely to spend theirs on travel.","sentence":"Older people tend to save their money. ___ young people are more likely to spend theirs on travel.","options":["Therefore,","In contrast,","Even so,","As a result,"],"correctIndex":1,"explanation":"对比两类人 → In contrast / By contrast（而…）。On the contrary 是「恰恰相反」，用来否定前一句说的话。Therefore、As a result 表示结果。","subSkill":"fronted_adverbial_clauses_for_cohesion"},{"id":"gen-11-4-107","type":"fill","instruction":"〔口语 Part 3 · 考生常见错误〕有一处漏了词，在空里补上。原句：In my view, it is big companies should pay for the pollution they cause.","sentence":"In my view, it is big companies ___ should pay for the pollution they cause.","acceptableAnswers":["that","who","which"],"explanation":"It is + 强调部分 + that/who + 其余部分：it is big companies that should …。漏了 that，句子就有两个谓语（is、should pay）。","subSkill":"cleft_sentences_for_emphasis_it_is_what"},{"id":"gen-11-4-108","type":"error","instruction":"〔写作 Task 2 · 考生常见错误〕点出用错的部分。","words":["It is no doubt","that","technology has changed","the way","we work."],"errorIndex":0,"correction":"There is no doubt","explanation":"「毫无疑问」是 There is no doubt that …，不说 It is no doubt。也可以写 Undoubtedly, … 或 Without doubt, …。","subSkill":"noun_clauses_as_subject_and_complement"},{"id":"gen-11-4-109","type":"error","instruction":"〔口语 Part 2 · 考生常见错误〕他其实每天晚上都复习了。点出用错的部分。","words":["I","still failed","the driving theory test,","even if","I","revised","every evening."],"errorIndex":3,"correction":"even though","explanation":"每天复习是真事 → even though（尽管）。even if 是「即使、就算」，用于假设或还不确定的情况。","subSkill":"concession_clauses_although_while_whereas"}],"5":[{"id":"gen-11-5-100","type":"fill","instruction":"〔写作 Task 2〕把两句合成一句：先承认对方的观点，再说自己的。原句：Some people say space exploration is a waste of money. But it has produced many useful inventions.","sentence":"___ space exploration costs a great deal, it has produced many useful inventions.","acceptableAnswers":["Although","While","Whilst","Though","Even though","Although it is true that","While it is true that","Whilst it is true that","Though it is true that","Although it may be true that","While it may be true that","Despite the fact that","In spite of the fact that","Although some people say","While some people say","Although some people say that","While some people say that","Although some argue that","While some argue that","Although critics say","While critics say","Even if","Although some people argue that","While some people argue that","Although some people argue","While some people argue","Although some argue","While some argue","Although critics argue that","While critics argue that","Although critics argue","While critics argue","Although many people say","Although many people say that","While many people say","Although it is often said that","While it is often said that","Even though it is true that","Though it may be true that","Whilst it may be true that","Although it's true that","While it's true that","Whilst it's true that","Though it's true that","Even though it's true that"],"explanation":"Although / While (it is true that) … 先让一步，再说自己的观点，比两个短句更有说服力。主句前不再加 but。","subSkill":"concession_clauses_although_while_whereas"},{"id":"gen-11-5-101","type":"fill","instruction":"〔写作 Task 2〕把两句合成一句，突出「真正能改变学生的是老师」。原句：I think the most important thing is teachers. Teachers can really change students' lives.","sentence":"___ who can really change students' lives.","acceptableAnswers":["It is teachers","It's teachers","It is good teachers","It is great teachers","It is the teachers","It is a good teacher","It is really teachers","It is ultimately teachers","Ultimately, it is teachers","Above all, it is teachers","I think it is teachers","I believe it is teachers","In my view, it is teachers","In my opinion, it is teachers","Ultimately it is teachers","Above all it is teachers","In my view it is teachers","In my opinion it is teachers","Teachers are the ones","Teachers are the people","Good teachers are the ones","Good teachers are the people","It's good teachers","It's great teachers","It's the teachers","It's a good teacher","It's really teachers","It's ultimately teachers","Ultimately, it's teachers","Above all, it's teachers","In my view, it's teachers","In my opinion, it's teachers","I think it's teachers","I believe it's teachers","It is the teacher","It's the teacher","It is only teachers","It's only teachers"],"explanation":"It is teachers who … =「正是老师（而不是别的）才能真正改变学生」，比 The most important thing is teachers 更准、更有力。","subSkill":"cleft_sentences_for_emphasis_it_is_what"},{"id":"gen-11-5-102","type":"fill","instruction":"〔写作 Task 2〕补全这段关于出国留学的论证：先让步，再说结果，最后强调。","sentence":"___ studying abroad can be expensive, it offers benefits that last a lifetime. Many students become ___ confident in a foreign language that they find work more easily. ___ is often living alone, not the degree itself, that changes them most.","acceptableAnswers":["Although","so","It"],"blankAnswers":[["Although","While","Whilst","Though","Even though","Despite the fact that","In spite of the fact that","Although it is true that","While it is true that","While it's true that","Although it's true that","Whilst it is true that","Though it is true that","Even if"],["so"],["It"]],"explanation":"① 后面是完整的句子，先让一步 → Although / While。② 形容词 confident 前 → so … that。③ 强调「正是独自生活」→ It is … that。","subSkill":"concession_clauses_although_while_whereas"},{"id":"gen-11-5-103","type":"fill","instruction":"〔写作 Task 2〕把两句合成一句，说出「多到…以至于…」。原句：There are a lot of distractions online. Many office workers find it hard to concentrate.","sentence":"There are ___ distractions online ___ a lot of office workers find it hard to concentrate.","acceptableAnswers":["so many","that"],"blankAnswers":[["so many","such a lot of","so many different","such a large number of","such a huge number of","such a great number of","such a vast number of"],["that"]],"explanation":"many 前面用 so：so many distractions that…。such many 不存在；too many 后面不接 that 从句。","subSkill":"result_clauses_such_that_so_that"},{"id":"gen-11-5-104","type":"scenario","instruction":"考生想说「虽然工资低一些，我还是选了离家近的这份工作，因为我最看重家人」。哪句准确？","context":"雅思口语 Part 2 · 题卡：Describe a difficult decision you made … and explain why you made it","dialogue":[],"options":["Although the pay was lower, but I chose it because the thing what matters most is my family.","Despite the pay was lower, I chose it because what is matter most to me is my family.","Even the pay was lower, I chose it because what matters most to me is my family.","Although the pay was lower, I chose it because what matters most to me is my family."],"correctIndex":3,"explanation":"第 4 句准确。第 1 句 although 和 but 重复，也不说 the thing what；第 2 句 Despite 后接了句子，what is matter 也错；第 3 句 Even 不能单独引出从句，要用 Even though。","subSkill":"concession_clauses_although_while_whereas"},{"id":"gen-11-5-105","type":"fill","instruction":"〔写作 Task 2〕把 so 和 But 换成更正式的句首连接。原句：Many parents work long hours, so their children spend a lot of time alone. But this does not always harm them.","sentence":"Many parents work long hours. ___, their children spend a lot of time alone. ___, this does not always harm them.","acceptableAnswers":["As a result","However"],"blankAnswers":[["As a result","Consequently","Therefore","As a consequence","Because of this","For this reason","Thus","Hence","Because of that","As a result of this","Inevitably","Accordingly","Due to this"],["However","Nevertheless","Nonetheless","Even so","That said","Having said that","That being said","Despite this","In spite of this","Despite that","Yet","Still","On the other hand","At the same time","All the same","Be that as it may","Fortunately","Interestingly","Surprisingly"]],"explanation":"① 前一句是原因 → As a result / Consequently。② 转折 → However / Even so。句首连接词后面加逗号，比 so、But 开头更正式。","subSkill":"fronted_adverbial_clauses_for_cohesion"},{"id":"gen-11-5-106","type":"fill","instruction":"〔写作 Task 2〕把两句合成一句，让「年轻人结婚的越来越少」这件事本身当主语。原句：Fewer young people are getting married. This shows that attitudes to family life have changed.","sentence":"___ fewer young people are getting married shows that attitudes to family life have changed.","acceptableAnswers":["The fact that","That"],"explanation":"The fact that + 完整的句子 可以整个当主语，动词用单数 shows，两句并成一句更紧凑。That 开头也对，但比较少见。","subSkill":"noun_clauses_as_subject_and_complement"},{"id":"gen-11-5-107","type":"fill","instruction":"〔口语 Part 3〕考官问：Are people less polite than they used to be? 补全考生的回答。","sentence":"___ some young people may seem less polite, I think ___ the pace of modern life, not bad manners, that makes people seem rude.","acceptableAnswers":["Although","it is"],"blankAnswers":[["Although","While","Whilst","Though","Even though","Even if","Despite the fact that","In spite of the fact that","While it is true that","Although it is true that","While it's true that","Although it's true that"],["it is","it's","it is really","it's really","it is actually","it's actually","it is mainly","it's mainly","it is mostly","it is probably","it's probably","it's mostly","it is often","it's often","it is largely","it's largely","it is more","it's more","it is just","it's just","it is simply","it's simply","it is perhaps","it's perhaps"]],"explanation":"① 先让一步：Although / While。② it is … that 强调真正的原因：是生活节奏太快，不是没礼貌。","subSkill":"cleft_sentences_for_emphasis_it_is_what"},{"id":"gen-11-5-108","type":"fill","instruction":"〔写作 Task 2〕把开头改得更有力，让重点落在后半句。原句：The surprising thing is this: many children now spend more time online than at school.","sentence":"___ is that many children now spend more time online than at school.","acceptableAnswers":["What is surprising","What is most surprising","What is perhaps surprising","What is particularly surprising","What is really surprising","What is even more surprising","What is more surprising","What is especially surprising","What is truly surprising","What is so surprising","What may be surprising","What might be surprising","What surprises many people","What surprises most people","What surprises some people","What surprises me","What surprises many","What many people find surprising","What may surprise many people","What might surprise many people","What is striking","What is remarkable","What is worrying","What is alarming","What is shocking","What is most striking","What is most worrying","What is most alarming","What is most shocking","What worries many parents","What worries me","The surprising thing","The surprising fact","The most surprising thing","What's surprising","What's most surprising","What's really surprising","What's particularly surprising","What's even more surprising","What's perhaps surprising","What's more surprising","What's especially surprising","What's truly surprising","What's so surprising","What's striking","What's remarkable","What's worrying","What's alarming","What's shocking","What's most striking","What's most worrying","What's most alarming","What's most shocking","What I find surprising","What I find most surprising","What surprises me most","What is perhaps most surprising","What's perhaps most surprising","What is interesting","What's interesting","What is concerning","What's concerning","What is astonishing","What's astonishing","What is most remarkable","What's most remarkable","The most surprising fact","The most striking thing"],"explanation":"What is surprising is that … 先卖个关子，再把重点放到 that 后面。What 从句当主语，用单数 is。","subSkill":"cleft_sentences_for_emphasis_it_is_what"},{"id":"gen-11-5-109","type":"fill","instruction":"〔写作 Task 2〕用 Such 开头改写，更正式有力。原句：The demand for places was so great that the school had to hold a lottery.","sentence":"___ the demand for places that the school had to hold a lottery.","acceptableAnswers":["Such was","So great was","So high was","So strong was","So intense was","So huge was","So enormous was","So overwhelming was","So heavy was"],"explanation":"Such was + 名词 + that … =「…之大，以至于…」，be 动词提到主语前（也可以说 So great was …）。正式写作里偶尔用一次效果好，别每段都用。","subSkill":"result_clauses_such_that_so_that"}]},"mission":{"title":"写作 Task 2 段落：有了网课，还要去学校吗？","description":"写一个雅思 Task 2 主体段（3 句）：先承认网课的好处，再说学校能给、屏幕给不了的东西和它带来的结果，最后用一句话说明理由（写法自选）。至少用对本单元的 2 种写法，不必每句都用。AI 老师会按雅思「语法多样性与准确性」给你反馈。","scenario":"题目：Some people believe that, with the growth of online learning, children no longer need to go to school. To what extent do you agree or disagree?<br>你只写正文里的一段。可以写自己上网课的经历，也可以写你观察到的同学、弟弟妹妹。","grammarType":"concession_clauses_although_while_whereas","scaffolds":[{"prefix":"Online learning clearly has some advantages.","suffix":"","hint":"先承认网课的好处，再转回你的观点：Although / While …, …（主句前不加 but）。","grammarCheck":"concession_clauses_although_while_whereas","example":"Although students can learn at their own pace at home, many of them find it hard to stay motivated without a teacher in the room."},{"prefix":"However, school offers something that a screen cannot.","suffix":"","hint":"说一个结果：… so + 形容词/副词 + that …，或 such (a) + 形容词 + 名词 + that …。","grammarCheck":"result_clauses_such_that_so_that","example":"Classroom discussions are often so lively that even shy students end up joining in."},{"prefix":"In my view, online courses should support schools rather than replace them.","suffix":"","hint":"最后一句说明理由，结构自选：可以用 What … is …、It is … that …，也可以写一个普通的句子。","grammarCheck":"cleft_sentences_for_emphasis_it_is_what","example":"What children need most is not more screen time but real contact with teachers and classmates."}]},"discover":{"story":{"title":"写作 Task 2 范文节选：自动化，谁来买单？","text":"读的时候想一想：作者认为自动化对所有人都是好事吗？谁付出的代价最大？蓝色的句子下面会逐句问你。\nQuestion: Some people believe that automation will make life better for everyone. To what extent do you agree or disagree?\nThere is no doubt that automation has made many products cheaper and many jobs safer. Although machines now do much of the dangerous work in factories and mines, the number of people in work has continued to rise in most countries. Whereas earlier machines mainly replaced physical labour, today's software can also handle office tasks such as accounting and translation.\nWhat worries many economists, however, is not the total number of jobs but the speed of change. Office work is now changing so quickly that a worker who trained ten years ago may find that their skills are already out of date. It is older and less-educated workers who usually pay the price, since they find it hardest to retrain.\nRetraining millions of workers would be expensive. Despite this, it is a sensible investment, because people who cannot find new work will cost the state far more in the long run. In short, automation can make life better for most people, but only if its costs are shared more fairly.","highlights":["Although machines now do much of the dangerous work","the number of people in work has continued to rise","What worries many economists","is not the total number of jobs but the speed of change","so quickly that","It is older and less-educated workers who usually pay the price","Despite this"]},"questions":[{"question":"第一段：<em>Although machines now do much of the dangerous work in factories and mines, the number of people in work has continued to rise in most countries.</em><br>Did the number of people in work go up or down, and is that what you would expect?","options":["It went up, which is surprising.","It went down, as you would expect.","It went up, as you would expect."],"correctIndex":0,"nudge":"逗号后面的主句才是作者要说的事实。Although 那半句先让一步：机器干了这么多活，人们本来会以为人数怎样？","explanation":"增加了，这和「机器抢走工作」的预期正好相反。<br><strong>规则 ①</strong>：Although + 从句 先承认一个事实，主句说出出乎意料的结果。主句前不加 but：一句只用一个连接词。","subSkill":"concession_clauses_although_while_whereas"},{"question":"第二段：<em>What worries many economists, however, is not the total number of jobs but the speed of change.</em><br>What are many economists most worried about?","options":["How many jobs there will be","How much workers will be paid","How fast work is changing"],"correctIndex":2,"nudge":"What worries many economists 是「让经济学家担心的东西」。往后找 is：is not … but … 里，真正让他们担心的是哪一个？","explanation":"担心的是变化的速度，不是工作总量。<br><strong>规则 ②</strong>：What + 从句 + is … 先把「担心的东西」悬着，重点放在 is 后面。What 从句当主语，动词一般用单数 is。","subSkill":"cleft_sentences_for_emphasis_it_is_what"},{"question":"第二段：<em>Office work is now changing so quickly that a worker who trained ten years ago may find that their skills are already out of date.</em><br>Why might a worker's skills be out of date?","options":["Because they trained too slowly","Because office work changes fast","Because they forgot what they learned"],"correctIndex":1,"nudge":"so quickly that…：先找出什么变得「很快」，再看 that 后面说的是它带来的什么。","explanation":"因为办公室的工作变得太快，十年前学的就过时了。<br><strong>规则 ③</strong>：so + 形容词/副词 + that = 太…以至于（that 后面是结果）；形容词 + 名词前用 such (a) … that（many / much 前仍用 so）。","subSkill":"result_clauses_such_that_so_that"},{"question":"比较原文这句的两种写法：<br>A. Older and less-educated workers usually pay the price.<br>B. <em>It is older and less-educated workers who usually pay the price.</em><br>Which version suggests that other groups suffer less?","options":["A","B","Both of them"],"correctIndex":1,"nudge":"两句的信息一样，B 多了 It is … who。读 B 的时候，你会不会想到「而不是别人」？","explanation":"B。It is … who 把「年纪大、学历低的工人」单独拎出来：正是他们，而不是别人，付出了代价。<br><strong>规则 ④</strong>：It is/was + 要强调的部分 + who/that + 其余部分 =「正是…」。","subSkill":"cleft_sentences_for_emphasis_it_is_what"},{"question":"第三段：<em>Retraining millions of workers would be expensive. Despite this, it is a sensible investment…</em><br>Does the writer think retraining is cheap, and is it worth doing?","options":["No, but it is still worth it.","Yes, so it is worth doing.","No, so it should not be done."],"correctIndex":0,"nudge":"this 指的是前一句的哪件事？Despite this = 尽管有「这件事」，作者还觉得值得吗？","explanation":"不便宜，但作者认为值得。Despite this = 尽管这样（很贵）。<br><strong>规则 ⑤</strong>：despite / in spite of 后面接名词、this 或 -ing（不加 of）；后面是完整的句子（主语 + 动词），就用 although。","subSkill":"fronted_adverbial_clauses_for_cohesion"},{"question":"你来试试：想写「虽然工厂的活工资高，但很少有年轻人愿意干」。<br>Which sentence is correct?","options":["Although factory work is well paid, but few young people want to do it.","Despite factory work is well paid, few young people want to do it.","Although factory work is well paid, few young people want to do it."],"correctIndex":2,"nudge":"先数一数每句有几个连接词，再看 Despite 后面跟的是名词，还是完整的句子。用规则 ① 和 ⑤。","explanation":"Although 后面是完整的句子，主句前不再加 but（规则 ①）；Despite 后面不能接「主语 + 动词」（规则 ⑤）。","subSkill":"concession_clauses_although_while_whereas"}],"tip":"【先想清楚：让步、结果、对比，还是强调？】\n\n① Although + 从句，主句前不加 but：一句只用一个连接词\n② What + 从句 + is …：重点在 is 后面；What 从句当主语，一般用单数 is\n③ so + 形容词/副词 + that；so many/much + 名词 + that；such (a) + 形容词 + 名词 + that → 结果\n④ It is/was + 强调部分 + who/that … = 正是…，不是别的\n⑤ despite / in spite of + 名词 / this / -ing；后面是完整句子，用 although\n⑥ 对比两类人 → whereas / while（连两半句）、In contrast,（另起一句）；on the contrary 只用来否定前一句\n⑦ even though + 事实；even if + 假设\n标点：however / therefore 连两句时，前面用句号或分号，不用逗号。\n\n【例句】\n✔ What worries many economists is not the number of jobs but the speed of change.\n✔ It is older workers who usually pay the price.\n\n【常见错误】\n✘ Although the course is free, but few people sign up. → 去掉 but（见 ①）\n✘ Despite it is expensive / Despite of the cost → Although it is expensive / Despite the cost（见 ⑤）\n✘ Sales rose, however, profits fell. → Sales rose; however, profits fell.（见标点）\n✘ People move to cities. Because jobs are easier to find. → …cities because jobs…（because 半句不能单独成句）\n✘ The reason is because … → 写作里 The reason is that …（reason 已经是原因）"}},"12":{"levels":{"1":[{"id":"gen-12-1-100","type":"choice","instruction":"〔写作 Task 2〕读题目，回答问题。原句：Some people think that university education should be free for all students.","sentence":"Which paraphrase keeps exactly the same meaning?","options":["It is sometimes argued that all students should pay university fees.","It is sometimes argued that higher education should be free for poorer students.","It is sometimes argued that higher education should cost students nothing.","It is sometimes argued that tertiary education should cost less than it does."],"correctIndex":2,"explanation":"free for all students = 对所有学生免费，和 cost students nothing 意思一样。只对穷学生免费、学费降一点、学生都要交费，都改了原意。换了词（higher / tertiary education）不代表意思没变，先核对意思。","subSkill":"key_word_transformation_paraphrase"},{"id":"gen-12-1-101","type":"choice","instruction":"〔写作 Task 1〕改写题目写开头句，选出信息完全一样的一句。原句：The graph below shows the number of overseas students at universities in the UK between 2000 and 2020.","sentence":"The graph illustrates ___","options":["why international students chose UK universities from 2000 to 2020.","how many British students went to study at foreign universities from 2000 to 2020.","the number of overseas students at UK universities in 2020.","how many international students attended UK universities from 2000 to 2020."],"correctIndex":3,"explanation":"the number of … = how many …；overseas = international；between … and … = from … to …。另外三句分别改成了「为什么」、换成了出国的英国学生、丢了时间段。","subSkill":"key_word_transformation_paraphrase"},{"id":"gen-12-1-102","type":"choice","instruction":"〔写作 Task 2〕读句子，回答问题。原句：Many developed countries are now facing a shortage of young workers.","sentence":"Which countries is the writer talking about?","options":["Poorer countries whose economies are still growing","Countries that are building new factories","Countries with very young populations","Wealthy countries with modern economies"],"correctIndex":3,"explanation":"developed countries = 发达国家（已经发展起来的富裕国家）；developing countries 才是「发展中国家」。-ed 和 -ing 一字之差，写错就把论点说反了。","subSkill":"word_formation_affixation_and_conversion"},{"id":"gen-12-1-103","type":"choice","instruction":"〔写作 Task 2〕读句子，回答问题。原句：For many families, cooking at home is far more economical than eating out.","sentence":"What is the writer's point about cooking at home?","options":["It costs families much less money.","It is good for the national economy.","It is healthier than restaurant food.","It takes up less of people's time."],"correctIndex":0,"explanation":"economical = 省钱、划算；economic = 和经济有关的（economic growth 经济增长）。两个词形意思不同，作文里常被混用。","subSkill":"word_formation_affixation_and_conversion"},{"id":"gen-12-1-104","type":"choice","instruction":"〔写作 Task 2〕读句子，回答问题。原句：Many adults hardly exercise once they start full-time work.","sentence":"What does the writer say about working adults?","options":["They almost never do exercise.","They train harder than before.","They find exercise hard to enjoy.","They do a great deal of exercise."],"correctIndex":0,"explanation":"hardly = 几乎不：hardly exercise 几乎不锻炼。它不是 hard 的副词（hard 本身就能当副词：train hard）。词尾多一个 -ly，意思完全变了。","subSkill":"word_formation_affixation_and_conversion"},{"id":"gen-12-1-105","type":"choice","instruction":"〔口语 Part 1〕考官说：Let's talk about where you live. 读考生的回答，回答问题。原句：I've lived in Chengdu for about ten years.","sentence":"Does the candidate still live in Chengdu?","options":["No, the candidate moved away.","Yes, for about ten years now.","No, that was ten years ago.","We can't tell from this."],"correctIndex":1,"explanation":"I've lived … for ten years（现在完成时）= 从十年前一直住到现在。说「以前住过、现在不住了」要用 I lived there for ten years。时态写错，考官会误解你的经历。","subSkill":"integrated_grammar_accuracy_review"},{"id":"gen-12-1-106","type":"scenario","instruction":"〔口语 Part 3〕读考生的回答，回答问题：What does the candidate mean by \"the main appeal of televised sport\"?","context":"雅思口语 Part 3 · Sport","dialogue":[{"speaker":"examiner","text":"Examiner: Why do so many people enjoy watching sport on TV?"},{"speaker":"player","text":"I suppose the main appeal of televised sport is the shared excitement. You feel part of something much bigger than yourself."}],"options":["The biggest drawback of watching at home","The most popular sport on television","What makes it attractive to viewers","The best channel for watching sport"],"correctIndex":2,"explanation":"the main appeal of televised sport = 电视体育最吸引人的地方，也就是「人们为什么爱看」。先用自己的话复述问题再展开，比照搬考官的原话自然得多。","subSkill":"key_word_transformation_paraphrase"},{"id":"gen-12-1-107","type":"choice","instruction":"〔写作 Task 2〕读句子，回答问题。原句：Local councils should do more to support the unemployed.","sentence":"Who does \"the unemployed\" refer to?","options":["People who do not have a job","One worker who has lost a job","People who work for councils","Companies that have no workers"],"correctIndex":0,"explanation":"the + 形容词 = 一类人：the unemployed 失业的人（the elderly 老人，the poor 穷人）。它表示复数，动词用 are，也不加 s。","subSkill":"word_formation_affixation_and_conversion"},{"id":"gen-12-1-108","type":"match","instruction":"〔写作 Task 2〕题目：Unpaid community service should be a compulsory part of high school programmes. 四种改写都以 Some argue that 开头，意思变了没有？连线。","left":["…high school students should have to do unpaid community work.","…teenagers should be paid for the community work they do.","…unpaid community service should be mandatory for high school students.","…high schools should offer community service as an optional activity."],"right":["Same meaning","Meaning changed"],"correctPairs":[[0,0],[1,1],[2,0],[3,1]],"explanation":"should have to、mandatory = compulsory，意思不变。被付钱（paid）、可选（optional）都把原意改了。改写只换说法，不改立场，也不改程度。","subSkill":"key_word_transformation_paraphrase"}],"2":[{"id":"gen-12-2-100","type":"choice","instruction":"〔写作 Task 2〕想说「网购对街边小店影响很大」。","sentence":"Online shopping has had a huge ___ on small high-street shops.","options":["affect","effective","affection","effect"],"correctIndex":3,"explanation":"a huge 后面要名词 → effect（影响），have an effect on。affect 是动词（Online shopping has affected…）；effective 是「有效的」；affection 是「喜爱」。","subSkill":"word_formation_affixation_and_conversion"},{"id":"gen-12-2-101","type":"choice","instruction":"〔口语 Part 1〕想说「外卖软件让在家吃上热饭方便多了」。","sentence":"Food delivery apps have made it much more ___ to get a hot meal at home.","options":["convenience","conveniently","convenient","inconvenience"],"correctIndex":2,"explanation":"make it + 形容词 + to do → more convenient（更方便）。convenience 是名词，conveniently 是副词。把 convenient 写成 convenience 是很常见的词形错误。","subSkill":"word_formation_affixation_and_conversion"},{"id":"gen-12-2-102","type":"choice","instruction":"〔写作 Task 2〕想说「人口迅速老龄化，给医疗带来压力」。","sentence":"The ___ ageing of the population is putting pressure on health services.","options":["rapidly","rapid","rapidity","fastly"],"correctIndex":1,"explanation":"the … of 中间的 ageing 是名词，修饰名词用形容词 rapid。说成 The population is ageing rapidly 时修饰的是动词，才用副词。fastly 不存在。","subSkill":"word_formation_affixation_and_conversion"},{"id":"gen-12-2-103","type":"choice","instruction":"〔写作 Task 2〕想说「选择不要孩子的夫妇越来越多」。","sentence":"The number of couples who choose not to have children ___ rising.","options":["is","are","have","were"],"correctIndex":0,"explanation":"主语的中心词是 number（数量，单数）→ is rising。couples 只是 of 后面的修饰语；who choose 跟着 couples 用复数，没错。","subSkill":"open_cloze_grammar_word_selection"},{"id":"gen-12-2-104","type":"choice","instruction":"〔写作 Task 2〕想泛指所有青少年：「青少年每晚至少需要睡八小时」。","sentence":"___ need at least eight hours of sleep a night.","options":["The teenagers","Teenagers","A teenager","Teenager"],"correctIndex":1,"explanation":"泛指一类人 → 复数名词不加 the：Teenagers need…。The teenagers 指某几个特定的人；A teenager 后面要用 needs；单数 teenager 前面不能什么都不加。","subSkill":"open_cloze_grammar_word_selection"},{"id":"gen-12-2-105","type":"choice","instruction":"〔写作 Task 1〕想说「上涨了 10 个百分点，达到 45%」。","sentence":"In 2020, the proportion of households with solar panels rose ___ 10 percentage points ___ 45%.","options":["by … to","to … by","of … at","at … of"],"correctIndex":0,"explanation":"by + 变化的幅度（涨了多少），to + 终点（涨到多少）。名词也一样：a rise of 10 points 说幅度，a rise in sales 说什么在涨。","subSkill":"open_cloze_grammar_word_selection"},{"id":"gen-12-2-106","type":"choice","instruction":"〔写作 Task 2 · 开头段〕改写题目，选出意思不变的一句。原句：Some people say that schools should teach practical skills rather than academic subjects.","options":["should teach practical skills as well as academic subjects.","should focus on practical skills instead of academic subjects.","should focus on academic subjects instead of practical skills.","already focus on practical skills instead of academic subjects."],"correctIndex":1,"explanation":"rather than = instead of（而不是）。as well as 变成了「两样都教」；第 3 句把两样对调了；already 把「应该」改成了「已经」。改写可以换词，不能改立场。","subSkill":"key_word_transformation_paraphrase","sentence":"Some argue that schools ___"},{"id":"gen-12-2-107","type":"choice","instruction":"〔写作 Task 2 · 开头段〕想把 Governments should ban junk food advertising 改成以广告开头，意思不变。","sentence":"Junk food advertising ___ by governments.","options":["should ban","should banned","should been banned","should be banned"],"correctIndex":3,"explanation":"广告是「被禁」的 → should be + 过去分词 banned。should ban 成了「广告去禁止」；should banned 少了 be；should been banned 把 be 写成了 been（should 后面用原形 be）。","subSkill":"key_word_transformation_paraphrase"},{"id":"gen-12-2-108","type":"match","instruction":"〔写作 Task 1〕四句都在说「销量大幅上升」。每个空填哪个词？连线。","left":["Sales rose ___ in 2019.","There was a ___ rise in sales in 2019.","2019 saw a ___ increase in sales.","Sales increased ___ in 2019."],"right":["sharp","sharply"],"correctPairs":[[0,1],[1,0],[2,0],[3,1]],"explanation":"修饰动词（rose, increased）用副词 sharply；修饰名词（rise, increase）用形容词 sharp。Task 1 里两种说法换着用，句式就有了变化。","subSkill":"word_formation_affixation_and_conversion"},{"id":"gen-12-2-109","type":"scenario","instruction":"〔口语 Part 3〕考生想说「很多人觉得电子书比带着厚厚的纸书方便」。哪句准确？","context":"雅思口语 Part 3 · Reading","dialogue":[{"speaker":"examiner","text":"Examiner: Why do some people prefer e-books to printed books?"}],"options":["There are many people think e-books are more convenient than carrying heavy books around.","Many people think e-books are more convenience than carrying books around.","Many people think e-books are more convenient than carrying heavy books around.","There are many people they think e-books are more convenient than carrying books around."],"correctIndex":2,"explanation":"直接说 Many people think … 就行。There are many people think 是「有很多人认为」的直译，一句里有两个谓语；more 后面要形容词 convenient，不用名词 convenience。","subSkill":"integrated_grammar_accuracy_review"}],"3":[{"id":"gen-12-3-100","type":"fill","instruction":"〔写作 Task 2 · 开头段〕用 Free childcare 作主语改写题目，意思不变。原句：Governments should provide free childcare for all working parents.","sentence":"Free childcare ___ for all working parents.","acceptableAnswers":["should be provided","should be provided by governments","should be provided by the government","should be provided by the state","should be provided by the authorities","ought to be provided","ought to be provided by governments","ought to be provided by the government","ought to be provided by the state","ought to be provided by the authorities","should be made available","should be made available by governments","should be made available by the government","should be made available by the state","should be made available by the authorities","ought to be made available","ought to be made available by governments","ought to be made available by the government","ought to be made available by the state","ought to be made available by the authorities","should be offered","should be offered by governments","should be offered by the government","should be offered by the state","should be offered by the authorities","ought to be offered","ought to be offered by governments","ought to be offered by the government","ought to be offered by the state","ought to be offered by the authorities","should be available","should be funded","should be funded by governments","should be funded by the government","should be funded by the state","should be funded by the authorities","should be provided by government","should be made available by government","should be guaranteed"],"explanation":"childcare 是「被提供」的 → should be provided。施动者 governments 可以省掉，也可以放到后面（by governments）。should provided、should be provide 都是常见错误。","subSkill":"key_word_transformation_paraphrase"},{"id":"gen-12-3-101","type":"fill","instruction":"〔写作 Task 2 · 开头段〕用名词短语改写，意思不变。原句：Young people are using social media more and more, and many parents are worried about this.","sentence":"The ___ of social media among young people has worried many parents.","acceptableAnswers":["increasing use","growing use","rising use","increased use","ever-increasing use","ever increasing use","ever-growing use","greater use","increasing usage","growing usage","rising usage","increased usage","increasing popularity","growing popularity","rising popularity","increased popularity","rise","rapid rise","growth","rapid growth","spread","rapid spread"],"explanation":"more and more 是在说「用得越来越多」→ the increasing / growing use of…。the 后面要名词 use；修饰名词用形容词 increasing，不用副词 increasingly。","subSkill":"word_formation_affixation_and_conversion"},{"id":"gen-12-3-102","type":"fill","instruction":"〔写作 Task 1〕换一种说法，意思不变。原句：The number of visitors to the national park rose dramatically between 2010 and 2019.","sentence":"There was a ___ in the number of visitors to the national park between 2010 and 2019.","acceptableAnswers":["dramatic rise","dramatic increase","sharp rise","sharp increase","steep rise","steep increase","huge rise","huge increase","massive rise","massive increase","enormous rise","enormous increase","rapid rise","rapid increase","significant rise","significant increase","substantial rise","substantial increase","considerable rise","considerable increase","marked rise","marked increase","remarkable rise","remarkable increase","spectacular rise","spectacular increase","very sharp rise","very sharp increase","very large rise","very large increase","dramatic surge","sharp surge","huge surge","massive surge","dramatic jump","sharp jump","huge jump","steep climb","very dramatic rise","very dramatic increase"],"explanation":"rose dramatically（动词 + 副词）→ a dramatic rise（形容词 + 名词）。名词后面用 in 引出「什么在涨」：a rise in the number of visitors。","subSkill":"word_formation_affixation_and_conversion"},{"id":"gen-12-3-103","type":"fill","instruction":"〔写作 Task 2〕用括号里词的合适形式填空，注意整句的意思。","sentence":"Investing in the ___ (develop) of rural areas would help to reduce ___ (employ) among young people.","acceptableAnswers":["development","unemployment"],"blankAnswers":[["development","redevelopment"],["unemployment","underemployment"]],"explanation":"the … of 中间要名词 → development。投资要减少的应该是「失业」，不是「就业」→ unemployment（un- 表示否定）。词形看位置，也要看意思。","subSkill":"word_formation_affixation_and_conversion"},{"id":"gen-12-3-104","type":"fill","instruction":"〔写作 Task 1〕每空填一个词，把数据说准确：失业率从 8% 降到 5%，降了三个百分点。","sentence":"Unemployment fell ___ 8% ___ 5% over the decade, a drop ___ three percentage points.","acceptableAnswers":["from","to","of"],"explanation":"from 起点 to 终点；a drop / rise of + 幅度（降了多少）。a drop in 后面接的是「什么在降」：a drop in unemployment。","subSkill":"open_cloze_grammar_word_selection"},{"id":"gen-12-3-105","type":"fill","instruction":"〔写作 Task 2 · 开头段〕不照抄 Some people say，换一个开头改写题目。原句：Some people say that video games make children more aggressive.","sentence":"___ that video games make children more aggressive.","acceptableAnswers":["It is sometimes argued","It is often argued","It has been argued","It has sometimes been argued","It is argued","It is sometimes claimed","It is often claimed","It has been claimed","It has sometimes been claimed","It is claimed","It is sometimes said","It is often said","It has been said","It has sometimes been said","It is said","It is sometimes suggested","It is often suggested","It has been suggested","It has sometimes been suggested","It is suggested","It is sometimes believed","It is often believed","It has been believed","It has sometimes been believed","It is believed","It is sometimes thought","It is often thought","It has been thought","It has sometimes been thought","It is thought","It is sometimes felt","It is often felt","It has been felt","It has sometimes been felt","It is felt","It is sometimes maintained","It is often maintained","It has been maintained","It has sometimes been maintained","It is maintained","It is sometimes held","It is often held","It has been held","It has sometimes been held","It is held","Some argue","Some people argue","There are those who argue","Some claim","Some people claim","There are those who claim","Some believe","Some people believe","There are those who believe","Some maintain","Some people maintain","There are those who maintain","Some suggest","Some people suggest","There are those who suggest","Some feel","Some people feel","There are those who feel","Some contend","Some people contend","There are those who contend","Some think","Some people think","There are those who think","Some critics argue","Some critics claim","Critics argue","Critics claim","Some commentators argue","Some commentators claim","Some people are of the opinion","Some are of the view","Some people hold the view","Some hold the view","One view is","There is a view","Some would argue","Some people would argue","It is frequently argued","It has often been argued","It is argued by some","Some people are of the view","Some are of the opinion","Some people hold the opinion","It is sometimes contended","It is often contended","It is sometimes asserted","Some assert","Some people assert"],"explanation":"It is sometimes argued / claimed that… 或 Some argue that… 都行，意思不变，又不照抄。别改成 It is widely believed：「一些人」变成了「普遍认为」。","subSkill":"key_word_transformation_paraphrase"},{"id":"gen-12-3-106","type":"reorder","instruction":"〔写作 Task 1 · 开头句〕排出这句：图表显示了 2015 年青少年上网花了多少时间。","words":["time","The","online","shows","teenagers","how","in","chart","spent","much","2015."],"correctSentence":"The chart shows how much time teenagers spent online in 2015.","explanation":"问句放进句子里，用陈述语序：how much time teenagers spent，不写 how much time did teenagers spend。Task 1 开头句常用 shows / compares + how much / how many…","subSkill":"key_word_transformation_paraphrase"},{"id":"gen-12-3-107","type":"fill","instruction":"〔写作 Task 2〕用 -ing 短语作主语，把句子改得更紧凑。原句：If children read for pleasure, their vocabulary grows.","sentence":"___ for pleasure ___ children's vocabulary.","acceptableAnswers":["Reading","expands"],"blankAnswers":[["Reading","Reading books","Reading regularly","Regular reading","Reading stories","Reading widely","Reading fiction","Reading novels","Reading books regularly"],["expands","improves","enriches","develops","broadens","widens","builds","increases","extends","boosts","grows","enlarges","strengthens","can expand","can improve","can enrich","can develop","can broaden","can widen","can build","can increase","can boost","helps to expand","helps expand","helps to build","helps build","helps to improve","helps improve","helps to develop","helps develop","helps to grow","helps grow","helps to increase","helps increase","enhances","can enhance","helps to enhance","helps enhance","helps to broaden","helps broaden","helps to enrich","helps enrich","helps to widen","helps widen","can strengthen","can extend","can enlarge","can grow","will expand","will improve","will enrich","will enhance","tends to expand","tends to improve","builds up"]],"explanation":"Reading for pleasure 当主语，是「一件事」，动词用单数 expands / improves，不写 expand。原句「词汇量增长」变成了「阅读扩大词汇量」。","subSkill":"integrated_grammar_accuracy_review"},{"id":"gen-12-3-108","type":"fill","instruction":"〔写作 Task 2〕用 which 把两句合成一句。原句：Many young people cannot afford to buy a home. This means that they live with their parents for longer.","sentence":"Many young people cannot afford to buy a home, ___ they live with their parents for longer.","acceptableAnswers":["which means that","which means","which is why","which explains why","which is the reason why","which is the reason","which means that in many cases","which often means that","which often means","which usually means that","which usually means","which in turn means that","which in turn means"],"explanation":"which 指前面整件事（买不起房），后面接 means that / is why。逗号后不能写 this means 或 it means：那就成了两个句子硬连在一起。","subSkill":"integrated_grammar_accuracy_review"},{"id":"gen-12-3-109","type":"fill","instruction":"〔写作 Task 2〕作者其实没有十足的证据，把这句改得留有余地。原句：Long working hours definitely cause health problems among office workers.","sentence":"Long working hours ___ contribute to health problems among office workers.","acceptableAnswers":["may","can","might","could","may well","might well","could well","may sometimes","can sometimes","might sometimes","could sometimes","may partly","can partly","might partly","could partly","may also","can also","might also","could also","may in some cases","can in some cases","are likely to","are thought to","are believed to","are said to","are widely thought to","are often thought to","appear to","seem to","tend to","may actually","may indeed","probably do","possibly do","arguably do","probably","possibly","arguably","often","sometimes","frequently","can often","may often","could potentially","may potentially","can potentially","may possibly","could possibly","might possibly","would appear to","are generally thought to","are generally believed to"],"explanation":"definitely cause 说得太死。may / can / might contribute to = 可能导致，更符合证据，这就是作文里常说的「留有余地」。主语 hours 是复数：are likely to，不是 is likely to。","subSkill":"integrated_grammar_accuracy_review"}],"4":[{"id":"gen-12-4-100","type":"fill","instruction":"〔写作 Task 2 · 考生常见错误〕这句的开头是中文直译，在空里改对。原句：There are many people think that cash will disappear in the near future.","sentence":"___ think that cash will disappear in the near future.","acceptableAnswers":["Many people","A lot of people","Lots of people","Plenty of people","Quite a few people","Many","A great many people","A large number of people","There are many people who","There are a lot of people who","There are lots of people who","There are plenty of people who","There are quite a few people who","Nowadays, many people","Nowadays many people","Today, many people","Today many people","These days, many people","These days many people","Many people now","Many people today","A number of people","There are many who","Many people these days","Numerous people","Many individuals"],"explanation":"「有很多人认为」直接写 Many people think…。There are many people think 一句里有两个谓语（are、think）；要保留 There are，就得加 who：There are many people who think…","subSkill":"error_correction_in_written_text"},{"id":"gen-12-4-101","type":"error","instruction":"〔写作 Task 2 · 考生常见错误〕点出用错的部分。","words":["Students","can now find","a great deal of","useful informations","online,","but","not all of it","is completely reliable."],"errorIndex":3,"correction":"useful information","explanation":"information 不可数，不加 s（advice、research、equipment 也一样）。后面的 not all of it is 用 it 和 is，也说明它是不可数的。","subSkill":"error_correction_in_written_text"},{"id":"gen-12-4-102","type":"fill","instruction":"〔写作 Task 2 · 考生常见错误〕有一处动词形式错了，在空里写出正确的形式。原句：One of the biggest problems in large cities are the shortage of affordable housing.","sentence":"One of the biggest problems in large cities ___ the shortage of affordable housing.","acceptableAnswers":["is"],"explanation":"主语的中心词是 One（其中一个），动词用单数 is。problems、cities 都只是修饰语，别被离动词最近的复数带跑。","subSkill":"error_correction_in_written_text"},{"id":"gen-12-4-103","type":"error","instruction":"〔写作 Task 2 · 考生常见错误〕点出用错的部分。","words":["In my view,","learning how to cook","is","important skill","that","all teenagers","should master","before leaving home."],"errorIndex":3,"correction":"an important skill","explanation":"skill 是单数可数名词，前面不能光着：an important skill。泛指也可以用复数：important skills。中文没有冠词，写作时很容易漏掉。","subSkill":"open_cloze_grammar_word_selection"},{"id":"gen-12-4-104","type":"error","instruction":"〔写作 Task 2 · 考生常见错误〕点出用错的部分。","words":["Constant","exam pressure","makes","many students","to feel","anxious","about","their future."],"errorIndex":4,"correction":"feel","explanation":"make + 人 + 动词原形：makes many students feel…，不加 to。换成 cause 才接 to do：causes many students to feel…","subSkill":"error_correction_in_written_text"},{"id":"gen-12-4-105","type":"choice","instruction":"〔写作 Task 2 · 考生常见写法〕原句有两处错，选出改对的句子。原句：Although the city council has spent a lot of money, but the problem of homeless remains.","options":["Although the city council has spent a lot of money, but the problem of homelessness remains.","Despite the city council has spent a lot of money, the problem of homelessness remains.","Although the city council has spent a lot of money, the problem of homelessness remains.","Although the city council has spent a lot of money, the problem of homeless remains."],"correctIndex":2,"explanation":"Although 后面不再加 but；problem of 后面要名词 homelessness（无家可归这个问题），homeless 是形容词。Despite 后面不能接「主语 + 动词」。","subSkill":"integrated_grammar_accuracy_review"},{"id":"gen-12-4-106","type":"choice","instruction":"〔写作 Task 2 · 考生常见写法〕考生改写题目时把意思改了，选出意思不变的一句。原句：All young people should be required to do a year of national service.","options":["It is argued that every young person should be allowed to do a year of national service.","It is argued that every young person should be encouraged to spend a year doing national service.","It is argued that some young people should be required to do a year of national service.","It is argued that every young person should have to spend a year doing national service."],"correctIndex":3,"explanation":"All → every young person，be required to → should have to，意思不变。考生的改写把「全部」改成「一部分」、「必须」改成「鼓励」。改写不能改范围和强度。","subSkill":"key_word_transformation_paraphrase","sentence":"考生写的：It is argued that some young people should be encouraged to do a year of national service. Which version keeps the original meaning?"},{"id":"gen-12-4-107","type":"fill","instruction":"〔写作 Task 2 · 考生常见错误〕有一处多了一个词，在空里改对。原句：People who they live in remote villages often have to travel for hours to see a doctor.","sentence":"People ___ in remote villages often have to travel for hours to see a doctor.","acceptableAnswers":["who live","that live","living","who are living","that are living","who reside","residing","that reside"],"explanation":"who 已经是从句的主语，后面不再加 they：People who live in…。也可以说 People living in…","subSkill":"error_correction_in_written_text"},{"id":"gen-12-4-108","type":"error","instruction":"〔写作 Task 1 · 考生常见错误〕点出用错的部分。","words":["In 2015,","there was","a sharp increase","of","online sales,","which","rose","to 40% of the total."],"errorIndex":3,"correction":"in","explanation":"increase / rise / fall 后面：in + 什么在变（an increase in online sales），of + 变了多少（an increase of 10%）。","subSkill":"open_cloze_grammar_word_selection"},{"id":"gen-12-4-109","type":"error","instruction":"〔写作 Task 2 · 考生常见错误〕点出用错的部分。","words":["In","the modern society,","people","spend","much less time","talking to their neighbours","than they used to."],"errorIndex":1,"correction":"modern society,","explanation":"society 泛指「社会」时不加 the：in modern society、society as a whole。特指某一个社会才加 the：the society we live in。","subSkill":"open_cloze_grammar_word_selection"}],"5":[{"id":"gen-12-5-100","type":"fill","instruction":"〔写作 Task 2 · 开头段〕题目问：人越来越长寿，是好是坏？用括号里词的合适形式补全开头段。","sentence":"Life expectancy ___ (rise) considerably in many countries over recent decades. While some see this ___ (develop) as a burden on society, I would argue that it is ___ (large) a positive change.","acceptableAnswers":["has risen","development","largely"],"blankAnswers":[["has risen","has been rising"],["development"],["largely"]],"explanation":"① over recent decades 连到现在 → has risen。② this 后面要名词 → development。③ 修饰「是好事」这个判断用副词 largely（基本上）。","subSkill":"integrated_grammar_accuracy_review"},{"id":"gen-12-5-101","type":"fill","instruction":"〔写作 Task 2 · 开头段〕不照抄题目里的 spend more money，换个说法，意思不变。原句：Many people think that the government should spend more money on hospitals.","sentence":"It is often argued that the government should increase ___ on hospitals.","acceptableAnswers":["its spending","spending","public spending","government spending","state spending","its expenditure","expenditure","public expenditure","government expenditure","the amount it spends","the money it spends","the amount of money it spends","how much it spends","its overall spending","overall spending","total spending","the amount spent","the money spent","the amount of money spent","the sum it spends","its total spending","total expenditure","its total expenditure","its overall expenditure","the spending"],"explanation":"spend more money on → increase (its) spending on：动词变成名词，意思不变，也避开了照抄。spending 不可数，不加 a，也不写 spendings。","subSkill":"key_word_transformation_paraphrase"},{"id":"gen-12-5-102","type":"fill","instruction":"〔写作 Task 2〕把两句合成一句，意思不变。原句：The scheme was introduced in 2018. It has since helped thousands of adults return to education.","sentence":"___ in 2018, the scheme has since helped thousands of adults return to education.","acceptableAnswers":["Introduced","First introduced","Having been introduced","Launched","First launched","Having been launched","Set up","First set up","Established","After being introduced","After its introduction","After its launch","After being launched","Implemented","First implemented","Created","Founded","First established","Rolled out","First rolled out","Brought in","Started","Initiated","Initially introduced","Originally introduced","Having first been introduced"],"explanation":"计划是「被推出」的 → 用过去分词 Introduced 开头，主语 the scheme 紧跟在逗号后。写成 Introducing 意思就成了计划自己去推出别的东西。","subSkill":"integrated_grammar_accuracy_review"},{"id":"gen-12-5-103","type":"fill","instruction":"〔写作 Task 1〕补全这段数据描述，括号里的词用合适的形式，其余每空一个词。","sentence":"Between 2000 and 2020, the share of adults who shopped online rose ___ 55 percentage points, reaching 70%. The ___ (sharp) increase came between 2010 and 2015, when the figure jumped from 30% ___ 55%.","acceptableAnswers":["by","sharpest","to"],"explanation":"① 涨了多少 → by。② the 后面要最高级 → sharpest（涨得最猛的那一段）。③ 涨到多少 → to。by / to 用错，数据就说错了。","subSkill":"open_cloze_grammar_word_selection"},{"id":"gen-12-5-104","type":"fill","instruction":"〔写作 Task 1 · 开头句〕改写题目，不照抄。原句：The table below gives information about the amount of waste produced by five countries in 2019.","sentence":"The table ___ how much waste five countries ___ in 2019.","acceptableAnswers":["compares","produced"],"blankAnswers":[["compares","shows","illustrates","indicates","presents","sets out","reveals","outlines","details","displays","provides information on","provides information about","gives details of","provides data on","depicts","summarises","summarizes","demonstrates","provides details of","gives data on","provides figures on","gives figures for"],["produced","generated","created","threw away","discarded"]],"explanation":"the amount of → how much：名词短语改成从句，从句里用陈述语序和过去时 produced（数据是 2019 年的），不写 did … produce。","subSkill":"key_word_transformation_paraphrase"},{"id":"gen-12-5-105","type":"scenario","instruction":"〔口语 Part 3〕考生想先用自己的话复述问题，再给出原因。哪句准确？","context":"雅思口语 Part 3 · Traditional crafts","dialogue":[{"speaker":"examiner","text":"Examiner: Why are fewer young people learning traditional crafts these days?"}],"options":["I think the main reason why are young people losing interest in crafts is that they see no future in them.","I think the main reason young people are losing interest in crafts is that they see no future in them.","I think the main reason of young people losing interest in crafts is because they see no future in them.","I think the main reason is because young people are losing interest in crafts and see no future."],"correctIndex":1,"explanation":"第 2 句准确：换了说法（fewer … learning → losing interest in），用陈述语序 young people are…。第 1 句语序错；第 3 句 reason of 应为 reason for / why；第 4 句把现象本身当成了原因。正式写作里 the reason is because 最好写成 the reason is that。","subSkill":"key_word_transformation_paraphrase"},{"id":"gen-12-5-106","type":"fill","instruction":"〔写作 Task 2〕把因果句改成一句假设：要是政府现在多投入，情况会更好。原句：Governments do not invest enough in early education, so many children start school behind their peers.","sentence":"If governments ___ more in early education, fewer children ___ school behind their peers.","acceptableAnswers":["invested","would start"],"blankAnswers":[["invested","spent","put","did invest","were to invest","were to spend","were to put"],["would start","would begin","might start","might begin","would be starting","would enter","would probably start","would probably begin","would likely start","would likely begin"]],"explanation":"事实是投入不够（现在）→ if + 过去式 invested，主句 would start。if 从句里不用 would 或 will：If governments would invest… 是常见错误。","subSkill":"integrated_grammar_accuracy_review"},{"id":"gen-12-5-107","type":"choice","instruction":"〔写作 Task 2〕把两个短句升级成一句，选出没有错误的一句。原句：Smartphones are very useful. But many teenagers rely on them too much.","options":["Smartphones are extremely useful, however many teenagers rely on them too heavily.","Despite being extremely useful, many teenagers rely on smartphones too heavily.","Despite smartphones are extremely useful, many teenagers rely on them too heavily.","While smartphones are extremely useful, many teenagers rely on them too heavily."],"correctIndex":3,"explanation":"While = 虽然，主句前不加 but。第 1 句 however 不能用逗号连两句（改成 …useful; however, …）；第 2 句 being useful 的逻辑主语成了 teenagers；第 3 句 Despite 后面不能接「主语 + 动词」。","subSkill":"error_correction_in_written_text"},{"id":"gen-12-5-108","type":"fill","instruction":"〔写作 Task 2〕补全这段论证，用括号里词的合适形式。","sentence":"Moreover, ___ (spend) time outdoors ___ (be) highly ___ (benefit) to children's mental health.","acceptableAnswers":["spending","is","beneficial"],"blankAnswers":[["spending"],["is","can be","may be","tends to be","could be","might be","appears to be","seems to be","has been shown to be","is often","is generally"],["beneficial"]],"explanation":"① 作主语用 -ing：spending。② -ing 短语当主语，动词用单数 is（outdoors 不是主语）。③ highly 后面要形容词 beneficial，benefit 是名词或动词。","subSkill":"word_formation_affixation_and_conversion"},{"id":"gen-12-5-109","type":"fill","instruction":"〔写作 Task 2 · 结论段〕补全结论句：承认成本高，再说为什么还是要投入。括号里的词用合适的形式。","sentence":"In conclusion, ___ the high upfront cost of renewable energy, I believe that ___ (invest) in it now is essential, ___ the price of delay will be far higher.","acceptableAnswers":["despite","investing","since"],"blankAnswers":[["despite","in spite of","notwithstanding","regardless of","for all","even with"],["investing"],["since","as","because","for","given that","because ultimately","as ultimately","considering that","seeing that"]],"explanation":"① the high cost 是名词短语 → despite / in spite of（不用 although）。② 作主语 → investing，动词用单数 is。③ 引出原因 → since / as / because。","subSkill":"integrated_grammar_accuracy_review"}]},"mission":{"title":"写作 Task 2 开头段：改写题目，亮出立场","description":"写一个雅思 Task 2 开头段（3 句）：先用自己的话改写题目，再说另一面（城市的好处），最后亮出你的立场（写法自选）。写完按小贴士查一遍主谓一致、冠词、时态、词形。AI 老师会按雅思「语法多样性与准确性」给你反馈。","scenario":"题目：Some people believe that it is better for children to grow up in the countryside than in a big city. To what extent do you agree or disagree?<br>你只写开头段。可以想想你自己是在城市还是乡下长大的，再决定立场。","grammarType":"key_word_transformation_paraphrase","scaffolds":[{"prefix":"","suffix":"","hint":"改写题目：意思不变（better … than … 要留住），换词也换结构。可以用 It is sometimes argued that … / Some argue that …，别整句照抄。","grammarCheck":"key_word_transformation_paraphrase","example":"It is sometimes argued that children benefit more from a rural upbringing than from growing up in a large city."},{"prefix":"Supporters of this view point to cleaner air, more open space and a slower pace of life.","suffix":"","hint":"再说另一面：城市的好处。用 While / Although …, … 写成一句，好处用名词短语说清（access to … / a wider range of …）。","grammarCheck":"word_formation_affixation_and_conversion","example":"While cities offer children access to better schools and a far wider range of activities, they can also be noisy and stressful places to grow up in."},{"prefix":"","suffix":"","hint":"结构自选：亮出你的立场，可以写 In my view, … / I would argue that …，也可以加一个条件或让步。写完查主谓一致和冠词。","grammarCheck":"integrated_grammar_accuracy_review","example":"In my view, the benefits of a rural childhood outweigh the drawbacks, provided that children still have access to good education."}]},"discover":{"story":{"title":"写作 Task 2：同一段话的初稿和改稿","text":"读的时候想一想：两稿的观点一样吗？改稿改了哪些地方，意思有没有变？蓝色的句子下面会逐句问你。\nQuestion: Some people think that children should start learning a foreign language at primary school rather than at secondary school. Do the advantages of this outweigh the disadvantages?\nFirst draft: Some people think that children should start learning a foreign language at primary school rather than at secondary school. I think the advantages are more than the disadvantages. Learning a language early is very benefit for the children, because they can copy new sounds without feel shy. The number of primary schools which teach English have grown quickly in my country. Although good teachers are expensive, but this money is worth to spend.\nRevised version: It is sometimes argued that foreign languages should be introduced in primary education rather than at secondary level. In my view, the benefits of this approach clearly outweigh the drawbacks. Early language learning is highly beneficial to children, as they can imitate new sounds without feeling self-conscious. The number of primary schools offering English has risen sharply in my country. Although hiring qualified teachers is expensive, this is money well spent.","highlights":["foreign languages should be introduced in primary education","rather than at secondary level","Early language learning is highly beneficial to children","The number of primary schools offering English has risen sharply","Although hiring qualified teachers is expensive","money well spent"]},"questions":[{"question":"改稿第一句：<em>It is sometimes argued that foreign languages should be introduced in primary education rather than at secondary level.</em><br>Does it give the same opinion as the Question above?","options":["No, it prefers secondary school.","Yes, the same idea in new words.","No, \"sometimes\" makes it weaker."],"correctIndex":1,"nudge":"和上面的 Question 逐块对照：Some people think ↔ It is sometimes argued；start learning ↔ be introduced；at primary school ↔ in primary education；rather than at secondary school ↔ rather than at secondary level。有哪一块的意思变了？","explanation":"一样，只是换了词、换了结构。<br><strong>规则 ①</strong>：开头段改写题目：意思一点不变（rather than 也要保留），换词也换结构（children start learning → languages be introduced），不整句照抄。","subSkill":"key_word_transformation_paraphrase"},{"question":"改稿第三句：<em>Early language learning is highly beneficial to children…</em><br>（初稿：…is very benefit for the children…）<br>Which word could replace <em>beneficial</em> here?","options":["usefully","useful","advantage"],"correctIndex":1,"nudge":"把三个词放回原句读一读：…is highly ___ to children。highly 后面这个词在说「早学外语」怎么样，像 important 一样。","explanation":"useful：和 beneficial 一样，说「早学外语」怎么样。初稿错在 very 后面用了名词 benefit。<br><strong>规则 ②</strong>：词形跟着位置走：very / highly 后面用形容词（beneficial），the … of 中间用名词（the benefits of this approach）。改写也可以换词性：learning a language early → early language learning。","subSkill":"word_formation_affixation_and_conversion"},{"question":"还是这一句：<em>…highly beneficial to children</em>（初稿写的是 the children）。<br>Which children does the writer mean?","options":["Children in general","Pupils in one class","The writer's children"],"correctIndex":0,"nudge":"改稿里 children 前面没有 the。没有 the 的复数名词，说的是某几个具体的孩子，还是一类人？","explanation":"泛指所有孩子。初稿的 the children 会让读者以为是某几个特定的孩子。<br><strong>规则 ③</strong>：泛指时，复数名词、不可数名词都不加 the（children, society）；读者知道是哪些时才用 the。单数可数名词不能光着用（a child）。","subSkill":"open_cloze_grammar_word_selection"},{"question":"第四句：<em>The number of primary schools offering English has risen sharply in my country.</em><br>What has risen sharply?","options":["How many schools teach English","The size of each primary school","The number of English lessons"],"correctIndex":0,"nudge":"has risen 的主语是 the number of …：上升的是「数量」这一个数字。它是哪些东西的数量？","explanation":"上升的是「教英语的小学有多少所」这个数字。<br><strong>规则 ④</strong>：主谓一致看中心词：the number of + 复数名词，动词跟 number 走，用单数 has（初稿的 have 错了）。","subSkill":"error_correction_in_written_text"},{"question":"最后一句：<em>Although hiring qualified teachers is expensive, this is money well spent.</em><br>Does the writer think the cost is a reason not to start early?","options":["Yes, the teachers cost too much.","Yes, unless the cost falls.","No, the cost is worth paying."],"correctIndex":2,"nudge":"Although 后面先承认一个事实（很贵）。逗号后面才是作者真正的看法：money well spent 是钱花得值，还是不值？","explanation":"不是。贵是事实，但作者认为这钱花得值（初稿的 worth to spend 要改成 worth spending 或 money well spent）。<br><strong>规则 ⑤</strong>：Although 已经带「虽然…但是」的意思，主句前不再加 but。<br>另：hiring qualified teachers is 用单数，因为主语是「雇老师」这件事（同规则 ④）。","subSkill":"error_correction_in_written_text"},{"question":"你来试试：把题目 <em>Some people think that the best way to reduce crime is to give longer prison sentences.</em> 改写成开头段的第一句。<br>Which sentence keeps the meaning and has no errors?","options":["It is sometimes argued that longer prison sentences is the most effective way to cut crime.","It is sometimes argued that building many more prisons is the most effective way to cut crime.","It is sometimes argued that longer prison sentences are the most effective way to cut crime."],"correctIndex":2,"nudge":"先看意思：题目说的是「判得更久」，还是「多建监狱」？再看主语 longer prison sentences 是单数还是复数。用规则 ① 和 ④。","explanation":"第 3 句意思不变、没有错（规则 ①）。第 1 句主语 sentences 是复数，要用 are，别被后面的单数 way 带跑（规则 ④）；第 2 句把「判得更久」改成了「多建监狱」，意思变了。","subSkill":"key_word_transformation_paraphrase"}],"tip":"【交卷前改一遍：意思不变，形式写对】\n\n① 改写题目：意思一点不变（rather than、all、must 都要留住），换词也换结构，不照抄\n② 词形看位置：very / highly 后用形容词（beneficial），the … of 中间用名词；可换词性改写：learning a language early → early language learning\n③ 泛指：复数、不可数名词不加 the（children, society）；单数可数名词前要有 a / an\n④ 主谓一致看中心词：the number of / one of + 复数名词 → 单数（has / is）；-ing 短语当主语 → 单数\n⑤ Although …, 主句前不加 but\n⑥ Task 1：rose by / a rise of 5 points（涨了多少），rose to 40%（涨到多少），a rise in sales（什么在涨）\n⑦ information、advice、research 不加 s\n交卷前专查四样：主谓一致、冠词、时态、词形。\n\n【例句】\n✔ It is sometimes argued that foreign languages should be introduced in primary education rather than at secondary level.\n✔ The number of primary schools offering English has risen sharply.\n\n【常见错误】\n✘ It is very benefit for children. → very beneficial for children（见 ②）\n✘ The number of students have doubled. → has doubled（见 ④）\n✘ Although it is expensive, but it is worth it. → 去掉 but（见 ⑤）\n✘ There are many people think that … → Many people think that …\n✘ The chart shows how much time did teenagers spend … → how much time teenagers spent"}}}};
